  function openWorkflowStarter(starterId) {
    if (!state.currentProject) {
      showToast({ key: 'actions.projectRequired' }, 'warning');
      return;
    }
    const starters = getWorkflowStarters();
    const tmpl = starters.find(s => s.id === starterId || s.actionId === starterId);
    if (!tmpl) return;
    const wf = JSON.parse(JSON.stringify(tmpl.wf));
    wf.project = state.currentProject;
    openEditWorkflowModal(wf);
  }

  function getWorkflowStarterTemplates() {
    return getWorkflowStarters();
  }

  function launchWorkflowStarter(starterId) {
    return openWorkflowStarter(starterId);
  }

  // -------------------------------------------------------------------------
  // 2. WORKFLOWS VIEW (With deterministic workflow builder draft)
  // -------------------------------------------------------------------------
  function renderWorkflowsView(container) {
    const allWorkflows = (state.dashboard && state.dashboard.workflows) || [];
    const workflows = state.workflowsIncludeArchived
      ? allWorkflows
      : allWorkflows.filter(w => w.state !== 'archived');
    const runs = (state.dashboard && state.dashboard.runs) || [];
    const schedulesCount = workflows.filter(w => w.trigger === 'cron').length;

    container.innerHTML = `
      <div class="page-header">
        <div class="page-title-group">
          <h1 data-i18n="workflows.title">${escapeHtml(t('workflows.title'))}</h1>
          <p data-i18n="workflows.subtitle">${escapeHtml(t('workflows.subtitle'))}</p>
        </div>
        <div class="page-actions">
          <button id="btn-new-workflow" class="btn btn-primary" data-i18n="workflows.btnNewWorkflow">${escapeHtml(t('workflows.btnNewWorkflow'))}</button>
          ${actionMenu(`
            <button id="btn-build-wf-prompt" class="btn" data-i18n="workflows.btnBuildPrompt">${escapeHtml(t('workflows.btnBuildPrompt'))}</button>
            <button id="btn-plan-workflow" class="btn" data-i18n="workflows.btnPlanWorkflow">${escapeHtml(t('workflows.btnPlanWorkflow'))}</button>
            <button id="btn-validate-workflows" class="btn" data-i18n="workflows.btnValidateAll">${escapeHtml(t('workflows.btnValidateAll'))}</button>
            <div class="menu-section-label" data-i18n="workflows.btnStarterTemplates">${escapeHtml(t('workflows.btnStarterTemplates'))}</div>
            ${[['template-worktree-check','workflows.starterWorktreeTitle'],['template-recent-changes','workflows.starterRecentTitle'],['template-handoff-review','workflows.starterHandoffTitle']].map(([id,key]) => `<button class="btn btn-starter-template" data-template-id="${id}" data-i18n="${key}">${escapeHtml(t(key))}</button>`).join('')}
          `, 'reading.more', true, 'btn-wf-starters-menu')}
        </div>
      </div>

      <div class="tabs-nav">
        <button class="tab-btn ${state.workflowsActiveTab === 'list' ? 'active' : ''}" data-wftab="list" data-i18n="workflows.tabList" data-i18n-params="${escapeHtml(JSON.stringify({ count: workflows.length }))}">${escapeHtml(t('workflows.tabList', { count: workflows.length }))}</button>
        <button class="tab-btn ${state.workflowsActiveTab === 'runs' ? 'active' : ''}" data-wftab="runs" data-i18n="workflows.tabRuns" data-i18n-params="${escapeHtml(JSON.stringify({ count: runs.length }))}">${escapeHtml(t('workflows.tabRuns', { count: runs.length }))}</button>
        <button class="tab-btn ${state.workflowsActiveTab === 'schedules' ? 'active' : ''}" data-wftab="schedules" data-i18n="workflows.tabSchedules" data-i18n-params="${escapeHtml(JSON.stringify({ count: schedulesCount }))}">${escapeHtml(t('workflows.tabSchedules', { count: schedulesCount }))}</button>
        ${actionMenu(`
          <button class="btn" data-wftab="plans" data-i18n="workspace.workflow.planning">${escapeHtml(t('workspace.workflow.planning'))}</button>
          <button class="btn" data-wftab="artifacts" data-i18n="workspace.workflow.outputs">${escapeHtml(t('workspace.workflow.outputs'))}</button>
          <button class="btn" data-wftab="health" data-i18n="workspace.workflow.health">${escapeHtml(t('workspace.workflow.health'))}</button>
        `, 'workspace.workflow.tools', false, 'btn-wf-secondary-menu')}
      </div>

      <div id="workflows-tab-content"></div>
    `;

    const updateSecondaryMenu = () => {
      const key = ({ plans: 'workspace.workflow.planning', artifacts: 'workspace.workflow.outputs', health: 'workspace.workflow.health' })[state.workflowsActiveTab] || 'workspace.workflow.tools';
      const summary = document.getElementById('btn-wf-secondary-menu');
      if (!summary) return;
      setElementDescriptor(summary.querySelector('span'), { key });
      summary.setAttribute('data-i18n-aria-label', key);
      summary.setAttribute('data-i18n-title', key);
      summary.setAttribute('aria-label', t(key));
      summary.title = t(key);
      summary.classList.toggle('active', key !== 'workspace.workflow.tools');
    };
    updateSecondaryMenu();
    syncViewButtons(container, 'data-wftab', state.workflowsActiveTab);
    container.querySelectorAll('[data-wftab]').forEach(tab => {
      tab.addEventListener('click', () => {
        state.workflowsActiveTab = tab.getAttribute('data-wftab');
        syncViewButtons(container, 'data-wftab', state.workflowsActiveTab);
        updateSecondaryMenu();
        workflowTabGen++;
        if (state.workflowsActiveTab !== 'health' && typeof dismissActiveHealthProposalModal === 'function') {
          dismissActiveHealthProposalModal();
        }
        renderWorkflowsTabContent();
      });
    });

    container.querySelectorAll('.btn-starter-template').forEach(btn => {
      btn.addEventListener('click', () => openWorkflowStarter(btn.getAttribute('data-template-id')));
    });

    document.getElementById('btn-new-workflow').addEventListener('click', () => {
      openEditWorkflowModal();
    });

    document.getElementById('btn-build-wf-prompt').addEventListener('click', () => {
      openWorkflowPromptBuilderModal();
    });

    document.getElementById('btn-plan-workflow')?.addEventListener('click', () => {
      openWorkflowPlannerModal();
    });

    document.getElementById('btn-validate-workflows')?.addEventListener('click', () => {
      openWorkflowsValidationModal();
    });

    renderWorkflowsTabContent();
  }

  let workflowTabGen = 0;

  function renderWorkflowsTabContent() {
    const target = document.getElementById('workflows-tab-content');
    if (!target) return;

    if (state.workflowsActiveTab === 'list') {
      const allWorkflows = (state.dashboard && state.dashboard.workflows) || [];
      const workflows = state.workflowsIncludeArchived
        ? allWorkflows
        : allWorkflows.filter(w => w.state !== 'archived');

      const listTabBtn = document.querySelector('[data-wftab="list"]');
      if (listTabBtn) {
        listTabBtn.setAttribute('data-i18n-params', JSON.stringify({ count: workflows.length }));
        listTabBtn.textContent = t('workflows.tabList', { count: workflows.length });
      }

      const topBarHtml = `
        <div style="display: flex; align-items: center; justify-content: flex-end; margin-bottom: 8px;">
          <label style="display: inline-flex; align-items: center; gap: 6px; font-size: 12px; cursor: pointer;">
            <input type="checkbox" id="chk-include-archived" ${state.workflowsIncludeArchived ? 'checked' : ''} />
            <span data-i18n="workflows.includeArchived">${escapeHtml(t('workflows.includeArchived'))}</span>
          </label>
        </div>
      `;

      if (workflows.length === 0) {
        target.innerHTML = `
          ${topBarHtml}
          <div class="empty-state">
            <div class="empty-state-title" data-i18n="workflows.emptyTitle">${escapeHtml(t('workflows.emptyTitle'))}</div>
            <div class="empty-state-desc" data-i18n="workflows.emptyDesc">${escapeHtml(t('workflows.emptyDesc'))}</div>
            <div style="display: flex; gap: 8px; margin-top: 12px;">
              <button id="btn-empty-build-wf" class="btn btn-secondary btn-sm" data-i18n="workflows.btnEmptyBuild">${escapeHtml(t('workflows.btnEmptyBuild'))}</button>
              <button id="btn-empty-create-wf" class="btn btn-primary btn-sm" data-i18n="workflows.btnEmptyCreate">${escapeHtml(t('workflows.btnEmptyCreate'))}</button>
            </div>
          </div>
        `;
        document.getElementById('btn-empty-create-wf')?.addEventListener('click', () => openEditWorkflowModal());
        document.getElementById('btn-empty-build-wf')?.addEventListener('click', () => openWorkflowPromptBuilderModal());
        document.getElementById('chk-include-archived')?.addEventListener('change', async (e) => {
          state.workflowsIncludeArchived = e.target.checked;
          const thisProject = state.currentProject;
          const thisGen = ++workflowTabGen;
          try {
            const list = await callBridge('workflows.list', { project: thisProject, includeArchived: state.workflowsIncludeArchived });
            if (thisGen !== workflowTabGen || state.currentProject !== thisProject || state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'list') return;
            if (state.dashboard) {
              state.dashboard.workflows = list;
            }
            renderWorkflowsTabContent();
          } catch (err) {
            if (thisGen !== workflowTabGen || state.currentProject !== thisProject) return;
            showToast({ key: 'workflows.actionFailed', params: { error: err.message } }, 'error');
          }
        });
        return;
      }

      target.innerHTML = `
        ${topBarHtml}
        <div class="workspace-list workflow-list">
          ${workflows.map(wf => {
            const triggerKey = ({manual:'workspace.trigger.manual',cron:'workspace.trigger.cron',watch:'workspace.trigger.watch'})[wf.trigger] || 'workspace.trigger.manual';
            const triggerParams = {};
            const stepCount = (wf.steps || []).length;
            const stepKey = stepCount === 1 ? 'workflows.stepCountOne' : 'workflows.stepsCount';
            return `
            <article class="workspace-row workflow-row" data-id="${escapeHtml(wf.id)}">
              <div class="workspace-row-icon" data-kind="${VelaContent.workflowKind(wf)}" aria-hidden="true">${VelaContent.icon(VelaContent.workflowKind(wf))}</div>
              <div class="workspace-row-content">
                <button class="row-title btn-wf-inspect" data-id="${escapeHtml(wf.id)}" title="${escapeHtml(wf.title || t('common.unnamedSession'))}">${escapeHtml(wf.title || t('common.unnamedSession'))}</button>
                ${wf.description ? `<p class="row-description">${escapeHtml(wf.description)}</p>` : ''}
                <div class="row-meta">${!state.currentProject && wf.project ? `<span>${escapeHtml(wf.project.split('/').filter(Boolean).pop())}</span>` : ''}<span data-i18n="${triggerKey}" data-i18n-params="${escapeHtml(JSON.stringify(triggerParams))}">${escapeHtml(t(triggerKey, triggerParams))}</span><span data-i18n="${stepKey}" data-i18n-params="${escapeHtml(JSON.stringify({ count: stepCount }))}">${escapeHtml(t(stepKey, { count: stepCount }))}</span>
                  ${wf.state === 'archived' ? `<span data-i18n="workflows.badgeArchived">${escapeHtml(t('workflows.badgeArchived'))}</span>` : wf.enabled === false ? `<span data-i18n="workflows.statusDisabled">${escapeHtml(t('workflows.statusDisabled'))}</span>` : `<span class="text-sage" data-i18n="workflows.statusEnabled">${escapeHtml(t('workflows.statusEnabled'))}</span>`}
                </div>
              </div>
              ${actionMenu(`
                ${menuAction('workflows.btnRun', 'play', {className:'btn-wf-run', data:`data-id="${escapeHtml(wf.id)}"`})}
                ${menuAction('workflows.btnDryRun', 'preview', {className:'btn-wf-dryrun', data:`data-id="${escapeHtml(wf.id)}"`})}
                ${menuAction('common.edit', 'edit', {className:'btn-wf-edit', data:`data-id="${escapeHtml(wf.id)}"`})}
                ${wf.trigger === 'watch' ? `<button class="btn btn-wf-preview-watch" data-id="${escapeHtml(wf.id)}" data-project="${escapeHtml(wf.project || '')}">${escapeHtml(t('watch.btnPreview'))}</button>` : ''}
              `)}
            </article>`;
          }).join('')}
        </div>
      `;

      document.getElementById('chk-include-archived')?.addEventListener('change', async (e) => {
        state.workflowsIncludeArchived = e.target.checked;
        const thisProject = state.currentProject;
        const thisGen = ++workflowTabGen;
        try {
          const list = await callBridge('workflows.list', { project: thisProject, includeArchived: state.workflowsIncludeArchived });
          if (thisGen !== workflowTabGen || state.currentProject !== thisProject || state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'list') return;
          if (state.dashboard) {
            state.dashboard.workflows = list;
          }
          renderWorkflowsTabContent();
        } catch (err) {
          if (thisGen !== workflowTabGen || state.currentProject !== thisProject) return;
          showToast({ key: 'workflows.actionFailed', params: { error: err.message } }, 'error');
        }
      });

      target.querySelectorAll('.btn-wf-inspect').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          if (id) openWorkflowInspectModal(id, workflows.find(w => w.id === id)?.project || state.currentProject);
        });
      });

      target.querySelectorAll('.btn-wf-preview-watch').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const proj = btn.getAttribute('data-project') || state.currentProject;
          if (id) openWatchPreviewModal(id, proj);
        });
      });

      target.querySelectorAll('.btn-wf-run').forEach(btn => {
        btn.addEventListener('click', async () => {
          const id = btn.getAttribute('data-id');
          try {
            const run = await callBridge('workflows.run', { id, dryRun: false });
            showToast({ key: 'workflows.runTriggeredToast' });
            await refreshDashboard(true, true);
            if (run && run.id) openRunDetail(run.id);
          } catch (err) {
            showToast({ key: 'workflows.runFailedToast', params: { error: err.message } }, 'error');
          }
        });
      });

      target.querySelectorAll('.btn-wf-dryrun').forEach(btn => {
        btn.addEventListener('click', async () => {
          const id = btn.getAttribute('data-id');
          try {
            const run = await callBridge('workflows.run', { id, dryRun: true });
            showToast({ key: 'workflows.dryRunCompletedToast' });
            await refreshDashboard(true, true);
            if (run && run.id) openRunDetail(run.id);
          } catch (err) {
            showToast({ key: 'workflows.dryRunFailedToast', params: { error: err.message } }, 'error');
          }
        });
      });

      target.querySelectorAll('.btn-wf-edit').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const wf = workflows.find(w => w.id === id);
          if (wf) openEditWorkflowModal(wf);
        });
      });

    } else if (state.workflowsActiveTab === 'runs') {
      const runs = (state.dashboard && state.dashboard.runs) || [];
      if (runs.length === 0) {
        target.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-title" data-i18n="workflows.runsEmptyTitle">${escapeHtml(t('workflows.runsEmptyTitle'))}</div>
            <div class="empty-state-desc" data-i18n="workflows.runsEmptyDesc">${escapeHtml(t('workflows.runsEmptyDesc'))}</div>
          </div>
        `;
        return;
      }

      target.innerHTML = `
        <div class="table-wrapper">
          <table class="data-table" id="workflow-runs-table">
            <thead>
              <tr>
                <th data-i18n="workflows.colWorkflow">${escapeHtml(t('workflows.colWorkflow'))}</th>
                <th data-i18n="workflows.colMode">${escapeHtml(t('workflows.colMode'))}</th>
                <th data-i18n="common.status">${escapeHtml(t('common.status'))}</th>
                <th data-i18n="workflows.colStartTime">${escapeHtml(t('workflows.colStartTime'))}</th>
                <th style="text-align: right; width: 140px;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
              </tr>
            </thead>
            <tbody>
              ${runs.map(r => `
                <tr class="clickable-row" data-id="${escapeHtml(r.id)}">
                  <td class="run-name-cell"><button class="row-title btn-open-run" data-id="${escapeHtml(r.id)}" title="${escapeHtml(runDisplayTitle(r))}">${escapeHtml(runDisplayTitle(r))}</button>
                    <details class="technical-disclosure run-identity"><summary data-i18n="workspace.run.details">${escapeHtml(t('workspace.run.details'))}</summary>
                      <dl class="field-list"><div class="field-row"><dt data-i18n="workflows.colRunId">${escapeHtml(t('workflows.colRunId'))}</dt><dd><code>${escapeHtml(r.id || '-')}</code></dd></div>
                      <div class="field-row"><dt data-i18n="workflows.colWorkflow">${escapeHtml(t('workflows.colWorkflow'))}</dt><dd><code>${escapeHtml(r.workflowId || '-')}</code></dd></div>
                      <div class="field-row"><dt data-i18n="workflows.colDuration">${escapeHtml(t('workflows.colDuration'))}</dt><dd>${typeof r.durationMs === 'number' && Number.isFinite(r.durationMs) ? escapeHtml(String(r.durationMs)) + ' ms' : '—'}</dd></div></dl>
                    </details>
                  </td>
                  <td>${r.dryRun ? `<span class="status-badge status-neutral" data-i18n="workflows.modeDryRun">${escapeHtml(t('workflows.modeDryRun'))}</span>` : `<span class="status-badge status-sage" data-i18n="workflows.modeExecute">${escapeHtml(t('workflows.modeExecute'))}</span>`}</td>
                  <td>${getRunStateBadge(r.state)}</td>
                  <td>${formatTime(r.startedAt)}</td>
                  <td style="text-align: right;">
                    <button class="btn btn-secondary btn-sm btn-replay-run" data-id="${escapeHtml(r.id)}" data-i18n="workflows.btnReplay">${escapeHtml(t('workflows.btnReplay'))}</button>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;

      target.querySelectorAll('tr.clickable-row').forEach(row => {
        row.addEventListener('click', (e) => {
          if (e.target.closest('button, details, summary')) return;
          openRunDetail(row.getAttribute('data-id'));
        });
      });

      target.querySelectorAll('.btn-open-run').forEach(btn => btn.addEventListener('click', () => openRunDetail(btn.dataset.id)));

      target.querySelectorAll('.btn-replay-run').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const runId = btn.getAttribute('data-id');
          try {
            await callBridge('workflows.replay', { runId });
            showToast({ key: 'workflows.replayedToast' });
            await refreshDashboard(true, true);
          } catch (err) {
            showToast({ key: 'workflows.replayFailedToast', params: { error: err.message } }, 'error');
          }
        });
      });

    } else if (state.workflowsActiveTab === 'plans') {
      renderWorkflowsPlansTab(target);
    } else if (state.workflowsActiveTab === 'schedules') {
      renderWorkflowsSchedulesTab(target);
    } else if (state.workflowsActiveTab === 'artifacts') {
      renderWorkflowsArtifactsTab(target);
    } else if (state.workflowsActiveTab === 'health') {
      target.innerHTML = `
        <div class="card">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.healthCardTitle">${escapeHtml(t('workflows.healthCardTitle'))}</span>
            <button id="btn-refresh-health" class="btn btn-ghost btn-sm" data-i18n="workflows.btnRefreshHealth">${escapeHtml(t('workflows.btnRefreshHealth'))}</button>
          </div>
          <div id="health-stats-container">
            <div class="stat-grid">
              <div class="stat-card">
                <div class="stat-label" data-i18n="workflows.statTotalRuns">${escapeHtml(t('workflows.statTotalRuns'))}</div>
                <div class="stat-value" id="health-total-runs">-</div>
                <div class="stat-sub" id="health-success-detail">-</div>
              </div>
              <div class="stat-card">
                <div class="stat-label" data-i18n="workflows.statSuccessRate">${escapeHtml(t('workflows.statSuccessRate'))}</div>
                <div class="stat-value" id="health-success-rate">-</div>
                <div class="stat-sub" id="health-approval-rejected">-</div>
              </div>
              <div class="stat-card">
                <div class="stat-label" data-i18n="workflows.statAvgDuration">${escapeHtml(t('workflows.statAvgDuration'))}</div>
                <div class="stat-value" id="health-avg-duration">-</div>
                <div class="stat-sub" id="health-tokens-stat">${escapeHtml(t('workflows.statTokensUnavailable'))}</div>
              </div>
            </div>
          </div>
        </div>
        <div class="card" style="margin-top: 16px;">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.healthFindingsTitle">${escapeHtml(t('workflows.healthFindingsTitle'))}</span>
          </div>
          <div id="workflow-health-findings" class="health-findings-container">
            <div class="empty-state" style="padding: 24px 0;">
              <div class="empty-state-title" data-i18n="common.loading">${escapeHtml(t('common.loading') || 'Loading...')}</div>
            </div>
          </div>
        </div>
        <div id="workflow-health-proposals-section" class="card" style="margin-top: 16px; display: none;">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.healthProposalsTitle">${escapeHtml(t('workflows.healthProposalsTitle'))}</span>
            <span id="health-proposals-incomplete-badge" class="badge badge-amber" style="display: none;" data-i18n="workflows.healthProposalsIncomplete">${escapeHtml(t('workflows.healthProposalsIncomplete'))}</span>
          </div>
          <div id="workflow-health-proposals-list" class="health-proposals-container"></div>
        </div>
      `;

      loadHealthData();
      document.getElementById('btn-refresh-health').addEventListener('click', loadHealthData);
    }
  }

  async function renderWorkflowsSchedulesTab(target) {
    target.innerHTML = `
      <div class="empty-state" style="padding: 40px 0;">
        <div class="empty-state-icon">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
        </div>
        <div class="empty-state-title" data-i18n="common.loading">${escapeHtml(t('common.loading') || 'Loading...')}</div>
      </div>
    `;

    try {
      const data = await callBridge('schedules.list', state.currentProject ? { project: state.currentProject } : {});
      const daemonRunning = data && data.daemonRunning === true;
      const intervalSeconds = (data && data.intervalSeconds) || 30;
      const schedules = Array.isArray(data && data.schedules) ? data.schedules : [];
      const events = Array.isArray(data && data.events) ? data.events : [];
      const workflows = (state.dashboard && state.dashboard.workflows) || [];

      const scheduleMap = new Map();
      schedules.forEach(s => { if (s && s.id) scheduleMap.set(s.id, s); });

      const scheduledItems = [];
      const seenIds = new Set();
      workflows.forEach(w => {
        if (w.trigger === 'cron') {
          scheduledItems.push({
            workflow: w,
            schedule: scheduleMap.get(w.id)
          });
          seenIds.add(w.id);
        }
      });
      schedules.forEach(s => {
        if (s && s.id && !seenIds.has(s.id)) {
          const matched = workflows.find(w => w.id === s.id);
          scheduledItems.push({
            workflow: matched || { id: s.id, name: s.id, trigger: 'cron' },
            schedule: s
          });
          seenIds.add(s.id);
        }
      });

      const sortedEvents = events.slice().sort((a, b) => {
        const tA = a.claimedAt || a.scheduledAt || '';
        const tB = b.claimedAt || b.scheduledAt || '';
        return tB.localeCompare(tA);
      });

      function getScheduleBadge(st) {
        if (!st || st === 'idle') return `<span class="status-badge status-neutral">${escapeHtml(st || 'idle')}</span>`;
        if (st === 'running' || st === 'claimed') return `<span class="status-badge status-sage">${escapeHtml(st)}</span>`;
        if (st === 'deferred') return `<span class="status-badge status-warning">${escapeHtml(st)}</span>`;
        if (st === 'needs_review') return `<span class="status-badge status-danger">${escapeHtml(st)}</span>`;
        return `<span class="status-badge status-neutral">${escapeHtml(st)}</span>`;
      }

      function getEventBadge(st) {
        if (st === 'claimed') return `<span class="status-badge status-warning">${escapeHtml(st)}</span>`;
        if (st === 'dispatched') return `<span class="status-badge status-sage">${escapeHtml(st)}</span>`;
        if (st === 'acknowledged') return `<span class="status-badge status-neutral">${escapeHtml(st)}</span>`;
        if (st === 'needs_review') return `<span class="status-badge status-danger">${escapeHtml(st)}</span>`;
        return `<span class="status-badge status-neutral">${escapeHtml(st || '-')}</span>`;
      }

      target.innerHTML = `
        <div class="daemon-status-banner">
          <div style="display: flex; align-items: center; gap: 10px;">
            <span class="status-dot ${daemonRunning ? 'status-dot-active' : ''}" style="width: 8px; height: 8px; border-radius: 50%; background: ${daemonRunning ? 'var(--status-sage-text)' : 'var(--text-muted)'}; display: inline-block;"></span>
            <div>
              <strong style="font-size: 13px;">${daemonRunning ? escapeHtml(t('workflows.daemonRunning')) : escapeHtml(t('workflows.daemonStopped'))}</strong>
              <div style="font-size: 11px; color: var(--text-secondary); margin-top: 2px;">
                ${escapeHtml(t('workflows.checkInterval', { seconds: intervalSeconds }))}
              </div>
            </div>
          </div>
          <button id="btn-refresh-schedules" class="btn btn-ghost btn-sm" data-i18n="workflows.btnRefreshHealth">${escapeHtml(t('workflows.btnRefreshHealth'))}</button>
        </div>

        <div class="card" style="margin-bottom: 16px;">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.schedulesListTitle">${escapeHtml(t('workflows.schedulesListTitle'))}</span>
            <span class="status-badge status-neutral">${scheduledItems.length}</span>
          </div>
          ${scheduledItems.length === 0 ? `
            <div style="padding: 24px 16px; text-align: center; color: var(--text-muted); font-size: 13px;">
              ${escapeHtml(t('workflows.emptyDesc'))}
            </div>
          ` : `
            <div class="table-wrapper" style="margin-bottom: 0;">
              <table class="data-table">
                <thead>
                  <tr>
                    <th data-i18n="workflows.colName">${escapeHtml(t('workflows.colName'))}</th>
                    <th data-i18n="workflows.colTrigger">${escapeHtml(t('workflows.colTrigger'))}</th>
                    <th data-i18n="workflows.timeZoneLabel">${escapeHtml(t('workflows.timeZoneLabel'))}</th>
                    <th data-i18n="workflows.catchUpPolicyLabel">${escapeHtml(t('workflows.catchUpPolicyLabel'))}</th>
                    <th data-i18n="workflows.colStatus">${escapeHtml(t('workflows.colStatus'))}</th>
                    <th data-i18n="workflows.colScheduledAt">${escapeHtml(t('workflows.colScheduledAt'))}</th>
                    <th style="text-align: right;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
                  </tr>
                </thead>
                <tbody>
                  ${scheduledItems.map(item => {
                    const w = item.workflow;
                    const s = item.schedule;
                    const st = s ? s.state : 'idle';
                    let catchUpDesc = w.catchUp === 'all' ? t('workflows.catchUpAll') : w.catchUp === 'skip' ? t('workflows.catchUpSkip') : t('workflows.catchUpLatest');
                    if (w.catchUpLimit) catchUpDesc += ` (max ${w.catchUpLimit})`;
                    const lastRunText = s && s.lastCheckedMinute ? formatTime(new Date(s.lastCheckedMinute * 60000)) : (s && s.lastRunId ? `<span class="code-badge">${escapeHtml(s.lastRunId.substring(0, 8))}</span>` : '—');
                    const errorNote = (s && (s.error || s.reason)) ? `<div style="font-size: 10px; color: var(--status-red-text); margin-top: 2px;">${escapeHtml(s.error || s.reason)}</div>` : '';

                    return `
                      <tr>
                        <td>
                          <strong>${escapeHtml(w.name || w.id)}</strong>
                          <div style="font-size: 11px; color: var(--text-muted);"><span class="code-badge">${escapeHtml(w.id ? w.id.substring(0, 16) : '-')}</span></div>
                        </td>
                        <td><code class="code-badge font-mono">${escapeHtml(w.cron || w.trigger || '-')}</code></td>
                        <td>${escapeHtml(w.timeZone || 'local')}</td>
                        <td style="font-size: 11px;">${escapeHtml(catchUpDesc)}</td>
                        <td>
                          ${getScheduleBadge(st)}
                          ${errorNote}
                        </td>
                        <td>${lastRunText}</td>
                        <td style="text-align: right;">
                          <button class="btn btn-secondary btn-xs btn-edit-sched-wf" data-id="${escapeHtml(w.id)}" data-i18n="common.edit">${escapeHtml(t('common.edit'))}</button>
                        </td>
                      </tr>
                    `;
                  }).join('')}
                </tbody>
              </table>
            </div>
          `}
        </div>

        <div class="card">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.dispatchesListTitle">${escapeHtml(t('workflows.dispatchesListTitle'))}</span>
            <span class="status-badge status-neutral">${sortedEvents.length}</span>
          </div>
          ${sortedEvents.length === 0 ? `
            <div style="padding: 24px 16px; text-align: center; color: var(--text-muted); font-size: 13px;">
              —
            </div>
          ` : `
            <div class="table-wrapper" style="margin-bottom: 0;">
              <table class="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th data-i18n="workflows.colName">${escapeHtml(t('workflows.colName'))}</th>
                    <th data-i18n="workflows.colScheduledAt">${escapeHtml(t('workflows.colScheduledAt'))}</th>
                    <th data-i18n="workflows.colDispatchedAt">${escapeHtml(t('workflows.colDispatchedAt'))}</th>
                    <th data-i18n="workflows.colStatus">${escapeHtml(t('workflows.colStatus'))}</th>
                    <th data-i18n="workflows.colDecision">${escapeHtml(t('workflows.colDecision'))}</th>
                    <th style="text-align: right;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
                  </tr>
                </thead>
                <tbody>
                  ${sortedEvents.map(ev => {
                    const isAckable = ev.state === 'claimed' || ev.state === 'needs_review';
                    const runBadge = ev.runId ? `<a href="#" class="btn-inspect-ev-run code-badge" data-runid="${escapeHtml(ev.runId)}" style="text-decoration:none; margin-left: 4px;">Run ${escapeHtml(ev.runId.substring(0, 8))}</a>` : '';
                    const lateText = (typeof ev.lateBySeconds === 'number' && ev.lateBySeconds > 0) ? `<span style="font-size: 10px; color: var(--status-amber-text); margin-left: 4px;">+${ev.lateBySeconds}s</span>` : '';
                    const errorText = ev.error ? `<div style="font-size: 10px; color: var(--status-red-text); margin-top: 2px;">${escapeHtml(ev.error)}</div>` : '';
                    const ackText = ev.acknowledgedAt ? `<div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">Ack @ ${formatTime(ev.acknowledgedAt)}</div>` : '';

                    return `
                      <tr>
                        <td><span class="code-badge font-mono">${escapeHtml(ev.id ? ev.id.substring(0, 10) : '-')}</span></td>
                        <td><strong>${escapeHtml(ev.workflowId || '-')}</strong></td>
                        <td style="font-size: 11px;">${ev.scheduledAt ? formatTime(ev.scheduledAt) : '—'}</td>
                        <td style="font-size: 11px;">${ev.claimedAt ? formatTime(ev.claimedAt) : '—'}${lateText}</td>
                        <td>
                          ${getEventBadge(ev.state)}
                          ${runBadge}
                          ${errorText}
                        </td>
                        <td style="font-size: 11px;">
                          ${ev.state === 'acknowledged' ? `<span class="status-badge status-sage" data-i18n="common.acknowledged">${escapeHtml(t('common.acknowledged') || 'Acknowledged')}</span>` : (isAckable ? `<span class="status-badge status-warning" data-i18n="inbox.pendingApproval">${escapeHtml(t('inbox.pendingApproval'))}</span>` : '—')}
                          ${ackText}
                        </td>
                        <td style="text-align: right;">
                          ${isAckable ? `
                            <button class="btn btn-secondary btn-xs btn-ack-event" data-id="${escapeHtml(ev.id)}" data-project="${escapeHtml(ev.project || state.currentProject || '')}" data-i18n="workflows.btnAcknowledge">${escapeHtml(t('workflows.btnAcknowledge'))}</button>
                          ` : '—'}
                        </td>
                      </tr>
                    `;
                  }).join('')}
                </tbody>
              </table>
            </div>
          `}
        </div>
      `;

      target.querySelector('#btn-refresh-schedules')?.addEventListener('click', () => {
        renderWorkflowsSchedulesTab(target);
      });

      target.querySelectorAll('.btn-edit-sched-wf').forEach(btn => {
        btn.addEventListener('click', () => {
          const wfId = btn.getAttribute('data-id');
          const wf = workflows.find(w => w.id === wfId) || { id: wfId, trigger: 'cron' };
          openEditWorkflowModal(wf);
        });
      });

      target.querySelectorAll('.btn-inspect-ev-run').forEach(a => {
        a.addEventListener('click', (e) => {
          e.preventDefault();
          const runId = a.getAttribute('data-runid');
          if (runId) openRunDetail(runId);
        });
      });

      target.querySelectorAll('.btn-ack-event').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const eventId = btn.getAttribute('data-id');
          const proj = btn.getAttribute('data-project') || state.currentProject;
          try {
            btn.disabled = true;
            await callBridge('schedules.resolve', { id: eventId, project: proj, decision: 'acknowledge' });
            showToast({ key: 'workflows.acknowledgedToast' });
            renderWorkflowsSchedulesTab(target);
          } catch (err) {
            showToast({ key: 'workflows.acknowledgeFailedToast', params: { error: err.message } }, 'error');
            btn.disabled = false;
          }
        });
      });

    } catch (err) {
      target.innerHTML = `
        <div class="alert-banner alert-danger">
          ${escapeHtml(err.message || String(err))}
        </div>
      `;
    }
  }

  async function renderWorkflowsArtifactsTab(target) {
    target.innerHTML = `
      <div class="empty-state" style="padding: 40px 0;">
        <div class="empty-state-icon">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
        </div>
        <div class="empty-state-title" data-i18n="common.loading">${escapeHtml(t('common.loading') || 'Loading...')}</div>
      </div>
    `;

    try {
      const proj = state.currentProject;
      const [listRes, inboxRes] = await Promise.all([
        callBridge('outputs.list', proj ? { project: proj } : {}),
        callBridge('outputs.inbox', proj ? { project: proj } : {}).catch(() => [])
      ]);

      const items = Array.isArray(listRes) ? listRes : (listRes && Array.isArray(listRes.items) ? listRes.items : []);
      const inboxItems = Array.isArray(inboxRes) ? inboxRes : (inboxRes && Array.isArray(inboxRes.items) ? inboxRes.items : []);
      state.workflowArtifactsCount = inboxItems.length;

      const tabBtn = document.querySelector('[data-wftab="artifacts"]');
      if (tabBtn) {
        tabBtn.setAttribute('data-i18n-params', JSON.stringify({ count: state.workflowArtifactsCount }));
        tabBtn.textContent = t('workflows.tabArtifacts', { count: state.workflowArtifactsCount });
      }

      if (items.length === 0) {
        target.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-title" data-i18n="workflows.artifactsEmptyTitle">${escapeHtml(t('workflows.artifactsEmptyTitle'))}</div>
            <div class="empty-state-desc" data-i18n="workflows.artifactsEmptyDesc">${escapeHtml(t('workflows.artifactsEmptyDesc'))}</div>
            <div style="margin-top: 12px;">
              <button id="btn-refresh-artifacts" class="btn btn-secondary btn-sm" data-i18n="workflows.btnRefreshHealth">${escapeHtml(t('workflows.btnRefreshHealth'))}</button>
            </div>
          </div>
        `;
        document.getElementById('btn-refresh-artifacts')?.addEventListener('click', () => renderWorkflowsArtifactsTab(target));
        return;
      }

      target.innerHTML = `
        <div class="card" style="margin-bottom: 16px;">
          <div class="card-header">
            <div>
              <span class="card-title" data-i18n="workflows.artifactsTitle">${escapeHtml(t('workflows.artifactsTitle'))}</span>
              <div style="font-size: 11px; color: var(--text-secondary); margin-top: 2px;" data-i18n="workflows.artifactsDesc">
                ${escapeHtml(t('workflows.artifactsDesc'))}
              </div>
            </div>
            <div style="display: flex; align-items: center; gap: 8px;">
              ${state.workflowArtifactsCount > 0 ? `<span class="status-badge status-warning">${state.workflowArtifactsCount} ${escapeHtml(t('workflows.unreadBadge'))}</span>` : ''}
              <button id="btn-refresh-artifacts" class="btn btn-ghost btn-sm" data-i18n="workflows.btnRefreshHealth">${escapeHtml(t('workflows.btnRefreshHealth'))}</button>
            </div>
          </div>
          <div class="table-wrapper">
            <table class="data-table">
              <thead>
                <tr>
                  <th data-i18n="workflows.colArtifactPath">${escapeHtml(t('workflows.colArtifactPath'))}</th>
                  <th data-i18n="workflows.colArtifactTarget">${escapeHtml(t('workflows.colArtifactTarget'))}</th>
                  <th data-i18n="workflows.colArtifactWorkflow">${escapeHtml(t('workflows.colArtifactWorkflow'))}</th>
                  <th data-i18n="common.status">${escapeHtml(t('common.status'))}</th>
                  <th data-i18n="workflows.colArtifactTime">${escapeHtml(t('workflows.colArtifactTime'))}</th>
                  <th style="text-align: right; width: 160px;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
                </tr>
              </thead>
              <tbody>
                ${items.map(item => {
                  const isUnread = item.unread === true;
                  const targetLabel = item.target === 'file' ? t('workflows.targetFile') : (item.target === 'inbox' ? t('workflows.targetInbox') : (item.target || 'stdout'));
                  return `
                    <tr class="${isUnread ? 'unread-row' : ''}">
                      <td>
                        <strong>${escapeHtml(item.path || item.id || '-')}</strong>
                        ${item.outputHash ? `<div style="font-size: 10px; font-family: var(--font-mono); color: var(--text-muted);">Hash: ${escapeHtml(item.outputHash.substring(0, 16))}...</div>` : ''}
                      </td>
                      <td>
                        <span class="code-badge">${escapeHtml(targetLabel)}</span>
                      </td>
                      <td>
                        ${item.runId ? `
                          <a href="#" class="btn-inspect-artifact-run code-badge" data-runid="${escapeHtml(item.runId)}">${escapeHtml(item.runId.substring(0, 8))}</a>
                        ` : '-'}
                        ${item.workflowId ? `<div style="font-size: 11px; color: var(--text-secondary); margin-top: 2px;">${escapeHtml(item.workflowId)}</div>` : ''}
                      </td>
                      <td>
                        ${isUnread ? `
                          <span class="status-badge status-warning" data-i18n="workflows.unreadBadge">${escapeHtml(t('workflows.unreadBadge'))}</span>
                        ` : `
                          <span class="status-badge status-neutral" data-i18n="workflows.readBadge">${escapeHtml(t('workflows.readBadge'))}</span>
                        `}
                      </td>
                      <td>${item.createdAt ? formatTime(item.createdAt) : '-'}</td>
                      <td style="text-align: right;">
                        <button class="btn btn-secondary btn-xs btn-view-artifact" data-id="${escapeHtml(item.id)}" data-project="${escapeHtml(item.project || state.currentProject || '')}" data-i18n="workflows.btnViewArtifact">${escapeHtml(t('workflows.btnViewArtifact'))}</button>
                        ${isUnread ? `
                          <button class="btn btn-ghost btn-xs btn-mark-read-artifact" data-id="${escapeHtml(item.id)}" data-project="${escapeHtml(item.project || state.currentProject || '')}" data-i18n="workflows.btnMarkRead">${escapeHtml(t('workflows.btnMarkRead'))}</button>
                        ` : ''}
                      </td>
                    </tr>
                  `;
                }).join('')}
              </tbody>
            </table>
          </div>
        </div>
      `;

      target.querySelector('#btn-refresh-artifacts')?.addEventListener('click', () => {
        renderWorkflowsArtifactsTab(target);
      });

      target.querySelectorAll('.btn-inspect-artifact-run').forEach(a => {
        a.addEventListener('click', (e) => {
          e.preventDefault();
          const runId = a.getAttribute('data-runid');
          if (runId) openRunDetail(runId);
        });
      });

      target.querySelectorAll('.btn-view-artifact').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const p = btn.getAttribute('data-project') || state.currentProject;
          const matched = items.find(i => i.id === id) || { id, project: p };
          openArtifactDetailModal(matched, () => renderWorkflowsArtifactsTab(target));
        });
      });

      target.querySelectorAll('.btn-mark-read-artifact').forEach(btn => {
        btn.addEventListener('click', async () => {
          const id = btn.getAttribute('data-id');
          const p = btn.getAttribute('data-project') || state.currentProject;
          btn.disabled = true;
          try {
            await callBridge('outputs.markRead', { project: p, id });
            showToast({ key: 'common.success' });
            renderWorkflowsArtifactsTab(target);
          } catch (err) {
            showToast({ key: 'common.error', params: { error: err.message || String(err) } }, 'error');
            btn.disabled = false;
          }
        });
      });

    } catch (err) {
      target.innerHTML = `
        <div class="alert-banner alert-danger">
          ${escapeHtml(err.message || String(err))}
        </div>
      `;
    }
  }

  async function openArtifactDetailModal(item, onUpdated) {
    const proj = item.project || state.currentProject;
    openModal(t('workflows.artifactDetailTitle'), `
      <div style="padding: 20px 0; text-align: center; color: var(--text-muted);">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
        <span style="margin-left: 8px;">${escapeHtml(t('common.loading') || 'Loading...')}</span>
      </div>
    `, `<button class="btn btn-secondary" data-close-modal>${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;

    try {
      const data = await callBridge('outputs.get', { project: proj, id: item.id });
      if (currentModalInstance !== thisModalInstance) return;
      const full = data || item;
      const isUnread = full.unread === true;

      const bodyHtml = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px; margin-bottom: 12px; background: var(--bg-card); padding: 10px 12px; border: 1px solid var(--border-color); border-radius: var(--radius-sm);">
          <div><span class="text-secondary" data-i18n="workflows.artifactMetaId">${escapeHtml(t('workflows.artifactMetaId'))}</span> <code class="code-badge">${escapeHtml(full.id || '-')}</code></div>
          <div><span class="text-secondary" data-i18n="workflows.artifactMetaTarget">${escapeHtml(t('workflows.artifactMetaTarget'))}</span> <strong>${escapeHtml(full.target || '-')}</strong></div>
          ${full.path ? `<div style="grid-column: 1 / -1;"><span class="text-secondary" data-i18n="workflows.artifactMetaPath">${escapeHtml(t('workflows.artifactMetaPath'))}</span> <code class="code-badge">${escapeHtml(full.path)}</code></div>` : ''}
          ${full.runId ? `<div><span class="text-secondary" data-i18n="workflows.artifactMetaRun">${escapeHtml(t('workflows.artifactMetaRun'))}</span> <a href="#" id="modal-link-artifact-run" class="code-badge">${escapeHtml(full.runId.substring(0, 8))}</a></div>` : ''}
          <div><span class="text-secondary" data-i18n="workflows.artifactMetaTime">${escapeHtml(t('workflows.artifactMetaTime'))}</span> ${full.createdAt ? formatTime(full.createdAt) : '-'}</div>
          ${full.outputHash ? `<div style="grid-column: 1 / -1;"><span class="text-secondary">Hash:</span> <span class="font-mono" style="word-break: break-all;">${escapeHtml(full.outputHash)}</span></div>` : ''}
        </div>

        <div style="margin-bottom: 6px; font-size: 12px; font-weight: 600;" data-i18n="workflows.artifactContentLabel">${escapeHtml(t('workflows.artifactContentLabel'))}</div>
        <div class="artifact-output-box">${escapeHtml(typeof full.content === 'string' ? full.content : JSON.stringify(full.content || '', null, 2))}</div>
      `;

      let footerHtml = '';
      if (isUnread) {
        footerHtml = `
          <button id="btn-modal-mark-read" class="btn btn-primary" data-i18n="workflows.btnMarkRead">${escapeHtml(t('workflows.btnMarkRead'))}</button>
          <button id="btn-modal-close-artifact" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
        `;
      } else {
        footerHtml = `
          <button id="btn-modal-close-artifact" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
        `;
      }

      openModal(t('workflows.artifactDetailTitle'), bodyHtml, footerHtml);

      document.getElementById('btn-modal-close-artifact')?.addEventListener('click', closeModal);
      document.getElementById('modal-link-artifact-run')?.addEventListener('click', (e) => {
        e.preventDefault();
        closeModal();
        if (full.runId) openRunDetail(full.runId);
      });

      document.getElementById('btn-modal-mark-read')?.addEventListener('click', async () => {
        const btn = document.getElementById('btn-modal-mark-read');
        if (btn) btn.disabled = true;
        try {
          await callBridge('outputs.markRead', { project: proj, id: full.id });
          showToast({ key: 'common.success' });
          closeModal();
          if (typeof onUpdated === 'function') onUpdated();
        } catch (err) {
          showToast({ key: 'common.error', params: { error: err.message || String(err) } }, 'error');
          if (btn) btn.disabled = false;
        }
      });

    } catch (err) {
      openModal(t('workflows.artifactDetailTitle'), `
        <div class="alert-banner alert-danger">${escapeHtml(err.message || String(err))}</div>
      `, `<button class="btn btn-secondary" data-close-modal>${escapeHtml(t('common.close'))}</button>`);
    }
  }

  async function openWorkflowInspectModal(wfId, project = state.currentProject) {
    const currentProject = project;
    openModal({ key: 'workflows.inspectTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-wf-inspect" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-wf-inspect')?.addEventListener('click', closeModal);

    let wf = null;
    let watchInfo = null;
    try {
      wf = await callBridge('workflows.get', { project: currentProject, id: wfId });
      const isWatchTrigger = (wf && wf.definition && wf.definition.trigger === 'watch') || (wf && wf.trigger === 'watch');
      if (isWatchTrigger) {
        try {
          watchInfo = await callBridge('watches.get', { project: currentProject, id: wfId });
        } catch (we) {}
      }
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const snapshotHash = wf.snapshotHash || '';
    const assetHash = wf.assetHash || '';
    const markdown = wf.markdown || '';
    const valid = wf.valid === true;
    const isArchived = wf.state === 'archived';
    const isEnabled = (wf.definition && wf.definition.enabled) !== false && !isArchived;
    const diagnostics = Array.isArray(wf.diagnostics) ? wf.diagnostics : [];
    const isWatch = (wf.definition && wf.definition.trigger === 'watch') || wf.trigger === 'watch';

    setElementDescriptor(document.getElementById('modal-title'), (wf.definition && wf.definition.title) || t('workflows.inspectTitle'));
    b.innerHTML = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px;" data-i18n="workflows.inspectDesc">${escapeHtml(t('workflows.inspectDesc'))}</p>

      <div class="card" style="margin-bottom: 12px;">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
          <div>
            <strong data-i18n="workflows.validStatus">${escapeHtml(t('workflows.validStatus'))}</strong>
            ${valid ? `<span class="status-badge status-sage" data-i18n="workflows.validTrue">${escapeHtml(t('workflows.validTrue'))}</span>` : `<span class="status-badge status-amber" data-i18n="workflows.validFalse">${escapeHtml(t('workflows.validFalse'))}</span>`}
          </div>
          <div>
            <strong data-i18n="common.status">${escapeHtml(t('common.status'))}:</strong>
            ${isArchived ? `<span class="status-badge status-neutral" data-i18n="workflows.badgeArchived">${escapeHtml(t('workflows.badgeArchived'))}</span>` : (isEnabled ? `<span class="status-badge status-sage" data-i18n="workflows.btnEnable">${escapeHtml(t('workflows.btnEnable'))}</span>` : `<span class="status-badge status-neutral" data-i18n="workflows.btnDisable">${escapeHtml(t('workflows.btnDisable'))}</span>`)}
          </div>
        </div>
      </div>

      ${isWatch ? `
        <div class="card" style="margin-bottom: 12px; font-size: 12px; background: var(--bg-subtle);">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <strong data-i18n="watch.title">${escapeHtml(t('watch.title'))}</strong>
            <button type="button" class="btn btn-secondary btn-sm" id="btn-inspect-watch-preview" data-i18n="watch.btnPreview">${escapeHtml(t('watch.btnPreview'))}</button>
          </div>
          ${(() => {
            const watchDef = (watchInfo && watchInfo.definition) || (wf.definition && wf.definition.watch) || wf.watch || {};
            const isFiles = watchDef.source === 'files';
            if (isFiles) {
              const pathsStr = Array.isArray(watchDef.paths) ? watchDef.paths.join(', ') : (watchDef.paths || '-');
              const recursiveStr = watchDef.recursive ? t('watch.recursiveYes') : t('watch.recursiveNo');
              const ignoreStr = (Array.isArray(watchDef.ignore) && watchDef.ignore.length > 0) ? watchDef.ignore.join(', ') : t('watch.ignoreDefault');
              return `
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px;">
                  <div><span class="text-secondary" data-i18n="watch.source">${escapeHtml(t('watch.source'))}:</span> <span class="code-badge">files</span></div>
                  <div><span class="text-secondary" data-i18n="watch.recursive">${escapeHtml(t('watch.recursive'))}:</span> ${escapeHtml(recursiveStr)}</div>
                  <div style="grid-column: 1 / -1;"><span class="text-secondary" data-i18n="watch.paths">${escapeHtml(t('watch.paths'))}:</span> <span class="font-mono">${escapeHtml(pathsStr)}</span></div>
                  <div style="grid-column: 1 / -1;"><span class="text-secondary" data-i18n="watch.ignore">${escapeHtml(t('watch.ignore'))}:</span> <span class="font-mono text-secondary">${escapeHtml(ignoreStr)}</span></div>
                  <div><span class="text-secondary" data-i18n="watch.minItemsLabel">${escapeHtml(t('watch.minItemsLabel'))}</span> ${watchDef.minItems || 1}</div>
                  <div><span class="text-secondary" data-i18n="watch.debounceLabel">${escapeHtml(t('watch.debounceLabel'))}</span> ${(watchDef.debounceSeconds !== undefined ? watchDef.debounceSeconds : 5)}s</div>
                </div>
              `;
            } else {
              return `
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px;">
                  <div><span class="text-secondary" data-i18n="watch.toolLabel">${escapeHtml(t('watch.toolLabel'))}</span> <span class="code-badge">${escapeHtml(watchDef.tool || (watchInfo && watchInfo.definition && watchInfo.definition.tool) || (wf.definition && wf.definition.watch && wf.definition.watch.tool) || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="watch.modeLabel">${escapeHtml(t('watch.modeLabel'))}</span> ${escapeHtml(watchDef.mode || (watchInfo && watchInfo.definition && watchInfo.definition.mode) || (wf.definition && wf.definition.watch && wf.definition.watch.mode) || '-')}</div>
                  <div><span class="text-secondary" data-i18n="watch.everyLabel">${escapeHtml(t('watch.everyLabel'))}</span> ${(watchDef.everySeconds || (watchInfo && watchInfo.definition && watchInfo.definition.everySeconds) || 60)}s</div>
                  <div><span class="text-secondary" data-i18n="watch.debounceLabel">${escapeHtml(t('watch.debounceLabel'))}</span> ${(watchDef.debounceSeconds !== undefined ? watchDef.debounceSeconds : ((watchInfo && watchInfo.definition && watchInfo.definition.debounceSeconds) || 10))}s</div>
                </div>
              `;
            }
          })()}
          ${(watchInfo && watchInfo.state) ? `
            <div style="margin-top: 6px; font-size: 11px; padding: 4px 6px; background: var(--bg-main); border-radius: 4px; border: 1px solid var(--border-color);">
              <div style="display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 4px;">
                <div>
                  <span class="text-secondary" data-i18n="common.status">${escapeHtml(t('common.status'))}:</span>
                  <span class="status-badge status-sage">${escapeHtml(watchInfo.state.state || watchInfo.state.status || 'watching')}</span>
                  ${typeof watchInfo.state.sequence === 'number' ? `<span style="margin-left: 8px; font-size: 10px; font-family: var(--font-mono); color: var(--text-muted);">seq: ${watchInfo.state.sequence}</span>` : ''}
                  ${typeof watchInfo.state.fileEventSerial === 'number' ? `<span style="margin-left: 8px; font-size: 10px; font-family: var(--font-mono); color: var(--text-muted);">${escapeHtml(t('watch.fileEventSerial'))}: ${watchInfo.state.fileEventSerial}</span>` : ''}
                </div>
                ${watchInfo.state.receipt ? `
                  <div style="font-size: 10px; color: var(--text-secondary);">
                    ${typeof watchInfo.state.receipt.filesRead === 'number' ? `<span>${escapeHtml(t('watch.previewFilesRead'))} ${watchInfo.state.receipt.filesRead}</span>` : ''}
                    ${typeof watchInfo.state.receipt.bytesRead === 'number' ? `<span style="margin-left: 6px;">${escapeHtml(t('watch.previewBytesRead'))} ${formatByteSize(watchInfo.state.receipt.bytesRead)}</span>` : ''}
                  </div>
                ` : ''}
              </div>
              ${watchInfo.state.historyIncomplete === true ? `
                <div class="alert-banner alert-warning" style="margin-top: 6px; font-size: 11px; margin-bottom: 0;" data-i18n="watch.historyIncompleteNotice">
                  ${escapeHtml(t('watch.historyIncompleteNotice'))}
                </div>
              ` : ''}
            </div>
          ` : ''}
        </div>
      ` : ''}

      ${diagnostics.length > 0 ? `
        <div style="margin-bottom: 12px;">
          <h4 style="font-size: 12px; font-weight: 600; margin-bottom: 4px;" data-i18n="workflows.diagnostics">${escapeHtml(t('workflows.diagnostics'))}</h4>
          ${diagnostics.map(d => `
            <div class="alert-banner alert-warning" style="margin-bottom: 4px; font-size: 11px;">
              <strong>${escapeHtml(d.code || 'diagnostic')}:</strong> ${escapeHtml(d.message || '')}
            </div>
          `).join('')}
        </div>
      ` : ''}

      <section class="workflow-definition-preview">
        ${(wf.definition && wf.definition.description) ? `<p class="reading-prose">${escapeHtml(wf.definition.description)}</p>` : ''}
        <h4 data-i18n="workflows.stepsLabel">${escapeHtml(t('workflows.stepsLabel'))}</h4>
        <ol class="workflow-step-list">${((wf.definition && wf.definition.steps) || []).map((step,index) => `<li><div><strong>${escapeHtml(step.title || step.name || step.tool || String(index + 1))}</strong><span class="code-badge">${escapeHtml(step.tool || '')}</span></div><details class="technical-disclosure"><summary data-i18n="common.techDetails">${escapeHtml(t('common.techDetails'))}</summary>${VelaContent.code(JSON.stringify(step.arguments || step.params || {}, null, 2), 'json')}</details></li>`).join('')}</ol>
      </section>
      <details class="technical-disclosure"><summary data-i18n="workflows.markdownSource">${escapeHtml(t('workflows.markdownSource'))}</summary>${VelaContent.code(markdown)}</details>
      <details class="technical-disclosure"><summary data-i18n="common.techDetails">${escapeHtml(t('common.techDetails'))}</summary><div class="memory-identity"><span>${escapeHtml(t('workflows.snapshotHash'))}: ${escapeHtml(snapshotHash)}</span><span>${escapeHtml(t('workflows.assetHash'))}: ${escapeHtml(assetHash)}</span></div></details>
      <div id="wf-inspect-msg" class="alert-banner alert-warning hidden" style="margin-top: 10px;"></div>
    `;

    f.innerHTML = `
      <div style="display: flex; justify-content: space-between; width: 100%;">
        <div style="display: flex; gap: 8px;">
          ${!isArchived ? `<button class="btn btn-secondary" id="btn-inspect-toggle-enabled" data-i18n="${isEnabled ? 'workflows.btnDisable' : 'workflows.btnEnable'}">${escapeHtml(t(isEnabled ? 'workflows.btnDisable' : 'workflows.btnEnable'))}</button>` : `<button class="btn btn-primary" id="btn-inspect-restore" data-i18n="workflows.btnRestore">${escapeHtml(t('workflows.btnRestore'))}</button>`}
          ${actionMenu(`<button class="btn" id="btn-inspect-clone" data-i18n="workflows.btnClone">${escapeHtml(t('workflows.btnClone'))}</button>${!isArchived ? `<button class="btn" id="btn-inspect-archive" data-i18n="workflows.btnArchive">${escapeHtml(t('workflows.btnArchive'))}</button>` : ''}`)}

        </div>
        <button class="btn btn-secondary btn-sm" id="btn-close-wf-inspect-2" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      </div>
    `;

    document.getElementById('btn-close-wf-inspect-2')?.addEventListener('click', closeModal);
    document.getElementById('btn-inspect-watch-preview')?.addEventListener('click', () => {
      openWatchPreviewModal(wfId, currentProject, watchInfo && watchInfo.state);
    });

    const msgEl = document.getElementById('wf-inspect-msg');

    // Clone
    document.getElementById('btn-inspect-clone')?.addEventListener('click', async () => {
      const defTitle = (wf.definition && wf.definition.title) || 'Workflow';
      const newTitle = prompt(t('workflows.cloneTitlePrompt'), defTitle + ' copy');
      if (!newTitle) return;
      try {
        await callBridge('workflows.clone', {
          project: currentProject,
          id: wfId,
          snapshotHash,
          title: newTitle
        });
        showToast({ key: 'workflows.cloneSuccess' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        if (msgEl) { msgEl.textContent = err.message; msgEl.classList.remove('hidden'); }
      }
    });

    // Toggle Enabled
    document.getElementById('btn-inspect-toggle-enabled')?.addEventListener('click', async () => {
      try {
        await callBridge('workflows.setEnabled', {
          project: currentProject,
          id: wfId,
          snapshotHash,
          enabled: !isEnabled
        });
        showToast({ key: 'workflows.toggleSuccess' });
        openWorkflowInspectModal(wfId, currentProject);
        await refreshDashboard(false, false);
      } catch (err) {
        if (msgEl) { msgEl.textContent = err.message; msgEl.classList.remove('hidden'); }
      }
    });

    // Archive
    document.getElementById('btn-inspect-archive')?.addEventListener('click', async () => {
      if (!confirm(t('workflows.archiveConfirm'))) return;
      try {
        await callBridge('workflows.remove', {
          project: currentProject,
          id: wfId,
          snapshotHash
        });
        showToast({ key: 'workflows.archiveSuccess' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        if (msgEl) { msgEl.textContent = err.message; msgEl.classList.remove('hidden'); }
      }
    });

    // Restore
    document.getElementById('btn-inspect-restore')?.addEventListener('click', async () => {
      try {
        await callBridge('workflows.restore', {
          project: currentProject,
          id: wfId,
          snapshotHash
        });
        showToast({ key: 'workflows.restoreSuccess' });
        openWorkflowInspectModal(wfId, currentProject);
        await refreshDashboard(true, true);
      } catch (err) {
        if (msgEl) { msgEl.textContent = err.message; msgEl.classList.remove('hidden'); }
      }
    });
  }

  async function openWatchPreviewModal(wfId, project, existingWatchState = null) {
    const proj = project || state.currentProject;
    openModal({ key: 'watch.previewTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-watch-prev" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    const thisProject = proj;
    const thisGen = renderGeneration;
    document.getElementById('btn-close-watch-prev')?.addEventListener('click', closeModal);

    let res = null;
    let watchDetails = null;
    try {
      const [previewRes, getRes] = await Promise.all([
        callBridge('watches.preview', { id: wfId, project: proj }),
        callBridge('watches.get', { id: wfId, project: proj }).catch(() => null)
      ]);
      res = previewRes;
      watchDetails = getRes;
    } catch (e) {
      if (currentModalInstance !== thisModalInstance || state.currentProject !== thisProject || thisGen !== renderGeneration) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance || state.currentProject !== thisProject || thisGen !== renderGeneration) return;

    const b = document.getElementById('modal-body');
    if (!b) return;

    const baseline = res.wouldInitializeBaseline === true;
    const entries = (res.snapshot && res.snapshot.entries) ? Object.keys(res.snapshot.entries).length : 0;
    const pending = res.pending || {};
    const pendingKeys = Object.keys(pending);
    const meetsMin = res.wouldMeetMinimum === true;
    const isFileSnapshot = res.snapshot && (res.snapshot.source === 'files' || typeof res.snapshot.filesRead === 'number');
    const changesList = Array.isArray(res.changes) ? res.changes : pendingKeys.map(k => pending[k] || { key: k });
    const fetchedState = (watchDetails && watchDetails.state) || null;
    const isHistoryIncomplete = (existingWatchState && existingWatchState.historyIncomplete === true) ||
                                (fetchedState && fetchedState.historyIncomplete === true) ||
                                res.historyIncomplete === true;

    b.innerHTML = `
      <div class="alert-banner alert-info" style="font-size: 11px; margin-bottom: 12px;" data-i18n="watch.previewDesc">
        ${escapeHtml(t('watch.previewDesc'))}
      </div>

      ${isHistoryIncomplete ? `
        <div class="alert-banner alert-warning" style="font-size: 11px; margin-bottom: 12px;" data-i18n="watch.historyIncompleteNotice">
          ${escapeHtml(t('watch.historyIncompleteNotice'))}
        </div>
      ` : ''}

      <div class="card" style="margin-bottom: 12px; font-size: 12px;">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
          <div>
            <span class="text-secondary" data-i18n="watch.previewBaselineStatus">${escapeHtml(t('watch.previewBaselineStatus'))}</span>
            <div style="font-weight: 500; margin-top: 2px;">
              ${baseline
                ? `<span class="status-badge status-amber" data-i18n="watch.previewBaselineTrue">${escapeHtml(t('watch.previewBaselineTrue'))}</span>`
                : `<span class="status-badge status-sage" data-i18n="watch.previewBaselineFalse">${escapeHtml(t('watch.previewBaselineFalse'))}</span>`}
            </div>
          </div>
          <div>
            <span class="text-secondary" data-i18n="watch.previewEntriesCount">${escapeHtml(t('watch.previewEntriesCount'))}</span>
            <div style="font-weight: 500; margin-top: 2px;">${entries}</div>
          </div>
          <div>
            <span class="text-secondary" data-i18n="watch.previewPendingCount">${escapeHtml(t('watch.previewPendingCount'))}</span>
            <div style="font-weight: 500; margin-top: 2px;">${changesList.length}</div>
          </div>
          <div>
            <span class="text-secondary" data-i18n="watch.previewMeetsMin">${escapeHtml(t('watch.previewMeetsMin'))}</span>
            <div style="font-weight: 500; margin-top: 2px;">
              ${meetsMin
                ? `<span class="status-badge status-sage" data-i18n="watch.previewYes">${escapeHtml(t('watch.previewYes'))}</span>`
                : `<span class="status-badge status-neutral" data-i18n="watch.previewNo">${escapeHtml(t('watch.previewNo'))}</span>`}
            </div>
          </div>
          ${isFileSnapshot ? `
            <div>
              <span class="text-secondary" data-i18n="watch.previewFilesRead">${escapeHtml(t('watch.previewFilesRead'))}</span>
              <div style="font-weight: 500; margin-top: 2px;">${res.snapshot.filesRead || 0} (${res.snapshot.directoriesRead || 0} 目录)</div>
            </div>
            <div>
              <span class="text-secondary" data-i18n="watch.previewBytesRead">${escapeHtml(t('watch.previewBytesRead'))}</span>
              <div style="font-weight: 500; margin-top: 2px;">${formatByteSize(res.snapshot.bytesRead || 0)}</div>
            </div>
          ` : ''}
        </div>
      </div>

      <h4 style="font-size: 12px; font-weight: 600; margin-bottom: 6px;" data-i18n="watch.pendingChangesTitle">
        ${escapeHtml(t('watch.pendingChangesTitle'))}
      </h4>

      ${changesList.length === 0 ? `
        <div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px; border: 1px dashed var(--border-color); border-radius: 4px;" data-i18n="watch.noPendingChanges">
          ${escapeHtml(t('watch.noPendingChanges'))}
        </div>
      ` : `
        <div class="table-wrapper" style="max-height: 200px; overflow-y: auto;">
          <table class="data-table" style="font-size: 11px;">
            <thead>
              <tr>
                <th data-i18n="watch.changeType">${escapeHtml(t('watch.changeType'))}</th>
                <th data-i18n="watch.changeKey">${escapeHtml(t('watch.changeKey'))}</th>
                <th data-i18n="watch.changeBefore">${escapeHtml(t('watch.changeBefore'))}</th>
                <th data-i18n="watch.changeAfter">${escapeHtml(t('watch.changeAfter'))}</th>
              </tr>
            </thead>
            <tbody>
              ${changesList.map(item => {
                const type = item.type || 'modified';
                let badgeClass = 'status-sage';
                if (type === 'removed') badgeClass = 'status-red';
                else if (type === 'modified') badgeClass = 'status-amber';
                else if (type === 'renamed') badgeClass = 'status-blue';

                const displayKey = (type === 'renamed' && item.previousKey)
                  ? `${item.previousKey} → ${item.key}`
                  : (item.key || '');

                const renderEntrySummary = (entry) => {
                  if (!entry) return '-';
                  const val = entry.value || entry;
                  if (typeof val === 'object' && val !== null) {
                    if (val.path || val.kind || val.contentHash) {
                      const kind = val.kind || 'file';
                      const bytesStr = typeof val.bytes === 'number' ? formatByteSize(val.bytes) : '';
                      const hashStr = val.contentHash ? `sha: ${val.contentHash.slice(0, 8)}` : '';
                      return `[${kind}] ${bytesStr} ${hashStr}`.trim();
                    }
                    return JSON.stringify(val);
                  }
                  return String(val);
                };

                return `
                  <tr>
                    <td><span class="status-badge ${badgeClass}">${escapeHtml(type)}</span></td>
                    <td class="font-mono">${escapeHtml(displayKey)}</td>
                    <td class="font-mono text-secondary" style="max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                      ${escapeHtml(renderEntrySummary(item.before))}
                    </td>
                    <td class="font-mono" style="max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                      ${escapeHtml(renderEntrySummary(item.after))}
                    </td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      `}
    `;
  }

  async function openWorkflowsValidationModal(cursor = null) {
    const currentProject = state.currentProject;
    openModal({ key: 'workflows.validateTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-wf-validate" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-wf-validate')?.addEventListener('click', closeModal);

    let val = null;
    try {
      const params = { project: currentProject, limit: 100 };
      if (cursor) params.cursor = cursor;
      val = await callBridge('workflows.validate', params);
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const results = Array.isArray(val.results) ? val.results : [];
    const checked = val.checked || results.length;
    const nextCursor = val.cursor;

    b.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;">
        <span class="text-secondary" style="font-size: 12px;" data-i18n="workflows.validateDesc">${escapeHtml(t('workflows.validateDesc'))}</span>
        <span class="status-badge status-neutral" data-i18n="workflows.validateChecked" data-i18n-params="${escapeHtml(JSON.stringify({ count: checked }))}">${escapeHtml(t('workflows.validateChecked', { count: checked }))}</span>
      </div>

      <div class="table-wrapper" style="max-height: 360px; overflow-y: auto;">
        <table class="data-table">
          <thead>
            <tr>
              <th>ID</th>
              <th data-i18n="workflows.validStatus">${escapeHtml(t('workflows.validStatus'))}</th>
              <th data-i18n="workflows.snapshotHash">${escapeHtml(t('workflows.snapshotHash'))}</th>
              <th data-i18n="workflows.diagnostics">${escapeHtml(t('workflows.diagnostics'))}</th>
            </tr>
          </thead>
          <tbody>
            ${results.map(r => `
              <tr>
                <td><strong>${escapeHtml(r.id)}</strong></td>
                <td>
                  ${r.valid ? `<span class="status-badge status-sage" data-i18n="workflows.validTrue">${escapeHtml(t('workflows.validTrue'))}</span>` : `<span class="status-badge status-amber" data-i18n="workflows.validFalse">${escapeHtml(t('workflows.validFalse'))}</span>`}
                </td>
                <td><span class="font-mono" style="font-size: 11px;">${r.snapshotHash ? escapeHtml(r.snapshotHash.substring(0, 10)) : '-'}</span></td>
                <td>
                  ${(r.diagnostics && r.diagnostics.length > 0) ? r.diagnostics.map(d => `<div style="font-size: 11px; color: var(--text-warning);">${escapeHtml(d.code || '')}: ${escapeHtml(d.message || '')}</div>`).join('') : '<span class="text-muted" style="font-size: 11px;">-</span>'}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    f.innerHTML = `
      <div style="display: flex; justify-content: space-between; width: 100%;">
        ${nextCursor ? `<button class="btn btn-secondary btn-sm" id="btn-wf-validate-next" data-i18n="workflows.loadNextPage">${escapeHtml(t('workflows.loadNextPage'))}</button>` : '<div></div>'}
        <button class="btn btn-secondary btn-sm" id="btn-close-wf-validate-2" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      </div>
    `;

    document.getElementById('btn-close-wf-validate-2')?.addEventListener('click', closeModal);
    document.getElementById('btn-wf-validate-next')?.addEventListener('click', () => {
      openWorkflowsValidationModal(nextCursor);
    });
  }

  function openWorkflowPlannerModal(params = {}) {
    const isFollowup = Boolean(params.previousPlanId && params.previousPlanHash);
    const prevQuestions = Array.isArray(params.questions) ? params.questions : [];

    const modalBody = `
      <div class="alert-banner alert-info" style="margin-bottom: 14px; font-size: 12px;" data-i18n="workflows.planModalDesc">
        ${escapeHtml(t('workflows.planModalDesc'))}
      </div>

      ${isFollowup && prevQuestions.length > 0 ? `
        <div class="plan-questions-card">
          <strong data-i18n="workflows.planQuestionsTitle">${escapeHtml(t('workflows.planQuestionsTitle'))}</strong>
          <ul style="margin: 6px 0 0 16px; padding: 0;">
            ${prevQuestions.map(q => `<li>${escapeHtml(q)}</li>`).join('')}
          </ul>
        </div>
      ` : ''}

      <div class="form-group">
        <label class="form-label" data-i18n="workflows.planDescLabel">${escapeHtml(t('workflows.planDescLabel'))} *</label>
        <textarea id="plan-workflow-description" class="form-textarea" rows="4" placeholder="${escapeHtml(t('workflows.planDescPlaceholder'))}" data-i18n-placeholder="workflows.planDescPlaceholder" style="font-size: 13px;">${escapeHtml(params.description || '')}</textarea>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">最多 8,000 UTF-8 字节。清晰描述任务、触发条件与预期产物。</div>
      </div>

      ${isFollowup ? `
        <div class="form-group">
          <label class="form-label" data-i18n="workflows.btnClarifyPlan">${escapeHtml(t('workflows.btnClarifyPlan'))} (Answers)</label>
          <textarea id="plan-workflow-answers" class="form-textarea" rows="3" placeholder="针对上述问题的逐条补充说明（每条非空，最多 8 条）..." style="font-size: 13px;"></textarea>
        </div>
      ` : ''}

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="workflows.planCodexCliLabel">${escapeHtml(t('workflows.planCodexCliLabel'))} *</label>
          <input type="text" id="plan-workflow-executable" class="form-input" style="font-family: var(--font-mono); font-size: 12px;" value="${escapeHtml(state.codexCliPath || '/opt/homebrew/bin/codex')}" placeholder="/opt/homebrew/bin/codex">
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="workflows.planModelLabel">${escapeHtml(t('workflows.planModelLabel'))} *</label>
          <input type="text" id="plan-workflow-model" class="form-input" style="font-family: var(--font-mono); font-size: 12px;" value="gpt-4o" placeholder="gpt-4o 或 o3-mini">
        </div>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="workflows.planEffortLabel">${escapeHtml(t('workflows.planEffortLabel'))}</label>
          <select id="plan-workflow-effort" class="form-select">
            <option value="low">low</option>
            <option value="medium">medium</option>
            <option value="high" selected>high</option>
            <option value="xhigh">xhigh</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="workflows.planTimeoutLabel">${escapeHtml(t('workflows.planTimeoutLabel'))}</label>
          <input type="number" id="plan-workflow-timeout" class="form-input" value="120" min="1" max="300">
        </div>
      </div>
    `;

    const modalFooter = `
      <button id="btn-cancel-plan-modal" class="btn btn-secondary" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button id="btn-submit-plan-modal" class="btn btn-primary" data-i18n="workflows.btnSubmitPlan">${escapeHtml(t('workflows.btnSubmitPlan'))}</button>
    `;

    openModal(t('workflows.planModalTitle'), modalBody, modalFooter);

    document.getElementById('btn-cancel-plan-modal')?.addEventListener('click', closeModal);

    document.getElementById('btn-submit-plan-modal')?.addEventListener('click', async () => {
      const desc = (document.getElementById('plan-workflow-description')?.value || '').trim();
      const executable = (document.getElementById('plan-workflow-executable')?.value || '').trim();
      const model = (document.getElementById('plan-workflow-model')?.value || '').trim();
      const effort = document.getElementById('plan-workflow-effort')?.value || 'high';
      const timeoutSeconds = parseInt(document.getElementById('plan-workflow-timeout')?.value || '120', 10);

      if (!desc) {
        showToast('请输入工作流描述', 'warning');
        return;
      }
      if (!executable || !executable.startsWith('/')) {
        showToast('请输入有效的 Codex 可执行文件绝对路径', 'warning');
        return;
      }
      if (!model) {
        showToast('请输入模型名称', 'warning');
        return;
      }

      const payload = {
        project: state.currentProject,
        description: desc,
        executable,
        model,
        effort,
        timeoutSeconds: Math.max(1, Math.min(300, timeoutSeconds)),
        answers: []
      };

      if (isFollowup) {
        payload.previousPlanId = params.previousPlanId;
        payload.previousPlanHash = params.previousPlanHash;
        const answersRaw = (document.getElementById('plan-workflow-answers')?.value || '').trim();
        if (answersRaw) {
          payload.answers = answersRaw.split('\n').map(s => s.trim()).filter(Boolean);
        }
      }

      const submitBtn = document.getElementById('btn-submit-plan-modal');
      if (submitBtn) submitBtn.disabled = true;

      try {
        const res = await callBridge('workflows.plan', payload);
        closeModal();
        showToast({ key: 'workflows.planCreatedToast' });
        state.workflowsActiveTab = 'plans';
        renderWorkflowsTabContent();
        if (res && res.id) {
          openPlanDetailModal(res.id);
        }
      } catch (err) {
        showToast({ key: 'common.error', params: { error: err.message || String(err) } }, 'error');
        if (submitBtn) submitBtn.disabled = false;
      }
    });
  }

  async function renderWorkflowsPlansTab(target) {
    target.innerHTML = `
      <div class="empty-state" style="padding: 40px 0;">
        <div class="empty-state-icon">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
        </div>
        <div class="empty-state-title" data-i18n="common.loading">${escapeHtml(t('common.loading') || 'Loading...')}</div>
      </div>
    `;

    try {
      const plans = await callBridge('workflows.plan.list', state.currentProject ? { project: state.currentProject } : {});
      const list = Array.isArray(plans) ? plans : [];
      state.workflowPlansCount = list.length;

      function getPlanStateBadge(st) {
        switch (st) {
          case 'pending_approval':
            return `<span class="status-badge status-amber" data-i18n="workflows.planStatePending">${escapeHtml(t('workflows.planStatePending'))}</span>`;
          case 'executing_or_uncertain':
            return `<span class="status-badge status-warning" data-i18n="workflows.planStateExecuting">${escapeHtml(t('workflows.planStateExecuting'))}</span>`;
          case 'draft':
            return `<span class="status-badge status-sage" data-i18n="workflows.planStateDraft">${escapeHtml(t('workflows.planStateDraft'))}</span>`;
          case 'needs_clarification':
            return `<span class="status-badge status-amber" data-i18n="workflows.planStateNeedsClarification">${escapeHtml(t('workflows.planStateNeedsClarification'))}</span>`;
          case 'rejected':
            return `<span class="status-badge status-neutral" data-i18n="workflows.planStateRejected">${escapeHtml(t('workflows.planStateRejected'))}</span>`;
          case 'failed':
            return `<span class="status-badge status-danger" data-i18n="workflows.planStateFailed">${escapeHtml(t('workflows.planStateFailed'))}</span>`;
          default:
            return `<span class="status-badge status-neutral">${escapeHtml(st || '-')}</span>`;
        }
      }

      target.innerHTML = `
        <div class="card">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.plansListTitle">${escapeHtml(t('workflows.plansListTitle'))}</span>
            <button id="btn-refresh-plans" class="btn btn-ghost btn-sm" data-i18n="workflows.btnRefreshHealth">${escapeHtml(t('workflows.btnRefreshHealth'))}</button>
          </div>
          ${list.length === 0 ? `
            <div style="padding: 32px 16px; text-align: center; color: var(--text-muted); font-size: 13px;">
              暂无规划方案。可点击右上角“从描述规划工作流...”创建。
            </div>
          ` : `
            <div class="table-wrapper" style="margin-bottom: 0;">
              <table class="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th data-i18n="workflows.colStatus">${escapeHtml(t('workflows.colStatus'))}</th>
                    <th>待澄清/未解决</th>
                    <th>Approval</th>
                    <th style="text-align: right;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
                  </tr>
                </thead>
                <tbody>
                  ${list.map(p => {
                    const qCount = (p.questions || []).length;
                    const uCount = (p.unresolved || []).length;
                    const notes = [];
                    if (qCount > 0) notes.push(`${qCount} 个问题`);
                    if (uCount > 0) notes.push(`${uCount} 项待办`);
                    const notesText = notes.length > 0 ? notes.join(', ') : '—';

                    return `
                      <tr>
                        <td>
                          <span class="code-badge font-mono">${escapeHtml(p.id ? p.id.substring(0, 12) : '-')}</span>
                          ${p.planHash ? `<div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">hash: ${escapeHtml(p.planHash.substring(0, 8))}</div>` : ''}
                        </td>
                        <td>${getPlanStateBadge(p.state)}</td>
                        <td style="font-size: 11px;">${escapeHtml(notesText)}</td>
                        <td style="font-size: 11px;"><span class="font-mono">${escapeHtml(p.approvalId ? p.approvalId.substring(0, 10) : '—')}</span></td>
                        <td style="text-align: right;">
                          <button class="btn btn-secondary btn-xs btn-view-plan-detail" data-id="${escapeHtml(p.id)}">详情 / 审阅</button>
                        </td>
                      </tr>
                    `;
                  }).join('')}
                </tbody>
              </table>
            </div>
          `}
        </div>
      `;

      target.querySelector('#btn-refresh-plans')?.addEventListener('click', () => {
        renderWorkflowsPlansTab(target);
      });

      target.querySelectorAll('.btn-view-plan-detail').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          if (id) openPlanDetailModal(id);
        });
      });

    } catch (err) {
      target.innerHTML = `
        <div class="alert-banner alert-danger">
          ${escapeHtml(err.message || String(err))}
        </div>
      `;
    }
  }

  async function openPlanDetailModal(planId) {
    openModal(t('workflows.planDetailTitle'), `
      <div style="padding: 24px; text-align: center; color: var(--text-muted);">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin" style="margin-bottom: 8px;"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
        <div>${escapeHtml(t('common.loading') || 'Loading...')}</div>
      </div>
    `, '');

    const thisModalInstance = currentModalInstance;

    try {
      const plan = await callBridge('workflows.plan.get', { project: state.currentProject, id: planId });
      if (currentModalInstance !== thisModalInstance) return;
      if (!plan) throw new Error('Plan not found');

      const req = plan.request || {};
      const isPending = plan.state === 'pending_approval';
      const isNeedsClarification = plan.state === 'needs_clarification';
      const hasDraft = plan.state === 'draft' && Boolean(plan.draft);
      const questions = Array.isArray(plan.questions) ? plan.questions : [];
      const unresolved = Array.isArray(plan.unresolved) ? plan.unresolved : [];

      function getPlanBadge(st) {
        switch (st) {
          case 'pending_approval':
            return `<span class="status-badge status-amber" data-i18n="workflows.planStatePending">${escapeHtml(t('workflows.planStatePending'))}</span>`;
          case 'executing_or_uncertain':
            return `<span class="status-badge status-warning" data-i18n="workflows.planStateExecuting">${escapeHtml(t('workflows.planStateExecuting'))}</span>`;
          case 'draft':
            return `<span class="status-badge status-sage" data-i18n="workflows.planStateDraft">${escapeHtml(t('workflows.planStateDraft'))}</span>`;
          case 'needs_clarification':
            return `<span class="status-badge status-amber" data-i18n="workflows.planStateNeedsClarification">${escapeHtml(t('workflows.planStateNeedsClarification'))}</span>`;
          case 'rejected':
            return `<span class="status-badge status-neutral" data-i18n="workflows.planStateRejected">${escapeHtml(t('workflows.planStateRejected'))}</span>`;
          case 'failed':
            return `<span class="status-badge status-danger" data-i18n="workflows.planStateFailed">${escapeHtml(t('workflows.planStateFailed'))}</span>`;
          default:
            return `<span class="status-badge status-neutral">${escapeHtml(st || '-')}</span>`;
        }
      }

      const bodyHtml = `
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid var(--border-color);">
          <div>
            <strong>${escapeHtml(plan.id)}</strong>
            <div style="font-size: 11px; color: var(--text-muted); font-family: var(--font-mono);">hash: ${escapeHtml(plan.planHash || '-')}</div>
          </div>
          <div>
            ${getPlanBadge(plan.state)}
          </div>
        </div>

        <div style="font-size: 12px; margin-bottom: 12px; background: var(--bg-subtle); border-radius: var(--radius-sm); padding: 10px;">
          <div style="font-weight: 500; margin-bottom: 4px;" data-i18n="workflows.planDescLabel">${escapeHtml(t('workflows.planDescLabel'))}:</div>
          <div style="white-space: pre-wrap; color: var(--text-main); font-size: 12px;">${escapeHtml(req.description || '—')}</div>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px; color: var(--text-secondary); margin-top: 8px; padding-top: 6px; border-top: 1px dashed var(--border-color);">
            <div><span data-i18n="ask.colModel">${escapeHtml(t('ask.colModel'))}:</span> <span class="font-mono">${escapeHtml(req.model || '—')}</span> (${escapeHtml(req.effort || 'high')})</div>
            <div><span data-i18n="ask.colExecutable">${escapeHtml(t('ask.colExecutable'))}:</span> <span class="font-mono">${escapeHtml(req.executable || '—')}</span></div>
            <div>Approval ID: <span class="font-mono">${escapeHtml(plan.approvalId || '—')}</span></div>
            <div>Run ID: <span class="font-mono">${escapeHtml(plan.runId || '—')}</span></div>
          </div>
        </div>

        ${questions.length > 0 ? `
          <div class="plan-questions-card">
            <strong data-i18n="workflows.planQuestionsTitle">${escapeHtml(t('workflows.planQuestionsTitle'))}</strong>
            <ul style="margin: 6px 0 0 16px; padding: 0;">
              ${questions.map(q => `<li>${escapeHtml(q)}</li>`).join('')}
            </ul>
          </div>
        ` : ''}

        ${unresolved.length > 0 ? `
          <div style="background: var(--bg-subtle); border: 1px solid var(--border-color); border-radius: var(--radius-sm); padding: 10px 12px; font-size: 12px; margin: 10px 0;">
            <strong data-i18n="workflows.planUnresolvedTitle">${escapeHtml(t('workflows.planUnresolvedTitle'))}</strong>
            <ul style="margin: 6px 0 0 16px; padding: 0;">
              ${unresolved.map(u => `<li>${escapeHtml(u)}</li>`).join('')}
            </ul>
          </div>
        ` : ''}

        ${hasDraft ? `
          <div style="margin-top: 12px;">
            <div style="font-size: 12px; font-weight: 600; margin-bottom: 4px;" data-i18n="workflows.planDraftReviewTitle">${escapeHtml(t('workflows.planDraftReviewTitle'))}:</div>
            <div class="plan-draft-preview">${escapeHtml(JSON.stringify(plan.draft, null, 2))}</div>
          </div>
        ` : ''}

        ${plan.error ? `
          <div class="alert-banner alert-danger" style="margin-top: 12px; font-size: 12px;">
            ${escapeHtml(plan.error)}
          </div>
        ` : ''}
      `;

      let footerActions = `<button id="btn-close-plan-detail" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`;
      if (isPending) {
        footerActions = `
          <button id="btn-cancel-pending-plan" class="btn btn-ghost" style="color: var(--status-red-text);" data-i18n="workflows.btnCancelPlan">${escapeHtml(t('workflows.btnCancelPlan'))}</button>
          <button id="btn-go-inbox-plan" class="btn btn-primary" data-i18n="workflows.btnGoToInbox">${escapeHtml(t('workflows.btnGoToInbox'))}</button>
          <button id="btn-close-plan-detail" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
        `;
      } else if (isNeedsClarification) {
        footerActions = `
          <button id="btn-clarify-plan-modal" class="btn btn-primary" data-i18n="workflows.btnClarifyPlan">${escapeHtml(t('workflows.btnClarifyPlan'))}</button>
          <button id="btn-close-plan-detail" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
        `;
      } else if (hasDraft) {
        footerActions = `
          <button id="btn-accept-plan-draft" class="btn btn-primary" data-i18n="workflows.btnAcceptDraft">${escapeHtml(t('workflows.btnAcceptDraft'))}</button>
          <button id="btn-close-plan-detail" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
        `;
      }

      openModal(t('workflows.planDetailTitle'), bodyHtml, footerActions);

      document.getElementById('btn-close-plan-detail')?.addEventListener('click', closeModal);

      document.getElementById('btn-go-inbox-plan')?.addEventListener('click', () => {
        closeModal();
        state.currentPage = 'inbox';
        navigateTo('inbox');
      });

      document.getElementById('btn-cancel-pending-plan')?.addEventListener('click', async () => {
        try {
          await callBridge('workflows.plan.cancel', { project: state.currentProject, id: plan.id, planHash: plan.planHash });
          showToast({ key: 'workflows.planCancelledToast' });
          closeModal();
          renderWorkflowsTabContent();
        } catch (err) {
          showToast({ key: 'workflows.planCancelFailedToast', params: { error: err.message } }, 'error');
        }
      });

      document.getElementById('btn-clarify-plan-modal')?.addEventListener('click', () => {
        closeModal();
        openWorkflowPlannerModal({
          previousPlanId: plan.id,
          previousPlanHash: plan.planHash,
          description: req.description,
          questions: plan.questions
        });
      });

      document.getElementById('btn-accept-plan-draft')?.addEventListener('click', async () => {
        const btn = document.getElementById('btn-accept-plan-draft');
        if (btn) btn.disabled = true;
        try {
          await callBridge('workflows.save', plan.draft);
          showToast({ key: 'workflows.draftAcceptedToast' });
          closeModal();
          await refreshDashboard(true, true);
        } catch (err) {
          showToast({ key: 'common.error', params: { error: err.message } }, 'error');
          if (btn) btn.disabled = false;
        }
      });

    } catch (err) {
      openModal(t('workflows.planDetailTitle'), `
        <div class="alert-banner alert-danger">${escapeHtml(err.message || String(err))}</div>
      `, `<button class="btn btn-secondary" data-close-modal>${escapeHtml(t('common.close'))}</button>`);
    }
  }

  let activeHealthProposalModalInstance = null;
  let activeHealthProposalCleanup = null;
  let healthProposalGen = 0;
  let healthProposalSession = null;
  let healthLoadGen = 0;

  function dismissActiveHealthProposalModal() {
    healthProposalGen++;
    healthProposalSession = null;
    if (!activeHealthProposalModalInstance) return;
    const targetInstance = activeHealthProposalModalInstance;
    activeHealthProposalModalInstance = null;

    if (currentModalInstance === targetInstance) {
      const modal = document.getElementById('modal-container');
      const proposalEl = modal && modal.querySelector('#health-timeout-proposal-preview, #health-timeout-proposal-review');
      if (modal && !modal.classList.contains('hidden') && proposalEl) {
        closeModal();
      }
    }

    const cleanup = activeHealthProposalCleanup;
    activeHealthProposalCleanup = null;
    if (typeof cleanup === 'function') {
      try {
        cleanup();
      } catch {}
    }
  }

  function isHealthComplete(h) {
    if (!h) return false;
    if (h.aggregateIncomplete === true) return false;
    if (h.coverage !== 'complete_within_selected_store_scope') return false;
    return true;
  }

  function isSourceScanCapReached(h, finding) {
    if (finding && finding.capReached) return true;
    if (finding && finding.sourceScan && finding.sourceScan.capReached) return true;
    if (!h) return false;
    if (h.capReached) return true;
    const scan = h.sourceScan;
    if (scan) {
      if (scan.capReached) return true;
      if (Array.isArray(scan)) {
        if (scan.some(s => s && s.capReached)) return true;
      } else if (typeof scan === 'object') {
        if (Object.values(scan).some(s => s && (s.capReached || (typeof s === 'object' && s.capReached)))) return true;
      }
    }
    return false;
  }

  function isHealthFindingEligible(finding, h) {
    if (!finding) return false;
    if (!isHealthComplete(h)) return false;
    if (isSourceScanCapReached(h, finding)) return false;
    if (finding.code !== 'timeout_observed') return false;
    const stateVal = String(finding.state || finding.stepState || '').toLowerCase();
    if (stateVal !== 'failed' && stateVal !== 'needs_review') return false;
    const eligibleTools = ['shell.test', 'shell.typecheck', 'agent.run'];
    if (!finding.tool || !eligibleTools.includes(finding.tool)) return false;
    return true;
  }

  async function loadHealthData() {
    const thisLoadGen = ++healthLoadGen;
    const thisTabGen = workflowTabGen;
    const thisProject = state.currentProject;

    const elFindings = document.getElementById('workflow-health-findings');
    const elProposalsSection = document.getElementById('workflow-health-proposals-section');
    const elProposalsList = document.getElementById('workflow-health-proposals-list');
    const elProposalsIncomplete = document.getElementById('health-proposals-incomplete-badge');

    try {
      // Item 7: AllProjects 不要发 proposal.list {}，显示需选项目
      const [h, propListData] = await Promise.all([
        callBridge('workflows.health', thisProject ? { project: thisProject } : {}),
        thisProject ? callBridge('workflows.health.proposal.list', { project: thisProject }).catch(() => null) : Promise.resolve(null)
      ]);

      if (thisLoadGen !== healthLoadGen || thisTabGen !== workflowTabGen || state.currentProject !== thisProject || state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'health') {
        return;
      }

      if (h) {
        const elRuns = document.getElementById('health-total-runs');
        const elDetail = document.getElementById('health-success-detail');
        const elRate = document.getElementById('health-success-rate');
        const elRej = document.getElementById('health-approval-rejected');
        const elDur = document.getElementById('health-avg-duration');
        const elTok = document.getElementById('health-tokens-stat');

        if (elRuns) {
          if (h.runs !== undefined && h.runs !== null) {
            setElementDescriptor(elRuns, formatNumber(h.runs));
          } else {
            setElementDescriptor(elRuns, { key: 'common.none' });
          }
        }
        if (elDetail) {
          if (h.successes !== undefined && h.failures !== undefined) {
            setElementDescriptor(elDetail, { key: 'workflows.statSuccessDetail', params: { successes: h.successes, failures: h.failures } });
          } else {
            setElementDescriptor(elDetail, '');
          }
        }
        if (elRate) {
          if (h.successRate !== null && h.successRate !== undefined) {
            setElementDescriptor(elRate, (h.successRate * 100).toFixed(1) + '%');
          } else {
            setElementDescriptor(elRate, { key: 'common.none' });
          }
        }
        if (elRej) {
          if (h.approvalRejected !== undefined) {
            setElementDescriptor(elRej, { key: 'workflows.statApprovalRejected', params: { count: h.approvalRejected } });
          } else {
            setElementDescriptor(elRej, '');
          }
        }
        if (elDur) {
          if (h.averageDurationMs !== null && h.averageDurationMs !== undefined) {
            setElementDescriptor(elDur, Math.round(h.averageDurationMs) + 'ms');
          } else {
            setElementDescriptor(elDur, { key: 'common.none' });
          }
        }
        if (elTok) {
          if (h.tokensAvailable && h.tokens !== null) {
            setElementDescriptor(elTok, { key: 'workflows.statTokens', params: { tokens: formatNumber(h.tokens) } });
          } else {
            setElementDescriptor(elTok, { key: 'workflows.statTokensUnavailable' });
          }
        }

        // Render health findings
        if (elFindings) {
          const findings = Array.isArray(h.findings) ? h.findings : [];
          if (findings.length === 0) {
            elFindings.innerHTML = `
              <div class="empty-state" style="padding: 24px 0;">
                <div class="empty-state-title" data-i18n="workflows.healthFindingsEmpty">${escapeHtml(t('workflows.healthFindingsEmpty'))}</div>
              </div>
            `;
          } else {
            let rowsHtml = '';
            findings.forEach(finding => {
              const eligible = isHealthFindingEligible(finding, h);
              const fid = String(finding.id || '');
              const rid = String(finding.runId || '');
              const code = String(finding.code || 'finding');
              const stepId = String(finding.stepId || '');
              const tool = String(finding.tool || '');
              const version = finding.workflowVersion;

              rowsHtml += `
                <div class="health-finding-row ${eligible ? 'eligible' : 'ineligible'}" data-finding-id="${escapeHtml(fid)}" data-run-id="${escapeHtml(rid)}">
                  <div class="finding-info">
                    <div class="finding-header">
                      <span class="finding-code">${escapeHtml(code)}</span>
                      ${eligible ? `<span class="badge badge-subtle" data-i18n="workflows.healthFindingEligible">${escapeHtml(t('workflows.healthFindingEligible'))}</span>` : `<span class="badge badge-subtle" data-i18n="workflows.healthFindingIneligible">${escapeHtml(t('workflows.healthFindingIneligible'))}</span>`}
                    </div>
                    <div class="finding-meta">
                      ${stepId ? `<span>${escapeHtml(t('workflows.healthFindingStep', { stepId: stepId, tool: tool || 'unknown' }))}</span>` : ''}
                      ${rid ? `<span>${escapeHtml(t('workflows.healthFindingRun', { runId: rid }))}</span>` : ''}
                      ${version !== undefined ? `<span>${escapeHtml(t('workflows.healthFindingVersion', { version: version }))}</span>` : ''}
                    </div>
                  </div>
                  <div class="finding-actions">
                    ${eligible ? `
                      <button class="btn btn-sm btn-primary btn-propose-health-timeout" data-finding-id="${escapeHtml(fid)}" aria-label="${escapeHtml(t('workflows.btnProposeTimeoutAria', { id: fid }))}" data-i18n="workflows.btnProposeTimeout">
                        ${escapeHtml(t('workflows.btnProposeTimeout'))}
                      </button>
                    ` : `
                      <span class="text-muted" style="font-size: 12px;" data-i18n="workflows.healthFindingIneligible">${escapeHtml(t('workflows.healthFindingIneligible'))}</span>
                    `}
                  </div>
                </div>
              `;
            });
            elFindings.innerHTML = rowsHtml;

            elFindings.querySelectorAll('.btn-propose-health-timeout').forEach(btn => {
              btn.addEventListener('click', () => {
                const targetFid = btn.getAttribute('data-finding-id');
                const matchedFinding = findings.find(f => String(f.id) === String(targetFid));
                if (targetFid && matchedFinding) {
                  openHealthTimeoutProposal(targetFid, matchedFinding, h);
                }
              });
            });
          }
        }

        // Render proposals list
        // Item 7: AllProjects不要发proposal.list {}，显示需选项目。
        if (elProposalsSection && elProposalsList) {
          if (!thisProject) {
            elProposalsSection.style.display = 'block';
            if (elProposalsIncomplete) {
              elProposalsIncomplete.style.display = 'none';
            }
            elProposalsList.innerHTML = `
              <div class="empty-state" style="padding: 16px 0;">
                <span class="text-muted" data-i18n="workflows.selectProjectFirst">${escapeHtml(t('workflows.selectProjectFirst'))}</span>
              </div>
            `;
          } else if (propListData && Array.isArray(propListData.items) && propListData.items.length > 0) {
            elProposalsSection.style.display = 'block';
            if (elProposalsIncomplete) {
              elProposalsIncomplete.style.display = (propListData.complete === false) ? 'inline-block' : 'none';
            }
            let propRowsHtml = '';
            propListData.items.forEach(prop => {
              const pid = String(prop.id || '');
              const st = String(prop.state || '');
              let stBadgeClass = 'badge-subtle';
              let stI18nKey = '';
              let stLabel = '';
              if (st === 'pending_review') {
                stBadgeClass = 'badge-amber';
                stI18nKey = 'workflows.healthProposalStatePending';
              } else if (st === 'accepting') {
                stBadgeClass = 'badge-amber';
                stI18nKey = 'workflows.healthProposalStateAccepting';
              } else if (st === 'accepted') {
                stBadgeClass = 'badge-sage';
                stI18nKey = 'workflows.healthProposalStateAccepted';
              } else if (st === 'rejected') {
                stBadgeClass = 'badge-subtle';
                stI18nKey = 'workflows.healthProposalStateRejected';
              } else if (st === 'invalidated') {
                stBadgeClass = 'badge-subtle';
                stI18nKey = 'workflows.healthProposalStateInvalidated';
              } else {
                stBadgeClass = 'badge-subtle';
                stLabel = st || 'unknown';
              }

              const isRecoverable = (st === 'accepting');
              const isReviewable = (st === 'pending_review' || st === 'accepting');

              propRowsHtml += `
                <div class="health-proposal-item-row" data-proposal-id="${escapeHtml(pid)}" data-state="${escapeHtml(st)}">
                  <div class="finding-info">
                    <div class="finding-header">
                      <span class="finding-code">${escapeHtml(pid)}</span>
                      <span class="badge ${stBadgeClass}" ${stI18nKey ? `data-i18n="${stI18nKey}"` : ''}>${escapeHtml(stI18nKey ? t(stI18nKey) : stLabel)}</span>
                    </div>
                    <div class="finding-meta">
                      ${prop.stepId ? `<span>${escapeHtml(t('workflows.healthFindingStep', { stepId: prop.stepId, tool: prop.tool || '' }))}</span>` : ''}
                      <span>${escapeHtml(t('workflows.healthProposalTimeoutChangeVal', { from: prop.fromTimeoutSeconds, to: prop.toTimeoutSeconds }))}</span>
                    </div>
                  </div>
                  <div class="finding-actions">
                    ${isReviewable ? `
                      <button class="btn btn-sm ${isRecoverable ? 'btn-warning' : 'btn-secondary'} btn-open-proposal-item" data-proposal-id="${escapeHtml(pid)}" aria-label="${escapeHtml(t(isRecoverable ? 'workflows.btnRecoverProposalAria' : 'workflows.btnReviewProposalAria', { id: pid }))}">
                        ${escapeHtml(t(isRecoverable ? 'workflows.btnRecoverProposal' : 'workflows.btnReviewProposal'))}
                      </button>
                    ` : ''}
                  </div>
                </div>
              `;
            });
            elProposalsList.innerHTML = propRowsHtml;

            // Item 8: 已有proposal review用actual proposal.get，不要合成needs_review finding。
            elProposalsList.querySelectorAll('.btn-open-proposal-item').forEach(btn => {
              btn.addEventListener('click', () => {
                const pid = btn.getAttribute('data-proposal-id');
                if (pid) {
                  openExistingHealthProposalReview(pid);
                }
              });
            });
          } else {
            elProposalsSection.style.display = 'none';
          }
        }
      }
    } catch {
      if (thisLoadGen !== healthLoadGen || thisTabGen !== workflowTabGen || state.currentProject !== thisProject) return;
      const elRuns = document.getElementById('health-total-runs');
      const elRate = document.getElementById('health-success-rate');
      const elDur = document.getElementById('health-avg-duration');
      if (elRuns) setElementDescriptor(elRuns, { key: 'common.none' });
      if (elRate) setElementDescriptor(elRate, { key: 'common.none' });
      if (elDur) setElementDescriptor(elDur, { key: 'common.none' });
      if (elFindings) {
        elFindings.innerHTML = `
          <div class="empty-state" style="padding: 24px 0;">
            <div class="empty-state-title" data-i18n="workflows.healthFindingsEmpty">${escapeHtml(t('workflows.healthFindingsEmpty'))}</div>
          </div>
        `;
      }
    }
  }

  // Item 8: 独立且真实的已有提案审阅入口，调用实际 proposal.get
  async function openExistingHealthProposalReview(proposalId) {
    const capturedProject = state.currentProject;
    if (!capturedProject) {
      showToast({ key: 'workflows.selectProjectFirst' }, 'warning');
      return;
    }

    dismissActiveHealthProposalModal();

    openModal(
      { key: 'workflows.healthProposalReviewTitle' },
      `<div id="health-timeout-proposal-review" class="health-proposal-modal-content" role="region" aria-label="${escapeHtml(t('workflows.healthProposalReviewAria'))}">
        <div class="empty-state" style="padding: 32px 0;">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
          <div class="empty-state-title" data-i18n="common.loading" style="margin-top: 8px;">${escapeHtml(t('common.loading') || 'Loading...')}</div>
        </div>
      </div>`,
      `<button id="btn-cancel-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnCancel" aria-label="${escapeHtml(t('workflows.btnCancelAria'))}">${escapeHtml(t('workflows.btnCancel'))}</button>`
    );

    const capturedModalInstance = currentModalInstance;
    activeHealthProposalModalInstance = capturedModalInstance;
    const thisGen = ++healthProposalGen;

    function isScopeValid() {
      if (thisGen !== healthProposalGen) return false;
      if (currentModalInstance !== capturedModalInstance) return false;
      if (activeHealthProposalModalInstance !== capturedModalInstance) return false;
      if (state.currentProject !== capturedProject) return false;
      if (state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'health') return false;
      const modal = document.getElementById('modal-container');
      if (!modal || modal.classList.contains('hidden')) return false;
      return true;
    }

    document.getElementById('btn-cancel-health-proposal')?.addEventListener('click', () => {
      dismissActiveHealthProposalModal();
    });

    try {
      const propRes = await callBridge('workflows.health.proposal.get', { project: capturedProject, id: proposalId });
      if (!isScopeValid()) return;
      if (!propRes) {
        renderProposalModalMutationError(new Error('Proposal not found'));
        return;
      }

      healthProposalSession = {
        gen: thisGen,
        modalInstance: capturedModalInstance,
        project: capturedProject,
        proposalId: propRes.id,
        findingId: propRes.findingId,
        runId: propRes.runId,
        workflowId: propRes.workflowId,
        workflowVersion: propRes.workflowVersion,
        stepId: propRes.stepId,
        proposal: propRes,
        proposalHash: propRes.proposalHash,
        snapshotHash: '',
        isMutating: false
      };

      renderHealthProposalReviewView(healthProposalSession);
    } catch (err) {
      if (!isScopeValid()) return;
      renderProposalModalMutationError(err);
    }
  }

  async function openHealthTimeoutProposal(findingId, cachedFinding = null, healthData = null) {
    const capturedProject = state.currentProject;
    if (!capturedProject) {
      showToast({ key: 'workflows.selectProjectFirst' }, 'warning');
      return;
    }

    dismissActiveHealthProposalModal();

    openModal(
      { key: 'workflows.healthProposalPreviewTitle' },
      `<div id="health-timeout-proposal-preview" class="health-proposal-modal-content" role="region" aria-label="${escapeHtml(t('workflows.healthProposalPreviewAria'))}">
        <div class="empty-state" style="padding: 32px 0;">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
          <div class="empty-state-title" data-i18n="common.loading" style="margin-top: 8px;">${escapeHtml(t('common.loading') || 'Loading...')}</div>
        </div>
      </div>`,
      `<button id="btn-cancel-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnCancel" aria-label="${escapeHtml(t('workflows.btnCancelAria'))}">${escapeHtml(t('workflows.btnCancel'))}</button>`
    );

    const capturedModalInstance = currentModalInstance;
    activeHealthProposalModalInstance = capturedModalInstance;
    const thisGen = ++healthProposalGen;

    function isProposalScopeStillValid() {
      if (thisGen !== healthProposalGen) return false;
      if (currentModalInstance !== capturedModalInstance) return false;
      if (activeHealthProposalModalInstance !== capturedModalInstance) return false;
      if (state.currentProject !== capturedProject) return false;
      if (state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'health') return false;
      const modal = document.getElementById('modal-container');
      if (!modal || modal.classList.contains('hidden')) return false;
      return true;
    }

    document.getElementById('btn-cancel-health-proposal')?.addEventListener('click', () => {
      dismissActiveHealthProposalModal();
    });

    function renderIneligibleModalView() {
      const modalBody = document.getElementById('modal-body');
      if (modalBody) {
        modalBody.innerHTML = `
          <div id="health-timeout-proposal-preview" class="health-proposal-modal-content" role="region" aria-label="${escapeHtml(t('workflows.healthProposalPreviewAria'))}">
            <div class="alert alert-subtle" data-i18n="workflows.healthFindingIneligibleDesc">${escapeHtml(t('workflows.healthFindingIneligibleDesc'))}</div>
          </div>
        `;
      }
    }

    let finding = cachedFinding;
    let h = healthData;
    let runData = null;
    let wfData = null;
    let propListData = null;

    try {
      if (!finding || !h) {
        h = await callBridge('workflows.health', { project: capturedProject });
        if (!isProposalScopeStillValid()) return;
        finding = (h && Array.isArray(h.findings)) ? h.findings.find(f => String(f.id) === String(findingId)) : null;
      }

      if (!finding) {
        if (!isProposalScopeStillValid()) return;
        renderIneligibleModalView();
        return;
      }

      // Check proposal.list first
      propListData = await callBridge('workflows.health.proposal.list', { project: capturedProject });
      if (!isProposalScopeStillValid()) return;

      const existingProp = (propListData && Array.isArray(propListData.items))
        ? propListData.items.find(p => String(p.findingId) === String(finding.id) || (finding.runId && p.runId === finding.runId && p.stepId === finding.stepId))
        : null;

      if (existingProp && ['pending_review', 'accepting', 'accepted', 'rejected', 'invalidated'].includes(existingProp.state)) {
        // Item 8: 已有proposal review用actual proposal.get，不要合成needs_review finding
        const actualProp = await callBridge('workflows.health.proposal.get', { project: capturedProject, id: existingProp.id });
        if (!isProposalScopeStillValid()) return;
        if (!actualProp) {
          renderProposalModalMutationError(new Error('Proposal not found'));
          return;
        }
        healthProposalSession = {
          gen: thisGen,
          modalInstance: capturedModalInstance,
          project: capturedProject,
          proposalId: actualProp.id,
          findingId: actualProp.findingId,
          runId: actualProp.runId,
          workflowId: actualProp.workflowId,
          workflowVersion: actualProp.workflowVersion,
          stepId: actualProp.stepId,
          proposal: actualProp,
          proposalHash: actualProp.proposalHash,
          snapshotHash: '',
          isMutating: false
        };
        renderHealthProposalReviewView(healthProposalSession);
        return;
      }

      // Item 2: Core workflows.health findings 实际没有 workflowId，必须真实 runs.get {project, id: finding.runId}
      // 确认 run.project === capturedProject，再以 run.workflowId 读取 workflows.get
      if (!finding.runId) {
        if (!isProposalScopeStillValid()) return;
        renderIneligibleModalView();
        return;
      }

      runData = await callBridge('runs.get', { project: capturedProject, id: finding.runId });
      if (!isProposalScopeStillValid()) return;

      if (!runData || runData.project !== capturedProject) {
        if (!isProposalScopeStillValid()) return;
        renderIneligibleModalView();
        return;
      }

      const workflowId = finding.workflowId || runData.workflowId || '';
      if (!workflowId) {
        if (!isProposalScopeStillValid()) return;
        renderIneligibleModalView();
        return;
      }

      wfData = await callBridge('workflows.get', { project: capturedProject, id: workflowId });
      if (!isProposalScopeStillValid()) return;
    } catch (err) {
      if (!isProposalScopeStillValid()) return;
      renderProposalModalMutationError(err);
      return;
    }

    const workflowId = finding.workflowId || (runData && runData.workflowId) || (wfData && wfData.id) || '';

    // Workflow validation before offering creation
    const isWfValid = wfData && wfData.valid === true;
    const isWfActive = wfData && wfData.state === 'active';
    const isVersionMatch = wfData && wfData.definition && wfData.definition.version === finding.workflowVersion;
    const defStep = (wfData && wfData.definition && Array.isArray(wfData.definition.steps))
      ? wfData.definition.steps.find(s => s.id === finding.stepId)
      : null;
    const isToolEligible = defStep && ['shell.test', 'shell.typecheck', 'agent.run'].includes(defStep.tool);

    // Item 1: Health 完整性真实字段是 aggregateIncomplete 与 coverage=complete_within_selected_store_scope；sourceScan任一capReached应隐藏创建
    const isComplete = isHealthComplete(h);
    const hasCapReached = isSourceScanCapReached(h, finding);

    const currentTimeout = (defStep && defStep.arguments && typeof defStep.arguments.timeoutSeconds === 'number')
      ? defStep.arguments.timeoutSeconds
      : 120;
    const isTimeoutDefaulted = !(defStep && defStep.arguments && typeof defStep.arguments.timeoutSeconds === 'number');

    // Item 4: max=min(current*2,300)，若min=current+1>max则不可创建，不能Math.max抬到301
    const minAllowed = currentTimeout + 1;
    const maxAllowed = Math.min(currentTimeout * 2, 300);
    const isRangeValid = (minAllowed <= maxAllowed);

    const canCreate = Boolean(isWfValid && isWfActive && isVersionMatch && isToolEligible && isRangeValid && isComplete && !hasCapReached);

    const initialValue = isRangeValid ? maxAllowed : minAllowed;

    // Item 3: observedSeconds 缺失时显示未知，不能用 configured timeout 当实际 duration
    let observedSeconds = null;
    if (runData && Array.isArray(runData.steps)) {
      const rStep = runData.steps.find(s => s.id === finding.stepId);
      if (rStep && typeof rStep.durationMs === 'number' && rStep.durationMs > 0) {
        observedSeconds = Math.round(rStep.durationMs / 1000);
      }
    }
    if (observedSeconds === null && runData && typeof runData.durationMs === 'number' && runData.durationMs > 0) {
      observedSeconds = Math.round(runData.durationMs / 1000);
    }
    if (observedSeconds === null && typeof finding.stepDuration === 'number' && finding.stepDuration > 0) {
      observedSeconds = Math.round(finding.stepDuration / 1000);
    }

    const sourceOutcomeUnknown = Boolean((runData && runData.outcomeUnknown) || finding.outcomeUnknown || finding.state === 'needs_review');

    if (!isProposalScopeStillValid()) return;

    healthProposalSession = {
      gen: thisGen,
      modalInstance: capturedModalInstance,
      project: capturedProject,
      findingId: finding.id,
      runId: finding.runId,
      workflowId: workflowId,
      workflowVersion: (wfData && wfData.definition) ? wfData.definition.version : finding.workflowVersion,
      stepId: finding.stepId,
      snapshotHash: wfData ? wfData.snapshotHash : '',
      currentTimeout: currentTimeout,
      timeoutDefaulted: isTimeoutDefaulted,
      minAllowed: minAllowed,
      maxAllowed: maxAllowed,
      sourceOutcomeUnknown: sourceOutcomeUnknown,
      isMutating: false
    };

    const modalTitleEl = document.getElementById('modal-title');
    if (modalTitleEl) setElementDescriptor(modalTitleEl, { key: 'workflows.healthProposalPreviewTitle' });

    const modalBody = document.getElementById('modal-body');
    const modalFooter = document.getElementById('modal-footer');

    if (modalBody) {
      modalBody.innerHTML = `
        <div id="health-timeout-proposal-preview" class="health-proposal-modal-content" role="region" aria-label="${escapeHtml(t('workflows.healthProposalPreviewAria'))}">
          <div class="health-evidence-grid">
            <div class="health-evidence-label" data-i18n="workflows.healthProposalObservedTimeout">${escapeHtml(t('workflows.healthProposalObservedTimeout'))}</div>
            <div class="health-evidence-value">${observedSeconds !== null ? `${observedSeconds}s` : `<span class="text-muted" data-i18n="common.unknown">${escapeHtml(t('common.unknown') || 'Unknown')}</span>`}</div>

            <div class="health-evidence-label" data-i18n="workflows.healthProposalOriginalTimeout">${escapeHtml(t('workflows.healthProposalOriginalTimeout'))}</div>
            <div class="health-evidence-value">
              ${currentTimeout}s
              ${isTimeoutDefaulted ? `<span class="badge badge-subtle" style="margin-left: 6px;" data-i18n="workflows.healthProposalDefaultedNotice">${escapeHtml(t('workflows.healthProposalDefaultedNotice'))}</span>` : ''}
            </div>

            <div class="health-evidence-label" data-i18n="workflows.healthProposalPermittedRange">${escapeHtml(t('workflows.healthProposalPermittedRange'))}</div>
            <div class="health-evidence-value">${isRangeValid ? `${minAllowed}s - ${maxAllowed}s` : `<span class="text-muted" data-i18n="workflows.healthFindingIneligibleDesc">${escapeHtml(t('workflows.healthFindingIneligibleDesc'))}</span>`}</div>

            <div class="health-evidence-label" data-i18n="workflows.healthProposalSourceOutcome">${escapeHtml(t('workflows.healthProposalSourceOutcome'))}</div>
            <div class="health-evidence-value">
              <span class="badge ${sourceOutcomeUnknown ? 'badge-amber' : 'badge-subtle'}">${escapeHtml(finding.state || (runData && runData.state) || 'needs_review')}</span>
              ${sourceOutcomeUnknown ? '<span style="font-size: 11px; color: var(--status-amber-text); margin-left: 6px;">(sourceOutcomeUnknown: true)</span>' : ''}
            </div>
          </div>

          <div class="alert alert-info" data-i18n="workflows.healthProposalNotice" style="font-size: 12px; line-height: 1.5;">
            ${escapeHtml(t('workflows.healthProposalNotice'))}
          </div>

          <details class="technical-evidence-details" id="health-timeout-technical-evidence">
            <summary data-i18n="workflows.healthProposalTechnicalSummary">${escapeHtml(t('workflows.healthProposalTechnicalSummary'))}</summary>
            <div class="technical-evidence-body">
              <div>${escapeHtml(t('workflows.healthProposalFindingId', { findingId: finding.id }))}</div>
              ${finding.runId ? `<div>${escapeHtml(t('workflows.healthProposalRunId', { runId: finding.runId }))}</div>` : ''}
              <div>${escapeHtml(t('workflows.healthProposalStep', { stepId: finding.stepId }))}</div>
              <div>${escapeHtml(t('workflows.healthProposalTool', { tool: finding.tool || (defStep && defStep.tool) || 'unknown' }))}</div>
              ${wfData && wfData.definition ? `<div>${escapeHtml(t('workflows.healthProposalWorkflowVersion', { version: wfData.definition.version }))}</div>` : ''}
            </div>
          </details>

          ${canCreate ? `
            <div class="form-group" style="margin-top: 10px;">
              <label for="health-timeout-new-seconds" style="font-weight: 500; font-size: 13px; display: block; margin-bottom: 6px;" data-i18n="workflows.healthProposalNewTimeoutLabel">${escapeHtml(t('workflows.healthProposalNewTimeoutLabel'))}</label>
              <input id="health-timeout-new-seconds" type="number" class="form-input" min="${minAllowed}" max="${maxAllowed}" value="${initialValue}" aria-label="${escapeHtml(t('workflows.healthProposalNewTimeoutAria'))}" style="width: 100%; max-width: 220px;" />
              <div class="form-hint" style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">${escapeHtml(t('workflows.healthProposalRangeHint', { min: minAllowed, max: maxAllowed }))}</div>
            </div>
          ` : `
            <div class="alert alert-subtle" data-i18n="workflows.healthFindingIneligibleDesc">
              ${escapeHtml(t('workflows.healthFindingIneligibleDesc'))}
            </div>
          `}
        </div>
      `;
    }

    if (modalFooter) {
      modalFooter.innerHTML = `
        <button id="btn-cancel-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnCancel" aria-label="${escapeHtml(t('workflows.btnCancelAria'))}">${escapeHtml(t('workflows.btnCancel'))}</button>
        ${canCreate ? `<button id="btn-create-health-timeout-proposal" class="btn btn-primary" data-i18n="workflows.btnCreateProposal" aria-label="${escapeHtml(t('workflows.btnCreateProposalAria'))}">${escapeHtml(t('workflows.btnCreateProposal'))}</button>` : ''}
      `;
    }

    document.getElementById('btn-cancel-health-proposal')?.addEventListener('click', () => {
      dismissActiveHealthProposalModal();
    });

    if (canCreate) {
      const inputEl = document.getElementById('health-timeout-new-seconds');
      const btnCreate = document.getElementById('btn-create-health-timeout-proposal');

      function parseTimeoutVal() {
        if (!inputEl) return null;
        const raw = inputEl.value.trim();
        if (!/^\d+$/.test(raw)) return null;
        const val = parseInt(raw, 10);
        if (isNaN(val) || !Number.isInteger(val)) return null;
        if (val < minAllowed || val > maxAllowed) return null;
        return val;
      }

      if (inputEl && btnCreate) {
        inputEl.addEventListener('input', () => {
          const val = parseTimeoutVal();
          btnCreate.disabled = (val === null);
        });
        btnCreate.disabled = (parseTimeoutVal() === null);

        // Item 5: create catch 先检查 generation/当前 closure 再写状态，使用当前闭包对象，晚错误不能抛 TypeError
        btnCreate.addEventListener('click', async () => {
          const localSession = healthProposalSession;
          if (!localSession || !isProposalScopeStillValid()) return;
          if (localSession.isMutating) return;
          const finalVal = parseTimeoutVal();
          if (finalVal === null) {
            btnCreate.disabled = true;
            return;
          }
          localSession.isMutating = true;
          btnCreate.disabled = true;

          try {
            const res = await callBridge('workflows.health.proposeTimeout', {
              project: localSession.project,
              workflowId: localSession.workflowId,
              workflowVersion: localSession.workflowVersion,
              snapshotHash: localSession.snapshotHash,
              runId: localSession.runId,
              stepId: localSession.stepId,
              findingId: localSession.findingId,
              newTimeoutSeconds: finalVal
            });

            if (!isProposalScopeStillValid()) return;

            localSession.proposal = res;
            localSession.proposalHash = res.proposalHash;
            localSession.isMutating = false;

            renderHealthProposalReviewView(localSession);
            loadHealthData();
          } catch (err) {
            if (localSession) {
              localSession.isMutating = false;
            }
            if (!isProposalScopeStillValid()) return;
            if (btnCreate) btnCreate.disabled = false;
            renderProposalModalMutationError(err);
          }
        });
      }
    }
  }

  function isSessionScopeValid(session) {
    if (!session) return false;
    if (session.gen !== healthProposalGen) return false;
    if (currentModalInstance !== session.modalInstance) return false;
    if (activeHealthProposalModalInstance !== session.modalInstance) return false;
    if (state.currentProject !== session.project) return false;
    if (state.currentPage !== 'workflows' || state.workflowsActiveTab !== 'health') return false;
    const modal = document.getElementById('modal-container');
    if (!modal || modal.classList.contains('hidden')) return false;
    return true;
  }

  function renderHealthProposalReviewView(session) {
    if (!session || !session.proposal) return;

    const modalTitleEl = document.getElementById('modal-title');
    if (modalTitleEl) setElementDescriptor(modalTitleEl, { key: 'workflows.healthProposalReviewTitle' });

    const modalBody = document.getElementById('modal-body');
    const modalFooter = document.getElementById('modal-footer');
    if (!modalBody || !modalFooter) return;

    const prop = session.proposal;
    const st = String(prop.state || '');

    // Item 6: review 根节点增加 data-state 为实际 prop.state，invalidated/未知状态不能标成 rejected
    let stBadgeClass = 'badge-subtle';
    let stI18nKey = '';
    let stLabel = '';
    if (st === 'pending_review') {
      stBadgeClass = 'badge-amber';
      stI18nKey = 'workflows.healthProposalStatePending';
    } else if (st === 'accepting') {
      stBadgeClass = 'badge-amber';
      stI18nKey = 'workflows.healthProposalStateAccepting';
    } else if (st === 'accepted') {
      stBadgeClass = 'badge-sage';
      stI18nKey = 'workflows.healthProposalStateAccepted';
    } else if (st === 'rejected') {
      stBadgeClass = 'badge-subtle';
      stI18nKey = 'workflows.healthProposalStateRejected';
    } else if (st === 'invalidated') {
      stBadgeClass = 'badge-subtle';
      stI18nKey = 'workflows.healthProposalStateInvalidated';
    } else {
      stBadgeClass = 'badge-subtle';
      stLabel = st || 'unknown';
    }

    modalBody.innerHTML = `
      <div id="health-timeout-proposal-review" data-proposal-id="${escapeHtml(prop.id)}" data-state="${escapeHtml(st)}" role="region" aria-label="${escapeHtml(t('workflows.healthProposalReviewAria'))}" class="health-proposal-review-card">
        <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--border-subtle); padding-bottom: 10px;">
          <div>
            <span style="font-weight: 600; font-size: 13px;">${escapeHtml(prop.id)}</span>
            <span style="font-size: 12px; color: var(--text-muted); margin-left: 8px;">v${prop.workflowVersion}</span>
          </div>
          <div>
            <span class="badge ${stBadgeClass}" ${stI18nKey ? `data-i18n="${stI18nKey}"` : ''}>${escapeHtml(stI18nKey ? t(stI18nKey) : stLabel)}</span>
          </div>
        </div>

        <div class="health-evidence-grid" style="margin-top: 6px;">
          <div class="health-evidence-label" data-i18n="workflows.healthProposalTimeoutChange">${escapeHtml(t('workflows.healthProposalTimeoutChange'))}</div>
          <div class="health-evidence-value">${escapeHtml(t('workflows.healthProposalTimeoutChangeVal', { from: prop.fromTimeoutSeconds, to: prop.toTimeoutSeconds }))}</div>

          <div class="health-evidence-label" data-i18n="workflows.healthProposalStep">${escapeHtml(t('workflows.healthProposalStep', { stepId: prop.stepId }))}</div>
          <div class="health-evidence-value">${escapeHtml(prop.tool || 'step')}</div>
        </div>

        ${(st === 'pending_review' && prop.sourceOutcomeUnknown) ? `
          <div class="health-uncertainty-block">
            <div id="health-timeout-uncertainty-warning" class="alert alert-warning" role="alert" data-i18n="workflows.healthUncertainWarning" style="margin-bottom: 8px;">
              ${escapeHtml(t('workflows.healthUncertainWarning'))}
            </div>
            <label class="checkbox-label" for="health-timeout-uncertain-ack" style="display: flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13px;">
              <input type="checkbox" id="health-timeout-uncertain-ack" aria-describedby="health-timeout-uncertainty-warning" aria-label="${escapeHtml(t('workflows.healthUncertainAckLabel'))}" />
              <span data-i18n="workflows.healthUncertainAck">${escapeHtml(t('workflows.healthUncertainAck'))}</span>
            </label>
          </div>
        ` : ''}

        ${st === 'accepting' ? `
          <div class="alert alert-warning" data-i18n="workflows.healthProposalStateAccepting">
            ${escapeHtml(t('workflows.healthProposalStateAccepting'))}
          </div>
        ` : ''}

        ${st === 'accepted' ? `
          <div class="alert alert-success" data-i18n="workflows.healthProposalAcceptedSummary" data-i18n-params="${escapeHtml(JSON.stringify({ candidateId: prop.acceptedWorkflowId, version: prop.acceptedWorkflowVersion }))}">
            ${escapeHtml(t('workflows.healthProposalAcceptedSummary', { candidateId: prop.acceptedWorkflowId, version: prop.acceptedWorkflowVersion }))}
          </div>
          <div style="padding: 10px; background: var(--bg-subtle); border-radius: 4px; font-size: 12px; color: var(--text-secondary);">
            <div data-i18n="workflows.healthProposalCandidateId" data-i18n-params="${escapeHtml(JSON.stringify({ candidateId: prop.acceptedWorkflowId }))}">
              ${escapeHtml(t('workflows.healthProposalCandidateId', { candidateId: prop.acceptedWorkflowId }))}
            </div>
            <div data-i18n="workflows.healthProposalCandidateState" style="margin-top: 4px;">
              ${escapeHtml(t('workflows.healthProposalCandidateState'))}
            </div>
          </div>
        ` : ''}

        ${st === 'rejected' ? `
          <div class="alert alert-subtle" data-i18n="workflows.healthProposalRejectedSummary">
            ${escapeHtml(t('workflows.healthProposalRejectedSummary'))}
          </div>
        ` : ''}

        ${st === 'invalidated' ? `
          <div class="alert alert-subtle" data-i18n="workflows.healthProposalInvalidatedSummary">
            ${escapeHtml(t('workflows.healthProposalInvalidatedSummary'))}
          </div>
        ` : ''}
      </div>
    `;

    if (st === 'pending_review') {
      modalFooter.innerHTML = `
        <button id="btn-cancel-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnCancel" aria-label="${escapeHtml(t('workflows.btnCancelAria'))}">${escapeHtml(t('workflows.btnCancel'))}</button>
        <button id="btn-reject-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnRejectProposal" aria-label="${escapeHtml(t('workflows.btnRejectProposalAria'))}">${escapeHtml(t('workflows.btnRejectProposal'))}</button>
        <button id="btn-accept-health-proposal" class="btn btn-primary" data-i18n="workflows.btnAcceptProposal" aria-label="${escapeHtml(t('workflows.btnAcceptProposalAria'))}" ${prop.sourceOutcomeUnknown ? 'disabled' : ''}>${escapeHtml(t('workflows.btnAcceptProposal'))}</button>
      `;

      const btnCancel = document.getElementById('btn-cancel-health-proposal');
      const btnReject = document.getElementById('btn-reject-health-proposal');
      const btnAccept = document.getElementById('btn-accept-health-proposal');
      const ackCheckbox = document.getElementById('health-timeout-uncertain-ack');

      btnCancel?.addEventListener('click', () => {
        dismissActiveHealthProposalModal();
      });

      if (ackCheckbox && btnAccept) {
        ackCheckbox.addEventListener('change', () => {
          btnAccept.disabled = !ackCheckbox.checked;
        });
      }

      btnReject?.addEventListener('click', async () => {
        const localSession = session;
        if (!localSession || !isSessionScopeValid(localSession)) return;
        if (localSession.isMutating) return;
        localSession.isMutating = true;
        btnReject.disabled = true;
        if (btnAccept) btnAccept.disabled = true;

        try {
          const res = await callBridge('workflows.health.proposal.decide', {
            project: localSession.project,
            id: localSession.proposal.id,
            proposalHash: localSession.proposalHash,
            decision: 'reject'
          });

          if (!isSessionScopeValid(localSession)) return;

          localSession.isMutating = false;
          localSession.proposal = res;
          localSession.proposalHash = res.proposalHash;
          renderHealthProposalReviewView(localSession);
          loadHealthData();
        } catch (err) {
          if (localSession) {
            localSession.isMutating = false;
          }
          if (!isSessionScopeValid(localSession)) return;
          btnReject.disabled = false;
          if (btnAccept) btnAccept.disabled = prop.sourceOutcomeUnknown ? !ackCheckbox?.checked : false;
          renderProposalModalMutationError(err);
        }
      });

      btnAccept?.addEventListener('click', async () => {
        const localSession = session;
        if (!localSession || !isSessionScopeValid(localSession)) return;
        if (localSession.isMutating) return;
        if (prop.sourceOutcomeUnknown) {
          if (!ackCheckbox || !ackCheckbox.checked) return;
        }
        localSession.isMutating = true;
        btnAccept.disabled = true;
        if (btnReject) btnReject.disabled = true;

        try {
          const res = await callBridge('workflows.health.proposal.decide', {
            project: localSession.project,
            id: localSession.proposal.id,
            proposalHash: localSession.proposalHash,
            decision: 'accept',
            acknowledgeUncertainSource: Boolean(prop.sourceOutcomeUnknown)
          });

          if (!isSessionScopeValid(localSession)) return;

          localSession.isMutating = false;
          localSession.proposal = res;
          localSession.proposalHash = res.proposalHash;
          renderHealthProposalReviewView(localSession);
          loadHealthData();
        } catch (err) {
          if (localSession) {
            localSession.isMutating = false;
          }
          if (!isSessionScopeValid(localSession)) return;
          btnAccept.disabled = false;
          if (btnReject) btnReject.disabled = false;
          renderProposalModalMutationError(err);
        }
      });

    } else if (st === 'accepting') {
      modalFooter.innerHTML = `
        <button id="btn-cancel-health-proposal" class="btn btn-secondary" data-i18n="workflows.btnCancel" aria-label="${escapeHtml(t('workflows.btnCancelAria'))}">${escapeHtml(t('workflows.btnCancel'))}</button>
        <button id="btn-recover-health-proposal" class="btn btn-warning" data-i18n="workflows.btnRecoverProposal" aria-label="${escapeHtml(t('workflows.btnRecoverProposalAria'))}">${escapeHtml(t('workflows.btnRecoverProposal'))}</button>
      `;

      const btnCancel = document.getElementById('btn-cancel-health-proposal');
      const btnRecover = document.getElementById('btn-recover-health-proposal');

      btnCancel?.addEventListener('click', () => {
        dismissActiveHealthProposalModal();
      });

      btnRecover?.addEventListener('click', async () => {
        const localSession = session;
        if (!localSession || !isSessionScopeValid(localSession)) return;
        if (localSession.isMutating) return;
        localSession.isMutating = true;
        btnRecover.disabled = true;

        try {
          const res = await callBridge('workflows.health.proposal.decide', {
            project: localSession.project,
            id: localSession.proposal.id,
            proposalHash: localSession.proposalHash,
            decision: 'recover'
          });

          if (!isSessionScopeValid(localSession)) return;

          localSession.isMutating = false;
          localSession.proposal = res;
          localSession.proposalHash = res.proposalHash;
          renderHealthProposalReviewView(localSession);
          loadHealthData();
        } catch (err) {
          if (localSession) {
            localSession.isMutating = false;
          }
          if (!isSessionScopeValid(localSession)) return;
          btnRecover.disabled = false;
          renderProposalModalMutationError(err);
        }
      });

    } else {
      modalFooter.innerHTML = `
        <button id="btn-close-health-modal" class="btn btn-secondary" data-i18n="common.close" aria-label="${escapeHtml(t('common.close'))}">${escapeHtml(t('common.close') || 'Close')}</button>
      `;
      document.getElementById('btn-close-health-modal')?.addEventListener('click', () => {
        dismissActiveHealthProposalModal();
      });
    }
  }

  function renderProposalModalMutationError(err) {
    const errText = String(err && (err.message || err.code || err) || '');
    const isStale = /stale|scan|private|cas|conflict/i.test(errText);

    const modalBody = document.getElementById('modal-body');
    if (!modalBody) return;

    const existingAlert = modalBody.querySelector('.health-mutation-error-container');
    if (existingAlert) existingAlert.remove();

    const errContainer = document.createElement('div');
    errContainer.className = 'health-mutation-error-container';
    if (isStale) {
      errContainer.innerHTML = `
        <div class="alert alert-danger" role="alert" style="margin-top: 14px;">
          <div style="margin-bottom: 8px;" data-i18n="workflows.healthProposalStaleError">${escapeHtml(t('workflows.healthProposalStaleError'))}</div>
          <button id="btn-recover-stale-health" class="btn btn-sm btn-secondary" data-i18n="workflows.healthProposalReviewLatestEvidence">${escapeHtml(t('workflows.healthProposalReviewLatestEvidence'))}</button>
        </div>
      `;
    } else {
      errContainer.innerHTML = `
        <div class="alert alert-danger" role="alert" style="margin-top: 14px;">
          <div>${escapeHtml(errText || t('workflows.healthProposalStaleError'))}</div>
        </div>
      `;
    }
    modalBody.appendChild(errContainer);

    const btnRecover = errContainer.querySelector('#btn-recover-stale-health');
    if (btnRecover) {
      btnRecover.addEventListener('click', () => {
        dismissActiveHealthProposalModal();
        loadHealthData();
      });
    }
  }

  function runDisplayTitle(run) {
    const workflow = ((state.dashboard && state.dashboard.workflows) || []).find(item => item.id === run.workflowId);
    const title = [run.title, run.workflowTitle, workflow?.title].find(value => typeof value === 'string' && value.trim());
    return title ? title.trim() : t('workspace.run.untitled');
  }

  function getRunStateBadge(st) {
    const s = String(st || '').toLowerCase();
    switch (s) {
      case 'completed':
      case 'success':
        return `<span class="status-badge status-sage" data-i18n="workflows.stateSuccess">${escapeHtml(t('workflows.stateSuccess'))}</span>`;
      case 'running':
        return `<span class="status-badge status-amber" data-i18n="workflows.stateRunning">${escapeHtml(t('workflows.stateRunning'))}</span>`;
      case 'failed':
      case 'error':
        return `<span class="status-badge status-red" data-i18n="workflows.stateFailed">${escapeHtml(t('workflows.stateFailed'))}</span>`;
      case 'rejected':
        return `<span class="status-badge status-red" data-i18n="workspace.run.rejected">${escapeHtml(t('workspace.run.rejected'))}</span>`;
      case 'pending approval':
      case 'pending_approval':
        return `<span class="status-badge status-amber" data-i18n="workflows.statePendingApproval">${escapeHtml(t('workflows.statePendingApproval'))}</span>`;
      case 'waiting_child':
        return `<span class="status-badge status-amber" data-i18n="workspace.run.waiting_child">${escapeHtml(t('workspace.run.waiting_child'))}</span>`;
      case 'blocked':
        return `<span class="status-badge status-neutral" data-i18n="workspace.run.blocked">${escapeHtml(t('workspace.run.blocked'))}</span>`;
      case 'needs_review':
        return `<span class="status-badge status-amber" data-i18n="workspace.run.needs_review">${escapeHtml(t('workspace.run.needs_review'))}</span>`;
      default:
        return `<span class="status-badge status-neutral">${escapeHtml(st || t('common.unknown'))}</span>`;
    }
  }

  // =========================================================================
  // RUN FEEDBACK (UI Round 21)
  // =========================================================================

  let activeRunFeedbackModalInstance = null;
  let activeRunFeedbackCleanup = null;
  let activeRunFeedbackSession = null;
  let runFeedbackGen = 0;

  function dismissActiveRunFeedbackModal() {
    runFeedbackGen++;
    activeRunFeedbackSession = null;
    if (!activeRunFeedbackModalInstance) return;
    const targetInstance = activeRunFeedbackModalInstance;
    activeRunFeedbackModalInstance = null;

    if (currentModalInstance === targetInstance) {
      const modal = document.getElementById('modal-container');
      const feedbackEl = modal && modal.querySelector('#run-feedback-review, #run-feedback-history');
      if (modal && !modal.classList.contains('hidden') && feedbackEl) {
        closeModal();
      }
    }

    const cleanup = activeRunFeedbackCleanup;
    activeRunFeedbackCleanup = null;
    if (typeof cleanup === 'function') {
      try {
        cleanup();
      } catch {}
    }
  }

  function getFeedbackOutcomeBadge(outcome) {
    const oc = String(outcome || '').toLowerCase();
    switch (oc) {
      case 'good':
        return `<span class="status-badge status-sage" data-i18n="runs.feedback.outcomeGood">${escapeHtml(t('runs.feedback.outcomeGood'))}</span>`;
      case 'bad':
        return `<span class="status-badge status-amber" data-i18n="runs.feedback.outcomeBad">${escapeHtml(t('runs.feedback.outcomeBad'))}</span>`;
      case 'clear':
        return `<span class="status-badge status-neutral" data-i18n="runs.feedback.outcomeClear">${escapeHtml(t('runs.feedback.outcomeClear'))}</span>`;
      default:
        return `<span class="status-badge status-neutral">${escapeHtml(outcome || '-')}</span>`;
    }
  }

  function updateRunFeedbackCard(feedback) {
    const cardContent = document.getElementById('run-feedback-card-content');
    if (!cardContent) return;
    cardContent._feedbackEpoch = (cardContent._feedbackEpoch || 0) + 1;
    if (!feedback || feedback.outcome === 'clear') {
      cardContent.innerHTML = `
        <div style="font-size: 11px; color: var(--text-muted);" data-i18n="runs.feedback.noFeedbackYet">
          ${escapeHtml(t('runs.feedback.noFeedbackYet'))}
        </div>
      `;
      return;
    }
    cardContent.innerHTML = `
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px;">
        <div style="display: flex; align-items: center; gap: 8px;">
          <span class="badge-subtle">r${escapeHtml(String(feedback.revision || 1))}</span>
          ${getFeedbackOutcomeBadge(feedback.outcome)}
        </div>
        <div style="font-size: 11px; color: var(--text-muted); font-family: var(--font-mono);">
          ${formatTime(feedback.createdAt)}
        </div>
      </div>
      <div style="font-size: 12px; color: var(--text-main); margin-top: 4px; line-height: 1.4; word-break: break-word;">
        ${escapeHtml(feedback.reason || '')}
      </div>
    `;
  }

  async function openRunFeedbackModal(run, triggerEl) {
    dismissActiveRunFeedbackModal();

    const capturedProject = ((run.project && run.project !== '*') ? run.project : (state.currentProject !== '*' ? state.currentProject : '')).trim();
    const capturedRunId = run.id;
    const capturedDrawerInstance = currentDrawerInstance;
    const currentGen = ++runFeedbackGen;

    // Call runs.feedback.prepare immediately with exactly { project, runId }
    const preparePromise = callBridge('runs.feedback.prepare', {
      project: capturedProject,
      runId: capturedRunId
    });

    const modalBodyHtml = `
      <div id="run-feedback-review" data-run-id="${escapeHtml(capturedRunId)}" class="run-feedback-form-container">
        <!-- Original Run State Row -->
        <div class="feedback-meta-row" style="margin-bottom: 12px;">
          <span style="font-size: 11px; color: var(--text-secondary);" data-i18n="runs.feedback.originalStateLabel">${escapeHtml(t('runs.feedback.originalStateLabel'))}</span>
          <span id="run-feedback-original-state">${getRunStateBadge(run.state)}</span>
        </div>

        <!-- Error Banner (stale CAS / server error) -->
        <div id="run-feedback-error-banner" class="alert-banner alert-danger hidden" style="margin-bottom: 12px;">
          <div id="run-feedback-error-text"></div>
          <div id="run-feedback-stale-actions" class="hidden" style="margin-top: 8px;">
            <button type="button" id="btn-reload-run-feedback" class="btn btn-secondary btn-xs" data-i18n="runs.feedback.btnReloadLatest">${escapeHtml(t('runs.feedback.btnReloadLatest'))}</button>
          </div>
        </div>

        <!-- Outcome Select -->
        <div class="form-group" style="margin-bottom: 12px;">
          <label for="run-feedback-outcome" class="form-label" data-i18n="runs.feedback.outcomeLabel">${escapeHtml(t('runs.feedback.outcomeLabel'))}</label>
          <select id="run-feedback-outcome" class="form-select">
            <option value="good" data-i18n="runs.feedback.outcomeGood">${escapeHtml(t('runs.feedback.outcomeGood'))}</option>
            <option value="bad" data-i18n="runs.feedback.outcomeBad">${escapeHtml(t('runs.feedback.outcomeBad'))}</option>
            <option value="clear" data-i18n="runs.feedback.outcomeClear">${escapeHtml(t('runs.feedback.outcomeClear'))}</option>
          </select>
          <div class="form-hint" style="font-size: 11px; color: var(--text-muted); margin-top: 4px;" data-i18n="runs.feedback.outcomeHint">
            ${escapeHtml(t('runs.feedback.outcomeHint'))}
          </div>
        </div>

        <!-- Reason Input -->
        <div class="form-group" style="margin-bottom: 12px;">
          <label for="run-feedback-reason" class="form-label" data-i18n="runs.feedback.reasonLabel">${escapeHtml(t('runs.feedback.reasonLabel'))}</label>
          <input type="text" id="run-feedback-reason" class="form-input" data-i18n-placeholder="runs.feedback.reasonPlaceholder" placeholder="${escapeHtml(t('runs.feedback.reasonPlaceholder'))}" autocomplete="off" />
          <div style="display: flex; justify-content: space-between; align-items: center; margin-top: 4px; font-size: 11px;">
            <span id="run-feedback-reason-warning" class="text-danger" style="display: none;"></span>
            <span id="run-feedback-byte-counter" class="text-muted font-mono" style="margin-left: auto;">0 / 1000 B</span>
          </div>
        </div>

        <div style="font-size: 11px; color: var(--text-muted); margin-top: 6px; line-height: 1.4;" data-i18n="runs.feedback.disclaimer">
          ${escapeHtml(t('runs.feedback.disclaimer'))}
        </div>
      </div>
    `;

    const modalFooterHtml = `
      <button type="button" id="btn-cancel-run-feedback" class="btn btn-secondary" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button type="button" id="btn-save-run-feedback" class="btn btn-primary" disabled data-i18n="runs.feedback.btnSave">${escapeHtml(t('runs.feedback.btnSave'))}</button>
    `;

    openModal({ key: 'runs.feedback.modalTitle' }, modalBodyHtml, modalFooterHtml, triggerEl);

    const sessionModalInstance = currentModalInstance;
    activeRunFeedbackModalInstance = sessionModalInstance;

    // Session closure object: Opaque hashes stored ONLY here in closure, never in inputs/DOM!
    const session = {
      generation: currentGen,
      project: capturedProject,
      runId: capturedRunId,
      modalInstance: sessionModalInstance,
      drawerInstance: capturedDrawerInstance,
      prepared: false,
      isPending: false,
      runHash: null,
      previousFeedbackHash: null,
      latestFeedback: null
    };
    activeRunFeedbackSession = session;

    activeRunFeedbackCleanup = () => {
      session.isPending = false;
      session.runHash = null;
      session.previousFeedbackHash = null;
    };

    function isScopeValid() {
      return (
        activeRunFeedbackSession === session &&
        session.generation === currentGen &&
        session.modalInstance === currentModalInstance
      );
    }

    const cancelBtn = document.getElementById('btn-cancel-run-feedback');
    const saveBtn = document.getElementById('btn-save-run-feedback');
    const outcomeSelect = document.getElementById('run-feedback-outcome');
    const reasonInput = document.getElementById('run-feedback-reason');
    const byteCounter = document.getElementById('run-feedback-byte-counter');
    const warningEl = document.getElementById('run-feedback-reason-warning');
    const errorBanner = document.getElementById('run-feedback-error-banner');
    const errorText = document.getElementById('run-feedback-error-text');
    const staleActions = document.getElementById('run-feedback-stale-actions');
    const reloadBtn = document.getElementById('btn-reload-run-feedback');
    const originalStateEl = document.getElementById('run-feedback-original-state');

    cancelBtn?.addEventListener('click', () => {
      dismissActiveRunFeedbackModal();
    });

    function getByteCount(str) {
      if (!str) return 0;
      return new TextEncoder().encode(str).length;
    }

    function validateForm() {
      if (!isScopeValid()) return false;
      const reasonVal = reasonInput ? reasonInput.value : '';
      const byteCount = getByteCount(reasonVal);
      if (byteCounter) byteCounter.textContent = `${byteCount} / 1000 B`;

      let isValid = true;
      let errorMsg = '';

      if (!session.prepared) {
        isValid = false;
      } else if (session.isPending) {
        isValid = false;
      } else if (byteCount === 0) {
        isValid = false;
      } else if (reasonVal.trim().length === 0) {
        isValid = false;
        errorMsg = t('runs.feedback.errorWhitespaceOnly');
      } else if (byteCount > 1000) {
        isValid = false;
        errorMsg = t('runs.feedback.errorByteLimit');
      } else if (/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(reasonVal)) {
        isValid = false;
        errorMsg = t('runs.feedback.errorControlChars');
      }

      if (byteCounter) {
        if (byteCount > 1000) {
          byteCounter.style.color = 'var(--status-red-text)';
        } else {
          byteCounter.style.color = 'var(--text-muted)';
        }
      }

      if (warningEl) {
        if (errorMsg && reasonVal.length > 0) {
          warningEl.textContent = errorMsg;
          warningEl.style.display = 'block';
        } else {
          warningEl.style.display = 'none';
        }
      }

      if (saveBtn) {
        saveBtn.disabled = !isValid;
      }
      return isValid;
    }

    let outcomeDirty = false;
    let reasonDirty = false;

    reasonInput?.addEventListener('input', () => {
      reasonDirty = true;
      validateForm();
    });
    reasonInput?.addEventListener('change', () => {
      reasonDirty = true;
      validateForm();
    });
    outcomeSelect?.addEventListener('change', () => {
      outcomeDirty = true;
      validateForm();
    });
    outcomeSelect?.addEventListener('input', () => {
      outcomeDirty = true;
      validateForm();
    });

    reasonInput?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        if (saveBtn && !saveBtn.disabled && !session.isPending) {
          saveBtn.click();
        }
      }
    });

    reloadBtn?.addEventListener('click', async () => {
      if (!isScopeValid()) return;
      if (errorBanner) errorBanner.classList.add('hidden');
      if (staleActions) staleActions.classList.add('hidden');
      try {
        const prep = await callBridge('runs.feedback.prepare', {
          project: session.project,
          runId: session.runId
        });
        if (!isScopeValid()) return;
        session.runHash = prep.runHash;
        session.previousFeedbackHash = prep.feedback ? prep.feedback.feedbackHash : null;
        session.latestFeedback = prep.feedback || null;
        session.prepared = true;
        if (prep.state && originalStateEl) {
          originalStateEl.innerHTML = getRunStateBadge(prep.state);
        }
        validateForm();
      } catch (err) {
        if (!isScopeValid()) return;
        if (errorBanner) errorBanner.classList.remove('hidden');
        if (errorText) errorText.textContent = err.message || String(err);
      }
    });

    // Handle initial prepare resolution
    try {
      const prep = await preparePromise;
      if (!isScopeValid()) return;

      session.runHash = prep.runHash;
      session.previousFeedbackHash = prep.feedback ? prep.feedback.feedbackHash : null;
      session.latestFeedback = prep.feedback || null;
      session.prepared = true;

      if (prep.state && originalStateEl) {
        originalStateEl.innerHTML = getRunStateBadge(prep.state);
      }

      // Prefill if feedback exists
      if (prep.feedback) {
        if (!outcomeDirty && outcomeSelect) outcomeSelect.value = prep.feedback.outcome || 'good';
        if (!reasonDirty && reasonInput) reasonInput.value = prep.feedback.reason || '';
      }

      validateForm();
    } catch (err) {
      if (!isScopeValid()) return;
      session.prepared = false;
      if (errorBanner) errorBanner.classList.remove('hidden');
      if (errorText) errorText.textContent = err.message || String(err);
      if (saveBtn) saveBtn.disabled = true;
      return;
    }

    // Save button click
    saveBtn?.addEventListener('click', async () => {
      if (!isScopeValid()) return;
      if (session.isPending || saveBtn.disabled) return;

      // Disable the exact save control and inputs while pending
      session.isPending = true;
      saveBtn.disabled = true;
      if (outcomeSelect) outcomeSelect.disabled = true;
      if (reasonInput) reasonInput.disabled = true;
      if (errorBanner) errorBanner.classList.add('hidden');
      if (staleActions) staleActions.classList.add('hidden');

      const outcomeVal = outcomeSelect ? outcomeSelect.value : 'good';
      const reasonVal = reasonInput ? reasonInput.value : '';

      const recordPayload = {
        project: session.project,
        runId: session.runId,
        runHash: session.runHash,
        previousFeedbackHash: (session.previousFeedbackHash !== undefined && session.previousFeedbackHash !== null) ? session.previousFeedbackHash : null,
        outcome: outcomeVal,
        reason: reasonVal
      };

      try {
        const res = await callBridge('runs.feedback.record', recordPayload);
        if (!isScopeValid()) return;

        session.isPending = false;
        showToast({ key: 'runs.feedback.savedSuccess' });
        dismissActiveRunFeedbackModal();

        if (state.selectedRunId === capturedRunId) {
          updateRunFeedbackCard(res);
        }
      } catch (err) {
        if (!isScopeValid()) return;
        session.isPending = false;
        if (outcomeSelect) outcomeSelect.disabled = false;
        if (reasonInput) reasonInput.disabled = false;
        validateForm();

        const errMsg = err && err.message ? err.message : String(err);
        const isStaleCAS = /cas|stale|hash|conflict|mismatch|version/i.test(errMsg);

        if (errorBanner) errorBanner.classList.remove('hidden');
        if (isStaleCAS) {
          if (errorText) errorText.textContent = t('runs.feedback.errorStaleCAS');
          if (staleActions) staleActions.classList.remove('hidden');
        } else {
          if (errorText) errorText.textContent = errMsg;
          if (staleActions) staleActions.classList.add('hidden');
        }
      }
    });
  }

  async function openRunFeedbackHistoryModal(run, triggerEl) {
    dismissActiveRunFeedbackModal();

    const capturedProject = ((run.project && run.project !== '*') ? run.project : (state.currentProject !== '*' ? state.currentProject : '')).trim();
    const capturedRunId = run.id;
    const capturedDrawerInstance = currentDrawerInstance;
    const currentGen = ++runFeedbackGen;

    const modalBodyHtml = `
      <div id="run-feedback-history" class="run-feedback-history-container">
        <!-- Bounded Scan Warning Banner -->
        <div id="run-feedback-history-warning" class="alert-banner alert-warning hidden" data-i18n="runs.feedback.historyBoundedWarning">
          ${escapeHtml(t('runs.feedback.historyBoundedWarning'))}
        </div>

        <!-- History Error Banner -->
        <div id="run-feedback-history-error" class="alert-banner alert-danger hidden"></div>

        <!-- History Detail Panel (expands on clicking history item) -->
        <div id="run-feedback-history-detail" class="history-detail-panel hidden">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px;">
            <strong id="history-detail-title" data-i18n="runs.feedback.historyDetailTitle">${escapeHtml(t('runs.feedback.historyDetailTitle'))}</strong>
            <button type="button" id="btn-close-history-detail" class="btn btn-ghost btn-xs" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
          </div>
          <div id="history-detail-body" style="font-size: 11px;"></div>
        </div>

        <!-- History Items List -->
        <div id="run-feedback-history-list" class="history-items-list">
          <div class="empty-state-desc text-muted" style="padding: 16px; text-align: center;" data-i18n="common.loading">
            ${escapeHtml(t('common.loading'))}
          </div>
        </div>

        <!-- Load More Pagination Button -->
        <div id="run-feedback-history-pagination" style="margin-top: 8px; text-align: center;">
          <button type="button" id="btn-more-run-feedback-history" class="btn btn-secondary btn-sm hidden" data-i18n="runs.feedback.btnMoreHistory">
            ${escapeHtml(t('runs.feedback.btnMoreHistory'))}
          </button>
        </div>
      </div>
    `;

    const modalFooterHtml = `
      <button type="button" id="btn-close-run-feedback-history" class="btn btn-secondary" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
    `;

    openModal({ key: 'runs.feedback.historyTitle' }, modalBodyHtml, modalFooterHtml, triggerEl);
    document.getElementById('btn-close-run-feedback-history')?.addEventListener('click', () => {
      closeModal();
    });

    const sessionModalInstance = currentModalInstance;
    activeRunFeedbackModalInstance = sessionModalInstance;

    const historySession = {
      generation: currentGen,
      project: capturedProject,
      runId: capturedRunId,
      modalInstance: sessionModalInstance,
      drawerInstance: capturedDrawerInstance,
      cursor: null,
      snapshotHash: null,
      items: [],
      isLoading: false
    };
    activeRunFeedbackSession = historySession;

    activeRunFeedbackCleanup = () => {
      historySession.items = [];
      historySession.cursor = null;
      historySession.snapshotHash = null;
    };

    function isScopeValid() {
      return (
        activeRunFeedbackSession === historySession &&
        historySession.generation === currentGen &&
        historySession.modalInstance === currentModalInstance
      );
    }

    const warningEl = document.getElementById('run-feedback-history-warning');
    const errorEl = document.getElementById('run-feedback-history-error');
    const listEl = document.getElementById('run-feedback-history-list');
    const moreBtn = document.getElementById('btn-more-run-feedback-history');
    const detailPanel = document.getElementById('run-feedback-history-detail');
    const detailBody = document.getElementById('history-detail-body');
    const closeDetailBtn = document.getElementById('btn-close-history-detail');

    closeDetailBtn?.addEventListener('click', () => {
      if (detailPanel) detailPanel.classList.add('hidden');
      if (listEl) listEl.querySelectorAll('.history-item-card').forEach(c => c.classList.remove('active-history-item'));
    });

    async function showHistoryDetail(historyId, itemCard) {
      if (!isScopeValid()) return;
      try {
        const detail = await callBridge('runs.feedback.history.get', {
          project: historySession.project,
          id: historyId
        });
        if (!isScopeValid()) return;

        if (listEl) listEl.querySelectorAll('.history-item-card').forEach(c => c.classList.remove('active-history-item'));
        if (itemCard) itemCard.classList.add('active-history-item');

        if (detailBody) {
          detailBody.innerHTML = `
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-bottom: 8px;">
              <div><span class="text-secondary" data-i18n="runs.feedback.revisionLabel">${escapeHtml(t('runs.feedback.revisionLabel'))}:</span> <strong>r${escapeHtml(String(detail.revision || '-'))}</strong></div>
              <div><span class="text-secondary" data-i18n="runs.feedback.outcomeLabel">${escapeHtml(t('runs.feedback.outcomeLabel'))}:</span> ${getFeedbackOutcomeBadge(detail.outcome)}</div>
              <div><span class="text-secondary">创建时间:</span> ${formatTime(detail.createdAt)}</div>
              ${detail.supersededAt ? `<div><span class="text-secondary" data-i18n="runs.feedback.supersededAtLabel">${escapeHtml(t('runs.feedback.supersededAtLabel'))}:</span> ${formatTime(detail.supersededAt)}</div>` : ''}
            </div>
            <div style="margin-top: 6px; padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px; line-height: 1.4;">
              <strong>${escapeHtml(detail.reason || '-')}</strong>
            </div>
          `;
        }
        if (detailPanel) detailPanel.classList.remove('hidden');
      } catch (err) {
        if (!isScopeValid()) return;
        if (errorEl) {
          errorEl.textContent = err.message || String(err);
          errorEl.classList.remove('hidden');
        }
      }
    }

    function renderHistoryItems(items, append = false) {
      if (!listEl) return;
      if (!append) {
        listEl.innerHTML = '';
      }
      if (!items || items.length === 0) {
        if (!append) {
          listEl.innerHTML = `<div class="empty-state-desc text-muted" style="padding: 16px; text-align: center;" data-i18n="runs.feedback.historyEmpty">${escapeHtml(t('runs.feedback.historyEmpty'))}</div>`;
        }
        return;
      }

      items.forEach(item => {
        const itemEl = document.createElement('div');
        itemEl.className = 'history-item-card';
        itemEl.setAttribute('data-history-id', item.historyId || item.id);
        itemEl.setAttribute('role', 'button');
        itemEl.setAttribute('tabindex', '0');

        itemEl.innerHTML = `
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px;">
            <div style="display: flex; align-items: center; gap: 8px;">
              <span class="badge-subtle">r${escapeHtml(String(item.revision || '-'))}</span>
              ${getFeedbackOutcomeBadge(item.outcome)}
            </div>
            <div style="font-size: 11px; color: var(--text-muted); font-family: var(--font-mono);">
              ${formatTime(item.createdAt)}
            </div>
          </div>
          <div class="history-item-reason" style="font-size: 12px; line-height: 1.4; color: var(--text-main); word-break: break-word;">
            ${escapeHtml(item.reason || '-')}
          </div>
          ${item.supersededAt ? `
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 4px;">
              <span data-i18n="runs.feedback.supersededAtLabel">${escapeHtml(t('runs.feedback.supersededAtLabel'))}:</span> ${formatTime(item.supersededAt)}
            </div>
          ` : ''}
        `;

        itemEl.addEventListener('click', () => {
          showHistoryDetail(item.historyId || item.id, itemEl);
        });
        itemEl.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            showHistoryDetail(item.historyId || item.id, itemEl);
          }
        });

        listEl.appendChild(itemEl);
      });
    }

    async function loadHistoryPage(cursor = null) {
      if (!isScopeValid()) return;
      historySession.isLoading = true;
      if (moreBtn) moreBtn.disabled = true;

      const params = {
        project: historySession.project,
        runId: historySession.runId,
        limit: 20
      };
      if (cursor) {
        params.cursor = cursor;
      }

      try {
        const res = await callBridge('runs.feedback.history.list', params);
        if (!isScopeValid()) return;
        historySession.isLoading = false;

        // Check for snapshot drift when paging
        if (cursor && historySession.snapshotHash && res.snapshotHash && res.snapshotHash !== historySession.snapshotHash) {
          if (errorEl) {
            errorEl.textContent = t('runs.feedback.historySnapshotStale');
            errorEl.classList.remove('hidden');
          }
          if (moreBtn) moreBtn.classList.add('hidden');
          return;
        }

        if (res.coverage === 'bounded_by_source_scan_cap') {
          if (warningEl) warningEl.classList.remove('hidden');
        } else {
          if (warningEl) warningEl.classList.add('hidden');
        }

        historySession.snapshotHash = res.snapshotHash || historySession.snapshotHash;
        historySession.cursor = res.cursor || null;

        const newItems = res.items || [];
        if (cursor) {
          historySession.items = historySession.items.concat(newItems);
          renderHistoryItems(newItems, true);
        } else {
          historySession.items = newItems;
          renderHistoryItems(newItems, false);
        }

        if (historySession.cursor) {
          if (moreBtn) {
            moreBtn.classList.remove('hidden');
            moreBtn.disabled = false;
          }
        } else {
          if (moreBtn) moreBtn.classList.add('hidden');
        }
      } catch (err) {
        if (!isScopeValid()) return;
        historySession.isLoading = false;
        if (errorEl) {
          errorEl.textContent = t('runs.feedback.historyUnavailable');
          errorEl.classList.remove('hidden');
        }
        if (moreBtn) moreBtn.classList.add('hidden');
        if (!cursor && listEl) {
          listEl.innerHTML = `<div class="empty-state-desc text-muted" style="padding: 16px; text-align: center;" data-i18n="runs.feedback.historyUnavailable">${escapeHtml(t('runs.feedback.historyUnavailable'))}</div>`;
        }
      }
    }

    moreBtn?.addEventListener('click', () => {
      if (historySession.cursor && !historySession.isLoading) {
        loadHistoryPage(historySession.cursor);
      }
    });

    // Initial load
    loadHistoryPage(null);
  }

  async function openRunDetail(runId) {
    state.selectedRunId = runId;
    openDrawer({ key: 'workflows.loadingRunDetail' }, { key: 'workflows.runAudit' });
    const capturedDrawerInstance = currentDrawerInstance;
    const capturedProject = state.currentProject;
    const capturedPage = state.currentPage;
    const capturedRunId = runId;

    try {
      const run = await callBridge('runs.get', { id: runId });
      const drawerEl = document.getElementById('detail-drawer');
      if (
        currentDrawerInstance !== capturedDrawerInstance ||
        state.selectedRunId !== capturedRunId ||
        state.currentProject !== capturedProject ||
        state.currentPage !== capturedPage ||
        !drawerEl ||
        !drawerEl.isConnected ||
        drawerEl.classList.contains('hidden')
      ) {
        return;
      }
      if (!run) {
        const e = new Error('workflows.runNotFound');
        e.i18nKey = 'workflows.runNotFound';
        throw e;
      }

      const actualProject = ((run.project && run.project !== '*') ? run.project : (state.currentProject !== '*' ? state.currentProject : '')).trim();
      const hasActualProject = !!actualProject;
      const runState = String(run.state || '').toLowerCase();
      const isTerminal = ['completed', 'failed', 'cancelled', 'rejected'].includes(runState);
      const isDry = !!(run.dryRun || run.isDryRun || run.is_dry_run);
      const isPriv = !!(run.isPrivate || run.is_private || run.private || (run.security && run.security.private));
      const isEligibleForFeedback = isTerminal && hasActualProject && !isDry && !isPriv && runState !== 'needs_review';

      const runSub = run.id ? { key: 'workflows.runSubtitle', params: { id: run.id.substring(0, 8) } } : { key: 'workflows.runAudit' };
      setDrawerTitle(run.title ? run.title : { key: 'workflows.runDetail' }, runSub);

      const isResumable = ['waiting_child', 'blocked', 'needs_review'].includes(runState);
      setDrawerCustomActions(`
        ${isEligibleForFeedback ? `
          <button type="button" id="btn-open-run-feedback" class="btn btn-secondary btn-sm" data-i18n="runs.feedback.btnOpen">${escapeHtml(t('runs.feedback.btnOpen'))}</button>
          <button type="button" id="btn-run-feedback-history" class="btn btn-secondary btn-sm" data-i18n="runs.feedback.btnHistory">${escapeHtml(t('runs.feedback.btnHistory'))}</button>
        ` : ''}
        ${isResumable ? `<button id="btn-drawer-resume" class="btn btn-primary btn-sm" data-i18n="workflows.btnResumeRun">${escapeHtml(t('workflows.btnResumeRun'))}</button>` : ''}
        <button id="btn-drawer-replay" class="btn btn-secondary btn-sm" data-i18n="workflows.btnReplayRun">${escapeHtml(t('workflows.btnReplayRun'))}</button>
      `);

      if (isEligibleForFeedback) {
        document.getElementById('btn-open-run-feedback')?.addEventListener('click', (e) => {
          openRunFeedbackModal(run, e.currentTarget);
        });
        document.getElementById('btn-run-feedback-history')?.addEventListener('click', (e) => {
          openRunFeedbackHistoryModal(run, e.currentTarget);
        });
      }

      document.getElementById('btn-drawer-replay')?.addEventListener('click', async () => {
        try {
          await callBridge('workflows.replay', { runId: run.id });
          showToast({ key: 'workflows.replaySubmittedToast' });
          closeDrawer();
          await refreshDashboard(true, true);
        } catch (e) {
          showToast({ key: 'workflows.replayFailedToast', params: { error: e.message } }, 'error');
        }
      });

      document.getElementById('btn-drawer-resume')?.addEventListener('click', async () => {
        const btn = document.getElementById('btn-drawer-resume');
        if (btn) btn.disabled = true;
        try {
          await callBridge('runs.resume', { id: run.id, project: run.project || state.currentProject });
          showToast({ key: 'workflows.resumeRequestedToast' });
          openRunDetail(run.id);
        } catch (err) {
          showToast({ key: 'common.error', params: { error: err.message || String(err) } }, 'error');
          if (btn) btn.disabled = false;
        }
      });

      const steps = run.steps || [];
      const drawerBody = document.getElementById('drawer-content');

      drawerBody.innerHTML = `
        ${run.state === 'waiting_child' ? `
          <div class="alert-banner alert-warning" style="margin-bottom: 12px; display: flex; align-items: center; justify-content: space-between;">
            <span data-i18n="workflows.waitingChildNotice">${escapeHtml(t('workflows.waitingChildNotice'))}</span>
            ${run.waitingChildId ? `
              <button type="button" id="btn-view-waiting-child" class="btn btn-ghost btn-xs" style="text-decoration: underline;">
                查看子运行 (${escapeHtml(run.waitingChildId.substring(0, 8))})
              </button>
            ` : ''}
          </div>
        ` : ''}
        ${run.state === 'blocked' ? `
          <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
            <span data-i18n="workflows.blockedNotice">${escapeHtml(t('workflows.blockedNotice'))}</span>
          </div>
        ` : ''}
        ${run.state === 'needs_review' ? `
          <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
            <span data-i18n="workflows.needsReviewNotice">${escapeHtml(t('workflows.needsReviewNotice'))}</span>
          </div>
        ` : ''}

        <div class="card">
          <div class="card-header">
            <span class="card-title" data-i18n="workflows.basicInfo">${escapeHtml(t('workflows.basicInfo'))}</span>
            ${getRunStateBadge(run.state)}
          </div>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px;">
            <div><span class="text-secondary" data-i18n="workflows.metaMode">${escapeHtml(t('workflows.metaMode'))}</span> <strong>${run.dryRun ? t('workflows.modeDryRunLabel') : t('workflows.modeActualLabel')}</strong></div>
            <div><span class="text-secondary" data-i18n="workflows.metaVersion">${escapeHtml(t('workflows.metaVersion'))}</span> v${escapeHtml(String(run.workflowVersion || 1))}</div>
            <div><span class="text-secondary" data-i18n="workflows.metaDuration">${escapeHtml(t('workflows.metaDuration'))}</span> ${run.durationMs ? escapeHtml(String(run.durationMs)) + 'ms' : '-'}</div>
            <div><span class="text-secondary" data-i18n="workflows.metaTriggerTime">${escapeHtml(t('workflows.metaTriggerTime'))}</span> ${formatTime(run.startedAt)}</div>
            ${run.parentRunId ? `
              <div><span class="text-secondary">父级运行:</span> <a href="#" id="link-parent-run" class="code-badge">${escapeHtml(run.parentRunId.substring(0, 8))}</a></div>
            ` : ''}
            ${(run.rootRunId && run.rootRunId !== run.id && run.rootRunId !== run.parentRunId) ? `
              <div><span class="text-secondary">根运行:</span> <a href="#" id="link-root-run" class="code-badge">${escapeHtml(run.rootRunId.substring(0, 8))}</a></div>
            ` : ''}
          </div>
        </div>

        ${isEligibleForFeedback ? `
          <div class="card" id="run-feedback-summary-card" style="margin-top: 12px; padding: 12px 14px; background: var(--bg-subtle);">
            <div class="card-header" style="margin-bottom: 6px;">
              <span class="card-title" data-i18n="runs.feedback.cardTitle">${escapeHtml(t('runs.feedback.cardTitle'))}</span>
              <span class="badge-subtle" data-i18n="runs.feedback.badgeManual">${escapeHtml(t('runs.feedback.badgeManual'))}</span>
            </div>
            <div style="font-size: 11px; color: var(--text-secondary); line-height: 1.5;" data-i18n="runs.feedback.desc">
              ${escapeHtml(t('runs.feedback.desc'))}
            </div>
            <div id="run-feedback-card-content" style="margin-top: 8px;">
              <div style="font-size: 14px; color: var(--text-muted);" data-i18n="common.loading">
                ${escapeHtml(t('common.loading'))}
              </div>
            </div>
          </div>
        ` : ''}

        ${(run.compositionMode === 'pipeline' && Array.isArray(run.stageResults) && run.stageResults.length > 0) ? `
          <div class="card" style="margin-top: 12px; padding: 12px 14px; background: var(--bg-subtle);">
            <div class="card-header" style="margin-bottom: 8px;">
              <span class="card-title">流水线阶段 (${run.stageResults.length})</span>
            </div>
            <div style="display: flex; flex-direction: column; gap: 6px;">
              ${run.stageResults.map((st, idx) => `
                <div style="padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px; font-size: 11px; display: flex; align-items: center; justify-content: space-between;">
                  <div style="display: flex; align-items: center; gap: 8px;">
                    <span class="pipeline-stage-badge">${idx + 1}</span>
                    <strong>${escapeHtml(st.id || 'stage')}</strong>
                    <span class="code-badge">${escapeHtml(st.workflowId || '')}</span>
                    ${st.skipped ? `<span class="status-badge status-neutral">已跳过</span>` : ''}
                  </div>
                  <div style="display: flex; align-items: center; gap: 6px;">
                    ${st.durationMs ? `<span style="font-family: var(--font-mono); color: var(--text-muted);">${escapeHtml(String(st.durationMs))}ms</span>` : ''}
                    ${getRunStateBadge(st.state)}
                    ${st.childRunId ? `
                      <button type="button" class="btn btn-ghost btn-xs btn-open-stage-run" data-run-id="${escapeHtml(st.childRunId)}" style="text-decoration: underline;">
                        查看子运行
                      </button>
                    ` : ''}
                  </div>
                </div>
              `).join('')}
            </div>
          </div>
        ` : ''}

        ${(() => {
          const rawOutput = run.output;
          const hasMeaningfulOutput = rawOutput !== undefined && rawOutput !== null && (typeof rawOutput === 'string' ? rawOutput.trim().length > 0 : (typeof rawOutput === 'object' ? Object.keys(rawOutput).length > 0 : Boolean(rawOutput)));
          const rawHash = (typeof run.outputHash === 'string') ? run.outputHash.trim() : '';
          const delivery = (run.outputDelivery && typeof run.outputDelivery === 'object') ? run.outputDelivery : null;
          const deliveryTarget = (delivery && typeof delivery.target === 'string') ? delivery.target.trim() : '';
          const deliveryPath = (delivery && typeof delivery.path === 'string') ? delivery.path.trim() : '';
          const deliveryState = (delivery && typeof delivery.state === 'string') ? delivery.state.trim().toLowerCase() : '';
          const hasDelivery = Boolean(delivery && (deliveryTarget || deliveryPath || deliveryState));
          if (!hasMeaningfulOutput && !rawHash && !hasDelivery) return '';
          const shortPath = deliveryPath ? (deliveryPath.split(/[\/\\]/).filter(Boolean).pop() || deliveryPath) : '';
          let statusBadgeHtml = '';
          if (deliveryState === 'delivered') {
            statusBadgeHtml = `<span class="status-badge status-sage" data-i18n="runs.output.delivered">${escapeHtml(t('runs.output.delivered'))}</span>`;
          } else if (deliveryState === 'prepared') {
            statusBadgeHtml = `<span class="status-badge status-amber" data-i18n="runs.output.pending">${escapeHtml(t('runs.output.pending'))}</span>`;
          } else if (!delivery && hasMeaningfulOutput) {
            statusBadgeHtml = `<span class="status-badge status-slate" data-i18n="runs.output.generated">${escapeHtml(t('runs.output.generated'))}</span>`;
          }
          return `
            <div class="card" style="margin-top: 12px; padding: 12px 14px; background: var(--bg-subtle);">
              <div class="card-header" style="margin-bottom: 8px;">
                <span class="card-title" style="font-size: 14px; font-weight: normal;" data-i18n="runs.output.title">${escapeHtml(t('runs.output.title'))}</span>
                ${statusBadgeHtml}
              </div>
              ${(deliveryTarget || shortPath) ? `
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 14px; margin-bottom: 8px;">
                  ${deliveryTarget ? `<div><span class="text-secondary" data-i18n="runs.output.target">${escapeHtml(t('runs.output.target'))}:</span> <strong>${escapeHtml(deliveryTarget)}</strong></div>` : ''}
                  ${shortPath ? `<div><span class="text-secondary" data-i18n="runs.output.location">${escapeHtml(t('runs.output.location'))}:</span> <code class="code-badge" title="${escapeHtml(deliveryPath)}">${escapeHtml(shortPath)}</code></div>` : ''}
                </div>
              ` : ''}
              ${hasMeaningfulOutput ? `<div class="artifact-output-box">${escapeHtml(typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput, null, 2))}</div>` : ''}
              ${(deliveryPath || rawHash) ? `
                <details style="margin-top: 8px; font-size: 14px;">
                  <summary class="text-secondary" style="cursor: pointer;" data-i18n="inbox.detailsSummary">${escapeHtml(t('inbox.detailsSummary'))}</summary>
                  <div style="margin-top: 6px; display: flex; flex-direction: column; gap: 4px; padding-left: 8px;">
                    ${deliveryPath ? `<div><span class="text-secondary" data-i18n="runs.output.canonicalPath">${escapeHtml(t('runs.output.canonicalPath'))}:</span> <code class="code-badge" style="word-break: break-all;">${escapeHtml(deliveryPath)}</code></div>` : ''}
                    ${rawHash ? `<div><span class="text-secondary" data-i18n="runs.output.hash">${escapeHtml(t('runs.output.hash'))}:</span> <span class="font-mono" style="word-break: break-all;">${escapeHtml(rawHash)}</span></div>` : ''}
                  </div>
                </details>
              ` : ''}
            </div>
          `;
        })()}

        ${run.context ? `
          <div class="card" style="margin-top: 12px; padding: 12px 14px; background: var(--bg-subtle);">
            <div class="card-header" style="margin-bottom: 8px;">
              <span class="card-title" data-i18n="workflows.contextEvidenceTitle">${escapeHtml(t('workflows.contextEvidenceTitle'))}</span>
              ${run.context.degraded ? `<span class="status-badge status-amber" data-i18n="workflows.degradedNotice">${escapeHtml(t('workflows.degradedNotice'))}</span>` : `<span class="status-badge status-sage">OK</span>`}
            </div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px; margin-bottom: 8px;">
              <div style="grid-column: 1 / -1;"><span class="text-secondary" data-i18n="workflows.promptHashLabel">${escapeHtml(t('workflows.promptHashLabel'))}:</span> <span class="font-mono" style="word-break: break-all;">${escapeHtml(run.context.promptHash || '-')}</span></div>
              <div><span class="text-secondary" data-i18n="workflows.memoryUsedTitle" data-i18n-params="${escapeHtml(JSON.stringify({ count: (run.context.memoryUsed || []).length }))}">${escapeHtml(t('workflows.memoryUsedTitle', { count: (run.context.memoryUsed || []).length }))}:</span> <span>${(run.context.memoryUsed || []).length} 条 (${run.context.memoryUsedTokens || 0} / ${run.context.memoryBudgetTokens || 0} tokens)</span></div>
              <div><span class="text-secondary" data-i18n="workflows.guidelinesUsedTitle" data-i18n-params="${escapeHtml(JSON.stringify({ count: (run.context.guidelinesUsed || []).length }))}">${escapeHtml(t('workflows.guidelinesUsedTitle', { count: (run.context.guidelinesUsed || []).length }))}:</span> <span>${(run.context.guidelinesUsed || []).length} 条</span></div>
            </div>
            ${run.context.renderedPrompt ? `
              <details style="margin-top: 8px;">
                <summary style="cursor: pointer; font-size: 12px; font-weight: 600; color: var(--text-secondary); user-select: none;" data-i18n="workflows.renderedPromptLabel">${escapeHtml(t('workflows.renderedPromptLabel'))}</summary>
                <div class="code-view" style="max-height: 180px; margin-top: 6px; font-size: 11px;">${escapeHtml(run.context.renderedPrompt)}</div>
              </details>
            ` : ''}
            ${(run.context.inputsUsed && run.context.inputsUsed.length > 0) ? `
              <details style="margin-top: 8px;">
                <summary style="cursor: pointer; font-size: 12px; font-weight: 600; color: var(--text-secondary); user-select: none;" data-i18n="workflows.inputsUsedTitle" data-i18n-params="${escapeHtml(JSON.stringify({ count: run.context.inputsUsed.length }))}">${escapeHtml(t('workflows.inputsUsedTitle', { count: run.context.inputsUsed.length }))}</summary>
                <div style="display: flex; flex-direction: column; gap: 6px; margin-top: 6px;">
                  ${run.context.inputsUsed.map(item => `
                    <div style="padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px; font-size: 11px;">
                      <div style="display: flex; align-items: center; justify-content: space-between;">
                        <strong>${escapeHtml(item.id || '-')}</strong>
                        <span class="status-badge ${item.state === 'resolved' ? 'status-sage' : 'status-amber'}">${escapeHtml(item.state || 'resolved')} (${escapeHtml(item.source || 'value')})</span>
                      </div>
                      ${item.valueHash ? `<div style="color: var(--text-muted); font-size: 10px; font-family: var(--font-mono); margin-top: 2px;">Hash: ${escapeHtml(item.valueHash)}</div>` : ''}
                      ${item.error ? `<div style="color: var(--status-red-text); font-size: 10px; margin-top: 2px;">Error: ${escapeHtml(item.error)}</div>` : ''}
                    </div>
                  `).join('')}
                </div>
              </details>
            ` : ''}
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 8px;" data-i18n="workflows.evidenceDisclaimer">${escapeHtml(t('workflows.evidenceDisclaimer'))}</div>
          </div>
        ` : ''}

        ${steps.length > 0 ? `
          <div style="margin-top: 14px;">
            <h3 style="font-size: 13px; font-weight: 600; margin-bottom: 8px;" data-i18n="workflows.executionSteps" data-i18n-params="${escapeHtml(JSON.stringify({ count: steps.length }))}">${escapeHtml(t('workflows.executionSteps', { count: steps.length }))}</h3>
            <div style="display: flex; flex-direction: column; gap: 10px;">
              ${steps.map((step, idx) => `
                <div class="card" style="margin-bottom: 0; padding: 10px 12px;">
                  <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
                    <div>
                      <strong>${idx + 1}. ${escapeHtml(step.title || t('workflows.defaultStepTitle'))}</strong>
                      <span class="code-badge" style="margin-left: 6px;">${escapeHtml(step.tool || '')}</span>
                    </div>
                    <div style="display: flex; align-items: center; gap: 6px;">
                      ${step.durationMs ? `<span style="font-size: 12px; font-family: var(--font-mono); color: var(--text-muted);">${escapeHtml(String(step.durationMs))}ms</span>` : ''}
                      ${getRunStateBadge(step.state)}
                    </div>
                  </div>
                  ${step.output ? `
                    <div class="code-view" style="max-height: 160px; font-size: 12px;">${escapeHtml(typeof step.output === 'string' ? step.output : JSON.stringify(step.output, null, 2))}</div>
                  ` : `<div style="font-size: 12px; color: var(--text-muted);" data-i18n="workflows.noOutput">${escapeHtml(t('workflows.noOutput'))}</div>`}
                </div>
              `).join('')}
            </div>
          </div>
        ` : ''}
      `;

      document.getElementById('btn-view-waiting-child')?.addEventListener('click', () => {
        if (run.waitingChildId) openRunDetail(run.waitingChildId);
      });
      document.getElementById('link-parent-run')?.addEventListener('click', (e) => {
        e.preventDefault();
        if (run.parentRunId) openRunDetail(run.parentRunId);
      });
      document.getElementById('link-root-run')?.addEventListener('click', (e) => {
        e.preventDefault();
        if (run.rootRunId) openRunDetail(run.rootRunId);
      });
      drawerBody.querySelectorAll('.btn-open-stage-run').forEach(btn => {
        btn.addEventListener('click', () => {
          const childId = btn.getAttribute('data-run-id');
          if (childId) openRunDetail(childId);
        });
      });

      if (isEligibleForFeedback) {
        const cardContentEl = document.getElementById('run-feedback-card-content');
        const capturedEpoch = cardContentEl ? (cardContentEl._feedbackEpoch || 0) : 0;

        callBridge('runs.feedback.prepare', { project: actualProject, runId: run.id })
          .then(prep => {
            const drawerEl = document.getElementById('detail-drawer');
            if (
              currentDrawerInstance !== capturedDrawerInstance ||
              state.selectedRunId !== capturedRunId ||
              state.currentProject !== capturedProject ||
              state.currentPage !== capturedPage ||
              !drawerEl ||
              !drawerEl.isConnected ||
              drawerEl.classList.contains('hidden') ||
              !cardContentEl ||
              !cardContentEl.isConnected ||
              (cardContentEl._feedbackEpoch || 0) !== (capturedEpoch || 0)
            ) {
              return;
            }
            const isValid =
              prep &&
              typeof prep === 'object' &&
              !Array.isArray(prep) &&
              ('feedback' in prep) &&
              (
                prep.feedback === null ||
                (
                  typeof prep.feedback === 'object' &&
                  !Array.isArray(prep.feedback) &&
                  (
                    prep.feedback.outcome === 'good' ||
                    prep.feedback.outcome === 'bad' ||
                    prep.feedback.outcome === 'clear'
                  )
                )
              );
            if (!isValid) {
              cardContentEl.innerHTML = `
                <div style="font-size: 14px; color: var(--text-muted);" data-i18n="runs.feedback.currentUnavailable">
                  ${escapeHtml(t('runs.feedback.currentUnavailable'))}
                </div>
              `;
              return;
            }
            updateRunFeedbackCard(prep.feedback);
          })
          .catch(() => {
            const drawerEl = document.getElementById('detail-drawer');
            if (
              currentDrawerInstance !== capturedDrawerInstance ||
              state.selectedRunId !== capturedRunId ||
              state.currentProject !== capturedProject ||
              state.currentPage !== capturedPage ||
              !drawerEl ||
              !drawerEl.isConnected ||
              drawerEl.classList.contains('hidden') ||
              !cardContentEl ||
              !cardContentEl.isConnected ||
              (cardContentEl._feedbackEpoch || 0) !== (capturedEpoch || 0)
            ) {
              return;
            }
            cardContentEl.innerHTML = `
              <div style="font-size: 14px; color: var(--text-muted);" data-i18n="runs.feedback.currentUnavailable">
                ${escapeHtml(t('runs.feedback.currentUnavailable'))}
              </div>
            `;
          });
      }
    } catch (err) {
      const drawerEl = document.getElementById('detail-drawer');
      if (
        currentDrawerInstance !== capturedDrawerInstance ||
        state.selectedRunId !== capturedRunId ||
        state.currentProject !== capturedProject ||
        state.currentPage !== capturedPage ||
        !drawerEl ||
        !drawerEl.isConnected ||
        drawerEl.classList.contains('hidden')
      ) {
        return;
      }
      setDrawerTitle({ key: 'common.loadFailed' }, { key: 'common.error' });
      const drawerContent = document.getElementById('drawer-content');
      if (drawerContent) {
        if (err && err.i18nKey) {
          drawerContent.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="workflows.fetchRunFailedPrefix">${escapeHtml(t('workflows.fetchRunFailedPrefix'))}</span><span data-i18n="${err.i18nKey}">${escapeHtml(t(err.i18nKey))}</span>
            </div>
          `;
        } else {
          drawerContent.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="workflows.fetchRunFailedPrefix">${escapeHtml(t('workflows.fetchRunFailedPrefix'))}</span><span>${escapeHtml(err ? err.message : String(err))}</span>
            </div>
          `;
        }
      }
    }
  }

  function openWorkflowPromptBuilderModal() {
    const modalBody = `
      <div class="alert-banner alert-info">
        <span data-i18n="workflows.builderNotice">${escapeHtml(t('workflows.builderNotice'))}</span>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.targetProjectLabel">${escapeHtml(t('workflows.targetProjectLabel'))}</label>
        <select id="wf-build-project" class="form-select">
          ${state.registeredProjects.map(p => `
            <option value="${escapeHtml(p.path || p.id)}" ${(state.currentProject === (p.path || p.id)) ? 'selected' : ''}>${escapeHtml(p.title || p.path)}</option>
          `).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.promptDescLabel">${escapeHtml(t('workflows.promptDescLabel'))}</label>
        <textarea id="wf-build-desc" class="form-textarea" data-i18n-placeholder="workflows.promptDescPlaceholder" placeholder="${escapeHtml(t('workflows.promptDescPlaceholder'))}"></textarea>
      </div>
    `;

    openModal({ key: 'workflows.builderModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-wf-build" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-confirm-wf-build" data-i18n="workflows.btnGenerateDraft">${escapeHtml(t('workflows.btnGenerateDraft'))}</button>
    `);

    document.getElementById('btn-cancel-wf-build').addEventListener('click', closeModal);
    document.getElementById('btn-confirm-wf-build').addEventListener('click', async () => {
      const project = document.getElementById('wf-build-project').value;
      const description = document.getElementById('wf-build-desc').value.trim();

      if (!project) {
        showToast({ key: 'workflows.selectProjectFirst' }, 'error');
        return;
      }
      if (!description) {
        showToast({ key: 'workflows.enterDescFirst' }, 'error');
        return;
      }

      try {
        const res = await callBridge('workflows.build', { project, description });
        closeModal();

        if (res && res.workflow) {
          showToast(res.message || { key: 'workflows.draftGeneratedToast' });
          // Load draft into editor
          openEditWorkflowModal(res.workflow, res.unresolvedInputs || []);
        }
      } catch (err) {
        showToast({ key: 'workflows.buildFailedToast', params: { error: err.message } }, 'error');
      }
    });
  }

  function openEditWorkflowModal(wf = null, unresolvedInputs = []) {
    const isEdit = !!(wf && wf.id);
    const defaultSteps = [
      {
        id: 'step-1',
        title: '检查工作区状态',
        tool: 'git.status',
        arguments: {}
      },
      {
        id: 'step-2',
        title: '运行单元测试',
        tool: 'shell.test',
        arguments: { executable: 'npm', args: ['test'], timeoutSeconds: 60 }
      }
    ];

    let wfType = (wf && Array.isArray(wf.pipeline) && wf.pipeline.length > 0) ? 'pipeline' : 'steps';
    let pipelineStages = (wf && Array.isArray(wf.pipeline)) ? JSON.parse(JSON.stringify(wf.pipeline)) : [];
    if (pipelineStages.length === 0) {
      pipelineStages = [{ id: 'stage_1', workflowId: '', when: 'always' }];
    }
    let outputTarget = (wf && wf.output && wf.output.target) ? wf.output.target : 'stdout';
    let outputPath = (wf && wf.output && wf.output.path) ? wf.output.path : 'report-{date}.md';
    let outputInbox = (wf && wf.output && wf.output.inbox !== undefined) ? Boolean(wf.output.inbox) : true;
    let outputStepId = (wf && wf.output && wf.output.stepId) ? wf.output.stepId : '';

    let steps = wf && wf.steps ? JSON.parse(JSON.stringify(wf.steps)) : defaultSteps;
    const initialTrigger = (wf && wf.trigger) ? wf.trigger : 'manual';
    const initialTimeZone = (wf && wf.timeZone) ? wf.timeZone : (Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC');
    const initialCatchUp = wf ? (wf.catchUp || 'skip') : 'latest';
    const initialCatchUpLimit = (wf && typeof wf.catchUpLimit === 'number') ? wf.catchUpLimit : 10;
    const initialCatchUpWindowHours = (wf && typeof wf.catchUpWindowHours === 'number') ? wf.catchUpWindowHours : 24;

    const initialWatch = (wf && (wf.watch || (wf.definition && wf.definition.watch))) || {};
    const initialWatchSource = initialWatch.source || (Array.isArray(initialWatch.paths) ? 'files' : 'tool');
    const initialWatchPaths = Array.isArray(initialWatch.paths) ? initialWatch.paths.join('\n') : (typeof initialWatch.paths === 'string' ? initialWatch.paths : '');
    const initialWatchRecursive = initialWatch.recursive !== undefined ? Boolean(initialWatch.recursive) : true;
    const initialWatchIgnore = Array.isArray(initialWatch.ignore) ? initialWatch.ignore.join('\n') : (typeof initialWatch.ignore === 'string' ? initialWatch.ignore : '');
    const initialWatchTool = initialWatch.tool || 'git.status';
    const initialWatchMode = initialWatch.mode || (initialWatchTool.startsWith('git.') ? 'output' : 'items');
    const initialWatchKey = initialWatch.key || 'id';
    const initialWatchEvery = typeof initialWatch.everySeconds === 'number' ? initialWatch.everySeconds : 60;
    const initialWatchMin = typeof initialWatch.minItems === 'number' ? initialWatch.minItems : 1;
    const initialWatchDebounce = typeof initialWatch.debounceSeconds === 'number' ? initialWatch.debounceSeconds : (initialWatchSource === 'files' ? 5 : 10);
    const initialWatchArgs = initialWatch.arguments || {};
    const initialWatchQuery = initialWatchArgs.query || '';
    const initialWatchTokens = typeof initialWatchArgs.budgetTokens === 'number' ? initialWatchArgs.budgetTokens : 1000;
    const initialWatchK = typeof initialWatchArgs.k === 'number' ? initialWatchArgs.k : 10;

    let contextEnabled = !!(wf && wf.context);
    let contextTemplate = (wf && wf.context && wf.context.template) || '';
    let contextMemoryEnabled = wf && wf.context && wf.context.memory ? (wf.context.memory.enabled !== false) : true;
    let contextMemoryBudget = (wf && wf.context && wf.context.memory && typeof wf.context.memory.budgetTokens === 'number') ? wf.context.memory.budgetTokens : 2000;
    let contextInputs = (wf && wf.context && Array.isArray(wf.context.inputs)) ? JSON.parse(JSON.stringify(wf.context.inputs)) : [];
    contextInputs.forEach(inp => {
      if (inp.workflow) {
        inp.type = 'workflow';
        inp.subworkflowId = inp.workflow.id || '';
        inp.subworkflowInputs = typeof inp.workflow.inputs === 'object' ? JSON.stringify(inp.workflow.inputs, null, 2) : (inp.workflow.inputs || '');
        inp.subworkflowStdin = inp.workflow.stdin || '';
      }
    });
    let selectedGuidelines = (wf && Array.isArray(wf.guidelines)) ? [...wf.guidelines] : [];

    const getCandidateWorkflows = (proj) => {
      const all = (state.dashboard && Array.isArray(state.dashboard.workflows)) ? state.dashboard.workflows : [];
      return all.filter(w => (!proj || w.project === proj) && (!wf || w.id !== wf.id));
    };

    const modalBody = `
      ${unresolvedInputs && unresolvedInputs.length > 0 ? `
        <div class="alert-banner alert-warning">
          <span>${escapeHtml(t('workflows.unresolvedParamsPrefix', { params: unresolvedInputs.join('、') }))}</span>
        </div>
      ` : ''}
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.titleLabel">${escapeHtml(t('workflows.titleLabel'))}</label>
        <input type="text" id="wf-modal-title" class="form-input" value="${escapeHtml(wf ? wf.title : t('workflows.defaultTitle'))}" data-i18n-placeholder="workflows.titlePlaceholder" placeholder="${escapeHtml(t('workflows.titlePlaceholder'))}">
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.projectLabel">${escapeHtml(t('workflows.projectLabel'))}</label>
        <select id="wf-modal-project" class="form-select">
          ${state.registeredProjects.map(p => `
            <option value="${escapeHtml(p.path || p.id)}" ${(wf && wf.project === (p.path || p.id)) ? 'selected' : ''}>${escapeHtml(p.title || p.path)}</option>
          `).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.descLabel">${escapeHtml(t('workflows.descLabel'))}</label>
        <input type="text" id="wf-modal-desc" class="form-input" value="${escapeHtml(wf ? wf.description || '' : t('workflows.defaultDesc'))}" data-i18n-placeholder="workflows.descPlaceholder" placeholder="${escapeHtml(t('workflows.descPlaceholder'))}">
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="workflows.triggerLabel">${escapeHtml(t('workflows.triggerLabel'))}</label>
        <select id="wf-modal-trigger" class="form-select">
          <option value="manual" ${initialTrigger === 'manual' ? 'selected' : ''}>manual (手动运行)</option>
          <option value="cron" ${initialTrigger === 'cron' ? 'selected' : ''}>cron (定时周期)</option>
          <option value="watch" ${initialTrigger === 'watch' ? 'selected' : ''}>watch (变更观察)</option>
          <option value="app_start" ${initialTrigger === 'app_start' ? 'selected' : ''}>app_start (应用启动)</option>
          <option value="session_completed" ${initialTrigger === 'session_completed' ? 'selected' : ''}>session_completed (会话结束)</option>
          <option value="git_event" ${initialTrigger === 'git_event' ? 'selected' : ''}>git_event (Git 变更)</option>
          <option value="usage_reset" ${initialTrigger === 'usage_reset' ? 'selected' : ''}>usage_reset (用量重置)</option>
        </select>
      </div>

      <div id="wf-schedule-policy-group" class="card ${initialTrigger === 'cron' ? '' : 'hidden'}" style="padding: 10px 12px; margin-bottom: 12px; background: var(--bg-subtle);">
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;" data-i18n="workflows.scheduleTitle">${escapeHtml(t('workflows.scheduleTitle'))}</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.cronLabel">${escapeHtml(t('workflows.cronLabel'))}</label>
            <input type="text" id="wf-modal-cron" class="form-input" value="${escapeHtml(wf ? wf.cron || '' : '0 * * * *')}" placeholder="*/30 * * * *">
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.timeZoneLabel">${escapeHtml(t('workflows.timeZoneLabel'))}</label>
            <input type="text" id="wf-modal-timezone" class="form-input" value="${escapeHtml(initialTimeZone)}" placeholder="Asia/Shanghai">
          </div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px;">
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.catchUpLabel">${escapeHtml(t('workflows.catchUpLabel'))}</label>
            <select id="wf-modal-catchup" class="form-select">
              <option value="latest" ${initialCatchUp === 'latest' ? 'selected' : ''} data-i18n="workflows.catchUpLatest">${escapeHtml(t('workflows.catchUpLatest'))} (推荐)</option>
              <option value="skip" ${initialCatchUp === 'skip' ? 'selected' : ''} data-i18n="workflows.catchUpSkip">${escapeHtml(t('workflows.catchUpSkip'))}</option>
              <option value="all" ${initialCatchUp === 'all' ? 'selected' : ''} data-i18n="workflows.catchUpAll">${escapeHtml(t('workflows.catchUpAll'))}</option>
            </select>
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.catchUpLimitLabel">${escapeHtml(t('workflows.catchUpLimitLabel'))}</label>
            <input type="number" id="wf-modal-catchup-limit" class="form-input" min="1" max="100" value="${escapeHtml(String(initialCatchUpLimit))}">
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.catchUpWindowLabel">${escapeHtml(t('workflows.catchUpWindowLabel'))}</label>
            <input type="number" id="wf-modal-catchup-window" class="form-input" min="1" max="168" value="${escapeHtml(String(initialCatchUpWindowHours))}">
          </div>
        </div>
      </div>

      <div id="wf-watch-config-group" class="card ${initialTrigger === 'watch' ? '' : 'hidden'}" style="padding: 10px 12px; margin-bottom: 12px; background: var(--bg-subtle);">
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;" data-i18n="watch.title">${escapeHtml(t('watch.title'))}</div>
        <div class="alert-banner alert-info" style="font-size: 11px; margin-bottom: 8px;" data-i18n="watch.baselineNotice">${escapeHtml(t('watch.baselineNotice'))}</div>
        <div class="alert-banner alert-warning" style="font-size: 11px; margin-bottom: 8px;" data-i18n="watch.approvalNotice">${escapeHtml(t('watch.approvalNotice'))}</div>

        <div class="form-group" style="margin-bottom: 8px;">
          <label class="form-label" data-i18n="watch.sourceLabel">${escapeHtml(t('watch.sourceLabel'))}</label>
          <select id="wf-watch-source" class="form-select">
            <option value="tool" ${initialWatchSource === 'tool' ? 'selected' : ''} data-i18n="watch.sourceTool">${escapeHtml(t('watch.sourceTool'))}</option>
            <option value="files" ${initialWatchSource === 'files' ? 'selected' : ''} data-i18n="watch.sourceFiles">${escapeHtml(t('watch.sourceFiles'))}</option>
          </select>
          <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" id="wf-watch-source-desc" data-i18n="${initialWatchSource === 'files' ? 'watch.sourceFilesDesc' : 'watch.sourceToolDesc'}">${escapeHtml(t(initialWatchSource === 'files' ? 'watch.sourceFilesDesc' : 'watch.sourceToolDesc'))}</div>
        </div>

        <div id="wf-watch-tool-section" class="${initialWatchSource === 'tool' ? '' : 'hidden'}">
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="watch.toolLabel">${escapeHtml(t('watch.toolLabel'))}</label>
              <select id="wf-watch-tool" class="form-select">
                <option value="git.status" ${initialWatchTool === 'git.status' ? 'selected' : ''}>git.status (只读输出)</option>
                <option value="git.diff" ${initialWatchTool === 'git.diff' ? 'selected' : ''}>git.diff (只读输出)</option>
                <option value="git.log" ${initialWatchTool === 'git.log' ? 'selected' : ''}>git.log (只读输出)</option>
                <option value="memory.recall" ${initialWatchTool === 'memory.recall' ? 'selected' : ''}>memory.recall (工程记忆召回)</option>
                <option value="library.retrieve" ${initialWatchTool === 'library.retrieve' ? 'selected' : ''}>library.retrieve (知识库段落)</option>
              </select>
              <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" data-i18n="watch.toolDesc">${escapeHtml(t('watch.toolDesc'))}</div>
            </div>
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="watch.modeLabel">${escapeHtml(t('watch.modeLabel'))}</label>
              <select id="wf-watch-mode" class="form-select" ${initialWatchTool.startsWith('git.') ? 'disabled' : ''}>
                <option value="output" ${initialWatchMode === 'output' ? 'selected' : ''} data-i18n="watch.modeOutput">${escapeHtml(t('watch.modeOutput'))}</option>
                <option value="items" ${initialWatchMode === 'items' ? 'selected' : ''} data-i18n="watch.modeItems">${escapeHtml(t('watch.modeItems'))}</option>
              </select>
            </div>
          </div>

          <div id="wf-watch-args-group" style="margin-bottom: 8px;">
            <div class="form-group ${['memory.recall', 'library.retrieve'].includes(initialWatchTool) ? '' : 'hidden'}" id="wf-watch-arg-query-group" style="margin-bottom: 6px;">
              <label class="form-label" data-i18n="watch.argQueryLabel">${escapeHtml(t('watch.argQueryLabel'))}</label>
              <input type="text" id="wf-watch-arg-query" class="form-input" value="${escapeHtml(initialWatchQuery)}" placeholder="release notes">
            </div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
              <div class="form-group ${initialWatchTool === 'memory.recall' ? '' : 'hidden'}" id="wf-watch-arg-tokens-group" style="margin-bottom: 0;">
                <label class="form-label" data-i18n="watch.argTokensLabel">${escapeHtml(t('watch.argTokensLabel'))}</label>
                <input type="number" id="wf-watch-arg-tokens" class="form-input" min="1" max="2000" value="${escapeHtml(String(initialWatchTokens))}">
              </div>
              <div class="form-group ${initialWatchTool === 'library.retrieve' ? '' : 'hidden'}" id="wf-watch-arg-k-group" style="margin-bottom: 0;">
                <label class="form-label" data-i18n="watch.argKLabel">${escapeHtml(t('watch.argKLabel'))}</label>
                <input type="number" id="wf-watch-arg-k" class="form-input" min="1" max="10" value="${escapeHtml(String(initialWatchK))}">
              </div>
            </div>
          </div>

          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="watch.keyLabel">${escapeHtml(t('watch.keyLabel'))}</label>
              <input type="text" id="wf-watch-key" class="form-input" value="${escapeHtml(initialWatchKey)}" ${initialWatchMode === 'output' ? 'disabled' : ''}>
            </div>
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="watch.everyLabel">${escapeHtml(t('watch.everyLabel'))}</label>
              <input type="number" id="wf-watch-every" class="form-input" min="30" max="86400" value="${escapeHtml(String(initialWatchEvery))}">
            </div>
          </div>
        </div>

        <div id="wf-watch-files-section" class="${initialWatchSource === 'files' ? '' : 'hidden'}">
          <div class="form-group" style="margin-bottom: 8px;">
            <label class="form-label" data-i18n="watch.pathsLabel">${escapeHtml(t('watch.pathsLabel'))}</label>
            <textarea id="wf-watch-paths" class="form-textarea code-editor" style="min-height: 60px; font-size: 11px; font-family: var(--font-mono);" data-i18n-placeholder="watch.pathsPlaceholder" placeholder="${escapeHtml(t('watch.pathsPlaceholder'))}">${escapeHtml(initialWatchPaths)}</textarea>
            <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" data-i18n="watch.pathsHint">${escapeHtml(t('watch.pathsHint'))}</div>
          </div>

          <div class="form-group" style="margin-bottom: 8px;">
            <label class="form-checkbox-label" style="font-size: 11px; margin-bottom: 0;">
              <input type="checkbox" id="wf-watch-recursive" ${initialWatchRecursive ? 'checked' : ''}>
              <span data-i18n="watch.recursiveLabel">${escapeHtml(t('watch.recursiveLabel'))}</span>
            </label>
            <div class="form-hint" style="font-size: 10px; color: var(--text-muted); margin-left: 20px;" data-i18n="watch.recursiveHint">${escapeHtml(t('watch.recursiveHint'))}</div>
          </div>

          <div class="form-group" style="margin-bottom: 8px;">
            <label class="form-label" data-i18n="watch.ignoreLabel">${escapeHtml(t('watch.ignoreLabel'))}</label>
            <textarea id="wf-watch-ignore" class="form-textarea code-editor" style="min-height: 52px; font-size: 11px; font-family: var(--font-mono);" data-i18n-placeholder="watch.ignorePlaceholder" placeholder="${escapeHtml(t('watch.ignorePlaceholder'))}">${escapeHtml(initialWatchIgnore)}</textarea>
            <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" data-i18n="watch.ignoreHint">${escapeHtml(t('watch.ignoreHint'))}</div>
          </div>
        </div>

        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="watch.minItemsLabel">${escapeHtml(t('watch.minItemsLabel'))}</label>
            <input type="number" id="wf-watch-min-items" class="form-input" min="1" max="100" value="${escapeHtml(String(initialWatchMin))}" ${initialWatchSource === 'tool' && initialWatchMode === 'output' ? 'disabled' : ''}>
            <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" data-i18n="watch.minItemsHint">${escapeHtml(t('watch.minItemsHint'))}</div>
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="watch.debounceLabel">${escapeHtml(t('watch.debounceLabel'))}</label>
            <input type="number" id="wf-watch-debounce" class="form-input" min="0" max="300" value="${escapeHtml(String(initialWatchDebounce))}">
            <div class="form-hint" style="font-size: 10px; color: var(--text-muted);" data-i18n="watch.debounceHint">${escapeHtml(t('watch.debounceHint'))}</div>
          </div>
        </div>

        ${isEdit ? `
          <div style="margin-top: 8px; display: flex; justify-content: flex-end;">
            <button type="button" class="btn btn-secondary btn-sm" id="btn-wf-modal-preview-watch" data-i18n="watch.btnPreview">${escapeHtml(t('watch.btnPreview'))}</button>
          </div>
        ` : ''}
      </div>

      <div class="form-group">
        <label class="form-label" data-i18n="workflows.typeSelectorLabel">${escapeHtml(t('workflows.typeSelectorLabel'))}</label>
        <select id="wf-modal-type" class="form-select">
          <option value="steps" ${wfType === 'steps' ? 'selected' : ''} data-i18n="workflows.typeSteps">${escapeHtml(t('workflows.typeSteps'))}</option>
          <option value="pipeline" ${wfType === 'pipeline' ? 'selected' : ''} data-i18n="workflows.typePipeline">${escapeHtml(t('workflows.typePipeline'))}</option>
        </select>
      </div>

      <!-- Pipeline Stages Builder -->
      <div class="card ${wfType === 'pipeline' ? '' : 'hidden'}" id="wf-pipeline-card" style="padding: 10px 12px; margin-bottom: 12px; background: var(--bg-subtle);">
        <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
          <div>
            <strong style="font-size: 13px;" data-i18n="workflows.pipelineTitle">${escapeHtml(t('workflows.pipelineTitle'))}</strong>
            <div style="font-size: 11px; color: var(--text-secondary); margin-top: 2px;" data-i18n="workflows.pipelineDesc">${escapeHtml(t('workflows.pipelineDesc'))}</div>
          </div>
          <button type="button" id="btn-add-pipeline-stage" class="btn btn-ghost btn-sm" data-i18n="workflows.btnAddStage">${escapeHtml(t('workflows.btnAddStage'))}</button>
        </div>
        <div id="wf-pipeline-stages-list" style="display: flex; flex-direction: column; gap: 6px; max-height: 260px; overflow-y: auto; margin-top: 8px;"></div>
      </div>

      <!-- Artifact Delivery Config -->
      <div class="card" id="wf-output-card" style="padding: 10px 12px; margin-bottom: 12px; background: var(--bg-subtle);">
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;" data-i18n="workflows.outputTargetTitle">${escapeHtml(t('workflows.outputTargetTitle'))}</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.outputTargetLabel">${escapeHtml(t('workflows.outputTargetLabel'))}</label>
            <select id="wf-output-target" class="form-select">
              <option value="stdout" ${outputTarget === 'stdout' ? 'selected' : ''} data-i18n="workflows.targetStdout">${escapeHtml(t('workflows.targetStdout'))}</option>
              <option value="inbox" ${outputTarget === 'inbox' ? 'selected' : ''} data-i18n="workflows.targetInbox">${escapeHtml(t('workflows.targetInbox'))}</option>
              <option value="file" ${outputTarget === 'file' ? 'selected' : ''} data-i18n="workflows.targetFile">${escapeHtml(t('workflows.targetFile'))}</option>
            </select>
          </div>
          <div class="form-group ${outputTarget === 'file' ? '' : 'hidden'}" id="wf-output-path-group" style="margin-bottom: 0;">
            <label class="form-label" data-i18n="workflows.outputPathLabel">${escapeHtml(t('workflows.outputPathLabel'))}</label>
            <input type="text" id="wf-output-path" class="form-input" value="${escapeHtml(outputPath)}" placeholder="reports/{date}.md">
          </div>
        </div>
        <div style="display: flex; align-items: center; gap: 16px; margin-top: 8px; flex-wrap: wrap;">
          <label class="form-checkbox-label ${outputTarget === 'file' ? '' : 'hidden'}" id="wf-output-inbox-group" style="font-size: 11px; margin-bottom: 0;">
            <input type="checkbox" id="wf-output-inbox" ${outputInbox ? 'checked' : ''}>
            <span data-i18n="workflows.outputInboxCheckbox">${escapeHtml(t('workflows.outputInboxCheckbox'))}</span>
          </label>
          <div class="form-group ${wfType === 'steps' && outputTarget !== 'stdout' ? '' : 'hidden'}" id="wf-output-stepid-group" style="margin-bottom: 0; display: flex; align-items: center; gap: 6px;">
            <label class="form-label" style="margin-bottom: 0; font-size: 11px;" data-i18n="workflows.outputStepIdLabel">${escapeHtml(t('workflows.outputStepIdLabel'))}:</label>
            <input type="text" id="wf-output-step-id" class="form-input" style="width: 120px; font-size: 11px; padding: 2px 6px;" value="${escapeHtml(outputStepId)}" placeholder="留空则取末步">
          </div>
        </div>
      </div>

      <!-- Standard Steps & Context Section -->
      <div id="wf-steps-section" class="${wfType === 'steps' ? '' : 'hidden'}">
        <div class="card" id="wf-context-card" style="padding: 10px 12px; margin-bottom: 12px; background: var(--bg-subtle);">
          <div style="display: flex; align-items: center; justify-content: space-between;">
            <label class="form-checkbox-label" style="margin-bottom: 0;">
              <input type="checkbox" id="wf-context-enable" ${contextEnabled ? 'checked' : ''}>
              <strong style="font-size: 13px;" data-i18n="workflows.enableContextLabel">${escapeHtml(t('workflows.enableContextLabel'))}</strong>
            </label>
          </div>
          <div id="wf-context-body" class="${contextEnabled ? '' : 'hidden'}" style="display: flex; flex-direction: column; gap: 10px; margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border-color);">
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="workflows.contextPromptLabel">${escapeHtml(t('workflows.contextPromptLabel'))}</label>
              <textarea id="wf-context-template" class="form-textarea code-editor" style="min-height: 64px; font-size: 12px;" data-i18n-placeholder="workflows.contextPromptPlaceholder" placeholder="${escapeHtml(t('workflows.contextPromptPlaceholder'))}">${escapeHtml(contextTemplate)}</textarea>
            </div>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
              <div class="form-group" style="margin-bottom: 0;">
                <label class="form-label" data-i18n="workflows.memoryPolicyTitle">${escapeHtml(t('workflows.memoryPolicyTitle'))}</label>
                <label class="form-checkbox-label">
                  <input type="checkbox" id="wf-context-mem-enable" ${contextMemoryEnabled ? 'checked' : ''}>
                  <span data-i18n="workflows.memoryEnabledLabel">${escapeHtml(t('workflows.memoryEnabledLabel'))}</span>
                </label>
              </div>
              <div class="form-group" style="margin-bottom: 0;">
                <label class="form-label" data-i18n="workflows.memoryBudgetLabel">${escapeHtml(t('workflows.memoryBudgetLabel'))}</label>
                <input type="number" id="wf-context-mem-budget" class="form-input" min="0" max="4000" value="${escapeHtml(String(contextMemoryBudget))}">
              </div>
            </div>

            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="workflows.guidelinesSelectLabel">${escapeHtml(t('workflows.guidelinesSelectLabel'))}</label>
              <div id="wf-guidelines-list" style="display: flex; flex-wrap: wrap; gap: 8px; max-height: 80px; overflow-y: auto;">
                <span style="font-size: 11px; color: var(--text-muted);">正在加载规约...</span>
              </div>
            </div>

            <div class="form-group" style="margin-bottom: 0;">
              <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
                <label class="form-label" style="margin-bottom: 0;" data-i18n="workflows.inputsBuilderTitle">${escapeHtml(t('workflows.inputsBuilderTitle'))}</label>
                <button type="button" id="btn-add-context-input" class="btn btn-ghost btn-sm" data-i18n="workflows.btnAddInput">${escapeHtml(t('workflows.btnAddInput'))}</button>
              </div>
              <div id="wf-context-inputs-list" style="display: flex; flex-direction: column; gap: 6px; max-height: 160px; overflow-y: auto;"></div>
            </div>
          </div>
        </div>

        <div style="margin-top: 6px;">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <label class="form-label" style="margin-bottom: 0;" data-i18n="workflows.stepsLabel">${escapeHtml(t('workflows.stepsLabel'))}</label>
            <button type="button" id="btn-add-step" class="btn btn-ghost btn-sm" data-i18n="workflows.btnAddStep">${escapeHtml(t('workflows.btnAddStep'))}</button>
          </div>
          <div id="wf-steps-list" style="display: flex; flex-direction: column; gap: 8px; max-height: 240px; overflow-y: auto;"></div>
        </div>
      </div>
    `;

    openModal({ key: isEdit ? 'workflows.editModalTitle' : 'workflows.newModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-wf" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-save-wf" data-i18n="workflows.btnSaveWorkflow">${escapeHtml(t('workflows.btnSaveWorkflow'))}</button>
    `);

    // Toggle schedule & watch policy visibility
    const triggerSelect = document.getElementById('wf-modal-trigger');
    const schedPolicyGroup = document.getElementById('wf-schedule-policy-group');
    const watchConfigGroup = document.getElementById('wf-watch-config-group');
    triggerSelect?.addEventListener('change', () => {
      const val = triggerSelect.value;
      if (schedPolicyGroup) {
        schedPolicyGroup.classList.toggle('hidden', val !== 'cron');
      }
      if (watchConfigGroup) {
        watchConfigGroup.classList.toggle('hidden', val !== 'watch');
      }
      if (val === 'cron' || val === 'watch') {
        const outTargetSelect = document.getElementById('wf-output-target');
        if (outTargetSelect && outTargetSelect.value === 'stdout') {
          outTargetSelect.value = 'inbox';
          const outputPathGroup = document.getElementById('wf-output-path-group');
          const outputInboxGroup = document.getElementById('wf-output-inbox-group');
          const outputStepIdGroup = document.getElementById('wf-output-stepid-group');
          outputPathGroup?.classList.add('hidden');
          outputInboxGroup?.classList.add('hidden');
          if (wfType === 'steps') outputStepIdGroup?.classList.remove('hidden');
        }
      }
    });

    // Watch Source / Tool / Mode Dynamic Rules
    const watchSourceSelect = document.getElementById('wf-watch-source');
    const watchToolSection = document.getElementById('wf-watch-tool-section');
    const watchFilesSection = document.getElementById('wf-watch-files-section');
    const watchSourceDesc = document.getElementById('wf-watch-source-desc');
    const watchToolSelect = document.getElementById('wf-watch-tool');
    const watchModeSelect = document.getElementById('wf-watch-mode');
    const watchKeyInput = document.getElementById('wf-watch-key');
    const watchMinInput = document.getElementById('wf-watch-min-items');
    const watchQueryGroup = document.getElementById('wf-watch-arg-query-group');
    const watchTokensGroup = document.getElementById('wf-watch-arg-tokens-group');
    const watchKGroup = document.getElementById('wf-watch-arg-k-group');

    const updateWatchFieldVisibility = () => {
      const src = watchSourceSelect ? watchSourceSelect.value : 'tool';
      if (src === 'files') {
        if (watchToolSection) watchToolSection.classList.add('hidden');
        if (watchFilesSection) watchFilesSection.classList.remove('hidden');
        if (watchMinInput) watchMinInput.disabled = false;
        if (watchSourceDesc) {
          watchSourceDesc.setAttribute('data-i18n', 'watch.sourceFilesDesc');
          watchSourceDesc.textContent = t('watch.sourceFilesDesc');
        }
      } else {
        if (watchToolSection) watchToolSection.classList.remove('hidden');
        if (watchFilesSection) watchFilesSection.classList.add('hidden');
        if (watchSourceDesc) {
          watchSourceDesc.setAttribute('data-i18n', 'watch.sourceToolDesc');
          watchSourceDesc.textContent = t('watch.sourceToolDesc');
        }
        if (!watchToolSelect || !watchModeSelect) return;
        const tool = watchToolSelect.value;
        const isGit = tool.startsWith('git.');
        if (isGit) {
          watchModeSelect.value = 'output';
          watchModeSelect.disabled = true;
          if (watchMinInput) { watchMinInput.value = '1'; watchMinInput.disabled = true; }
          if (watchKeyInput) { watchKeyInput.disabled = true; }
          watchQueryGroup?.classList.add('hidden');
          watchTokensGroup?.classList.add('hidden');
          watchKGroup?.classList.add('hidden');
        } else {
          watchModeSelect.disabled = false;
          const mode = watchModeSelect.value;
          if (mode === 'output') {
            if (watchMinInput) { watchMinInput.value = '1'; watchMinInput.disabled = true; }
            if (watchKeyInput) { watchKeyInput.disabled = true; }
          } else {
            if (watchMinInput) { watchMinInput.disabled = false; }
            if (watchKeyInput) { watchKeyInput.disabled = false; }
          }
          watchQueryGroup?.classList.remove('hidden');
          if (tool === 'memory.recall') {
            watchTokensGroup?.classList.remove('hidden');
            watchKGroup?.classList.add('hidden');
          } else if (tool === 'library.retrieve') {
            watchTokensGroup?.classList.add('hidden');
            watchKGroup?.classList.remove('hidden');
          }
        }
      }
    };

    watchSourceSelect?.addEventListener('change', updateWatchFieldVisibility);
    watchToolSelect?.addEventListener('change', updateWatchFieldVisibility);
    watchModeSelect?.addEventListener('change', updateWatchFieldVisibility);
    updateWatchFieldVisibility();

    document.getElementById('btn-wf-modal-preview-watch')?.addEventListener('click', () => {
      if (wf && wf.id) {
        openWatchPreviewModal(wf.id, wf.project || state.currentProject);
      }
    });

    // Toggle workflow type (steps vs pipeline)
    const typeSelect = document.getElementById('wf-modal-type');
    const pipelineCard = document.getElementById('wf-pipeline-card');
    const stepsSection = document.getElementById('wf-steps-section');
    const outputStepIdGroup = document.getElementById('wf-output-stepid-group');
    typeSelect?.addEventListener('change', () => {
      wfType = typeSelect.value;
      if (wfType === 'pipeline') {
        pipelineCard?.classList.remove('hidden');
        stepsSection?.classList.add('hidden');
        outputStepIdGroup?.classList.add('hidden');
        renderPipelineStages();
      } else {
        pipelineCard?.classList.add('hidden');
        stepsSection?.classList.remove('hidden');
        const outT = document.getElementById('wf-output-target')?.value || 'stdout';
        if (outT !== 'stdout') outputStepIdGroup?.classList.remove('hidden');
      }
    });

    // Toggle output target settings
    const outputTargetSelect = document.getElementById('wf-output-target');
    const outputPathGroup = document.getElementById('wf-output-path-group');
    const outputInboxGroup = document.getElementById('wf-output-inbox-group');
    outputTargetSelect?.addEventListener('change', () => {
      const targetVal = outputTargetSelect.value;
      if (targetVal === 'file') {
        outputPathGroup?.classList.remove('hidden');
        outputInboxGroup?.classList.remove('hidden');
      } else {
        outputPathGroup?.classList.add('hidden');
        outputInboxGroup?.classList.add('hidden');
      }
      if (wfType === 'steps' && targetVal !== 'stdout') {
        outputStepIdGroup?.classList.remove('hidden');
      } else {
        outputStepIdGroup?.classList.add('hidden');
      }
    });

    // Render pipeline stages
    const renderPipelineStages = () => {
      const listEl = document.getElementById('wf-pipeline-stages-list');
      if (!listEl) return;
      const curProj = document.getElementById('wf-modal-project')?.value || state.currentProject;
      const candWfs = getCandidateWorkflows(curProj);

      listEl.innerHTML = pipelineStages.map((st, idx) => `
        <div class="pipeline-stage-row">
          <span class="pipeline-stage-badge">${idx + 1}</span>
          <input type="text" class="form-input wf-stage-id" data-idx="${idx}" value="${escapeHtml(st.id || '')}" placeholder="阶段 ID" style="width: 110px; font-size: 11px; padding: 2px 6px;">
          <select class="form-select wf-stage-wf" data-idx="${idx}" style="flex: 2; font-size: 11px; padding: 2px 6px;">
            <option value="">— 选择同项目子工作流 —</option>
            ${candWfs.map(w => `
              <option value="${escapeHtml(w.id)}" ${st.workflowId === w.id ? 'selected' : ''}>${escapeHtml(w.title || w.id)}</option>
            `).join('')}
          </select>
          <select class="form-select wf-stage-when" data-idx="${idx}" style="width: 140px; font-size: 11px; padding: 2px 6px;" ${idx === 0 ? 'disabled' : ''}>
            <option value="always" ${st.when === 'always' ? 'selected' : ''} data-i18n="workflows.whenAlways">${escapeHtml(t('workflows.whenAlways'))}</option>
            <option value="has_output" ${st.when === 'has_output' ? 'selected' : ''} data-i18n="workflows.whenHasOutput">${escapeHtml(t('workflows.whenHasOutput'))}</option>
            <option value="no_output" ${st.when === 'no_output' ? 'selected' : ''} data-i18n="workflows.whenNoOutput">${escapeHtml(t('workflows.whenNoOutput'))}</option>
          </select>
          <div style="display: flex; gap: 2px;">
            <button type="button" class="btn-icon-subtle btn-stage-up" data-idx="${idx}" title="上移">↑</button>
            <button type="button" class="btn-icon-subtle btn-stage-down" data-idx="${idx}" title="下移">↓</button>
            <button type="button" class="btn-icon-subtle btn-stage-del" data-idx="${idx}" title="删除" style="color: var(--status-red-text);" ${pipelineStages.length <= 1 ? 'disabled' : ''}>×</button>
          </div>
        </div>
      `).join('');

      listEl.querySelectorAll('.wf-stage-id').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (pipelineStages[idx]) pipelineStages[idx].id = e.target.value.trim();
        });
      });
      listEl.querySelectorAll('.wf-stage-wf').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (pipelineStages[idx]) pipelineStages[idx].workflowId = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-stage-when').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (pipelineStages[idx] && idx > 0) pipelineStages[idx].when = e.target.value;
        });
      });
      listEl.querySelectorAll('.btn-stage-up').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          if (idx > 0) {
            const temp = pipelineStages[idx];
            pipelineStages[idx] = pipelineStages[idx - 1];
            pipelineStages[idx - 1] = temp;
            if (pipelineStages[0]) pipelineStages[0].when = 'always';
            renderPipelineStages();
          }
        });
      });
      listEl.querySelectorAll('.btn-stage-down').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          if (idx < pipelineStages.length - 1) {
            const temp = pipelineStages[idx];
            pipelineStages[idx] = pipelineStages[idx + 1];
            pipelineStages[idx + 1] = temp;
            if (pipelineStages[0]) pipelineStages[0].when = 'always';
            renderPipelineStages();
          }
        });
      });
      listEl.querySelectorAll('.btn-stage-del').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          if (pipelineStages.length > 1) {
            pipelineStages.splice(idx, 1);
            if (pipelineStages[0]) pipelineStages[0].when = 'always';
            renderPipelineStages();
          }
        });
      });
    };

    renderPipelineStages();

    document.getElementById('btn-add-pipeline-stage')?.addEventListener('click', () => {
      if (pipelineStages.length >= 16) {
        showToast('流水线最多支持 16 个阶段', 'warning');
        return;
      }
      pipelineStages.push({
        id: 'stage_' + (pipelineStages.length + 1),
        workflowId: '',
        when: 'always'
      });
      renderPipelineStages();
    });

    // Toggle workflow context body
    const contextEnableCb = document.getElementById('wf-context-enable');
    const contextBody = document.getElementById('wf-context-body');
    contextEnableCb?.addEventListener('change', () => {
      contextEnabled = Boolean(contextEnableCb.checked);
      if (contextBody) {
        if (contextEnabled) {
          contextBody.classList.remove('hidden');
        } else {
          contextBody.classList.add('hidden');
        }
      }
    });

    // Load guidelines for project
    const loadGuidelines = async (proj) => {
      const glContainer = document.getElementById('wf-guidelines-list');
      if (!glContainer) return;
      try {
        const list = await callBridge('guidelines.list', proj ? { project: proj } : {});
        const arr = Array.isArray(list) ? list : [];
        if (arr.length === 0) {
          glContainer.innerHTML = `<span style="font-size: 11px; color: var(--text-muted);">无可用工程规约</span>`;
          return;
        }
        glContainer.innerHTML = arr.map(g => `
          <label class="form-checkbox-label" style="font-size: 11px; margin-bottom: 2px;">
            <input type="checkbox" class="wf-guideline-cb" value="${escapeHtml(g.id)}" ${selectedGuidelines.includes(g.id) ? 'checked' : ''}>
            <span>${escapeHtml(g.title || g.id)}</span>
          </label>
        `).join('');
      } catch {
        glContainer.innerHTML = `<span style="font-size: 11px; color: var(--text-muted);">加载规约失败</span>`;
      }
    };

    const projectSelect = document.getElementById('wf-modal-project');
    loadGuidelines(projectSelect?.value || state.currentProject);
    projectSelect?.addEventListener('change', () => {
      loadGuidelines(projectSelect.value);
    });

    // Context Inputs Builder
    const renderContextInputs = () => {
      const listEl = document.getElementById('wf-context-inputs-list');
      if (!listEl) return;
      if (contextInputs.length === 0) {
        listEl.innerHTML = `<div style="font-size: 11px; color: var(--text-muted); padding: 4px 0;">未添加上下文输入源</div>`;
        return;
      }
      const curProj = document.getElementById('wf-modal-project')?.value || state.currentProject;
      const candWfs = getCandidateWorkflows(curProj);

      listEl.innerHTML = contextInputs.map((inp, idx) => `
        <div style="padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px; font-size: 11px;">
          <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <input type="text" class="form-input wf-inp-id" data-idx="${idx}" value="${escapeHtml(inp.id || '')}" placeholder="${escapeHtml(t('workflows.inputIdLabel'))}" style="width: 120px; font-size: 11px; padding: 2px 6px;">
            <select class="form-select wf-inp-type" data-idx="${idx}" style="width: 140px; font-size: 11px; padding: 2px 6px;">
              <option value="tool" ${inp.type === 'tool' ? 'selected' : ''} data-i18n="workflows.inputTypeTool">${escapeHtml(t('workflows.inputTypeTool'))}</option>
              <option value="retrieve" ${inp.type === 'retrieve' ? 'selected' : ''} data-i18n="workflows.inputTypeRetrieve">${escapeHtml(t('workflows.inputTypeRetrieve'))}</option>
              <option value="stdin" ${inp.type === 'stdin' ? 'selected' : ''} data-i18n="workflows.inputTypeStdin">${escapeHtml(t('workflows.inputTypeStdin'))}</option>
              <option value="value" ${inp.type === 'value' ? 'selected' : ''} data-i18n="workflows.inputTypeValue">${escapeHtml(t('workflows.inputTypeValue'))}</option>
              <option value="workflow" ${inp.type === 'workflow' ? 'selected' : ''} data-i18n="workflows.sourceWorkflow">${escapeHtml(t('workflows.sourceWorkflow'))}</option>
            </select>
            <label class="form-checkbox-label" style="font-size: 11px; margin-bottom: 0; margin-left: auto;">
              <input type="checkbox" class="wf-inp-opt" data-idx="${idx}" ${inp.optional ? 'checked' : ''}>
              <span data-i18n="workflows.inputOptionalLabel">${escapeHtml(t('workflows.inputOptionalLabel'))}</span>
            </label>
            <button type="button" class="btn-icon-subtle btn-del-context-input" data-idx="${idx}" style="color: var(--status-red-text);">×</button>
          </div>
          ${inp.type === 'tool' ? `
            <div style="display: flex; align-items: center; gap: 6px;">
              <span class="text-secondary">Git:</span>
              <select class="form-select wf-inp-tool-sel" data-idx="${idx}" style="font-size: 11px; padding: 2px 6px; width: 140px;">
                <option value="git.status" ${(inp.tool || 'git.status') === 'git.status' ? 'selected' : ''}>git.status</option>
                <option value="git.diff" ${inp.tool === 'git.diff' ? 'selected' : ''}>git.diff</option>
                <option value="git.log" ${inp.tool === 'git.log' ? 'selected' : ''}>git.log</option>
              </select>
            </div>
          ` : ''}
          ${inp.type === 'retrieve' ? `
            <div style="display: flex; align-items: center; gap: 6px;">
              <input type="text" class="form-input wf-inp-query" data-idx="${idx}" value="${escapeHtml(inp.query || '')}" placeholder="${escapeHtml(t('workflows.retrieveQueryLabel'))}" style="flex: 1; font-size: 11px; padding: 2px 6px;">
              <input type="number" class="form-input wf-inp-k" data-idx="${idx}" value="${escapeHtml(String(inp.k || 5))}" min="1" max="20" placeholder="k" style="width: 50px; font-size: 11px; padding: 2px 6px;">
            </div>
          ` : ''}
          ${inp.type === 'stdin' ? `
            <div style="color: var(--text-muted); font-size: 10px;">${escapeHtml(t('workflows.runInputsDesc'))}</div>
          ` : ''}
          ${inp.type === 'value' ? `
            <input type="text" class="form-input wf-inp-val" data-idx="${idx}" value="${escapeHtml(inp.value || '')}" placeholder="Literal value" style="width: 100%; font-size: 11px; padding: 2px 6px;">
          ` : ''}
          ${inp.type === 'workflow' ? `
            <div style="display: flex; flex-direction: column; gap: 4px; margin-top: 4px;">
              <div style="display: flex; align-items: center; gap: 6px;">
                <span class="text-secondary" style="font-size: 11px;" data-i18n="workflows.subworkflowSelectLabel">${escapeHtml(t('workflows.subworkflowSelectLabel'))}:</span>
                <select class="form-select wf-inp-subwf-sel" data-idx="${idx}" style="font-size: 11px; padding: 2px 6px; flex: 1;">
                  <option value="">— 选择同项目子工作流 —</option>
                  ${candWfs.map(w => `
                    <option value="${escapeHtml(w.id)}" ${inp.subworkflowId === w.id ? 'selected' : ''}>${escapeHtml(w.title || w.id)}</option>
                  `).join('')}
                </select>
              </div>
              <div style="display: flex; gap: 6px;">
                <input type="text" class="form-input wf-inp-subwf-inputs" data-idx="${idx}" value="${escapeHtml(inp.subworkflowInputs || '')}" placeholder="${escapeHtml(t('workflows.subworkflowInputsLabel'))} (如 {'topic': '...'})" style="flex: 1; font-size: 11px; padding: 2px 6px; font-family: var(--font-mono);">
                <input type="text" class="form-input wf-inp-subwf-stdin" data-idx="${idx}" value="${escapeHtml(inp.subworkflowStdin || '')}" placeholder="${escapeHtml(t('workflows.subworkflowStdinLabel'))} (如 {{earlier.text}})" style="flex: 1; font-size: 11px; padding: 2px 6px; font-family: var(--font-mono);">
              </div>
            </div>
          ` : ''}
        </div>
      `).join('');

      listEl.querySelectorAll('.wf-inp-id').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].id = e.target.value.trim();
        });
      });
      listEl.querySelectorAll('.wf-inp-type').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (!contextInputs[idx]) return;
          contextInputs[idx].type = e.target.value;
          if (e.target.value === 'tool') contextInputs[idx].tool = 'git.status';
          if (e.target.value === 'retrieve') { contextInputs[idx].query = ''; contextInputs[idx].k = 5; }
          if (e.target.value === 'workflow') { contextInputs[idx].subworkflowId = ''; contextInputs[idx].subworkflowInputs = ''; contextInputs[idx].subworkflowStdin = ''; }
          renderContextInputs();
        });
      });
      listEl.querySelectorAll('.wf-inp-opt').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].optional = e.target.checked;
        });
      });
      listEl.querySelectorAll('.wf-inp-tool-sel').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].tool = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-inp-query').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].query = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-inp-k').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].k = parseInt(e.target.value, 10) || 5;
        });
      });
      listEl.querySelectorAll('.wf-inp-val').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].value = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-inp-subwf-sel').forEach(el => {
        el.addEventListener('change', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].subworkflowId = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-inp-subwf-inputs').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].subworkflowInputs = e.target.value;
        });
      });
      listEl.querySelectorAll('.wf-inp-subwf-stdin').forEach(el => {
        el.addEventListener('input', e => {
          const idx = parseInt(el.getAttribute('data-idx'), 10);
          if (contextInputs[idx]) contextInputs[idx].subworkflowStdin = e.target.value;
        });
      });
      listEl.querySelectorAll('.btn-del-context-input').forEach(el => {
        el.addEventListener('click', () => {
          contextInputs.splice(parseInt(el.getAttribute('data-idx'), 10), 1);
          renderContextInputs();
        });
      });
    };

    renderContextInputs();

    document.getElementById('btn-add-context-input')?.addEventListener('click', () => {
      contextInputs.push({
        id: 'input_' + (contextInputs.length + 1),
        type: 'tool',
        tool: 'git.status',
        optional: false
      });
      renderContextInputs();
    });

    const renderSteps = () => {
      const container = document.getElementById('wf-steps-list');
      if (!container) return;
      container.innerHTML = steps.map((s, idx) => `
        <div class="card" style="padding: 8px 10px; margin-bottom: 0; background: var(--bg-subtle);">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <input type="text" class="form-input wf-step-title" data-idx="${idx}" value="${escapeHtml(s.title || '')}" data-i18n-placeholder="workflows.stepTitlePlaceholder" placeholder="${escapeHtml(t('workflows.stepTitlePlaceholder'))}" style="width: 160px; font-size: 11px; padding: 2px 6px;">
            <select class="form-select wf-step-tool" data-idx="${idx}" style="font-size: 11px; padding: 2px 6px;">
              <option value="git.status" ${s.tool === 'git.status' ? 'selected' : ''}>git.status (只读)</option>
              <option value="git.diff" ${s.tool === 'git.diff' ? 'selected' : ''}>git.diff (只读)</option>
              <option value="git.log" ${s.tool === 'git.log' ? 'selected' : ''}>git.log (只读)</option>
              <option value="shell.test" ${s.tool === 'shell.test' ? 'selected' : ''}>shell.test (需要审批)</option>
              <option value="shell.typecheck" ${s.tool === 'shell.typecheck' ? 'selected' : ''}>shell.typecheck (需要审批)</option>
              <option value="file.write" ${s.tool === 'file.write' ? 'selected' : ''}>file.write (需要审批)</option>
              <option value="agent.run" ${s.tool === 'agent.run' ? 'selected' : ''}>agent.run (需要审批)</option>
              <option value="connector.call" ${s.tool === 'connector.call' ? 'selected' : ''}>connector.call (外部连接器)</option>
            </select>
            <div style="display: flex; gap: 2px;">
              <button type="button" class="btn-icon-subtle btn-step-up" data-idx="${idx}" data-i18n-title="workflows.btnStepUp" title="${escapeHtml(t('workflows.btnStepUp'))}">↑</button>
              <button type="button" class="btn-icon-subtle btn-step-down" data-idx="${idx}" data-i18n-title="workflows.btnStepDown" title="${escapeHtml(t('workflows.btnStepDown'))}">↓</button>
              <button type="button" class="btn-icon-subtle btn-step-del" data-idx="${idx}" data-i18n-title="workflows.btnStepDel" title="${escapeHtml(t('workflows.btnStepDel'))}" style="color: var(--status-red-text);">×</button>
            </div>
          </div>
          <div>
            <textarea class="form-textarea code-editor wf-step-args" data-idx="${idx}" style="min-height: 56px; font-size: 12px; padding: 6px 8px;" placeholder="${s.tool === 'agent.run' ? escapeHtml(t('workflows.stepArgsAgentPlaceholder')) : escapeHtml(t('workflows.stepArgsPlaceholder'))}">${escapeHtml(typeof s.arguments === 'object' ? JSON.stringify(s.arguments, null, 2) : s.arguments || '{}')}</textarea>
            ${s.tool === 'agent.run' ? `
              <div style="display: flex; align-items: center; justify-content: space-between; margin-top: 6px; padding: 4px 8px; background: var(--bg-main); border-radius: 4px; border: 1px solid var(--border-color); font-size: 11px;">
                <div style="display: flex; align-items: center; gap: 6px;">
                  <span>${escapeHtml(t('workflows.contextSectionTitle'))}:</span>
                  ${(s.arguments && s.arguments.promptMode === 'workflow_context') ? `
                    <span class="status-badge status-sage" data-i18n="workflows.contextDeliveryEnabledBadge">${escapeHtml(t('workflows.contextDeliveryEnabledBadge'))}</span>
                  ` : `
                    <span class="status-badge status-neutral">未注入上下文</span>
                  `}
                </div>
                <button type="button" class="btn btn-ghost btn-sm btn-toggle-step-context" data-idx="${idx}" style="font-size: 11px; padding: 1px 6px;">
                  ${(s.arguments && s.arguments.promptMode === 'workflow_context') ? '取消上下文' : escapeHtml(t('workflows.btnEnableContextDelivery'))}
                </button>
              </div>
              <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;" data-i18n="workflows.agentRunNotice">${escapeHtml(t('workflows.agentRunNotice'))}</div>
            ` : ''}
          </div>
        </div>
      `).join('');

      container.querySelectorAll('.wf-step-title').forEach(inp => {
        inp.addEventListener('input', (e) => {
          steps[parseInt(inp.getAttribute('data-idx'), 10)].title = e.target.value;
        });
      });

      container.querySelectorAll('.wf-step-tool').forEach(sel => {
        sel.addEventListener('change', (e) => {
          const idx = parseInt(sel.getAttribute('data-idx'), 10);
          const tool = e.target.value;
          steps[idx].tool = tool;
          if (tool === 'shell.test') {
            steps[idx].arguments = { executable: 'npm', args: ['test'], timeoutSeconds: 60 };
          } else if (tool === 'shell.typecheck') {
            steps[idx].arguments = { executable: 'npm', args: ['run', 'typecheck'], timeoutSeconds: 60 };
          } else if (tool === 'file.write') {
            steps[idx].arguments = { path: 'relative.txt', content: '...' };
          } else if (tool === 'agent.run') {
            steps[idx].arguments = { executable: '', args: [], timeoutSeconds: 120 };
          } else if (tool === 'connector.call') {
            steps[idx].arguments = {
              toolSlug: '',
              version: '1.0.0',
              catalogHash: '',
              connectedAccountId: '',
              arguments: {}
            };
          } else {
            steps[idx].arguments = {};
          }
          renderSteps();
        });
      });

      container.querySelectorAll('.btn-toggle-step-context').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          const st = steps[idx];
          if (!st || st.tool !== 'agent.run') return;
          if (typeof st.arguments !== 'object' || st.arguments === null) {
            st.arguments = {};
          }
          if (st.arguments.promptMode === 'workflow_context') {
            delete st.arguments.promptMode;
            if (Array.isArray(st.arguments.args)) {
              st.arguments.args = st.arguments.args.filter(a => a !== '{{vela.prompt}}');
            }
          } else {
            st.arguments.promptMode = 'workflow_context';
            if (!Array.isArray(st.arguments.args)) {
              st.arguments.args = [];
            }
            if (!st.arguments.args.includes('{{vela.prompt}}')) {
              st.arguments.args.push('{{vela.prompt}}');
            }
          }
          renderSteps();
        });
      });

      container.querySelectorAll('.wf-step-args').forEach(tx => {
        tx.addEventListener('change', (e) => {
          const idx = parseInt(tx.getAttribute('data-idx'), 10);
          try {
            steps[idx].arguments = JSON.parse(e.target.value);
          } catch {
            steps[idx].arguments = e.target.value;
          }
        });
      });

      container.querySelectorAll('.btn-step-up').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          if (idx > 0) {
            const temp = steps[idx];
            steps[idx] = steps[idx - 1];
            steps[idx - 1] = temp;
            renderSteps();
          }
        });
      });

      container.querySelectorAll('.btn-step-down').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          if (idx < steps.length - 1) {
            const temp = steps[idx];
            steps[idx] = steps[idx + 1];
            steps[idx + 1] = temp;
            renderSteps();
          }
        });
      });

      container.querySelectorAll('.btn-step-del').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          steps.splice(idx, 1);
          renderSteps();
        });
      });
    };

    renderSteps();

    document.getElementById('btn-add-step').addEventListener('click', () => {
      steps.push({
        id: 'step-' + (steps.length + 1),
        title: t('workflows.newStepDefaultTitle'),
        tool: 'git.status',
        arguments: {}
      });
      renderSteps();
    });

    document.getElementById('btn-cancel-wf').addEventListener('click', closeModal);
    document.getElementById('btn-save-wf').addEventListener('click', async () => {
      const title = document.getElementById('wf-modal-title').value.trim();
      const project = document.getElementById('wf-modal-project').value;
      const description = document.getElementById('wf-modal-desc').value.trim();
      const trigger = document.getElementById('wf-modal-trigger').value;

      if (!title) {
        showToast({ key: 'workflows.titleRequired' }, 'error');
        return;
      }
      if (!project) {
        showToast({ key: 'workflows.projectRequired' }, 'error');
        return;
      }

      let cron = undefined;
      let timeZone = undefined;
      let catchUp = undefined;
      let catchUpLimit = undefined;
      let catchUpWindowHours = undefined;

      if (trigger === 'cron') {
        cron = document.getElementById('wf-modal-cron').value.trim();
        if (!cron) {
          showToast('Cron 表达式不能为空', 'error');
          return;
        }
        timeZone = document.getElementById('wf-modal-timezone').value.trim() || undefined;
        catchUp = document.getElementById('wf-modal-catchup').value;
        const rawLimit = parseInt(document.getElementById('wf-modal-catchup-limit').value, 10);
        if (isNaN(rawLimit) || rawLimit < 1 || rawLimit > 100) {
          showToast({ key: 'workflows.catchUpLimitLabel' }, 'error');
          return;
        }
        catchUpLimit = rawLimit;

        const rawWindow = parseInt(document.getElementById('wf-modal-catchup-window').value, 10);
        if (isNaN(rawWindow) || rawWindow < 1 || rawWindow > 168) {
          showToast({ key: 'workflows.catchUpWindowLabel' }, 'error');
          return;
        }
        catchUpWindowHours = rawWindow;
      }

      const wfTypeVal = document.getElementById('wf-modal-type')?.value || 'steps';
      const outTarget = document.getElementById('wf-output-target')?.value || 'stdout';

      if ((trigger === 'cron' || trigger === 'watch') && outTarget === 'stdout') {
        showToast({ key: 'workflows.scheduledOutputMustBeDurable' }, 'error');
        return;
      }

      let watchObj = undefined;
      if (trigger === 'watch') {
        const wSource = document.getElementById('wf-watch-source')?.value || 'tool';
        if (wSource === 'files') {
          const rawPathsText = (document.getElementById('wf-watch-paths')?.value || '').trim();
          const paths = rawPathsText.split('\n').map(s => s.trim()).filter(Boolean);
          if (paths.length === 0) {
            showToast({ key: 'watch.pathsRequired' }, 'error');
            return;
          }
          if (paths.length > 16) {
            showToast({ key: 'watch.pathsLimitExceeded' }, 'error');
            return;
          }
          if (new Set(paths).size !== paths.length) {
            showToast({ key: 'watch.pathsDuplicate' }, 'error');
            return;
          }
          const defaultEx = ['.git', '.vela', '.build', 'node_modules', '.DS_Store'];
          for (const p of paths) {
            if (p === '.') continue;
            if (p.startsWith('/') || p.endsWith('/') || p.includes('\0') || p.length > 1024) {
              showToast({ key: 'watch.pathsInvalidFormat' }, 'error');
              return;
            }
            const parts = p.split('/');
            if (parts.length > 32 || parts.some(part => !part || part === '.' || part === '..')) {
              showToast({ key: 'watch.pathsInvalidFormat' }, 'error');
              return;
            }
            if (parts.some(part => defaultEx.includes(part))) {
              showToast({ key: 'watch.pathsExcluded' }, 'error');
              return;
            }
          }
          for (const p of paths) {
            const hasOverlap = paths.some(other => {
              if (other === p) return false;
              if (p === '.') return true;
              return other.startsWith(p + '/');
            });
            if (hasOverlap) {
              showToast({ key: 'watch.pathsOverlap' }, 'error');
              return;
            }
          }

          const recursive = Boolean(document.getElementById('wf-watch-recursive')?.checked);
          const rawIgnoreText = (document.getElementById('wf-watch-ignore')?.value || '').trim();
          const ignore = rawIgnoreText.split('\n').map(s => s.trim()).filter(Boolean);
          if (ignore.length > 32) {
            showToast({ key: 'watch.ignoreLimitExceeded' }, 'error');
            return;
          }
          for (const ig of ignore) {
            if (ig.startsWith('/') || ig.includes('\0') || ig.split('/').includes('..') || ig.length > 160) {
              showToast({ key: 'watch.ignoreInvalid' }, 'error');
              return;
            }
          }

          const wMin = Math.max(1, Math.min(100, parseInt(document.getElementById('wf-watch-min-items')?.value, 10) || 1));
          const wDebounce = Math.max(0, Math.min(300, parseInt(document.getElementById('wf-watch-debounce')?.value, 10) || 5));

          watchObj = {
            source: 'files',
            paths: [...paths].sort(),
            recursive: recursive,
            ignore: ignore,
            minItems: wMin,
            debounceSeconds: wDebounce
          };
        } else {
          const wTool = document.getElementById('wf-watch-tool')?.value || 'git.status';
          const wMode = document.getElementById('wf-watch-mode')?.value || (wTool.startsWith('git.') ? 'output' : 'items');
          const wKey = wMode === 'items' ? (document.getElementById('wf-watch-key')?.value.trim() || 'id') : undefined;
          const wEvery = Math.max(30, Math.min(86400, parseInt(document.getElementById('wf-watch-every')?.value, 10) || 60));
          const wMin = wMode === 'output' ? 1 : Math.max(1, Math.min(100, parseInt(document.getElementById('wf-watch-min-items')?.value, 10) || 1));
          const wDebounce = Math.max(0, Math.min(300, parseInt(document.getElementById('wf-watch-debounce')?.value, 10) || 10));

          let wArgs = {};
          if (wTool === 'memory.recall') {
            const q = (document.getElementById('wf-watch-arg-query')?.value || '').trim();
            const tok = Math.max(1, Math.min(2000, parseInt(document.getElementById('wf-watch-arg-tokens')?.value, 10) || 1000));
            wArgs = { query: q, budgetTokens: tok };
          } else if (wTool === 'library.retrieve') {
            const q = (document.getElementById('wf-watch-arg-query')?.value || '').trim();
            const kVal = Math.max(1, Math.min(10, parseInt(document.getElementById('wf-watch-arg-k')?.value, 10) || 10));
            wArgs = { query: q, k: kVal };
          } else {
            wArgs = {};
          }

          watchObj = {
            source: 'tool',
            tool: wTool,
            arguments: wArgs,
            mode: wMode,
            everySeconds: wEvery,
            minItems: wMin,
            debounceSeconds: wDebounce
          };
          if (wKey) {
            watchObj.key = wKey;
          }
        }
      }

      let outputObj = undefined;
      if (outTarget === 'file') {
        const outPath = (document.getElementById('wf-output-path')?.value || '').trim();
        if (!outPath) {
          showToast('请输入交付文件的相对路径', 'error');
          return;
        }
        outputObj = {
          target: 'file',
          path: outPath,
          inbox: Boolean(document.getElementById('wf-output-inbox')?.checked),
          stepId: wfTypeVal === 'steps' ? (document.getElementById('wf-output-step-id')?.value.trim() || undefined) : undefined
        };
      } else if (outTarget === 'inbox') {
        outputObj = {
          target: 'inbox',
          stepId: wfTypeVal === 'steps' ? (document.getElementById('wf-output-step-id')?.value.trim() || undefined) : undefined
        };
      } else if (outTarget === 'stdout') {
        outputObj = { target: 'stdout' };
      }

      let payload = null;

      if (wfTypeVal === 'pipeline') {
        if (pipelineStages.length < 1 || pipelineStages.length > 16) {
          showToast('流水线阶段数量必须在 1 到 16 之间', 'error');
          return;
        }
        for (let i = 0; i < pipelineStages.length; i++) {
          const st = pipelineStages[i];
          if (!st.id || !st.id.trim()) {
            showToast(`流水线第 ${i + 1} 阶段缺少有效 ID`, 'error');
            return;
          }
          if (!st.workflowId || !st.workflowId.trim()) {
            showToast(`流水线第 ${i + 1} 阶段未选择子工作流`, 'error');
            return;
          }
        }

        payload = {
          id: (wf && wf.id) ? wf.id : undefined,
          title,
          project,
          description,
          trigger,
          cron,
          timeZone,
          catchUp,
          catchUpLimit,
          catchUpWindowHours,
          watch: watchObj,
          enabled: wf ? wf.enabled : true,
          pipeline: pipelineStages.map((st, idx) => ({
            id: st.id.trim(),
            workflowId: st.workflowId.trim(),
            when: idx === 0 ? 'always' : (st.when || 'always')
          })),
          output: outputObj
        };
      } else {
        for (const s of steps) {
          if (typeof s.arguments === 'string') {
            try {
              s.arguments = JSON.parse(s.arguments);
            } catch {
              showToast({ key: 'workflows.invalidArgsJson', params: { title: s.title } }, 'error');
              return;
            }
          }
          if (['agent.run', 'shell.test', 'shell.typecheck'].includes(s.tool)) {
            const argsObj = s.arguments;
            if (!argsObj || typeof argsObj !== 'object' || Array.isArray(argsObj)) {
              showToast({ key: 'workflows.argsMustBeObject', params: { title: s.title } }, 'error');
              return;
            }
            if (typeof argsObj.executable !== 'string' || !argsObj.executable.trim()) {
              showToast({ key: 'workflows.executableRequired', params: { title: s.title, tool: s.tool } }, 'error');
              return;
            }
            if (!Array.isArray(argsObj.args) || !argsObj.args.every(a => typeof a === 'string')) {
              showToast({ key: 'workflows.argsMustBeStringArray', params: { title: s.title, tool: s.tool } }, 'error');
              return;
            }
          }
        }

        let contextObj = undefined;
        if (contextEnabled) {
          const template = (document.getElementById('wf-context-template')?.value || '').trim();
          if (!template) {
            showToast({ key: 'workflows.contextTemplateRequired' }, 'error');
            return;
          }

          // Must have at least one agent.run with promptMode === 'workflow_context' and exactly one {{vela.prompt}}
          const contextualAgentStep = steps.find(s => {
            if (s.tool !== 'agent.run' || !s.arguments) return false;
            if (s.arguments.promptMode !== 'workflow_context') return false;
            const args = s.arguments.args || [];
            return Array.isArray(args) && args.filter(a => a === '{{vela.prompt}}').length === 1 && args.filter(a => a.includes('{{vela.prompt}}')).length === 1;
          });

          if (!contextualAgentStep) {
            showToast({ key: 'workflows.contextMissingAgentStep' }, 'error');
            return;
          }

          // Validate context inputs
          const normalizedInputs = [];
          const seenIds = new Set();
          const reservedIds = ['input', 'guidelines', 'memory', 'config', 'vela'];
          const idRegex = /^[A-Za-z_][A-Za-z0-9_]{0,63}$/;

          for (const inp of contextInputs) {
            const inpId = (inp.id || '').trim();
            if (!inpId || !idRegex.test(inpId) || reservedIds.includes(inpId) || seenIds.has(inpId)) {
              showToast(`输入标识 ID 无效或重复: ${inpId || '未命名'}`, 'error');
              return;
            }
            seenIds.add(inpId);

            const item = { id: inpId, optional: Boolean(inp.optional) };
            if (inp.type === 'tool') {
              item.tool = inp.tool || 'git.status';
              item.arguments = inp.arguments || {};
            } else if (inp.type === 'retrieve') {
              item.retrieve = {
                query: (inp.query || '').trim(),
                k: Math.max(1, Math.min(20, parseInt(inp.k, 10) || 5))
              };
            } else if (inp.type === 'stdin') {
              item.source = 'stdin';
            } else if (inp.type === 'workflow') {
              let subInputs = undefined;
              if (inp.subworkflowInputs) {
                try {
                  subInputs = typeof inp.subworkflowInputs === 'object' ? inp.subworkflowInputs : JSON.parse(inp.subworkflowInputs);
                } catch {
                  subInputs = undefined;
                }
              }
              item.workflow = {
                id: (inp.subworkflowId || '').trim(),
                inputs: subInputs,
                stdin: (inp.subworkflowStdin || '').trim() || undefined
              };
            } else {
              item.value = inp.value || '';
            }
            normalizedInputs.push(item);
          }

          const memEnabled = Boolean(document.getElementById('wf-context-mem-enable')?.checked);
          const memBudget = Math.max(0, Math.min(4000, parseInt(document.getElementById('wf-context-mem-budget')?.value, 10) || 2000));

          contextObj = {
            version: 1,
            template,
            inputs: normalizedInputs,
            memory: {
              enabled: memEnabled,
              budgetTokens: memBudget
            }
          };
        } else {
          // Strip workflow_context promptMode if context is disabled
          steps.forEach(s => {
            if (s.arguments && s.arguments.promptMode === 'workflow_context') {
              delete s.arguments.promptMode;
              if (Array.isArray(s.arguments.args)) {
                s.arguments.args = s.arguments.args.filter(a => a !== '{{vela.prompt}}');
              }
            }
          });
        }

        const checkedGuidelines = Array.from(document.querySelectorAll('.wf-guideline-cb:checked')).map(cb => cb.value);

        payload = {
          id: (wf && wf.id) ? wf.id : undefined,
          title,
          project,
          description,
          trigger,
          cron,
          timeZone,
          catchUp,
          catchUpLimit,
          catchUpWindowHours,
          watch: watchObj,
          enabled: wf ? wf.enabled : true,
          guidelines: checkedGuidelines,
          context: contextObj,
          steps,
          output: outputObj
        };
      }

      try {
        await callBridge('workflows.save', payload);
        showToast({ key: 'workflows.savedToast' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        showToast({ key: 'workflows.saveFailedToast', params: { error: err.message } }, 'error');
      }
    });
  }

  // -------------------------------------------------------------------------
  // 3. SETUP VIEW (Complete Memory lifecycle, Guidelines editor, Library URL/Path)
  // -------------------------------------------------------------------------
  function renderSetupView(container) {
    container.innerHTML = `
      <div class="page-header">
        <div class="page-title-group">
          <h1 data-i18n="setupL.header.title">${escapeHtml(t('setupL.header.title'))}</h1>
          <p data-i18n="setupL.header.desc">${escapeHtml(t('setupL.header.desc'))}</p>
        </div>
        <div class="page-actions">
          <button id="btn-scan-setup" class="btn btn-secondary btn-sm" data-i18n="setupL.actions.scan">${escapeHtml(t('setupL.actions.scan'))}</button>
          ${actionMenu(`<button id="btn-open-setup-memory" class="btn" type="button" data-i18n="setupL.tabs.memoryHome">${escapeHtml(t('setupL.tabs.memoryHome'))}</button><button id="btn-audit-setup" class="btn btn-secondary btn-sm" data-i18n="setupL.actions.audit">${escapeHtml(t('setupL.actions.audit'))}</button><button id="btn-catalog-setup" class="btn btn-secondary btn-sm" data-i18n="setup.catalogBtn">${escapeHtml(t('setup.catalogBtn'))}</button>`)}
        </div>
      </div>

      <div class="tabs-nav">
        <button class="tab-btn ${state.setupActiveTab === 'rules' ? 'active' : ''}" data-setuptab="rules" data-i18n="setupL.tabs.rules">${escapeHtml(t('setupL.tabs.rules'))}</button>
        <button class="tab-btn ${state.setupActiveTab === 'skills' ? 'active' : ''}" data-setuptab="skills" data-i18n="setupL.tabs.skills">${escapeHtml(t('setupL.tabs.skills'))}</button>
        <button class="tab-btn ${state.setupActiveTab === 'hooks' ? 'active' : ''}" data-setuptab="hooks" data-i18n="setupL.tabs.hooks">${escapeHtml(t('setupL.tabs.hooks'))}</button>
        <button class="tab-btn ${state.setupActiveTab === 'mcp' ? 'active' : ''}" data-setuptab="mcp" data-i18n="setupL.tabs.mcp">${escapeHtml(t('setupL.tabs.mcp'))}</button>
        <button class="tab-btn ${state.setupActiveTab === 'guidelines' ? 'active' : ''}" data-setuptab="guidelines" data-i18n="setupL.tabs.guidelines">${escapeHtml(t('setupL.tabs.guidelines'))}</button>
        <button class="tab-btn ${state.setupActiveTab === 'library' ? 'active' : ''}" data-setuptab="library" data-i18n="setupL.tabs.library">${escapeHtml(t('setupL.tabs.library'))}</button>
      </div>

      <div id="setup-tab-content"></div>
    `;

    syncViewButtons(container, 'data-setuptab', state.setupActiveTab);
    container.querySelectorAll('[data-setuptab]').forEach(tab => {
      tab.addEventListener('click', () => {
        state.setupActiveTab = tab.getAttribute('data-setuptab');
        syncViewButtons(container, 'data-setuptab', state.setupActiveTab);
        renderSetupTabContent();
      });
    });

    // Memory has one home in the primary navigation. Setup keeps an explicit route
    // so the legacy entry remains discoverable without rendering a second list.
    document.getElementById('btn-open-setup-memory')?.addEventListener('click', () => navigateTo('memory'));

    document.getElementById('btn-catalog-setup')?.addEventListener('click', openSetupCatalogModal);

    document.getElementById('btn-scan-setup').addEventListener('click', async () => {
      try {
        await callBridge('setup.scan', state.currentProject ? { project: state.currentProject } : {});
        showToast({ key: 'setupL.toast.scanSuccess' });
        await refreshDashboard(true, true);
      } catch (e) {
        showToast({ key: 'setupL.toast.scanFailed', params: { error: e.message } }, 'error');
      }
    });

    document.getElementById('btn-audit-setup').addEventListener('click', async () => {
      try {
        const res = await callBridge('setup.audit', state.currentProject ? { project: state.currentProject } : {});
        const diag = (res && res.diagnostics) || [];
        if (diag.length === 0) {
          showToast({ key: 'setupL.toast.auditPassed' }, 'info');
        } else {
          showToast({ key: 'setupL.toast.auditWarning', params: { count: diag.length } }, 'warning');
        }
      } catch (e) {
        showToast({ key: 'setupL.toast.auditFailed', params: { error: e.message } }, 'error');
      }
    });

    renderSetupTabContent();
  }

  function renderSetupTabContent() {
    const target = document.getElementById('setup-tab-content');
    if (!target) return;

    if (state.setupActiveTab === 'memory') state.setupActiveTab = 'rules';
    if (state.setupActiveTab === 'guidelines') {
      renderGuidelinesSection(target);
    } else if (state.setupActiveTab === 'library') {
      renderLibrarySection(target);
    } else if (state.setupActiveTab === 'mcp') {
      renderMcpSection(target);
    } else {
      renderArtifactsSection(target, state.setupActiveTab);
    }
  }

  function getSetupContentStatusBadge(status) {
    switch (status) {
      case 'sanitized': return `<span class="status-badge status-sage" data-i18n="setup.statusSanitized">${escapeHtml(t('setup.statusSanitized'))}</span>`;
      case 'metadata_only_mixed_auth_store': return `<span class="status-badge status-amber" data-i18n="setup.statusMetadataOnly">${escapeHtml(t('setup.statusMetadataOnly'))}</span>`;
      case 'withheld_unparsed_configuration': return `<span class="status-badge status-amber" data-i18n="setup.statusUnparsedConfig">${escapeHtml(t('setup.statusUnparsedConfig'))}</span>`;
      case 'withheld_invalid_json': return `<span class="status-badge status-amber" data-i18n="setup.statusInvalidJson">${escapeHtml(t('setup.statusInvalidJson'))}</span>`;
      case 'unavailable': return `<span class="status-badge status-red" data-i18n="setup.statusUnavailable">${escapeHtml(t('setup.statusUnavailable'))}</span>`;
      case 'source_missing': return `<span class="status-badge status-neutral" data-i18n="setup.statusSourceMissing">${escapeHtml(t('setup.statusSourceMissing'))}</span>`;
      default: return '';
    }
  }

  function openArtifactDrawer(art) {
    const loc = formatAssetLocation(art.path, art.scope, state.currentProject);
    const projectLabel = setupProjectLabel(art.project);
    openDrawer(setupAssetDisplayName(art) || { key: 'setupL.artifacts.drawerTitle' }, art.scope !== 'global' && projectLabel ? `${projectLabel} · ${loc.relativePath}` : loc.displayText);
    const drawerContent = document.getElementById('drawer-content');
    if (!drawerContent) return;

    const assetDiag = Array.isArray(art.diagnostics) ? art.diagnostics : [];
    const assetContentStatus = art.contentStatus ? getSetupContentStatusBadge(art.contentStatus) : '';

    drawerContent.innerHTML = `
      <section>
        <h3 class="section-heading" data-i18n="setupL.drawer.readonlyPreview">${escapeHtml(t('setupL.drawer.readonlyPreview'))}</h3>
        ${assetDiag.length > 0 ? `<p class="setup-row-diag" role="status" data-i18n="asset.diagnosticsFound" data-i18n-params="${escapeHtml(JSON.stringify({ count: assetDiag.length }))}">${escapeHtml(t('asset.diagnosticsFound', { count: assetDiag.length }))}</p>` : ''}
        <div data-setup-document>${art.content ? VelaContent.file(art.content, art.path || setupAssetDisplayName(art)) : `<p class="text-secondary">${tHtml('setupL.drawer.noContent')}</p>`}</div>
        <div style="display: flex; gap: 6px; margin-top: 12px; flex-wrap: wrap;">
          <button class="btn btn-secondary btn-sm btn-drawer-setup-history" data-id="${escapeHtml(art.id)}" data-i18n="setup.historyBtn">${escapeHtml(t('setup.historyBtn'))}</button>
          <button class="btn btn-secondary btn-sm btn-drawer-setup-relations" data-id="${escapeHtml(art.id)}" data-i18n="setup.relationsBtn">${escapeHtml(t('setup.relationsBtn'))}</button>
        </div>
      </section>

      <details class="technical-disclosure">
        <summary data-i18n="asset.technicalDetails">${escapeHtml(t('asset.technicalDetails'))}</summary>
        <section>
          <h3 class="section-heading" data-i18n="setupL.drawer.basicInfo">${escapeHtml(t('setupL.drawer.basicInfo'))}</h3>
          <dl class="field-list">
            <div class="field-row"><dt data-i18n="setup.colType">${escapeHtml(t('setup.colType'))}</dt><dd>${escapeHtml(art.type || '-')}</dd></div>
            <div class="field-row"><dt data-i18n="setup.colProvider">${escapeHtml(t('setup.colProvider'))}</dt><dd>${escapeHtml(art.provider || '-')}</dd></div>
            <div class="field-row"><dt data-i18n="setup.colScope">${escapeHtml(t('setup.colScope'))}</dt><dd>${escapeHtml(loc.scopePrefix || t('asset.scopeUnknown'))}</dd></div>
            <div class="field-row"><dt data-i18n="setupL.drawer.tokens">${escapeHtml(t('setupL.drawer.tokens'))}</dt><dd>${escapeHtml(typeof art.tokens === 'number' ? art.tokens.toLocaleString() : '-')}</dd></div>
            ${assetContentStatus ? `<div class="field-row"><dt data-i18n="asset.contentStatus">${escapeHtml(t('asset.contentStatus'))}</dt><dd>${assetContentStatus}</dd></div>` : ''}
          </dl>
        </section>
        <section>
          <h3 class="section-heading" data-i18n="asset.location">${escapeHtml(t('asset.location'))}</h3>
          <div class="setup-row-scope" title="${escapeHtml(art.path || '')}">${escapeHtml(loc.displayText)}</div>
          <details class="technical-disclosure">
            <summary data-i18n="asset.locationFull">${escapeHtml(t('asset.locationFull'))}</summary>
          <div class="font-mono" style="font-size: 13px; word-break: break-all;">${escapeHtml(art.path || '-')}</div>
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 6px; font-size: 12px; margin-top: 10px; color: var(--text-secondary);">
            <div><span>ID:</span> <span class="font-mono">${escapeHtml(art.id || '-')}</span></div>
            <div><span>Hash:</span> <span class="font-mono">${escapeHtml(art.hash || '-')}</span></div>
          </div>
          <div style="display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap;">
            ${art.path ? `<button type="button" class="btn btn-secondary btn-sm btn-drawer-copy-path" data-clipboard="${escapeHtml(art.path)}" data-i18n="comfort.copyFullPath">${escapeHtml(t('comfort.copyFullPath'))}</button>` : ''}
            ${art.path ? `<button type="button" class="btn btn-ghost btn-sm btn-drawer-reveal-path" data-path="${escapeHtml(art.path)}" data-i18n="setupL.artifacts.reveal">${escapeHtml(t('setupL.artifacts.reveal'))}</button>` : ''}
          </div>
          </details>
        </section>
      </details>
    `;

    drawerContent.querySelector('.btn-drawer-copy-path')?.addEventListener('click', async (e) => {
      const text = e.currentTarget.getAttribute('data-clipboard');
      if (text) {
        try {
          if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
            await navigator.clipboard.writeText(text);
          } else {
            const input = document.createElement('textarea');
            input.value = text;
            document.body.appendChild(input);
            input.select();
            document.execCommand('copy');
            input.remove();
          }
          showToast({ key: 'comfort.copiedToast' });
        } catch {}
      }
    });

    drawerContent.querySelector('.btn-drawer-setup-history')?.addEventListener('click', () => {
      openSetupHistoryAndDiffModal(art);
    });
    drawerContent.querySelector('.btn-drawer-setup-relations')?.addEventListener('click', () => {
      openSetupRelationsModal(art);
    });
    drawerContent.querySelector('.btn-drawer-reveal-path')?.addEventListener('click', async (e) => {
      const path = e.currentTarget.getAttribute('data-path');
      if (path) {
        try {
          await callBridge('system.reveal', { path });
        } catch (err) {
          showToast({ key: 'setupL.toast.revealFailed', params: { error: err.message } }, 'error');
        }
      }
    });
    loadSetupEditing(art, currentDrawerInstance);
  }

  // Drafts live only in this window, never in localStorage or a project file.
  // Opening and every Review/prepare use a fresh authoritative snapshot; Preview is local rendering.
  const setupEditDrafts = new Map();
  const setupEditRequests = new Map();
  const setupEditRequestLimit = 32;
  let setupEditRequestCounter = 0;
  let activeSetupEdit = null;

  function setupEditKey(art) {
    return JSON.stringify([art.project || state.currentProject, art.id]);
  }

  function setupProjectLabel(path) {
    if (!path) return '';
    const project = (state.dashboard.projects || []).find(item => (item.path || item.id) === path);
    return project?.title || project?.name || String(path).split('/').filter(Boolean).pop() || t('common.unnamedProject');
  }

  function setupSourceIdentityKey(identity) {
    if (!identity || typeof identity !== 'object' || Array.isArray(identity)) return '';
    const ordered = value => Array.isArray(value) ? value.map(ordered) : value && typeof value === 'object' ? Object.keys(value).sort().map(key => [key, ordered(value[key])]) : value;
    return JSON.stringify(ordered(identity));
  }

  function setupEditChangeLabel(value) {
    const labels = { applied: 'setupEdit.applied', undone: 'setupEdit.undone', pending_approval: 'setupEdit.pending', rejected: 'setupEdit.rejected', expired: 'setupEdit.expired', failed: 'setupEdit.failed', needs_review: 'setupEdit.needsReview' };
    return labels[value] || 'setupEdit.unknown';
  }

  function setupEditBlockLabel(block, index) {
    if (block.kind === 'heading') return block.source.trim().replace(/^#{1,6}\s*/, '').slice(0, 70);
    return t(`setupEdit.block.${['code','list','blockquote','metadata'].includes(block.kind) ? block.kind : 'paragraph'}`, { number: index + 1 });
  }

  async function loadSetupEditing(art, drawerInstance) {
    const project = art.project || state.currentProject;
    if (art.scope === 'global' || !project || !['instruction', 'skill'].includes(art.type)) return;
    const current = () => currentDrawerInstance === drawerInstance && !document.getElementById('detail-drawer').classList.contains('hidden');
    try {
      const snapshot = await callBridge('setup.edit.get', { project, artifactId: art.id });
      if (!current()) return;
      const body = document.getElementById('drawer-content');
      if (snapshot.editable) {
        // The inventory is an observation. After a reviewed write (or an
        // external edit), reading/copying must use the same current source as
        // the editor, including an intentionally empty document.
        const documentView = body.querySelector('[data-setup-document]');
        if (documentView) documentView.innerHTML = VelaContent.file(snapshot.content, art.path);
        if (snapshot.observationStale) documentView?.insertAdjacentHTML('afterend', `<p class="setup-edit-note" role="status" data-i18n="setupEdit.currentSource">${escapeHtml(t('setupEdit.currentSource'))}</p>`);
        setDrawerCustomActions(`<button type="button" id="btn-setup-edit" class="btn btn-secondary btn-sm" data-i18n="setupEdit.edit">${escapeHtml(t('setupEdit.edit'))}</button>`);
        document.getElementById('btn-setup-edit').addEventListener('click', () => openSetupEditor(art));
        const blocks = VelaContent.blocks(snapshot.content);
        const preview = body.querySelector('.reading-file-preview');
        // Inline controls are offered only when offsets are exact. The original
        // source/copy controls keep the whole document, including its metadata.
        if (preview && blocks.length) {
          preview.innerHTML = blocks.map((block, index) => block.kind === 'metadata'
            ? `<details class="technical-disclosure reading-frontmatter"><summary data-i18n="reading.metadata">${escapeHtml(t('reading.metadata'))}</summary>${VelaContent.code(block.source)}<button type="button" class="btn btn-ghost btn-sm btn-edit-setup-block" data-block="${index}" data-i18n="setupEdit.editBlock">${escapeHtml(t('setupEdit.editBlock'))}</button></details>`
            : `<div class="setup-editable-block">${VelaContent.markdown(block.source)}<button type="button" class="btn btn-ghost btn-sm btn-edit-setup-block" data-block="${index}" data-i18n-aria-label="setupEdit.editBlockLabel" data-i18n-params="${escapeHtml(JSON.stringify({ block: setupEditBlockLabel(block, index) }))}" aria-label="${escapeHtml(t('setupEdit.editBlockLabel', { block: setupEditBlockLabel(block, index) }))}">${VelaContent.icon('edit')}<span data-i18n="setupEdit.editBlock">${escapeHtml(t('setupEdit.editBlock'))}</span></button></div>`).join('');
          preview.querySelectorAll('.btn-edit-setup-block').forEach(button => button.addEventListener('click', () => openSetupEditor(art, blocks[Number(button.dataset.block)])));
        }
      } else {
        body.insertAdjacentHTML('beforeend', `<p class="setup-edit-note" data-i18n="setupEdit.readOnly">${escapeHtml(t('setupEdit.readOnly'))}</p>`);
      }
      const changes = Array.isArray(snapshot.changes) ? snapshot.changes : [];
      if (changes.length) {
        body.insertAdjacentHTML('beforeend', `<section class="setup-edit-history"><h3 class="section-heading" data-i18n="setupEdit.changes">${escapeHtml(t('setupEdit.changes'))}</h3>${changes.map(change => `<div class="setup-edit-history-row"><div><span data-i18n="${setupEditChangeLabel(change.state)}">${escapeHtml(t(setupEditChangeLabel(change.state)))}</span><time>${escapeHtml(formatTime(change.createdAt))}</time></div>${change.canUndo ? `<button type="button" class="btn btn-secondary btn-sm btn-setup-undo" data-journal="${escapeHtml(change.journalId)}" data-i18n="setupEdit.undo">${escapeHtml(t('setupEdit.undo'))}</button>` : ''}</div>`).join('')}</section>`);
        body.querySelectorAll('.btn-setup-undo').forEach(button => button.addEventListener('click', () => openSetupUndo(art, button.dataset.journal)));
        if (snapshot.changesHasMore) body.querySelector('.setup-edit-history').insertAdjacentHTML('beforeend', `<p class="setup-edit-note" data-i18n="setupEdit.historyLimit">${escapeHtml(t('setupEdit.historyLimit'))}</p>`);
      }
    } catch (error) {
      if (!current()) return;
      const body = document.getElementById('drawer-content');
      body.insertAdjacentHTML('beforeend', `<p class="setup-edit-note" role="status" data-i18n="setupEdit.unavailable">${escapeHtml(t('setupEdit.unavailable'))}</p>`);
    }
  }

  async function openSetupEditor(art, requestedBlock = null) {
    const project = art.project || state.currentProject;
    const key = setupEditKey(art);
    let existing = setupEditDrafts.get(key);
    // A prior success notice can cover this editor's footer. This is scoped to
    // starting an edit; lightweight dialogs such as Cmd-K retain their notices.
    document.querySelectorAll('#toast-container .toast-info').forEach(toast => toast._dismiss?.(true));
    openModal({ key: 'setupEdit.title', params: { name: setupAssetDisplayName(art) } }, `<div class="setup-editor"><p data-i18n="common.loading">${escapeHtml(t('common.loading'))}</p></div>`);
    const instance = currentModalInstance;
    const current = () => currentModalInstance === instance && !document.getElementById('modal-container').classList.contains('hidden');
    let snapshot;
    try {
      snapshot = await callBridge('setup.edit.get', { project, artifactId: art.id });
      if (!current()) return;
      if (!snapshot.editable || typeof snapshot.content !== 'string') throw new Error(t('setupEdit.readOnly'));
    } catch (error) {
      if (current()) {
        document.getElementById('modal-body').innerHTML = `<p class="alert-banner alert-warning" role="alert">${escapeHtml(error.message)}</p>${existing ? `<h3 data-i18n="setupEdit.savedDraft">${escapeHtml(t('setupEdit.savedDraft'))}</h3>${VelaContent.file(existing.content, art.path)}<button type="button" id="btn-setup-unavailable-discard" class="btn btn-ghost" data-i18n="setupEdit.discard">${escapeHtml(t('setupEdit.discard'))}</button>` : ''}`;
        document.getElementById('btn-setup-unavailable-discard')?.addEventListener('click', () => { setupEditDrafts.delete(key); closeModal(); });
      }
      return;
    }
    // Re-read after the fresh get: a late prepare can settle while this editor opens.
    existing = setupEditDrafts.get(key);
    let carriedRequest = setupEditRequests.get(key);
    // A fresh get is authoritative for a previously submitted request. Terminal
    // history releases the same-payload gate; needs_review remains explicit.
    if (carriedRequest?.approvalId) {
      const change = (Array.isArray(snapshot.changes) ? snapshot.changes : []).find(item => item?.approvalId === carriedRequest.approvalId);
      if (change && ['applied', 'rejected', 'expired', 'failed', 'undone'].includes(change.state)) {
        setupEditRequests.delete(key); carriedRequest = undefined;
      } else if (change?.state === 'needs_review') {
        carriedRequest.state = 'unknown';
      }
    }
    // Never let an old prepare callback mutate a reopened editor's draft object.
    // The request record remains separate and blocks only its exact frozen payload.
    const draft = existing && carriedRequest ? { ...existing, requestUnknown: false } : (existing || { content: snapshot.content, baseHash: snapshot.baseHash, sourceIdentity: snapshot.sourceIdentity, requestUnknown: false });
    if (existing && carriedRequest) setupEditDrafts.set(key, draft);
    let stale = draft.baseHash !== snapshot.baseHash || setupSourceIdentityKey(draft.sourceIdentity) !== setupSourceIdentityKey(snapshot.sourceIdentity);
    let selection = !existing && requestedBlock && snapshot.content.slice(requestedBlock.start, requestedBlock.end) === requestedBlock.source ? { ...requestedBlock } : null;
    let mode = 'write', busy = false, generation = 0, reviewedContent = null;
    // Keep at most eight changed drafts. Never silently evict an existing edit.
    if (!existing && setupEditDrafts.size >= 8) {
      document.getElementById('modal-body').innerHTML = `<p class="alert-banner alert-warning" data-i18n="setupEdit.draftLimit">${escapeHtml(t('setupEdit.draftLimit'))}</p>`;
      return;
    }
    const saveDraft = () => {
      if (draft.content !== snapshot.content || draft.requestUnknown || stale) setupEditDrafts.set(key, draft);
      else setupEditDrafts.delete(key);
    };
    const onRequestSettled = event => {
      if (event.detail?.key === key && current()) updateActions();
    };
    window.addEventListener('vela:setup-edit-request-settled', onRequestSettled);
    activeSetupEdit = { instance, key, saveDraft, cleanup: () => window.removeEventListener('vela:setup-edit-request-settled', onRequestSettled) };
    document.getElementById('modal-body').innerHTML = `<div class="setup-editor">
      <p class="setup-edit-target" data-testid="setup-edit-target"><strong>${escapeHtml(setupProjectLabel(project))}</strong><span title="${escapeHtml(snapshot.relativePath)}">${escapeHtml(snapshot.relativePath)}</span></p>
      <p class="setup-edit-note" data-i18n="setupEdit.intro">${escapeHtml(t('setupEdit.intro'))}</p>
      ${stale ? `<div class="alert-banner alert-warning" role="alert"><span data-i18n="setupEdit.stale">${escapeHtml(t('setupEdit.stale'))}</span><button type="button" id="btn-setup-rebase" class="btn btn-secondary btn-sm" data-i18n="setupEdit.reload">${escapeHtml(t('setupEdit.reload'))}</button></div>` : ''}
      ${draft.requestUnknown ? `<p class="alert-banner alert-warning" role="alert" data-i18n="setupEdit.requestUnknown">${escapeHtml(t('setupEdit.requestUnknown'))}</p>` : ''}
      <p id="setup-edit-request-state" class="alert-banner alert-warning" role="status" hidden></p>
      <div class="setup-editor-toolbar"><div class="tabs-nav" role="group" data-i18n-aria-label="setupEdit.viewLabel" aria-label="${escapeHtml(t('setupEdit.viewLabel'))}">${['write','preview','diff'].map(view => `<button type="button" class="tab-btn ${view === 'write' ? 'active' : ''}" data-edit-view="${view}" aria-pressed="${view === 'write'}" data-i18n="setupEdit.${view}">${escapeHtml(t('setupEdit.' + view))}</button>`).join('')}</div><span id="setup-edit-scope" class="setup-edit-note"></span></div>
      <div id="setup-editor-write"><label for="setup-editor-source" class="setup-edit-note" data-i18n="setupEdit.sourceLabel">${escapeHtml(t('setupEdit.sourceLabel'))}</label><textarea id="setup-editor-source" class="form-textarea" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" aria-describedby="setup-edit-help"></textarea><p id="setup-edit-help" class="setup-edit-note" data-i18n="setupEdit.draftNote">${escapeHtml(t('setupEdit.draftNote'))}</p></div>
      <div id="setup-editor-preview" hidden></div><div id="setup-editor-diff" hidden></div>
      <p id="setup-edit-error" class="alert-banner alert-warning" role="alert" hidden></p>
    </div>`;
    document.getElementById('modal-footer').classList.remove('hidden');
    document.getElementById('modal-footer').innerHTML = `<button type="button" id="btn-setup-discard" class="btn btn-ghost" data-i18n="setupEdit.discard">${escapeHtml(t('setupEdit.discard'))}</button><span class="setup-editor-spacer"></span><button type="button" class="btn btn-secondary" id="btn-setup-editor-close" data-i18n="common.close">${escapeHtml(t('common.close'))}</button><button type="button" class="btn btn-primary" id="btn-setup-review" data-i18n="setupEdit.review">${escapeHtml(t('setupEdit.review'))}</button><button type="button" class="btn btn-primary" id="btn-setup-request" data-i18n="setupEdit.request" hidden>${escapeHtml(t('setupEdit.request'))}</button>`;
    const area = document.getElementById('setup-editor-source');
    area.maxLength = 65536;
    const usesCRLF = snapshot.content.includes('\r\n') && !snapshot.content.replace(/\r\n/g, '').includes('\n');
    const errorBox = document.getElementById('setup-edit-error');
    const reviewButton = document.getElementById('btn-setup-review');
    const requestButton = document.getElementById('btn-setup-request');
    const params = () => ({ project, artifactId: art.id, baseHash: draft.baseHash, sourceIdentity: draft.sourceIdentity, content: draft.content });
    const requestMatchesDraft = request => Boolean(request && request.content === draft.content && request.baseHash === draft.baseHash && setupSourceIdentityKey(request.sourceIdentity) === setupSourceIdentityKey(draft.sourceIdentity));
    const matchingRequest = () => {
      const request = setupEditRequests.get(key);
      return requestMatchesDraft(request) ? request : null;
    };
    function setError(error) { errorBox.textContent = error.message || String(error); errorBox.hidden = false; }
    function updateRequestState() {
      const request = matchingRequest();
      const state = document.getElementById('setup-edit-request-state');
      if (!request || !state) return false;
      const messageKey = request.state === 'inFlight' ? 'setupEdit.requestPending' : request.state === 'submitted' ? 'setupEdit.requestSubmitted' : 'setupEdit.requestUnknown';
      state.dataset.i18n = messageKey;
      state.textContent = t(messageKey);
      state.hidden = false;
      return true;
    }
    function updateActions() {
      const tooLarge = new TextEncoder().encode(draft.content).length > 65536;
      const changed = draft.content !== snapshot.content;
      const requestBlocked = updateRequestState();
      const state = document.getElementById('setup-edit-request-state');
      if (state && !requestBlocked) state.hidden = true;
      reviewButton.disabled = busy || stale || draft.requestUnknown || requestBlocked || !changed || tooLarge;
      requestButton.disabled = busy || stale || draft.requestUnknown || requestBlocked || reviewedContent !== draft.content || tooLarge;
      reviewButton.hidden = mode === 'diff' && reviewedContent === draft.content;
      requestButton.hidden = !reviewButton.hidden;
      area.readOnly = busy;
      document.getElementById('btn-setup-discard').disabled = busy;
      if (tooLarge) setError({ message: t('setupEdit.tooLarge') });
    }
    function updateScope() {
      const scope = document.getElementById('setup-edit-scope');
      scope.innerHTML = selection ? `<button type="button" class="btn btn-ghost btn-sm" id="btn-setup-edit-whole" data-i18n="setupEdit.whole">${escapeHtml(t('setupEdit.whole'))}</button>` : `<span data-i18n="setupEdit.wholeLabel">${escapeHtml(t('setupEdit.wholeLabel'))}</span>`;
      document.getElementById('btn-setup-edit-whole')?.addEventListener('click', () => { if (busy) return; selection = null; area.value = draft.content; updateScope(); area.focus(); });
    }
    async function setView(view) {
      if (busy || !current()) return;
      mode = view;
      ['write','preview','diff'].forEach(name => {
        document.getElementById('setup-editor-' + name).hidden = name !== view;
        const button = document.querySelector(`[data-edit-view="${name}"]`);
        button.classList.toggle('active', name === view); button.setAttribute('aria-pressed', String(name === view));
      });
      errorBox.hidden = true;
      if (view === 'preview') document.getElementById('setup-editor-preview').innerHTML = VelaContent.file(draft.content, art.path);
      if (view === 'diff') {
        const seq = ++generation;
        const target = document.getElementById('setup-editor-diff');
        target.innerHTML = `<p data-i18n="common.loading">${escapeHtml(t('common.loading'))}</p>`;
        busy = true; updateActions();
        try {
          const frozen = params();
          const preview = await callBridge('setup.edit.preview', frozen);
          if (!current() || generation !== seq) return;
          // Only the helper's freshly validated before/after becomes a review.
          if (preview.before !== snapshot.content || preview.after !== frozen.content) throw new Error(t('setupEdit.changedDuringReview'));
          target.innerHTML = VelaContent.change(preview.before, preview.after);
          if (target.querySelector('[data-review-complete="false"]')) throw new Error(t('reading.changeTooLarge'));
          reviewedContent = frozen.content;
        } catch (error) {
          if (current()) { target.innerHTML = ''; reviewedContent = null; setError(error); }
        } finally { if (current()) { busy = false; updateActions(); } }
      }
      updateActions();
    }
    area.value = selection ? draft.content.slice(selection.start, selection.end) : draft.content;
    area.addEventListener('input', () => {
      // HTML textareas normalize CRLF to LF; retain a document's uniform EOL
      // convention when composing the new source instead of rewriting it.
      const edited = usesCRLF ? area.value.replace(/\n/g, '\r\n') : area.value;
      if (selection) {
        draft.content = draft.content.slice(0, selection.start) + edited + draft.content.slice(selection.end);
        selection.end = selection.start + edited.length;
      } else draft.content = edited;
      reviewedContent = null; errorBox.hidden = true; saveDraft(); updateActions();
    });
    document.querySelectorAll('[data-edit-view]').forEach(button => button.addEventListener('click', () => setView(button.dataset.editView)));
    document.getElementById('btn-setup-editor-close').addEventListener('click', closeModal);
    document.getElementById('btn-setup-discard').addEventListener('click', () => {
      setupEditDrafts.delete(key); activeSetupEdit?.cleanup?.(); activeSetupEdit = null; closeModal();
    });
    document.getElementById('btn-setup-rebase')?.addEventListener('click', () => {
      // Preserve the exact draft for copying instead of silently discarding or
      // rebasing it onto a source the user has not compared.
      mode = 'preview';
      document.getElementById('setup-editor-preview').innerHTML = `<h3 data-i18n="setupEdit.savedDraft">${escapeHtml(t('setupEdit.savedDraft'))}</h3>${VelaContent.file(draft.content, art.path)}<h3 data-i18n="setupEdit.diskVersion">${escapeHtml(t('setupEdit.diskVersion'))}</h3>${VelaContent.file(snapshot.content, art.path)}<button type="button" class="btn btn-secondary" id="btn-setup-use-current-base" data-i18n="setupEdit.useCurrentBase">${escapeHtml(t('setupEdit.useCurrentBase'))}</button>`;
      ['write','diff'].forEach(name => { document.getElementById('setup-editor-' + name).hidden = true; });
      document.getElementById('setup-editor-preview').hidden = false;
      document.querySelectorAll('[data-edit-view]').forEach(button => { button.classList.toggle('active', button.dataset.editView === 'preview'); button.setAttribute('aria-pressed', String(button.dataset.editView === 'preview')); });
      document.getElementById('btn-setup-use-current-base').addEventListener('click', () => {
        draft.baseHash = snapshot.baseHash; draft.sourceIdentity = snapshot.sourceIdentity;
        stale = false; reviewedContent = null; saveDraft();
        document.getElementById('btn-setup-rebase').closest('.alert-banner').hidden = true;
        setView('diff');
      });
      updateActions();
    });
    reviewButton.addEventListener('click', () => setView('diff'));
    requestButton.addEventListener('click', async () => {
      if (busy || requestButton.disabled || !current()) return;
      const frozen = params();
      if (!setupEditRequests.has(key) && setupEditRequests.size >= setupEditRequestLimit) {
        setError({ message: t('setupEdit.requestLimit') }); return;
      }
      const request = { id: ++setupEditRequestCounter, state: 'inFlight', ...frozen };
      setupEditRequests.set(key, request);
      saveDraft();
      busy = true; updateActions();
      try {
        const result = await callBridge('setup.edit.prepare', frozen);
        if (!result?.approval?.id) throw new Error(t('setupEdit.requestUnknown'));
        if (setupEditRequests.get(key) === request) { request.state = 'submitted'; request.approvalId = result.approval.id; }
        // Delete only the exact draft that submitted this exact frozen payload.
        if (setupEditDrafts.get(key) === draft && requestMatchesDraft(request)) setupEditDrafts.delete(key);
        window.dispatchEvent(new CustomEvent('vela:setup-edit-request-settled', { detail: { key, requestId: request.id, state: 'submitted' } }));
        if (!current()) { await refreshDashboard(true, true); return; }
        const route = activeRouteEpoch, page = state.currentPage, scope = state.currentProject;
        activeSetupEdit.cleanup?.(); activeSetupEdit = null; closeModal(); closeDrawer();
        showToast({ key: 'setupEdit.requested' });
        await refreshDashboard(true, true);
        if (activeRouteEpoch === route && state.currentPage === page && state.currentProject === scope) navigateTo('inbox');
      } catch (error) {
        // A broken bridge can lose the response after prepare committed. Keep
        // the exact frozen request separate from later reopened draft content.
        if (setupEditRequests.get(key) === request) request.state = 'unknown';
        if (setupEditDrafts.get(key) === draft && requestMatchesDraft(request)) { draft.requestUnknown = true; saveDraft(); }
        window.dispatchEvent(new CustomEvent('vela:setup-edit-request-settled', { detail: { key, requestId: request.id, state: 'unknown' } }));
        if (current()) { setError({ message: t('setupEdit.requestUnknown') + ' ' + error.message }); }
      } finally { if (current()) { busy = false; updateActions(); } }
    });
    updateScope(); updateActions(); area.focus();
  }

  function openSetupUndo(art, journalId) {
    const project = art.project || state.currentProject;
    openModal({ key: 'setupEdit.undoTitle' }, `<div class="setup-undo"><p data-i18n="setupEdit.undoPrompt" data-i18n-params="${escapeHtml(JSON.stringify({ name: setupAssetDisplayName(art) }))}">${escapeHtml(t('setupEdit.undoPrompt', { name: setupAssetDisplayName(art) }))}</p><p class="setup-edit-note" data-i18n="setupEdit.undoNote">${escapeHtml(t('setupEdit.undoNote'))}</p><p id="setup-undo-error" class="alert-banner alert-warning" role="alert" hidden></p></div>`, `<button class="btn btn-secondary" data-close-modal data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button><button class="btn btn-primary" id="btn-setup-confirm-undo" data-i18n="setupEdit.undo">${escapeHtml(t('setupEdit.undo'))}</button>`);
    const instance = currentModalInstance;
    document.getElementById('btn-setup-confirm-undo').addEventListener('click', async event => {
      const button = event.currentTarget; button.disabled = true;
      try {
        const result = await callBridge('setup.edit.undo', { project, artifactId: art.id, journalId });
        if (currentModalInstance !== instance) return;
        if (result?.outcomeUnknown || result?.state !== 'undone') throw new Error(t('setupEdit.undoUncertain'));
        closeModal(); closeDrawer();
        showToast({ key: 'setupEdit.undone' });
        await refreshDashboard(true, true);
      } catch (error) {
        if (currentModalInstance !== instance) return;
        const box = document.getElementById('setup-undo-error'); box.textContent = error.message; box.hidden = false;
      }
    });
  }

  function bindSetupRowActions(container, artifactsList) {
    if (!container) return;

    container.querySelectorAll('.btn-preview-artifact').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const art = artifactsList.find(a => a.id === id);
        if (art) openArtifactDrawer(art);
      });
    });

    container.querySelectorAll('.btn-setup-more').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const dropdown = btn.closest('.setup-more-dropdown');
        const menu = dropdown?.querySelector('.setup-more-menu');
        if (!menu) return;
        const isOpen = !menu.hidden;

        document.querySelectorAll('.setup-more-menu:not([hidden])').forEach(m => {
          if (m !== menu) {
            m.hidden = true;
            m.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more')?.setAttribute('aria-expanded', 'false');
          }
        });

        if (isOpen) {
          menu.hidden = true;
          btn.setAttribute('aria-expanded', 'false');
        } else {
          menu.hidden = false;
          btn.setAttribute('aria-expanded', 'true');
        }
      });

      btn.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          const dropdown = btn.closest('.setup-more-dropdown');
          const menu = dropdown?.querySelector('.setup-more-menu');
          if (menu) {
            menu.hidden = false;
            btn.setAttribute('aria-expanded', 'true');
            const firstItem = menu.querySelector('.dropdown-item');
            firstItem?.focus();
          }
        }
      });
    });

    container.querySelectorAll('.setup-more-menu').forEach(menu => {
      menu.addEventListener('keydown', (e) => {
        const items = Array.from(menu.querySelectorAll('.dropdown-item'));
        const currentIndex = items.indexOf(document.activeElement);
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          const nextIndex = (currentIndex + 1) % items.length;
          items[nextIndex]?.focus();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          const prevIndex = (currentIndex - 1 + items.length) % items.length;
          items[prevIndex]?.focus();
        } else if (e.key === 'Escape') {
          e.preventDefault();
          menu.hidden = true;
          const btn = menu.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more');
          if (btn) {
            btn.setAttribute('aria-expanded', 'false');
            btn.focus();
          }
        } else if (e.key === 'Tab') {
          menu.hidden = true;
          menu.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more')?.setAttribute('aria-expanded', 'false');
        }
      });
    });

    container.querySelectorAll('.btn-setup-history').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const menu = btn.closest('.setup-more-menu');
        if (menu) {
          menu.hidden = true;
          menu.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more')?.setAttribute('aria-expanded', 'false');
        }
        const id = btn.getAttribute('data-id');
        const art = artifactsList.find(a => a.id === id);
        if (art) openSetupHistoryAndDiffModal(art);
      });
    });

    container.querySelectorAll('.btn-setup-relations').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const menu = btn.closest('.setup-more-menu');
        if (menu) {
          menu.hidden = true;
          menu.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more')?.setAttribute('aria-expanded', 'false');
        }
        const id = btn.getAttribute('data-id');
        const art = artifactsList.find(a => a.id === id);
        if (art) openSetupRelationsModal(art);
      });
    });

    container.querySelectorAll('.btn-reveal-path').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        const menu = btn.closest('.setup-more-menu');
        if (menu) {
          menu.hidden = true;
          menu.closest('.setup-more-dropdown')?.querySelector('.btn-setup-more')?.setAttribute('aria-expanded', 'false');
        }
        const path = btn.getAttribute('data-path');
        if (path) {
          try {
            await callBridge('system.reveal', { path });
          } catch (err) {
            showToast({ key: 'setupL.toast.revealFailed', params: { error: err.message } }, 'error');
          }
        }
      });
    });
  }

  function formatAssetLocation(fullPath, scope, currentProject) {
    const s = String(scope || '').trim().toLowerCase();
    let scopePrefix = '';
    if (s === 'project') {
      scopePrefix = t('comfort.scopeProject');
    } else if (s === 'global') {
      scopePrefix = t('comfort.scopeGlobal');
    } else if (s === 'user') {
      scopePrefix = t('comfort.scopeUser');
    } else if (s === 'shared') {
      scopePrefix = t('comfort.scopeShared');
    } else if (s === 'workspace') {
      scopePrefix = t('comfort.scopeWorkspace');
    } else if (scope) {
      scopePrefix = String(scope).trim();
    }

    if (!fullPath || typeof fullPath !== 'string' || !fullPath.trim()) {
      const fallbackPrefix = scopePrefix || t('asset.scopeUnknown');
      return {
        displayText: fallbackPrefix || '-',
        scopePrefix: fallbackPrefix || '-',
        relativePath: '-'
      };
    }

    const normPath = fullPath.trim().replace(/\\/g, '/').replace(/\/+$/, '');

    if (!normPath.startsWith('/') && !/^[a-zA-Z]:/.test(normPath)) {
      const rel = normPath.replace(/^\.\//, '');
      const prefix = scopePrefix || t('asset.scopeUnknown');
      return {
        displayText: `${prefix} › ${rel}`,
        scopePrefix: prefix,
        relativePath: rel
      };
    }

    const candidates = [];
    if (currentProject && typeof currentProject === 'string' && currentProject.trim()) {
      candidates.push(currentProject.trim());
    }
    if (state && state.dashboard && Array.isArray(state.dashboard.projects)) {
      for (const p of state.dashboard.projects) {
        if (p) {
          if (typeof p.root === 'string' && p.root.trim()) candidates.push(p.root.trim());
          if (typeof p.path === 'string' && p.path.trim()) candidates.push(p.path.trim());
        }
      }
    }

    let longestCand = null;
    for (const cand of candidates) {
      const normCand = cand.replace(/\\/g, '/').replace(/\/+$/, '');
      if (!normCand) continue;
      if (normPath === normCand || normPath.startsWith(normCand + '/')) {
        if (!longestCand || normCand.length > longestCand.length) {
          longestCand = normCand;
        }
      }
    }

    if (longestCand) {
      let rel = normPath.slice(longestCand.length).replace(/^\/+/, '');
      if (!rel) {
        const segs = normPath.split('/').filter(Boolean);
        rel = segs[segs.length - 1] || '.';
      }
      const prefix = scopePrefix || t('asset.scopeUnknown');
      return {
        displayText: `${prefix} › ${rel}`,
        scopePrefix: prefix,
        relativePath: rel
      };
    }

    const segs = normPath.split('/').filter(Boolean);
    const basename = segs.length > 0 ? segs[segs.length - 1] : normPath;
    const prefix = scopePrefix || (s === 'project' ? t('comfort.scopeProject') : t('asset.scopeUnknown'));
    return {
      displayText: `${prefix} › ${basename}`,
      scopePrefix: prefix,
      relativePath: basename
    };
  }

  function renderArtifactsSection(target, typeName) {
    const artifacts = (state.dashboard && state.dashboard.artifacts) || [];
    const filtered = artifacts.filter(a => {
      const t = (a.type || '').toLowerCase();
      if (typeName === 'rules') return t === 'instruction' || t === 'rule';
      if (typeName === 'skills') return t === 'skill' || t === 'command';
      if (typeName === 'hooks') return a.containsHooks === true || t === 'hook';
      if (typeName === 'mcp') return t === 'mcp' || a.containsMCP === true;
      if (typeName === 'configurations') return t === 'configuration';
      return t === typeName.toLowerCase();
    });

    const typeLabel = (() => {
      const key = 'setupL.tabs.' + typeName;
      const label = t(key);
      return (label && label !== key) ? label : typeName;
    })();

    const groupOrder = ['project', 'shared'];
    const groupMap = new Map();
    filtered.forEach(a => {
      const g = setupScopeGroup(a.scope);
      if (!groupMap.has(g.key)) groupMap.set(g.key, Object.assign({ items: [] }, g));
      groupMap.get(g.key).items.push(a);
    });
    const groups = Array.from(groupMap.values()).sort((x, y) => {
      const ix = groupOrder.indexOf(x.key);
      const iy = groupOrder.indexOf(y.key);
      return (ix === -1 ? 99 : ix) - (iy === -1 ? 99 : iy) || String(x.key).localeCompare(String(y.key));
    });

    const summaryHtml = '';

    if (filtered.length === 0) {
      target.innerHTML = `
        ${summaryHtml}
        <div class="empty-state">
          <div class="empty-state-title" data-i18n="setupL.artifacts.emptyTitle" data-i18n-params="${escapeHtml(JSON.stringify({ type: typeLabel }))}">${escapeHtml(t('setupL.artifacts.emptyTitle', { type: typeLabel }))}</div>
          <div class="empty-state-desc" data-i18n="setupL.artifacts.emptyDesc">${escapeHtml(t('setupL.artifacts.emptyDesc'))}</div>
        </div>
      `;
      return;
    }

    target.innerHTML = `
      ${summaryHtml}
      <div class="setup-groups">
        ${groups.map((group, gi) => {
          const groupLabel = group.labelText || t(group.labelKey);
          return `<section class="setup-group" data-setup-group="${escapeHtml(group.key)}">
          <div class="setup-group-head">
            <h3${group.labelKey ? ` data-i18n="${group.labelKey}"` : ''}>${escapeHtml(groupLabel)}</h3>
            <span class="setup-group-count">${escapeHtml(t('asset.group.count', { count: group.items.length }))}</span>
          </div>
          <div class="workspace-list asset-list"${gi === 0 ? ' id="asset-list"' : ''}>
            ${group.items.map(a => renderAssetRow(a, typeLabel)).join('')}
          </div>
        </section>`;
        }).join('')}
      </div>
    `;

    bindSetupRowActions(target, filtered);
  }

  function setupScopeGroup(rawScope) {
    const scope = String(rawScope || '').trim().toLowerCase();
    if (scope === 'project' || scope === 'workspace') return { key: 'project', labelKey: 'asset.group.project' };
    if (scope === 'global' || scope === 'user' || scope === 'shared') return { key: 'shared', labelKey: 'asset.group.shared' };
    if (!scope) return { key: 'unknown', labelKey: 'asset.group.unknown' };
    return { key: 'scope:' + scope, labelText: String(rawScope).trim() };
  }

  function setupAssetDisplayName(asset) {
    const title = typeof asset?.title === 'string' ? asset.title.trim() : '';
    const sourcePath = typeof asset?.path === 'string' ? asset.path.trim().replace(/\\/g, '/').replace(/\/+$/, '') : '';
    const parts = sourcePath.split('/').filter(Boolean);
    const basename = parts.at(-1) || '';
    if (basename.toLowerCase() === 'skill.md' && parts.length > 1 && (!title || title.toLowerCase() === 'skill.md')) return parts.at(-2);
    if (title) return title;
    if (basename) return basename;
    return t('asset.unnamed');
  }

  function setupAssetIconKind(asset) {
    const type = String(asset?.type || '').trim().toLowerCase();
    if (asset?.containsHooks === true || type === 'hook') return 'hook';
    if (asset?.containsMCP === true || type === 'mcp') return 'connector';
    if (type === 'skill' || type === 'command') return 'skill';
    if (type === 'rule' || type === 'instruction' || type === 'guideline') return 'rule';
    if (type === 'library' || type === 'knowledge') return 'book';
    return 'document';
  }

  // A list row leads with a readable name and a project-relative location. Diagnostics only
  // take a slot when they exist; health is never asserted by a badge on a healthy entry.
  function renderAssetRow(a, typeLabel) {
    const loc = formatAssetLocation(a.path, a.scope, state.currentProject);
    const name = setupAssetDisplayName(a);
    const iconKind = setupAssetIconKind(a);
    const diag = Array.isArray(a.diagnostics) ? a.diagnostics : [];
    const provider = (a.provider && String(a.provider).toLowerCase() !== 'generic') ? (String(a.provider).toLowerCase() === 'shared' ? t('asset.provider.shared') : String(a.provider)) : '';
    const metaCells = [
      provider ? `<span class="setup-row-provider">${escapeHtml(provider)}</span>` : '',
      diag.length > 0
        ? `<button type="button" class="setup-row-diag is-clickable btn-preview-artifact" data-id="${escapeHtml(a.id)}" title="${escapeHtml(t('asset.diagnostics'))}" data-i18n="setupL.artifacts.warningCount" data-i18n-params="${escapeHtml(JSON.stringify({ count: diag.length }))}">${escapeHtml(t('setupL.artifacts.warningCount', { count: diag.length }))}</button>`
        : ''
    ].filter(Boolean).join('');
    return `<article class="workspace-row asset-row" data-testid="asset-row" data-asset-id="${escapeHtml(a.id)}">
      <div class="workspace-row-icon" data-kind="${escapeHtml(iconKind)}" aria-hidden="true">${VelaContent.icon(iconKind)}</div>
      <div class="workspace-row-content">
        <button class="row-title setup-row-name btn-preview-artifact btn-setup-view" data-id="${escapeHtml(a.id)}" title="${escapeHtml(name)}">${escapeHtml(name)}</button>
        <div class="asset-location setup-row-scope" data-testid="asset-location" title="${escapeHtml(a.path || '')}">${escapeHtml(loc.displayText)}</div>
        ${metaCells ? `<div class="row-meta">${metaCells}</div>` : ''}
      </div>
      ${actionMenu(`
        ${menuAction('asset.openItem', 'preview', { className: 'btn-preview-artifact btn-setup-view', data: `data-id="${escapeHtml(a.id)}"` })}
        <button class="btn btn-setup-history btn-setup-action-history" data-id="${escapeHtml(a.id)}" data-i18n="setup.historyBtn">${escapeHtml(t('setup.historyBtn'))}</button>
        <button class="btn btn-setup-relations btn-setup-action-relations" data-id="${escapeHtml(a.id)}" data-i18n="setup.relationsBtn">${escapeHtml(t('setup.relationsBtn'))}</button>
        ${a.path ? `<button class="btn btn-reveal-path btn-setup-action-reveal" data-path="${escapeHtml(a.path)}" data-i18n="setupL.artifacts.reveal">${escapeHtml(t('setupL.artifacts.reveal'))}</button>` : ''}
      `, 'asset.rowActions')}
    </article>`;
  }

  async function openSetupCatalogModal() {
    openModal({ key: 'setup.catalogTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-setup-catalog" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-setup-catalog')?.addEventListener('click', closeModal);

    let cat = null;
    try {
      cat = await callBridge('setup.catalog', {});
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    if (!b) return;

    const providers = Array.isArray(cat.providers) ? cat.providers : [];
    const projectLocs = Array.isArray(cat.projectLocations) ? cat.projectLocations : [];
    const globalLocs = Array.isArray(cat.globalLocations) ? cat.globalLocations : [];
    const limits = Array.isArray(cat.limitations) ? cat.limitations : [];

    b.innerHTML = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px;" data-i18n="setup.catalogDesc">${escapeHtml(t('setup.catalogDesc'))}</p>

      <div class="card" style="margin-bottom: 12px;">
        <div style="font-size: 12px; display: flex; gap: 16px; align-items: center;">
          <div><strong data-i18n="setup.catalogVersion">${escapeHtml(t('setup.catalogVersion'))}</strong> <span class="font-mono">${escapeHtml(cat.catalogVersion || '-')}</span></div>
          <div><strong data-i18n="setup.catalogProviders">${escapeHtml(t('setup.catalogProviders'))}:</strong> ${providers.map(p => `<span class="code-badge" style="margin-left: 4px;">${escapeHtml(p)}</span>`).join('')}</div>
        </div>
      </div>

      <div style="margin-bottom: 14px;">
        <h4 style="font-size: 13px; font-weight: 600; margin-bottom: 6px;" data-i18n="setup.catalogLocations">${escapeHtml(t('setup.catalogLocations'))}</h4>
        <div class="table-wrapper" style="max-height: 240px; overflow-y: auto;">
          <table class="data-table">
            <thead>
              <tr>
                <th data-i18n="setup.colPath">${escapeHtml(t('setup.colPath'))}</th>
                <th data-i18n="setup.colProvider">${escapeHtml(t('setup.colProvider'))}</th>
                <th data-i18n="setup.colType">${escapeHtml(t('setup.colType'))}</th>
                <th data-i18n="setup.colScope">${escapeHtml(t('setup.colScope'))}</th>
                <th data-i18n="setup.colRecursive">${escapeHtml(t('setup.colRecursive'))}</th>
              </tr>
            </thead>
            <tbody>
              ${projectLocs.map(l => `
                <tr>
                  <td><code style="font-size: 11px;">${escapeHtml(l.path)}</code></td>
                  <td><span class="code-badge">${escapeHtml(l.provider)}</span></td>
                  <td>${escapeHtml(l.type)}</td>
                  <td><span class="status-badge status-neutral">project</span></td>
                  <td>${l.recursive ? '✓' : '-'}</td>
                </tr>
              `).join('')}
              ${globalLocs.map(l => `
                <tr>
                  <td><code style="font-size: 11px;">${escapeHtml(l.path)}</code></td>
                  <td><span class="code-badge">${escapeHtml(l.provider)}</span></td>
                  <td>${escapeHtml(l.type)}</td>
                  <td><span class="status-badge status-sage">global</span></td>
                  <td>${l.recursive ? '✓' : '-'}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <div>
        <h4 style="font-size: 13px; font-weight: 600; margin-bottom: 6px;" data-i18n="setup.catalogLimits">${escapeHtml(t('setup.catalogLimits'))}</h4>
        <div style="background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 6px; padding: 8px 12px; font-size: 11px; color: var(--text-secondary);">
          <ul style="margin: 0; padding-left: 18px;">
            ${limits.map(lim => `<li style="margin-bottom: 4px;">${escapeHtml(lim)}</li>`).join('')}
          </ul>
        </div>
      </div>
    `;
  }

  async function openSetupHistoryAndDiffModal(art) {
    const isGlobal = art.scope === 'global';
    const identity = isGlobal ? { id: art.id, scope: 'global' } : { id: art.id, project: art.project || state.currentProject };

    openModal({ key: 'setup.historyTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-setup-history" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-setup-history')?.addEventListener('click', closeModal);

    let hist = null;
    try {
      hist = await callBridge('setup.history', identity);
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    if (!b) return;

    let allRevisions = Array.isArray(hist.revisions) ? [...hist.revisions] : [];
    let nextBefore = hist.nextBefore;
    let isLoadingEarlier = false;
    let setupHistoryGen = 0;

    const fileName = art.path ? art.path.split('/').pop() : (art.id || '');
    const relPath = art.path || '';

    function renderRevisionsRows() {
      return allRevisions.map(r => `
        <tr>
          <td><span class="font-mono">v${escapeHtml(String(r.revision ?? 1))}</span></td>
          <td><span class="font-mono">${escapeHtml(String(r.sourceBytes ?? '-'))} B</span></td>
          <td><span class="font-mono" style="font-size: 11px;">${r.sanitizedHash ? escapeHtml(r.sanitizedHash.substring(0, 10)) : '-'}</span></td>
          <td><span class="font-mono" style="font-size: 11px;">${formatTime(r.observedAt)}</span></td>
          <td><span class="status-badge status-neutral">${escapeHtml(r.contentStatus || r.state || '-')}</span></td>
        </tr>
      `).join('');
    }

    function updateCompareSelects(preferredFrom, preferredTo) {
      const fromEl = document.getElementById('diff-from-select');
      const toEl = document.getElementById('diff-to-select');
      if (!fromEl || !toEl) return;
      const curFrom = preferredFrom !== undefined ? preferredFrom : fromEl.value;
      const curTo = preferredTo !== undefined ? preferredTo : toEl.value;

      fromEl.innerHTML = allRevisions.map(r => `<option value="${r.revision}">v${r.revision}</option>`).join('');
      toEl.innerHTML = allRevisions.map(r => `<option value="${r.revision}">v${r.revision}</option>`).join('');

      if (curFrom && allRevisions.some(r => String(r.revision) === String(curFrom))) {
        fromEl.value = String(curFrom);
      } else {
        fromEl.value = String(allRevisions[1] ? allRevisions[1].revision : (allRevisions[0]?.revision ?? 1));
      }

      if (curTo && allRevisions.some(r => String(r.revision) === String(curTo))) {
        toEl.value = String(curTo);
      } else {
        toEl.value = String(allRevisions[0]?.revision ?? 1);
      }
    }

    b.innerHTML = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 8px;" data-i18n="setup.historyDesc">${escapeHtml(t('setup.historyDesc'))}</p>

      <div class="card" style="margin-bottom: 10px; padding: 8px 12px;">
        <div style="display: flex; justify-content: space-between; align-items: baseline; gap: 8px;">
          <div>
            <strong style="font-size: 13px;">${escapeHtml(fileName)}</strong>
            <span class="code-badge" style="font-size: 11px; margin-left: 6px;">v${escapeHtml(String(art.revision ?? 1))}</span>
            <span class="code-badge" style="font-size: 10px; margin-left: 4px;">${escapeHtml(art.scope || 'project')}</span>
          </div>
          <div style="font-size: 11px; color: var(--text-secondary); max-width: 50%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${escapeHtml(relPath)}</div>
        </div>
        <details class="memory-meta-details" style="margin-top: 6px;">
          <summary style="font-size: 11px; color: var(--text-secondary); cursor: pointer;" data-i18n="memory.techMetaSummary">${escapeHtml(t('memory.techMetaSummary'))}</summary>
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 4px; font-size: 11px; margin-top: 4px; color: var(--text-secondary);">
            <div><span data-i18n="setup.colScope">${escapeHtml(t('setup.colScope'))}:</span> <span class="code-badge">${escapeHtml(art.scope || 'project')}</span></div>
            <div><span>ID:</span> <span class="font-mono">${escapeHtml(art.id)}</span></div>
            <div><span>Hash:</span> <span class="font-mono">${escapeHtml(art.hash || '-')}</span></div>
            <div style="grid-column: 1 / -1;"><span data-i18n="setup.colPath">${escapeHtml(t('setup.colPath'))}:</span> <span class="font-mono" style="font-size: 10px; word-break: break-all;">${escapeHtml(art.path || '')}</span></div>
          </div>
        </details>
      </div>

      <div style="margin-bottom: 12px;">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
          <h4 style="font-size: 13px; font-weight: 600; margin: 0;">
            <span data-i18n="setup.revision">${escapeHtml(t('setup.revision'))}</span>
            <span id="setup-revisions-count">(${allRevisions.length})</span>
          </h4>
          <div id="setup-earlier-container">
            ${nextBefore ? `
              <button id="btn-load-earlier-setup-revisions" class="btn btn-secondary btn-xs" data-i18n="setup.loadEarlierRevisions">${escapeHtml(t('setup.loadEarlierRevisions'))}</button>
            ` : (allRevisions.length > 0 ? `
              <span class="text-secondary" style="font-size: 11px;" data-i18n="setup.allRevisionsLoaded">${escapeHtml(t('setup.allRevisionsLoaded'))}</span>
            ` : '')}
          </div>
        </div>
        ${allRevisions.length === 0 ? `
          <div class="text-secondary" style="font-size: 12px; padding: 12px 0;" data-i18n="setup.historyEmpty">${escapeHtml(t('setup.historyEmpty'))}</div>
        ` : `
          <div class="table-wrapper" style="max-height: 160px; overflow-y: auto;">
            <table class="data-table">
              <thead>
                <tr>
                  <th data-i18n="setup.revision">${escapeHtml(t('setup.revision'))}</th>
                  <th data-i18n="setup.sourceBytes">${escapeHtml(t('setup.sourceBytes'))}</th>
                  <th data-i18n="setup.sanitizedHash">${escapeHtml(t('setup.sanitizedHash'))}</th>
                  <th data-i18n="setup.observedAt">${escapeHtml(t('setup.observedAt'))}</th>
                  <th data-i18n="common.status">${escapeHtml(t('common.status'))}</th>
                </tr>
              </thead>
              <tbody id="setup-history-tbody">
                ${renderRevisionsRows()}
              </tbody>
            </table>
          </div>
        `}
      </div>

      <div class="card" style="padding: 10px 12px; margin-bottom: 12px;">
        <span class="card-title" style="font-size: 12px; margin-bottom: 8px; display: block;" data-i18n="setup.diffSelectCompare">${escapeHtml(t('setup.diffSelectCompare'))}</span>
        <div style="display: flex; gap: 10px; align-items: flex-end;">
          <div>
            <label style="font-size: 11px; color: var(--text-secondary);" data-i18n="setup.diffFrom">${escapeHtml(t('setup.diffFrom'))}</label>
            <select id="diff-from-select" class="form-select" style="min-width: 90px;">
              ${allRevisions.map(r => `<option value="${r.revision}" ${r.revision === (allRevisions[1] ? allRevisions[1].revision : allRevisions[0]?.revision) ? 'selected' : ''}>v${r.revision}</option>`).join('')}
            </select>
          </div>
          <div>
            <label style="font-size: 11px; color: var(--text-secondary);" data-i18n="setup.diffTo">${escapeHtml(t('setup.diffTo'))}</label>
            <select id="diff-to-select" class="form-select" style="min-width: 90px;">
              ${allRevisions.map(r => `<option value="${r.revision}" ${r.revision === allRevisions[0]?.revision ? 'selected' : ''}>v${r.revision}</option>`).join('')}
            </select>
          </div>
          <button id="btn-run-setup-diff" class="btn btn-secondary btn-sm" data-i18n="setup.btnRunDiff">${escapeHtml(t('setup.btnRunDiff'))}</button>
        </div>
      </div>

      <div id="setup-diff-result"></div>
    `;

    function bindEarlierBtn() {
      const btn = document.getElementById('btn-load-earlier-setup-revisions');
      if (!btn) return;
      btn.addEventListener('click', async () => {
        if (!nextBefore || isLoadingEarlier) return;
        isLoadingEarlier = true;
        btn.disabled = true;
        btn.textContent = t('setup.loadingEarlier');
        const curFrom = document.getElementById('diff-from-select')?.value;
        const curTo = document.getElementById('diff-to-select')?.value;
        const thisGen = ++setupHistoryGen;

        try {
          const more = await callBridge('setup.history', { ...identity, before: nextBefore, limit: 30 });
          if (currentModalInstance !== thisModalInstance || thisGen !== setupHistoryGen) return;

          nextBefore = more.nextBefore;
          const map = new Map();
          for (const r of allRevisions) map.set(r.revision, r);
          for (const r of (more.revisions || [])) {
            if (!map.has(r.revision)) map.set(r.revision, r);
          }
          allRevisions = Array.from(map.values()).sort((a, b) => b.revision - a.revision);

          const tbody = document.getElementById('setup-history-tbody');
          if (tbody) tbody.innerHTML = renderRevisionsRows();

          const countEl = document.getElementById('setup-revisions-count');
          if (countEl) countEl.textContent = `(${allRevisions.length})`;

          updateCompareSelects(curFrom, curTo);

          const earlierCont = document.getElementById('setup-earlier-container');
          if (earlierCont) {
            if (nextBefore) {
              earlierCont.innerHTML = `<button id="btn-load-earlier-setup-revisions" class="btn btn-secondary btn-xs" data-i18n="setup.loadEarlierRevisions">${escapeHtml(t('setup.loadEarlierRevisions'))}</button>`;
              bindEarlierBtn();
            } else {
              earlierCont.innerHTML = `<span class="text-secondary" style="font-size: 11px;" data-i18n="setup.allRevisionsLoaded">${escapeHtml(t('setup.allRevisionsLoaded'))}</span>`;
            }
          }
        } catch (err) {
          if (currentModalInstance !== thisModalInstance || thisGen !== setupHistoryGen) return;
          showToast({ key: 'common.error', params: { error: err.message } }, 'error');
          btn.disabled = false;
          btn.textContent = t('setup.loadEarlierRevisions');
        } finally {
          isLoadingEarlier = false;
        }
      });
    }

    bindEarlierBtn();

    document.getElementById('btn-run-setup-diff')?.addEventListener('click', async () => {
      const fromVal = parseInt(document.getElementById('diff-from-select')?.value || '1', 10);
      const toVal = parseInt(document.getElementById('diff-to-select')?.value || '1', 10);
      const diffContainer = document.getElementById('setup-diff-result');
      if (!diffContainer) return;
      diffContainer.innerHTML = `<div class="text-secondary" style="font-size: 12px; padding: 12px 0;">${escapeHtml(t('common.loading'))}</div>`;

      try {
        const diffRes = await callBridge('setup.diff', { ...identity, from: fromVal, to: toVal });
        if (currentModalInstance !== thisModalInstance) return;

        if (diffRes.diffAvailable === false) {
          diffContainer.innerHTML = `
            <div class="alert-banner alert-warning">
              <span data-i18n="setup.diffUnavailable" data-i18n-params="${escapeHtml(JSON.stringify({ reason: diffRes.reason || 'Not available' }))}">${escapeHtml(t('setup.diffUnavailable', { reason: diffRes.reason || 'Not available' }))}</span>
            </div>
          `;
          return;
        }

        const removed = Array.isArray(diffRes.removed) ? diffRes.removed : [];
        const added = Array.isArray(diffRes.added) ? diffRes.added : [];

        if (diffRes.sourceChanged && !diffRes.sanitizedTextChanged) {
          diffContainer.innerHTML = `
            <div class="alert-banner alert-warning">
              <span data-i18n="setup.diffSourceChangedOnly">${escapeHtml(t('setup.diffSourceChangedOnly'))}</span>
            </div>
          `;
          return;
        }

        if (removed.length === 0 && added.length === 0) {
          diffContainer.innerHTML = `
            <div class="alert-banner alert-sage">
              <span data-i18n="setup.noDiffContent">${escapeHtml(t('setup.noDiffContent'))}</span>
            </div>
          `;
          return;
        }

        diffContainer.innerHTML = `
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
            <span style="font-size: 12px; font-weight: 600;">
              <span data-i18n="setup.diffStartLine">${escapeHtml(t('setup.diffStartLine'))}</span> ${escapeHtml(String(diffRes.startLine ?? 1))}
            </span>
            <span class="status-badge status-neutral" style="font-size: 11px;">single_replacement_block</span>
          </div>
          <div class="diff-container" style="max-height: 220px; overflow-y: auto;">
            ${removed.map(l => `<div class="diff-line deletion"><span class="diff-marker">-</span><span>${escapeHtml(l)}</span></div>`).join('')}
            ${added.map(l => `<div class="diff-line addition"><span class="diff-marker">+</span><span>${escapeHtml(l)}</span></div>`).join('')}
          </div>
          <div style="font-size: 11px; color: var(--text-secondary); margin-top: 6px;" data-i18n="setup.diffNotice">
            ${escapeHtml(t('setup.diffNotice'))}
          </div>
        `;
      } catch (err) {
        if (diffContainer) diffContainer.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(err.message)}</div>`;
      }
    });
  }

  async function openSetupRelationsModal(art) {
    const isGlobal = art.scope === 'global';
    const identity = isGlobal ? { id: art.id, scope: 'global' } : { id: art.id, project: art.project || state.currentProject };

    openModal({ key: 'setup.relationsTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-setup-rel" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-setup-rel')?.addEventListener('click', closeModal);

    let relData = null;
    try {
      relData = await callBridge('setup.relations', identity);
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    if (!b) return;

    const relations = Array.isArray(relData.relations) ? relData.relations : [];

    b.innerHTML = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px;" data-i18n="setup.relationsDesc">${escapeHtml(t('setup.relationsDesc'))}</p>

      <div class="alert-banner alert-neutral" style="margin-bottom: 12px; font-size: 11px;">
        <span data-i18n="setup.relationRuntimeLoadedNotice">${escapeHtml(t('setup.relationRuntimeLoadedNotice'))}</span>
      </div>

      ${relations.length === 0 ? `
        <div class="empty-state" style="padding: 24px 0;">
          <div class="empty-state-title" data-i18n="setup.noRelations">${escapeHtml(t('setup.noRelations'))}</div>
        </div>
      ` : `
        <div class="table-wrapper">
          <table class="data-table">
            <thead>
              <tr>
                <th data-i18n="setup.colRelation">${escapeHtml(t('setup.colRelation'))}</th>
                <th data-i18n="setup.colTargetArtifact">${escapeHtml(t('setup.colTargetArtifact'))}</th>
                <th data-i18n="setup.colPath">${escapeHtml(t('setup.colPath'))}</th>
              </tr>
            </thead>
            <tbody>
              ${relations.map(r => `
                <tr>
                  <td>
                    ${r.relation === 'identical_observed_bytes' ? `<span class="status-badge status-sage" data-i18n="setup.relationIdenticalBytes">${escapeHtml(t('setup.relationIdenticalBytes'))}</span>` :
                      r.relation === 'same_declared_skill_name' ? `<span class="status-badge status-blue" data-i18n="setup.relationSameNameSkills">${escapeHtml(t('setup.relationSameNameSkills'))}</span>` :
                      `<span class="status-badge status-amber" data-i18n="setup.relationAgentsOverride">${escapeHtml(t('setup.relationAgentsOverride'))}</span>`}
                  </td>
                  <td><strong>${escapeHtml(r.artifactId || '-')}</strong></td>
                  <td><span class="font-mono" style="font-size: 11px;">${escapeHtml(r.path || '-')}</span></td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `}
    `;
  }

  // --- Real Guidelines Management (guidelines.list, guidelines.save) ---
  async function renderGuidelinesSection(target) {
    const thisGen = renderGeneration;
    const thisPage = state.currentPage;
    const thisScope = state.currentProject;

    target.innerHTML = `
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px;">
        <span class="text-secondary" style="font-size: 12px;" data-i18n="setupL.guidelines.headerDesc">${escapeHtml(t('setupL.guidelines.headerDesc'))}</span>
        <button id="btn-new-guideline" class="btn btn-primary btn-sm" data-i18n="setupL.guidelines.btnNew">${escapeHtml(t('setupL.guidelines.btnNew'))}</button>
      </div>
      <div id="guidelines-list-container">
        <div class="text-secondary" style="font-size: 12px; padding: 20px 0;" data-i18n="setupL.common.loading">${escapeHtml(t('setupL.common.loading'))}</div>
      </div>
    `;

    document.getElementById('btn-new-guideline').addEventListener('click', () => openCreateOrEditGuidelineModal());

    try {
      const guidelines = await callBridge('guidelines.list', state.currentProject ? { project: state.currentProject } : {});
      if (thisGen !== renderGeneration || state.currentPage !== thisPage || state.currentProject !== thisScope || !document.contains(target)) return;
      const list = Array.isArray(guidelines) ? guidelines : [];
      const cont = document.getElementById('guidelines-list-container');
      if (!cont) return;

      if (list.length === 0) {
        cont.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-title" data-i18n="setupL.guidelines.emptyTitle">${escapeHtml(t('setupL.guidelines.emptyTitle'))}</div>
            <div class="empty-state-desc" data-i18n="setupL.guidelines.emptyDesc">${escapeHtml(t('setupL.guidelines.emptyDesc'))}</div>
            <button id="btn-empty-add-gl" class="btn btn-primary btn-sm" style="margin-top: 12px;" data-i18n="setupL.guidelines.btnCreate">${escapeHtml(t('setupL.guidelines.btnCreate'))}</button>
          </div>
        `;
        document.getElementById('btn-empty-add-gl').addEventListener('click', () => openCreateOrEditGuidelineModal());
        return;
      }

      cont.innerHTML = `
        <div class="table-wrapper">
          <table class="data-table">
            <thead>
              <tr>
                <th data-i18n="setupL.guidelines.tableTitle">${escapeHtml(t('setupL.guidelines.tableTitle'))}</th>
                <th data-i18n="setupL.guidelines.tableScope">${escapeHtml(t('setupL.guidelines.tableScope'))}</th>
                <th data-i18n="setupL.guidelines.tableProject">${escapeHtml(t('setupL.guidelines.tableProject'))}</th>
                <th data-i18n="setupL.guidelines.tableUpdated">${escapeHtml(t('setupL.guidelines.tableUpdated'))}</th>
                <th style="text-align: right; width: 140px;" data-i18n="setupL.table.actions">${escapeHtml(t('setupL.table.actions'))}</th>
              </tr>
            </thead>
            <tbody>
              ${list.map(g => `
                <tr>
                  <td><strong>${escapeHtml(g.title || g.id)}</strong></td>
                  <td><span class="code-badge">${escapeHtml(g.scope || 'project')}</span></td>
                  <td style="font-size: 11px; color: var(--text-secondary);">${g.project ? escapeHtml(g.project.split('/').pop()) : tHtml('setupL.scope.global')}</td>
                  <td style="font-size: 11px; color: var(--text-secondary);">${formatTime(g.updatedAt || g.createdAt)}</td>
                  <td style="text-align: right;">
                    <button class="btn btn-secondary btn-sm btn-view-gl" data-id="${escapeHtml(g.id)}" data-i18n="setupL.common.view">${escapeHtml(t('setupL.common.view'))}</button>
                    <button class="btn btn-ghost btn-sm btn-edit-gl" data-id="${escapeHtml(g.id)}" data-i18n="setupL.common.edit">${escapeHtml(t('setupL.common.edit'))}</button>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;

      cont.querySelectorAll('.btn-view-gl').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const g = list.find(item => item.id === id);
          if (g) {
            openDrawer(g.title || { key: 'setupL.guidelines.drawerTitle' }, g.id);
            document.getElementById('drawer-content').innerHTML = `
              <div class="card">
                <div class="card-header">
                  <span class="card-title" data-i18n="setupL.drawer.basicInfo">${escapeHtml(t('setupL.drawer.basicInfo'))}</span>
                  <span class="status-badge status-neutral" data-i18n="setupL.guidelines.badgeSnapshot">${escapeHtml(t('setupL.guidelines.badgeSnapshot'))}</span>
                </div>
                <div style="font-size: 11px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
                  <div><span class="text-secondary" data-i18n="setupL.guidelines.scopeLabel">${escapeHtml(t('setupL.guidelines.scopeLabel'))}</span> ${escapeHtml(g.scope || 'project')}</div>
                  <div><span class="text-secondary" data-i18n="setupL.guidelines.projectLabel">${escapeHtml(t('setupL.guidelines.projectLabel'))}</span> ${g.project ? escapeHtml(g.project) : tHtml('setupL.scope.global')}</div>
                  <div><span class="text-secondary" data-i18n="setupL.guidelines.modeLabel">${escapeHtml(t('setupL.guidelines.modeLabel'))}</span> <span data-i18n="setupL.guidelines.modeValue">${escapeHtml(t('setupL.guidelines.modeValue'))}</span></div>
                  <div><span class="text-secondary" data-i18n="setupL.guidelines.runtimeImpactLabel">${escapeHtml(t('setupL.guidelines.runtimeImpactLabel'))}</span> <span data-i18n="setupL.guidelines.runtimeImpactValue">${escapeHtml(t('setupL.guidelines.runtimeImpactValue'))}</span></div>
                </div>
              </div>
              <div>
                <h3 style="font-size: 13px; font-weight: 600; margin-bottom: 6px;" data-i18n="setupL.guidelines.contentTitle">${escapeHtml(t('setupL.guidelines.contentTitle'))}</h3>
                <div class="code-view">${escapeHtml(g.content || '')}</div>
              </div>
            `;
          }
        });
      });

      cont.querySelectorAll('.btn-edit-gl').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const g = list.find(item => item.id === id);
          if (g) openCreateOrEditGuidelineModal(g);
        });
      });

    } catch (err) {
      if (thisGen !== renderGeneration || state.currentPage !== thisPage || state.currentProject !== thisScope || !document.contains(target)) return;
      const cont = document.getElementById('guidelines-list-container');
      if (cont) {
        cont.innerHTML = `
          <div class="alert-banner alert-danger">${tHtml('setupL.guidelines.loadFailed', { error: err.message })}</div>
        `;
      }
    }
  }

  function openCreateOrEditGuidelineModal(initial = null) {
    const isEdit = !!(initial && initial.id);
    const modalBody = `
      <div class="form-group">
        <label class="form-label" data-i18n="setupL.guidelines.modalTitleLabel">${escapeHtml(t('setupL.guidelines.modalTitleLabel'))}</label>
        <input type="text" id="gl-title" class="form-input" value="${escapeHtml(initial ? initial.title : '')}" placeholder="${escapeHtml(t('setupL.guidelines.modalTitlePlaceholder'))}" data-i18n-placeholder="setupL.guidelines.modalTitlePlaceholder">
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="setupL.guidelines.modalScopeLabel">${escapeHtml(t('setupL.guidelines.modalScopeLabel'))}</label>
          <select id="gl-scope" class="form-select">
            <option value="project" ${(initial && initial.scope === 'project') ? 'selected' : ''} data-i18n="setupL.guidelines.scopeProject">${escapeHtml(t('setupL.guidelines.scopeProject'))}</option>
            <option value="global" ${(initial && initial.scope === 'global') ? 'selected' : ''} data-i18n="setupL.guidelines.scopeGlobal">${escapeHtml(t('setupL.guidelines.scopeGlobal'))}</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="setupL.guidelines.modalProjectLabel">${escapeHtml(t('setupL.guidelines.modalProjectLabel'))}</label>
          <select id="gl-project" class="form-select">
            <option value="" data-i18n="setupL.guidelines.projectNone">${escapeHtml(t('setupL.guidelines.projectNone'))}</option>
            ${state.registeredProjects.map(p => `
              <option value="${escapeHtml(p.path || p.id)}" ${(initial && initial.project === (p.path || p.id)) ? 'selected' : ''}>${escapeHtml(p.title || p.path)}</option>
            `).join('')}
          </select>
        </div>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="setupL.guidelines.modalContentLabel">${escapeHtml(t('setupL.guidelines.modalContentLabel'))}</label>
        <textarea id="gl-content" class="form-textarea code-editor" style="min-height: 140px;" placeholder="${escapeHtml(t('setupL.guidelines.modalContentPlaceholder'))}" data-i18n-placeholder="setupL.guidelines.modalContentPlaceholder">${escapeHtml(initial ? initial.content || '' : '')}</textarea>
      </div>
    `;

    openModal(isEdit ? { key: 'setupL.guidelines.modalEditTitle' } : { key: 'setupL.guidelines.modalCreateTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-gl" data-i18n="setupL.common.cancel">${escapeHtml(t('setupL.common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-save-gl" data-i18n="setupL.guidelines.btnSave">${escapeHtml(t('setupL.guidelines.btnSave'))}</button>
    `);

    document.getElementById('btn-cancel-gl').addEventListener('click', closeModal);
    document.getElementById('btn-save-gl').addEventListener('click', async () => {
      const title = document.getElementById('gl-title').value.trim();
      const scope = document.getElementById('gl-scope').value;
      const project = document.getElementById('gl-project').value;
      const content = document.getElementById('gl-content').value.trim();

      if (!title || !content) {
        showToast({ key: 'setupL.guidelines.toastValidationEmpty' }, 'error');
        return;
      }

      try {
        await callBridge('guidelines.save', {
          id: isEdit ? initial.id : undefined,
          title,
          scope,
          project: project || undefined,
          content
        });
        showToast({ key: 'setupL.guidelines.toastSaved' });
        closeModal();
        renderGuidelinesSection(document.getElementById('setup-tab-content'));
      } catch (err) {
        showToast({ key: 'setupL.guidelines.toastSaveFailed', params: { error: err.message } }, 'error');
      }
    });
  }

  // ===========================================================================
  // REUSE FRAGMENT: Codex Memory Reuse, Provider Trust & Outcomes
  // ===========================================================================
  function isSafeNonNegativeInteger(val) {
    return typeof val === 'number' && Number.isSafeInteger(val) && val >= 0;
  }

  function formatSafeCount(val) {
    return isSafeNonNegativeInteger(val) ? val.toLocaleString() : '未提供';
  }

  function safeEscapeHtml(str) {
    if (typeof escapeHtml === 'function') {
      return escapeHtml(str);
    }
    if (str === null || str === undefined) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function formatSafeTime(isoStr) {
    if (typeof formatTime === 'function') {
      return formatTime(isoStr);
    }
    if (!isoStr) return '-';
    try {
      const d = new Date(isoStr);
      if (!isNaN(d.getTime())) return d.toLocaleString();
    } catch {}
    return String(isoStr);
  }

  function isAlreadyInstalledHook(sugOrPreview) {
    if (!sugOrPreview) return false;
    const ops = sugOrPreview.operations || sugOrPreview.preview || [];
    return sugOrPreview.alreadyInstalled === true && Array.isArray(ops) && ops.length === 0;
  }

  function renderProviderTrustNotice(sugOrPreview, isApplied = false) {
    if (!sugOrPreview || !sugOrPreview.requiresProviderTrust) return '';
    const noticeKey = isApplied ? 'improve.providerTrustNoticeApplied' : 'improve.providerTrustNoticeUnapplied';

    return `
      <div class="alert-banner alert-warning" style="margin-top: 8px; font-size: 11px; line-height: 1.5; border-color: var(--status-amber-border); background-color: var(--status-amber-bg); color: var(--status-amber-text);" role="note">
        <div style="font-weight: 600; margin-bottom: 2px;" data-i18n="improve.providerTrustTitle">${t('improve.providerTrustTitle')}</div>
        <div data-i18n="${noticeKey}">
          ${tHtml(noticeKey)}
        </div>
      </div>
    `;
  }

  function renderAlreadyInstalledNotice(sugOrPreview) {
    if (!isAlreadyInstalledHook(sugOrPreview)) return '';
    return `
      <div class="alert-banner alert-neutral" style="margin-top: 8px; font-size: 11px; line-height: 1.5; border-color: var(--status-sage-border); background-color: var(--status-sage-bg); color: var(--status-sage-text);" role="note">
        <div style="font-weight: 600; margin-bottom: 2px;" data-i18n="improve.alreadyInstalledTitle">✓ ${t('improve.alreadyInstalledTitle')}</div>
        <div data-i18n="improve.alreadyInstalledDesc">${tHtml('improve.alreadyInstalledDesc')}</div>
      </div>
    `;
  }

  let reuseModalSequence = 0;
  let reuseOutcomesSequence = 0;

  function openConfigureReuseModal() {
    const registered = (state.registeredProjects || []);
    const scopedProject = state.currentProject;

    let selectedProj = '';
    if (scopedProject && registered.some(p => (p.path || p.id) === scopedProject)) {
      selectedProj = scopedProject;
    }

    const projectOptionsHtml = `
      <option value="" ${!selectedProj ? 'selected' : ''} data-i18n="reuse.selectProjectPlaceholder">${t('reuse.selectProjectPlaceholder')}</option>
      ${registered.map(p => {
        const pPath = p.path || p.id || '';
        const pDisplayName = p.title || p.name || (pPath ? pPath.split('/').filter(Boolean).pop() : t('common.unnamedProject'));
        const isSel = pPath === selectedProj;
        return `<option value="${safeEscapeHtml(pPath)}" ${isSel ? 'selected' : ''}>${safeEscapeHtml(pDisplayName)}</option>`;
      }).join('')}
    `;

    const bodyHtml = `
      <p style="font-size: 12px; color: var(--text-main); margin-bottom: 12px; line-height: 1.5;" data-i18n="reuse.modalNoticeDesc">
        ${t('reuse.modalNoticeDesc')}
      </p>
      <div class="form-group" style="margin-bottom: 12px;">
        <label class="form-label" for="reuse-project-select" style="font-size: 12px; font-weight: 600; margin-bottom: 4px; display: block;" data-i18n="reuse.targetProjectLabel">${t('reuse.targetProjectLabel')}</label>
        <select id="reuse-project-select" class="form-control" style="width: 100%; font-size: 12px; padding: 6px 8px;">
          ${projectOptionsHtml}
        </select>
      </div>
      <div id="reuse-dialog-error" role="alert" aria-live="polite"></div>
    `;

    const footerHtml = `
      <button class="btn btn-secondary" id="btn-cancel-reuse" data-i18n="common.cancel">${t('common.cancel')}</button>
      <button class="btn btn-primary" id="btn-preview-reuse" data-i18n="reuse.btnPreviewDiff" ${!selectedProj ? 'disabled' : ''}>${t('reuse.btnPreviewDiff')}</button>
    `;

    openModal({ key: 'reuse.modalTitle' }, bodyHtml, footerHtml);

    const sel = document.getElementById('reuse-project-select');
    const btnPreview = document.getElementById('btn-preview-reuse');
    const btnCancel = document.getElementById('btn-cancel-reuse');
    const errEl = document.getElementById('reuse-dialog-error');

    if (btnCancel) {
      btnCancel.addEventListener('click', closeModal);
    }

    if (sel && btnPreview) {
      sel.addEventListener('change', () => {
        const val = (sel.value || '').trim();
        btnPreview.disabled = !val;
        if (errEl) errEl.innerHTML = '';
      });
    }

    if (btnPreview && sel) {
      btnPreview.addEventListener('click', async () => {
        const chosenProject = (sel.value || '').trim();
        if (!chosenProject) return;

        const registeredList = state.registeredProjects || [];
        const matchedProj = registeredList.find(p => (p.path || p.id) === chosenProject);
        if (!matchedProj || !matchedProj.path) {
          if (errEl) {
            errEl.innerHTML = `<div class="alert-banner alert-danger" style="margin-top: 10px; font-size: 11px;" data-i18n="reuse.unregisteredProjectError">${t('reuse.unregisteredProjectError')}</div>`;
          }
          return;
        }
        const verifiedProject = matchedProj.path;

        btnPreview.disabled = true;
        sel.disabled = true;
        const originalText = btnPreview.textContent;
        setElementDescriptor(btnPreview, { key: 'reuse.previewLoading' });
        if (errEl) errEl.innerHTML = '';

        const thisSeq = ++reuseModalSequence;
        const thisModal = currentModalInstance;
        const thisPage = state.currentPage;
        const thisProject = state.currentProject;

        try {
          const suggestion = await callBridge('reuse.preview', { project: verifiedProject });

          const modal = document.getElementById('modal-container');
          const isModalOpen = modal && !modal.classList.contains('hidden');
          if (thisSeq !== reuseModalSequence || thisModal !== currentModalInstance || !isModalOpen || !document.contains(modal) || state.currentPage !== thisPage || state.currentProject !== thisProject) {
            return;
          }

          closeModal();
          if (suggestion && suggestion.id) {
            openImprovePreviewDrawer(suggestion.id);
          } else {
            showToast({ key: 'reuse.previewMissingIdToast' }, 'warning');
          }
        } catch (err) {
          const modal = document.getElementById('modal-container');
          const isModalOpen = modal && !modal.classList.contains('hidden');
          if (thisSeq !== reuseModalSequence || thisModal !== currentModalInstance || !isModalOpen || !document.contains(modal) || state.currentPage !== thisPage || state.currentProject !== thisProject) {
            return;
          }

          btnPreview.disabled = false;
          setElementDescriptor(btnPreview, { key: 'reuse.btnSimulatePreview' });
          sel.disabled = false;
          if (errEl) {
            errEl.innerHTML = `
              <div class="alert-banner alert-danger" style="margin-top: 10px; font-size: 11px;">
                ${t('reuse.previewFailedError', { error: safeEscapeHtml(err.message || String(err)) })}
              </div>
            `;
          }
        }
      });
    }
  }

  async function openReuseOutcomesDrawer(memoryId) {
    if (!memoryId) {
      showToast({ key: 'reuse.missingIdToast' }, 'warning');
      return;
    }

    const memories = (state.dashboard && state.dashboard.memories) || [];
    const mem = memories.find(m => m.id === memoryId);

    if (!mem) {
      showToast({ key: 'reuse.memNotFoundToast' }, 'warning');
      return;
    }

    const targetProject = mem.project;
    if (!targetProject || typeof targetProject !== 'string') {
      showToast({ key: 'reuse.missingProjectToast' }, 'warning');
      return;
    }

    const projObj = (state.registeredProjects || []).find(p => p && p.path === targetProject);
    if (!projObj || !projObj.path) {
      showToast({ key: 'reuse.projectNotConnectedToast' }, 'warning');
      return;
    }

    const projectFriendlyName = projObj.title || projObj.name || (targetProject ? targetProject.split('/').filter(Boolean).pop() : t('common.currentProject'));
    const memTitle = mem.title || t('reuse.defaultMemoryTitle');

    openDrawer({ key: 'reuse.drawerTitle' }, `${memTitle} · ${projectFriendlyName}`);

    const thisSeq = ++reuseOutcomesSequence;
    const thisDrawer = currentDrawerInstance;
    const thisPage = state.currentPage;
    const thisProject = state.currentProject;

    try {
      const outcomes = await callBridge('reuse.outcomes', { project: targetProject, id: memoryId });

      const drawer = document.getElementById('detail-drawer');
      const isDrawerOpen = drawer && !drawer.classList.contains('hidden');
      if (thisSeq !== reuseOutcomesSequence || thisDrawer !== currentDrawerInstance || !isDrawerOpen || !document.contains(drawer) || state.currentPage !== thisPage || state.currentProject !== thisProject) {
        return;
      }

      if (!outcomes) {
        const e = new Error('reuse.noOutcomesData');
        e.i18nKey = 'reuse.noOutcomesData';
        throw e;
      }

      renderReuseOutcomesDrawerContent(outcomes, mem, targetProject, projectFriendlyName);
    } catch (err) {
      const drawer = document.getElementById('detail-drawer');
      const isDrawerOpen = drawer && !drawer.classList.contains('hidden');
      if (thisSeq !== reuseOutcomesSequence || thisDrawer !== currentDrawerInstance || !isDrawerOpen || !document.contains(drawer) || state.currentPage !== thisPage || state.currentProject !== thisProject) {
        return;
      }

      setDrawerTitle({ key: 'reuse.fetchFailedDrawerTitle' }, { key: 'reuse.fetchFailedDrawerSubtitle' });
      const drawerBody = document.getElementById('drawer-content');
      if (drawerBody) {
        if (err && err.i18nKey) {
          drawerBody.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="reuse.fetchFailedPrefix">${escapeHtml(t('reuse.fetchFailedPrefix'))}</span><span data-i18n="${err.i18nKey}">${escapeHtml(t(err.i18nKey))}</span>
            </div>
          `;
        } else {
          drawerBody.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="reuse.fetchFailedPrefix">${escapeHtml(t('reuse.fetchFailedPrefix'))}</span><span>${safeEscapeHtml(err.message || String(err))}</span>
            </div>
          `;
        }
      }
    }
  }

  function renderReuseOutcomesDrawerContent(outcomes, mem, targetProject, projectFriendlyName) {
    const drawerBody = document.getElementById('drawer-content');
    if (!drawerBody) return;

    const receipts = Array.isArray(outcomes.receipts) ? outcomes.receipts : [];
    const offeredSessions = outcomes.offeredSessions;
    const matchedSessions = outcomes.matchedSessions;
    const indexedSessionRecords = outcomes.indexedSessionRecords;
    const sessionIds = Array.isArray(outcomes.sessionIds) ? outcomes.sessionIds : [];
    const signals = Array.isArray(outcomes.observedVerificationSignals) ? outcomes.observedVerificationSignals : [];

    const verificationCorrectionCount = outcomes.verificationCorrectionCount;
    const agentAdoption = outcomes.agentAdoption;
    const analysisCoverage = outcomes.analysisCoverage;

    const limitations = Array.isArray(outcomes.limitations) ? outcomes.limitations : [];
    const method = outcomes.method || '';
    const knownSessions = (state.dashboard && state.dashboard.sessions) || [];

    const displayCorrectionCount = (verificationCorrectionCount !== null && isSafeNonNegativeInteger(verificationCorrectionCount))
      ? verificationCorrectionCount.toLocaleString()
      : t('common.notProvided');

    const displayReduction = t('common.notProvided');

    const displayAdoption = (agentAdoption === 'not_measured' || !agentAdoption)
      ? t('reuse.notMeasured')
      : safeEscapeHtml(agentAdoption);

    const displayCoverage = (analysisCoverage === 'not_established' || !analysisCoverage)
      ? t('reuse.notEstablished')
      : safeEscapeHtml(analysisCoverage);

    drawerBody.innerHTML = `
      <div class="card" style="margin-bottom: 10px; padding: 10px 12px;">
        <div class="card-header" style="margin-bottom: 6px;">
          <span class="card-title" style="font-size: 12px;">${safeEscapeHtml(mem.title || t('reuse.defaultMemoryTitle'))}</span>
          ${mem.state && typeof getMemoryStateBadge === 'function' ? getMemoryStateBadge(mem.state) : ''}
        </div>
        <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 6px;">
          <span data-i18n="reuse.projectLabel">${t('reuse.projectLabel')}</span><strong style="color: var(--text-main);">${safeEscapeHtml(projectFriendlyName)}</strong>
        </div>
        <details style="font-size: 10.5px; color: var(--text-muted);">
          <summary style="cursor: pointer; user-select: none;" data-i18n="reuse.techSummary">${t('reuse.techSummary')}</summary>
          <div class="font-mono" style="margin-top: 4px; display: grid; gap: 2px;">
            <div><span data-i18n="reuse.memoryIdLabel">${t('reuse.memoryIdLabel')}</span> <span style="user-select: all;">${safeEscapeHtml(mem.id)}</span></div>
            <div><span data-i18n="reuse.projectPathLabel">${t('reuse.projectPathLabel')}</span> <span style="user-select: all;">${safeEscapeHtml(targetProject)}</span></div>
          </div>
        </details>
      </div>

      <table class="data-table" style="width: 100%; font-size: 11px; margin-bottom: 10px; border: 1px solid var(--border-subtle); border-radius: var(--radius-sm); border-collapse: collapse;">
        <tbody>
          <tr style="border-bottom: 1px solid var(--border-subtle);">
            <td style="color: var(--text-secondary); padding: 5px 8px; width: 35%;" data-i18n="reuse.tableOfferedSessions">${t('reuse.tableOfferedSessions')}</td>
            <td class="font-mono" style="font-weight: 600; padding: 5px 8px;">${formatSafeCount(offeredSessions)}</td>
            <td style="color: var(--text-secondary); padding: 5px 8px; width: 35%;" data-i18n="reuse.tableMatchedSessions">${t('reuse.tableMatchedSessions')}</td>
            <td class="font-mono" style="font-weight: 600; padding: 5px 8px;">${formatSafeCount(matchedSessions)}</td>
          </tr>
          <tr style="border-bottom: 1px solid var(--border-subtle);">
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableIndexedRecords">${t('reuse.tableIndexedRecords')}</td>
            <td class="font-mono" style="font-weight: 600; padding: 5px 8px;">${formatSafeCount(indexedSessionRecords)}</td>
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableReceiptsCount">${t('reuse.tableReceiptsCount')}</td>
            <td class="font-mono" style="font-weight: 600; padding: 5px 8px;">${receipts.length}</td>
          </tr>
          <tr style="border-bottom: 1px solid var(--border-subtle);">
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableCoverage">${t('reuse.tableCoverage')}</td>
            <td style="padding: 5px 8px;"><span class="status-badge status-neutral">${displayCoverage}</span></td>
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableAdoption">${t('reuse.tableAdoption')}</td>
            <td style="padding: 5px 8px;"><span class="status-badge status-neutral">${displayAdoption}</span></td>
          </tr>
          <tr>
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableCorrectionCount">${t('reuse.tableCorrectionCount')}</td>
            <td style="color: var(--text-muted); padding: 5px 8px;">${displayCorrectionCount}</td>
            <td style="color: var(--text-secondary); padding: 5px 8px;" data-i18n="reuse.tableCorrectionRate">${t('reuse.tableCorrectionRate')}</td>
            <td style="color: var(--text-muted); padding: 5px 8px;">${displayReduction}</td>
          </tr>
        </tbody>
      </table>

      <div class="improve-methodology-note" role="note" style="margin-bottom: 12px;">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
        <span data-i18n="reuse.methodologyNote">${t('reuse.methodologyNote')}</span>
      </div>

      <div style="margin-bottom: 16px;">
        <h3 style="font-size: 13px; font-weight: 600; margin-bottom: 8px;" data-i18n="reuse.receiptsTitle" data-i18n-params="${escapeHtml(JSON.stringify({ count: receipts.length }))}">${t('reuse.receiptsTitle', { count: receipts.length })}</h3>
        ${receipts.length === 0 ? `
          <div class="empty-state" style="padding: 16px 14px; margin-bottom: 12px;">
            <div class="empty-state-title" style="font-size: 12.5px;" data-i18n="reuse.emptyReceiptsTitle">${t('reuse.emptyReceiptsTitle')}</div>
            <div class="empty-state-desc" style="font-size: 11px; line-height: 1.6; text-align: left; margin-top: 8px; max-width: 480px; margin-left: auto; margin-right: auto;" data-i18n="reuse.emptyReceiptsDesc">
              ${t('reuse.emptyReceiptsDesc')}
            </div>
          </div>
        ` : `
          <div style="display: flex; flex-direction: column; gap: 8px;">
            ${receipts.map(r => {
              const matchedRecord = knownSessions.find(s =>
                s.project === targetProject &&
                String(s.provider || '').toLowerCase() === 'codex' &&
                Boolean(s.sourceSessionId && s.sourceSessionId === r.sourceSessionId) &&
                sessionIds.includes(s.id)
              );
              const isMapped = Boolean(matchedRecord);
              const displayTokens = (r.usedTokens !== null && r.usedTokens !== undefined && isSafeNonNegativeInteger(r.usedTokens))
                ? r.usedTokens.toLocaleString()
                : t('common.notProvided');

              return `
                <div class="card" style="margin-bottom: 0; padding: 10px 12px;">
                  <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; margin-bottom: 4px;">
                    <div style="display: flex; align-items: center; gap: 6px; font-size: 11px;">
                      <span class="status-badge status-sage" data-i18n="reuse.badgeContextProvided">${t('reuse.badgeContextProvided')}</span>
                      <span style="color: var(--text-secondary);">${formatSafeTime(r.servedAt)}</span>
                      <span class="badge-subtle font-mono">${safeEscapeHtml(r.event || 'SessionStart')}</span>
                    </div>
                    <div>
                      ${isMapped ? `
                        <button type="button" class="btn-open-source" data-session-id="${safeEscapeHtml(matchedRecord.id)}" title="${t('reuse.indexedSessionTitle', { id: safeEscapeHtml(matchedRecord.id) })}">
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
                          <span>${safeEscapeHtml(matchedRecord.title || t('reuse.indexedSessionFallback'))}</span>
                        </button>
                      ` : `
                        <span style="color: var(--text-secondary); font-size: 11px;" data-i18n="reuse.unmatchedProviderSession">${t('reuse.unmatchedProviderSession')}</span>
                      `}
                    </div>
                  </div>

                  <details style="margin-top: 6px; font-size: 10px; color: var(--text-muted);">
                    <summary style="cursor: pointer; user-select: none;" data-i18n="reuse.receiptTechSummary">${t('reuse.receiptTechSummary')}</summary>
                    <div class="font-mono" style="margin-top: 4px; display: grid; gap: 2px;">
                      <div><span data-i18n="reuse.receiptIdLabel">${t('reuse.receiptIdLabel')}</span> <span style="user-select: all;">${safeEscapeHtml(r.id || '-')}</span></div>
                      <div><span data-i18n="reuse.providerSessionIdLabel">${t('reuse.providerSessionIdLabel')}</span> <span style="user-select: all;">${safeEscapeHtml(r.sourceSessionId || '-')}</span></div>
                      <div><span data-i18n="reuse.contextHashLabel">${t('reuse.contextHashLabel')}</span> <span style="user-select: all;">${safeEscapeHtml(r.contextHash || '-')}</span></div>
                      <div><span data-i18n="reuse.deliveryChannelLabel">${t('reuse.deliveryChannelLabel')}</span> <span>${safeEscapeHtml(r.delivery || '-')}</span></div>
                      <div><span data-i18n="reuse.usedTokensLabel">${t('reuse.usedTokensLabel')}</span> <span>${displayTokens}</span></div>
                    </div>
                  </details>
                </div>
              `;
            }).join('')}
          </div>
        `}
      </div>

      <div style="margin-bottom: 16px;">
        <h3 style="font-size: 13px; font-weight: 600; margin-bottom: 4px;" data-i18n="reuse.subsequentSignalsTitle" data-i18n-params="${escapeHtml(JSON.stringify({ count: signals.length }))}">${t('reuse.subsequentSignalsTitle', { count: signals.length })}</h3>
        <p style="font-size: 11px; color: var(--text-secondary); margin-bottom: 8px;" data-i18n="reuse.subsequentSignalsSubtitle">
          ${t('reuse.subsequentSignalsSubtitle')}
        </p>
        ${signals.length === 0 ? `
          <div style="font-size: 12px; color: var(--text-muted); padding: 8px 0;" data-i18n="reuse.noSignals">${t('reuse.noSignals')}</div>
        ` : `
          <div style="display: flex; flex-direction: column; gap: 6px;">
            ${signals.map(sig => {
              const quote = sig.quote || sig.summary || sig.content || t('reuse.defaultSignalContent');
              return `
                <div class="card" style="margin-bottom: 0; padding: 8px 12px;">
                  <div style="font-size: 12px; color: var(--text-main); font-style: italic; line-height: 1.45; margin-bottom: 4px;">
                    "${safeEscapeHtml(quote)}"
                  </div>
                  <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; font-size: 11px;">
                    <span class="badge-subtle font-mono">${safeEscapeHtml(sig.clusterKey || 'verification')}</span>
                    ${sig.sourceSession ? `
                      <button type="button" class="btn-open-source" data-session-id="${safeEscapeHtml(sig.sourceSession)}" ${sig.sourceMessage ? `data-message-id="${safeEscapeHtml(sig.sourceMessage)}"` : ''} title="${t('reuse.locateSignalSessionTooltip')}" data-i18n-title="reuse.locateSignalSessionTooltip">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
                        <span data-i18n="reuse.locateSourceMsg">${t('reuse.locateSourceMsg')}</span>
                      </button>
                    ` : ''}
                  </div>
                  <details style="margin-top: 4px; font-size: 10px; color: var(--text-muted);">
                    <summary style="cursor: pointer; user-select: none;" data-i18n="reuse.signalTechSummary">${t('reuse.signalTechSummary')}</summary>
                    <div class="font-mono" style="margin-top: 2px;">
                      <div><span data-i18n="reuse.sessionIdLabel">${t('reuse.sessionIdLabel')}</span> ${safeEscapeHtml(sig.sourceSession || '-')}</div>
                      ${sig.sourceMessage ? `<div><span data-i18n="reuse.messageIdLabel">${t('reuse.messageIdLabel')}</span> ${safeEscapeHtml(sig.sourceMessage)}</div>` : ''}
                    </div>
                  </details>
                </div>
              `;
            }).join('')}
          </div>
        `}
      </div>

      ${(method || limitations.length > 0) ? `
        <details class="card" style="margin-top: 10px; padding: 8px 12px;">
          <summary style="font-size: 11px; font-weight: 600; cursor: pointer; color: var(--text-secondary); user-select: none;" data-i18n="reuse.methodologySummary">${t('reuse.methodologySummary')}</summary>
          ${method ? `<div style="font-size: 11px; color: var(--text-secondary); margin-top: 6px; line-height: 1.5;">${safeEscapeHtml(method)}</div>` : ''}
          ${limitations.length > 0 ? `
            <ul style="padding-left: 18px; font-size: 10.5px; color: var(--text-muted); margin-top: 6px; line-height: 1.5;">
              ${limitations.map(lim => `<li>${safeEscapeHtml(lim)}</li>`).join('')}
            </ul>
          ` : ''}
        </details>
      ` : ''}
    `;
  }

  // --- Complete Memory Management (Lifecycle tabs, Blume content-first cards, provenance) ---
  function renderMemorySection(target) {
    const memories = (state.dashboard && state.dashboard.memories) || [];
    const activeFilter = state.memoryFilter || 'all';

    const filterTabs = [
      { key: 'all', labelKey: 'memory.tabAll', label: t('memory.tabAll'), count: memories.length },
      { key: 'candidate', labelKey: 'memory.tabCandidate', label: t('memory.tabCandidate'), count: memories.filter(m => (m.state || 'candidate').toLowerCase() === 'candidate').length },
      { key: 'active', labelKey: 'memory.tabActive', label: t('memory.tabActive'), count: memories.filter(m => (m.state || '').toLowerCase() === 'active').length },
      { key: 'superseded', labelKey: 'memory.tabSuperseded', label: t('memory.tabSuperseded'), count: memories.filter(m => (m.state || '').toLowerCase() === 'superseded').length },
      { key: 'archived', labelKey: 'memory.tabArchived', label: t('memory.tabArchived'), count: memories.filter(m => (m.state || '').toLowerCase() === 'archived').length }
    ];

    const displayedMemories = memories.filter(m => {
      if (activeFilter === 'all') return true;
      const st = (m.state || 'candidate').toLowerCase();
      return st === activeFilter;
    });

    target.innerHTML = `
      <div class="memory-toolbar">
        <div class="memory-primary-actions">
          <button id="btn-new-memory" class="btn btn-primary btn-sm" data-i18n="memory.btnNewMemory">${t('memory.btnNewMemory')}</button>
          <button id="btn-knowledge-ask" class="btn btn-secondary btn-sm" data-i18n="ask.modalBtn">${t('ask.modalBtn')}</button>
          <details class="action-menu"><summary class="btn btn-ghost icon-action" aria-label="${escapeHtml(t('reading.tools'))}" title="${escapeHtml(t('reading.tools'))}"><span aria-hidden="true">···</span></summary><div class="action-menu-items">
            ${[['btn-configure-reuse','memory.btnConfigReuse'],['btn-recall-tester','memory.btnRecallTester'],['btn-semantic-memory','memory.btnSemanticMemory'],['btn-export-memory-archive','memory.btnExportArchive'],['btn-import-memory-archive','memory.btnImportArchive']].map(([id,key]) => `<button id="${id}" type="button" class="btn btn-ghost btn-sm" data-i18n="${key}">${t(key)}</button>`).join('')}
          </div></details>

        </div>
        <div class="memory-filter-bar" aria-label="Memory filters">
          ${filterTabs.map(tab => `<button type="button" class="memory-filter-btn ${activeFilter === tab.key ? 'active' : ''}" data-filter="${tab.key}" aria-pressed="${activeFilter === tab.key}"><span data-i18n="${tab.labelKey}">${tab.label}</span><span class="memory-filter-count">${tab.count}</span></button>`).join('')}
        </div>

      </div>

      <div class="memory-card-list">
        ${memories.length === 0 ? `
          <div class="empty-state">
            <div class="empty-state-title" data-i18n="memory.emptyTitle">${t('memory.emptyTitle')}</div>
            <div class="empty-state-desc" data-i18n="memory.emptyDesc">${t('memory.emptyDesc')}</div>
            <button id="btn-empty-new-mem" class="btn btn-primary btn-sm" style="margin-top: 12px;" data-i18n="memory.btnNewMemory">${t('memory.btnNewMemory')}</button>
          </div>
        ` : (displayedMemories.length === 0 ? `
          <div class="empty-state" style="padding: 32px 16px;">
            <div class="empty-state-desc" data-i18n="memory.categoryEmptyDesc" data-i18n-params="${escapeHtml(JSON.stringify({ category: filterTabs.find(t => t.key === activeFilter)?.label || activeFilter }))}">${t('memory.categoryEmptyDesc', { category: filterTabs.find(t => t.key === activeFilter)?.label || activeFilter })}</div>
          </div>
        ` : displayedMemories.map(m => {
          const st = (m.state || 'candidate').toLowerCase();
          let provenanceHtml = '';
          const memSrcSession = m.sourceSession || (m.provenance && (m.provenance.session || m.provenance.sessionId));
          const memSrcMsg = m.sourceMessage || (m.provenance && (m.provenance.message || m.provenance.messageId));
          if (memSrcSession) {
            const knownSession = ((state.dashboard && state.dashboard.sessions) || []).find(s => s.id === memSrcSession);
            const sessionLabel = (knownSession && knownSession.title) ? knownSession.title : t('memory.sourceSessionDefault');
            const tooltipTitle = memSrcMsg
              ? t('memory.sourceSessionTooltip', { sessionId: memSrcSession, messageId: memSrcMsg })
              : t('memory.sourceSessionTooltipShort', { sessionId: memSrcSession });
            provenanceHtml = `
              <span data-i18n="memory.sourcePrefix">${t('memory.sourcePrefix')}</span>
              <button type="button" class="btn-open-source" data-session-id="${escapeHtml(memSrcSession)}" ${memSrcMsg ? `data-message-id="${escapeHtml(memSrcMsg)}"` : ''} title="${escapeHtml(tooltipTitle)}">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
                <span>${escapeHtml(sessionLabel)}</span>
              </button>
            `;
          } else if (m.sourceFile) {
            provenanceHtml = `<span><span data-i18n="memory.sourceFilePrefix">${t('memory.sourceFilePrefix')}</span><span class="font-mono">${escapeHtml(m.sourceFile)}</span></span>`;
          } else if (m.sourceCommit) {
            provenanceHtml = `<span><span data-i18n="memory.sourceCommitPrefix">${t('memory.sourceCommitPrefix')}</span><span class="font-mono">${escapeHtml(m.sourceCommit.slice(0, 7))}</span></span>`;
          } else {
            provenanceHtml = `<span style="color: var(--text-muted);" data-i18n="memory.manualOrigin">${t('memory.manualOrigin')}</span>`;
          }

          const memoryStateKeyMap = { candidate: 'memory.stateCandidate', active: 'memory.stateActive', superseded: 'memory.stateSuperseded', archived: 'memory.stateArchived' };
          const memoryStateKey = memoryStateKeyMap[st] || '';
          const memoryStateText = memoryStateKey ? t(memoryStateKey) : st;

          return `
            <div class="memory-card${st === 'candidate' ? ' is-candidate' : ''}" data-id="${escapeHtml(m.id)}">
              <div class="memory-card-header">
                <div class="memory-card-title-group">
                  <button class="row-title memory-card-title btn-mem-view" data-id="${escapeHtml(m.id)}" title="${escapeHtml(m.title || t('memory.unnamedMemory'))}">${escapeHtml(m.title || t('memory.unnamedMemory'))}</button>
                  <div class="memory-card-meta">
                    <span class="memory-state is-${escapeHtml(st)}"${memoryStateKey ? ` data-i18n="${memoryStateKey}"` : ''}>${escapeHtml(memoryStateText)}</span>
                    ${renderMemoryTypeInline(m.type)}
                    ${renderMemoryScopeInline(m.scope)}
                  </div>
                </div>
                <div class="memory-card-actions">
                  <details class="action-menu"><summary class="btn btn-ghost btn-sm" aria-label="${escapeHtml(t('reading.more'))}" title="${escapeHtml(t('reading.more'))}">•••</summary><div class="action-menu-items"><button class="btn btn-ghost btn-sm btn-mem-edit" data-id="${escapeHtml(m.id)}" data-i18n="memory.btnEdit">${t('memory.btnEdit')}</button>                  ${st === 'candidate' ? `<button class="btn btn-secondary btn-sm btn-mem-activate" data-id="${escapeHtml(m.id)}" data-i18n="memory.btnActivate">${t('memory.btnActivate')}</button>` : ''}
                  ${st === 'active' ? `<button class="btn btn-ghost btn-sm btn-mem-supersede" data-id="${escapeHtml(m.id)}" title="${t('memory.btnSupersedeTitle')}" data-i18n-title="memory.btnSupersedeTitle" data-i18n="memory.btnSupersede">${t('memory.btnSupersede')}</button>` : ''}
                  ${st !== 'archived' ? `<button class="btn btn-ghost btn-sm btn-mem-archive" data-id="${escapeHtml(m.id)}" data-i18n="memory.btnArchive">${t('memory.btnArchive')}</button>` : ''}
                  <button class="btn btn-ghost btn-sm btn-memory-outcomes" data-memory-id="${escapeHtml(m.id)}" data-i18n="memory.btnOutcomes">${t('memory.btnOutcomes')}</button>


                </div></details>
                </div>
              </div>

              <div class="memory-content">${VelaContent.markdown(m.content || '')}</div>

              <div class="memory-provenance">
                ${provenanceHtml}
              </div>


            </div>
          `;
        }).join(''))}
      </div>
    `;

    if (target.id === 'memory-page-content') {
      const actions = target.querySelector('.memory-primary-actions');
      const header = document.querySelector('#page-container > .page-header');
      if (actions && header) { header.querySelector(':scope > .memory-primary-actions')?.remove(); header.append(actions); }
    }

    target.querySelectorAll('.memory-filter-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        state.memoryFilter = btn.getAttribute('data-filter') || 'all';
        renderMemorySection(target);
      });
    });

    const btnExportArchive = document.getElementById('btn-export-memory-archive');
    if (btnExportArchive) btnExportArchive.addEventListener('click', openExportMemoryArchiveModal);

    const btnImportArchive = document.getElementById('btn-import-memory-archive');
    if (btnImportArchive) btnImportArchive.addEventListener('click', openImportMemoryArchiveModal);

    const btnNew = document.getElementById('btn-new-memory');
    if (btnNew) btnNew.addEventListener('click', () => openCreateOrEditMemoryModal());

    const btnEmptyNew = document.getElementById('btn-empty-new-mem');
    if (btnEmptyNew) btnEmptyNew.addEventListener('click', () => openCreateOrEditMemoryModal());

    const btnConfigReuse = document.getElementById('btn-configure-reuse');
    if (btnConfigReuse) btnConfigReuse.addEventListener('click', openConfigureReuseModal);

    const btnRecall = document.getElementById('btn-recall-tester');
    if (btnRecall) btnRecall.addEventListener('click', openRecallModal);

    const btnSemanticMemory = document.getElementById('btn-semantic-memory');
    if (btnSemanticMemory) btnSemanticMemory.addEventListener('click', openSemanticMemoryModal);

    const btnKnowledgeAsk = document.getElementById('btn-knowledge-ask');
    if (btnKnowledgeAsk) btnKnowledgeAsk.addEventListener('click', openKnowledgeAskModal);

    target.querySelectorAll('.btn-mem-activate').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        try {
          await callBridge('memory.transition', { id, state: 'active' });
          showToast({ key: 'memory.activatedToast' });
          await refreshDashboard(true, true);
        } catch (e) {
          showToast({ key: 'memory.activateFailedToast', params: { error: e.message } }, 'error');
        }
      });
    });

    target.querySelectorAll('.btn-mem-archive').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        try {
          await callBridge('memory.transition', { id, state: 'archived' });
          showToast({ key: 'memory.archivedToast' });
          await refreshDashboard(true, true);
        } catch (e) {
          showToast({ key: 'memory.archiveFailedToast', params: { error: e.message } }, 'error');
        }
      });
    });

    target.querySelectorAll('.btn-mem-supersede').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        openSupersedeMemoryModal(id);
      });
    });

    target.querySelectorAll('.btn-mem-edit').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const m = memories.find(item => item.id === id);
        if (m) openCreateOrEditMemoryModal(m);
      });
    });

    target.querySelectorAll('.btn-memory-outcomes').forEach(btn => {
      btn.addEventListener('click', () => {
        const memId = btn.getAttribute('data-memory-id');
        openReuseOutcomesDrawer(memId);
      });
    });

    target.querySelectorAll('.btn-mem-view').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const m = memories.find(item => item.id === id);
        if (m) {
          openDrawer(m.title || t('memory.unnamedMemory'), t('memory.title'));
          setDrawerCustomActions(`<button id="btn-edit-memory-detail" class="btn btn-secondary">${escapeHtml(t('common.edit'))}</button>`);
          document.getElementById('btn-edit-memory-detail')?.addEventListener('click', () => openCreateOrEditMemoryModal(m));
          const drawerBody = document.getElementById('drawer-content');
          if (drawerBody) {
            drawerBody.innerHTML = `
              <div class="memory-detail-status">${getMemoryStateBadge(m.state)} ${renderMemoryTypeBadge(m.type)} ${renderMemoryScopeBadge(m.scope)}</div>
              <div>${VelaContent.file(m.content || '', 'Memory.md')}</div>
              <details class="memory-detail-metadata"><summary data-i18n="memory.techMetaSummary">${t('memory.techMetaSummary')}</summary>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px;">
                  <div><span class="text-secondary" data-i18n="memory.metaType">${t('memory.metaType')}</span> ${renderMemoryTypeInline(m.type)} (${escapeHtml(m.type || '-')})</div>
                  <div><span class="text-secondary" data-i18n="memory.metaScope">${t('memory.metaScope')}</span> ${renderMemoryScopeInline(m.scope)} (${escapeHtml(m.scope || '-')})</div>
                  <div><span class="text-secondary" data-i18n="memory.metaProject">${t('memory.metaProject')}</span> ${escapeHtml(m.project || '-')}</div>
                  <div><span class="text-secondary" data-i18n="memory.metaBranch">${t('memory.metaBranch')}</span> <span class="font-mono">${escapeHtml(m.branch || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="memory.metaWorktree">${t('memory.metaWorktree')}</span> <span class="font-mono">${escapeHtml(m.worktree || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="memory.metaTask">${t('memory.metaTask')}</span> ${escapeHtml(m.task || '-')}</div>
                  <div><span class="text-secondary" data-i18n="memory.metaSourceFile">${t('memory.metaSourceFile')}</span> <span class="font-mono">${escapeHtml(m.sourceFile || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="memory.metaSourceCommit">${t('memory.metaSourceCommit')}</span> <span class="font-mono">${escapeHtml(m.sourceCommit || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="memory.metaSourceSession">${t('memory.metaSourceSession')}</span> <span class="font-mono">${escapeHtml(m.sourceSession || (m.provenance && (m.provenance.session || m.provenance.sessionId)) || '-')}</span></div>
                  <div><span class="text-secondary" data-i18n="memory.metaSourceMessage">${t('memory.metaSourceMessage')}</span> <span class="font-mono">${escapeHtml(m.sourceMessage || (m.provenance && (m.provenance.message || m.provenance.messageId)) || '-')}</span></div>
                </div>
                <div class="memory-identity"><span>${escapeHtml(m.id)}</span>${(m.checksum || m.hash) ? `<span>${escapeHtml(m.checksum || m.hash)}</span>` : ''}<span>${formatTime(m.updatedAt || m.createdAt)}</span></div>
              </details>
                <div style="margin-top: 10px; padding-top: 8px; border-top: 1px dashed var(--border-color); display: flex; gap: 8px; flex-wrap: wrap;">
                  <button type="button" class="btn btn-secondary btn-sm btn-drawer-memory-outcomes" data-memory-id="${escapeHtml(m.id)}">
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>
                    <span data-i18n="memory.btnViewReuseOutcomes">${t('memory.btnViewReuseOutcomes')}</span>
                  </button>
                  ${(m.sourceSession || (m.provenance && (m.provenance.session || m.provenance.sessionId))) ? `
                    <button type="button" class="btn-open-source" data-session-id="${escapeHtml(m.sourceSession || (m.provenance && (m.provenance.session || m.provenance.sessionId)))}" ${(m.sourceMessage || (m.provenance && (m.provenance.message || m.provenance.messageId))) ? `data-message-id="${escapeHtml(m.sourceMessage || (m.provenance && (m.provenance.message || m.provenance.messageId)))}"` : ''}>
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
                      <span data-i18n="memory.btnLocateSourceMsg">${t('memory.btnLocateSourceMsg')}</span>
                    </button>
                  ` : ''}
                </div>

            `;
            const outcomesBtn = drawerBody.querySelector('.btn-drawer-memory-outcomes');
            if (outcomesBtn) {
              outcomesBtn.addEventListener('click', () => {
                openReuseOutcomesDrawer(m.id);
              });
            }
          }
        }
      });
    });
  }

  async function openExportMemoryArchiveModal() {
    const currentProject = state.currentProject;
    if (!currentProject) {
      openModal({ key: 'memory.archiveExportTitle' }, `
        <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
          <span data-i18n="memory.selectProjectFirst">${escapeHtml(t('memory.selectProjectFirst'))}</span>
        </div>
        <p style="font-size: 13px; color: var(--text-secondary);" data-i18n="memory.archiveExportDesc">${escapeHtml(t('memory.archiveExportDesc'))}</p>
      `, `
        <button class="btn btn-secondary" id="btn-close-export-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      `);
      document.getElementById('btn-close-export-modal')?.addEventListener('click', closeModal);
      return;
    }

    openModal({ key: 'memory.archiveExportTitle' }, `
      <div style="font-size: 13px; color: var(--text-secondary); padding: 24px 0; text-align: center;">
        <div class="spin" style="display: inline-block; margin-bottom: 8px;">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="2" x2="12" y2="6"></line><line x1="12" y1="18" x2="12" y2="22"></line><line x1="4.93" y1="4.93" x2="7.76" y2="7.76"></line><line x1="16.24" y1="16.24" x2="19.07" y2="19.07"></line><line x1="2" y1="12" x2="6" y2="12"></line><line x1="18" y1="12" x2="22" y2="12"></line><line x1="4.93" y1="19.07" x2="7.76" y2="16.24"></line><line x1="16.24" y1="7.76" x2="19.07" y2="4.93"></line></svg>
        </div>
        <div data-i18n="memory.archiveValidating">${escapeHtml(t('memory.archiveValidating'))}</div>
      </div>
    `, '');

    try {
      const res = await callBridge('memory.archive.export', { project: currentProject });
      if (!res || !res.archive) {
        throw new Error('No archive payload returned');
      }

      const archive = res.archive;
      const count = typeof res.count === 'number' ? res.count : (archive.entries ? archive.entries.length : 0);
      const bytes = typeof res.bytes === 'number' ? res.bytes : JSON.stringify(archive).length;
      const version = archive.version || 1;
      const isNative = Boolean(state.isBridgeAvailable && (window.webkit?.messageHandlers?.vela || window.vela));

      openModal({ key: 'memory.archiveExportTitle' }, `
        <div class="alert-banner alert-info" style="margin-bottom: 12px;">
          <span data-i18n="memory.archiveExportNotice">${escapeHtml(t('memory.archiveExportNotice'))}</span>
        </div>
        <div class="card" style="padding: 12px 14px; background: var(--bg-subtle); margin-bottom: 12px;">
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
            <div><span class="text-secondary" data-i18n="memory.archivePreviewSource">${escapeHtml(t('memory.archivePreviewSource'))}</span> <span class="font-mono">${escapeHtml(currentProject)}</span></div>
            <div><span class="text-secondary" data-i18n="memory.archivePreviewCount">${escapeHtml(t('memory.archivePreviewCount'))}</span> <strong>${count}</strong></div>
            <div><span class="text-secondary" data-i18n="memory.archivePreviewBytes">${escapeHtml(t('memory.archivePreviewBytes'))}</span> <span class="font-mono">${formatNumber(bytes)} bytes</span></div>
            <div><span class="text-secondary" data-i18n="memory.archivePreviewVersion">${escapeHtml(t('memory.archivePreviewVersion'))}</span> <span class="font-mono">v${version}</span></div>
          </div>
        </div>
      `, `
        <button class="btn btn-secondary" id="btn-cancel-export" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
        <button class="btn btn-primary" id="btn-confirm-export" data-i18n="memory.btnConfirmExport">${escapeHtml(t('memory.btnConfirmExport'))}</button>
      `);

      document.getElementById('btn-cancel-export')?.addEventListener('click', closeModal);
      document.getElementById('btn-confirm-export')?.addEventListener('click', async () => {
        const btn = document.getElementById('btn-confirm-export');
        if (btn) btn.disabled = true;
        if (isNative) {
          try {
            const saveRes = await callBridge('system.saveMemoryArchive', { archive });
            if (saveRes && saveRes.cancelled) {
              if (btn) btn.disabled = false;
              return;
            }
            if (saveRes && saveRes.saved) {
              showToast({ key: 'memory.exportSuccess', params: { count } });
              closeModal();
            } else {
              throw new Error(saveRes?.error || 'Save failed');
            }
          } catch (err) {
            showToast(err.message || String(err), 'error');
            if (btn) btn.disabled = false;
          }
        } else {
          try {
            const blob = new Blob([JSON.stringify(archive, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            const cleanName = currentProject.split('/').filter(Boolean).pop() || 'project';
            a.href = url;
            a.download = `vela-memory-archive-${cleanName}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast({ key: 'memory.exportSuccess', params: { count } });
            closeModal();
          } catch (err) {
            showToast(err.message || String(err), 'error');
            if (btn) btn.disabled = false;
          }
        }
      });
    } catch (err) {
      openModal({ key: 'memory.archiveExportTitle' }, `
        <div class="alert-banner alert-danger">
          <span>${escapeHtml(err.message || String(err))}</span>
        </div>
      `, `
        <button class="btn btn-secondary" id="btn-close-export-err" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      `);
      document.getElementById('btn-close-export-err')?.addEventListener('click', closeModal);
    }
  }

  function openImportMemoryArchiveModal() {
    const currentProject = state.currentProject;
    if (!currentProject) {
      openModal({ key: 'memory.archiveImportTitle' }, `
        <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
          <span data-i18n="memory.selectProjectFirst">${escapeHtml(t('memory.selectProjectFirst'))}</span>
        </div>
        <p style="font-size: 13px; color: var(--text-secondary);" data-i18n="memory.archiveImportDesc">${escapeHtml(t('memory.archiveImportDesc'))}</p>
      `, `
        <button class="btn btn-secondary" id="btn-close-import-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      `);
      document.getElementById('btn-close-import-modal')?.addEventListener('click', closeModal);
      return;
    }

    openModal({ key: 'memory.archiveImportTitle' }, `
      <div class="alert-banner alert-info" style="margin-bottom: 12px;">
        <span data-i18n="memory.archiveImportDesc">${escapeHtml(t('memory.archiveImportDesc'))}</span>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="memory.archiveFileLabel">${escapeHtml(t('memory.archiveFileLabel'))}</label>
        <input type="file" id="memory-archive-file-input" class="form-input" accept=".json,application/json">
      </div>
      <div id="import-archive-preview-area"></div>
    `, `
      <button class="btn btn-secondary" id="btn-cancel-import" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-confirm-import" disabled data-i18n="memory.btnConfirmImport">${escapeHtml(t('memory.btnConfirmImport'))}</button>
    `);

    const thisModalInstance = currentModalInstance;
    let importGeneration = 0;
    let validatedArchive = null;
    const fileInput = document.getElementById('memory-archive-file-input');
    const previewArea = document.getElementById('import-archive-preview-area');
    const confirmBtn = document.getElementById('btn-confirm-import');

    const invalidateImport = () => {
      importGeneration++;
      validatedArchive = null;
      if (confirmBtn) confirmBtn.disabled = true;
    };

    document.getElementById('btn-cancel-import')?.addEventListener('click', () => {
      invalidateImport();
      closeModal();
    });

    fileInput?.addEventListener('change', async (e) => {
      const currentGen = ++importGeneration;
      validatedArchive = null;
      if (confirmBtn) confirmBtn.disabled = true;

      const file = e.target.files && e.target.files[0];
      if (!file) {
        if (previewArea) previewArea.innerHTML = '';
        return;
      }

      if (file.size > 1024 * 1024) {
        if (currentGen !== importGeneration || currentModalInstance !== thisModalInstance) return;
        if (previewArea) {
          previewArea.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="memory.archiveSizeError">${escapeHtml(t('memory.archiveSizeError'))} (${formatNumber(file.size)} bytes)</span>
            </div>
          `;
        }
        return;
      }

      if (previewArea) {
        previewArea.innerHTML = `
          <div style="font-size: 12px; color: var(--text-muted); padding: 12px 0; text-align: center;" data-i18n="memory.archiveValidating">
            ${escapeHtml(t('memory.archiveValidating'))}
          </div>
        `;
      }

      try {
        const text = await file.text();
        if (currentGen !== importGeneration || currentModalInstance !== thisModalInstance) return;

        let archiveJson;
        try {
          archiveJson = JSON.parse(text);
        } catch {
          throw new Error(t('memory.archiveInvalidJson'));
        }

        const valRes = await callBridge('memory.archive.validate', { archive: archiveJson });
        if (currentGen !== importGeneration || currentModalInstance !== thisModalInstance) return;

        if (!valRes || !valRes.valid) {
          throw new Error(valRes?.error || t('memory.archiveValidationFailed', { error: 'Unknown validation failure' }));
        }

        const entries = archiveJson.entries || [];
        const sourceProj = (archiveJson.source && archiveJson.source.project) || '-';

        const typeCounts = {};
        entries.forEach(e => {
          const ty = (e.record && e.record.type) || 'fact';
          typeCounts[ty] = (typeCounts[ty] || 0) + 1;
        });
        const breakdownHtml = Object.entries(typeCounts).map(([ty, cnt]) => `
          <span class="status-badge status-neutral" style="font-size: 11px;">${escapeHtml(formatMemoryType(ty))}: ${cnt}</span>
        `).join(' ');

        previewArea.innerHTML = `
          <div class="card" style="padding: 12px 14px; background: var(--bg-subtle); margin-top: 10px;">
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px; margin-bottom: 10px;">
              <div><span class="text-secondary" data-i18n="memory.archivePreviewSource">${escapeHtml(t('memory.archivePreviewSource'))}</span> <span class="font-mono">${escapeHtml(sourceProj)}</span></div>
              <div><span class="text-secondary" data-i18n="memory.archivePreviewTarget">${escapeHtml(t('memory.archivePreviewTarget'))}</span> <span class="font-mono">${escapeHtml(currentProject)}</span></div>
              <div><span class="text-secondary" data-i18n="memory.archivePreviewCount">${escapeHtml(t('memory.archivePreviewCount'))}</span> <strong>${valRes.count || entries.length}</strong></div>
              <div><span class="text-secondary" data-i18n="memory.archivePreviewBytes">${escapeHtml(t('memory.archivePreviewBytes'))}</span> <span class="font-mono">${formatNumber(valRes.bytes || file.size)} bytes</span></div>
            </div>
            <div style="margin-bottom: 10px;">
              <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 4px;" data-i18n="memory.archivePreviewCategories">${escapeHtml(t('memory.archivePreviewCategories'))}</div>
              <div style="display: flex; gap: 6px; flex-wrap: wrap;">${breakdownHtml}</div>
            </div>
            <div class="alert-banner alert-warning" style="margin-bottom: 10px; font-size: 11px;">
              <span data-i18n="memory.archivePreviewNotice">${escapeHtml(t('memory.archivePreviewNotice'))}</span>
            </div>
            <div>
              <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 4px;" data-i18n="memory.archivePreviewEntries" data-i18n-params="${escapeHtml(JSON.stringify({ shown: Math.min(entries.length, 5), total: entries.length }))}">${escapeHtml(t('memory.archivePreviewEntries', { shown: Math.min(entries.length, 5), total: entries.length }))}</div>
              <div style="display: flex; flex-direction: column; gap: 6px; max-height: 140px; overflow-y: auto;">
                ${entries.slice(0, 5).map(e => `
                  <div style="padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px; font-size: 11px;">
                    <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px;">
                      <strong>${escapeHtml((e.record && e.record.title) || t('memory.unnamedMemory'))}</strong>
                      ${renderMemoryTypeBadge((e.record && e.record.type) || 'fact')}
                    </div>
                    <div style="color: var(--text-secondary); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${escapeHtml((e.record && e.record.content) || '')}</div>
                  </div>
                `).join('')}
              </div>
            </div>
          </div>
        `;

        validatedArchive = archiveJson;
        confirmBtn.disabled = false;
      } catch (err) {
        if (currentGen !== importGeneration || currentModalInstance !== thisModalInstance) return;
        validatedArchive = null;
        if (confirmBtn) confirmBtn.disabled = true;
        if (previewArea) {
          previewArea.innerHTML = `
            <div class="alert-banner alert-danger">
              <span data-i18n="memory.archiveValidationFailed" data-i18n-params="${escapeHtml(JSON.stringify({ error: err.message || String(err) }))}">${escapeHtml(t('memory.archiveValidationFailed', { error: err.message || String(err) }))}</span>
            </div>
          `;
        }
      }
    });

    confirmBtn?.addEventListener('click', async () => {
      if (!validatedArchive || currentModalInstance !== thisModalInstance) return;
      const toImport = validatedArchive;
      confirmBtn.disabled = true;
      try {
        const res = await callBridge('memory.archive.import', {
          project: currentProject,
          archive: toImport
        });
        if (currentModalInstance !== thisModalInstance) return;
        const imported = (res && typeof res.imported === 'number') ? res.imported : 0;
        const skipped = (res && typeof res.skipped === 'number') ? res.skipped : 0;
        showToast({
          key: 'memory.importSuccess',
          params: { imported, skipped }
        });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        if (currentModalInstance === thisModalInstance) {
          showToast(err.message || String(err), 'error');
          confirmBtn.disabled = false;
        }
      }
    });
  }

  async function openSemanticMemoryModal() {
    const currentProject = state.currentProject;
    if (!currentProject) {
      openModal({ key: 'memory.semanticModalTitle' }, `
        <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
          <span data-i18n="memory.selectProjectFirst">${escapeHtml(t('memory.selectProjectFirst'))}</span>
        </div>
      `, `
        <button class="btn btn-secondary" id="btn-close-semantic-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      `);
      document.getElementById('btn-close-semantic-modal')?.addEventListener('click', closeModal);
      return;
    }

    let selectedLang = 'en';
    let statusRequestSeq = 0;
    let isCancelled = false;
    let isIndexing = false;

    const modalBody = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px;" data-i18n="memory.semanticSubtitle">
        ${escapeHtml(t('memory.semanticSubtitle'))}
      </p>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px;">
        <div class="form-group" style="margin-bottom: 0;">
          <label class="form-label" data-i18n="memory.semanticLangSelect">${escapeHtml(t('memory.semanticLangSelect'))}</label>
          <select id="semantic-lang-select" class="form-select">
            <option value="en" selected data-i18n="memory.semanticLangEn">${escapeHtml(t('memory.semanticLangEn'))}</option>
            <option value="zh-Hans" data-i18n="memory.semanticLangZh">${escapeHtml(t('memory.semanticLangZh'))}</option>
          </select>
        </div>
        <div class="form-group" style="margin-bottom: 0;">
          <label class="form-label" data-i18n="memory.semanticBatchSizeLabel">${escapeHtml(t('memory.semanticBatchSizeLabel'))}</label>
          <input type="number" id="semantic-batch-size" class="form-input" min="1" max="200" value="32" />
        </div>
      </div>

      <div id="semantic-status-area" style="margin-bottom: 12px;">
        <div class="text-secondary" style="font-size: 11px; padding: 12px 0; text-align: center;">...</div>
      </div>

      <div id="semantic-progress-container" style="display: none; margin-bottom: 12px;">
        <div class="semantic-progress-wrap">
          <div id="semantic-progress-bar" class="semantic-progress-bar" style="width: 0%;"></div>
        </div>
        <div id="semantic-progress-msg" style="font-size: 11px; color: var(--text-secondary); font-family: var(--font-mono); margin-top: 4px;"></div>
      </div>
    `;

    openModal({ key: 'memory.semanticModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-close-semantic-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      <button class="btn btn-danger" id="btn-cancel-semantic-index" style="display: none;" data-i18n="memory.btnCancelIndexing">${escapeHtml(t('memory.btnCancelIndexing'))}</button>
      <button class="btn btn-primary" id="btn-start-semantic-index" data-i18n="memory.btnBuildSemanticIndex">${escapeHtml(t('memory.btnBuildSemanticIndex'))}</button>
    `);

    const thisModalInstance = currentModalInstance;

    const closeBtn = document.getElementById('btn-close-semantic-modal');
    const cancelBtn = document.getElementById('btn-cancel-semantic-index');
    const startBtn = document.getElementById('btn-start-semantic-index');
    const langSelect = document.getElementById('semantic-lang-select');
    const batchInput = document.getElementById('semantic-batch-size');
    const statusArea = document.getElementById('semantic-status-area');
    const progressContainer = document.getElementById('semantic-progress-container');
    const progressBar = document.getElementById('semantic-progress-bar');
    const progressMsg = document.getElementById('semantic-progress-msg');

    closeBtn?.addEventListener('click', () => {
      isCancelled = true;
      closeModal();
    });

    async function loadStatus() {
      if (!statusArea) return;
      const thisSeq = ++statusRequestSeq;
      const thisLang = selectedLang;
      statusArea.innerHTML = `<div class="text-secondary" style="font-size: 11px; padding: 12px 0; text-align: center;" data-i18n="memory.semanticLoadingStatus">${escapeHtml(t('memory.semanticLoadingStatus'))}</div>`;
      try {
        const res = await callBridge('memory.semantic.status', {
          project: currentProject,
          language: thisLang
        });
        if (thisSeq !== statusRequestSeq || thisLang !== selectedLang || currentModalInstance !== thisModalInstance) return;

        if (!res || res.status === 'unavailable' || !res.model) {
          statusArea.innerHTML = `
            <div class="alert-banner alert-warning" style="margin-bottom: 8px;">
              <div style="font-weight: 600;" data-i18n="memory.semanticStatusUnavailable">${escapeHtml(t('memory.semanticStatusUnavailable'))}</div>
              <div style="font-size: 11px; margin-top: 2px;">${escapeHtml(res?.reason || t('memory.semanticModelNotDetected'))}</div>
            </div>
          `;
          if (startBtn) startBtn.disabled = true;
          return;
        }

        if (startBtn) startBtn.disabled = false;
        const model = res.model || {};
        const isInc = Boolean(res.indexIncomplete);

        statusArea.innerHTML = `
          <div class="card" style="padding: 10px 12px; margin-bottom: 8px;">
            <div style="display: flex; align-items: center; justify-content: space-between; font-size: 11px; margin-bottom: 6px;">
              <div>
                <span class="text-secondary" data-i18n="memory.semanticModelLabel">${escapeHtml(t('memory.semanticModelLabel'))}</span>
                <code class="code-badge font-mono">${escapeHtml(model.id || '-')}</code>
                <span class="text-secondary" style="margin-left: 6px;" data-i18n="memory.semanticModelDim">${escapeHtml(t('memory.semanticModelDim'))}</span>
                <span class="font-mono">${escapeHtml(String(model.dimension || '-'))}</span>
                ${model.revision ? `<span class="text-secondary" style="margin-left: 6px;">(rev ${escapeHtml(String(model.revision))})</span>` : ''}
              </div>
              <div>
                ${isInc
                  ? `<span class="status-badge status-amber" data-i18n="memory.semanticIndexIncomplete">${escapeHtml(t('memory.semanticIndexIncomplete'))}</span>`
                  : `<span class="status-badge status-sage" data-i18n="memory.semanticIndexComplete">${escapeHtml(t('memory.semanticIndexComplete'))}</span>`}
              </div>
            </div>
            <div class="semantic-stat-grid">
              <div class="semantic-stat-box">
                <div class="text-secondary" style="font-size: 11px;" data-i18n="memory.semanticScanned">${escapeHtml(t('memory.semanticScanned'))}</div>
                <div class="semantic-stat-value">${escapeHtml(String(res.scanned ?? '-'))}</div>
              </div>
              <div class="semantic-stat-box">
                <div class="text-secondary" style="font-size: 11px;" data-i18n="memory.semanticEligible">${escapeHtml(t('memory.semanticEligible'))}</div>
                <div class="semantic-stat-value">${escapeHtml(String(res.eligible ?? '-'))}</div>
              </div>
              <div class="semantic-stat-box">
                <div class="text-secondary" style="font-size: 11px;" data-i18n="memory.semanticIndexed">${escapeHtml(t('memory.semanticIndexed'))}</div>
                <div class="semantic-stat-value" style="color: var(--color-sage);">${escapeHtml(String(res.indexed ?? '-'))}</div>
              </div>
              <div class="semantic-stat-box">
                <div class="text-secondary" style="font-size: 11px;" data-i18n="memory.semanticStale">${escapeHtml(t('memory.semanticStale'))}</div>
                <div class="semantic-stat-value" style="color: var(--color-amber);">${escapeHtml(String(res.stale ?? '-'))}</div>
              </div>
              <div class="semantic-stat-box">
                <div class="text-secondary" style="font-size: 11px;" data-i18n="memory.semanticMissing">${escapeHtml(t('memory.semanticMissing'))}</div>
                <div class="semantic-stat-value">${escapeHtml(String(res.missing ?? '-'))}</div>
              </div>
            </div>
          </div>
        `;
      } catch (err) {
        if (thisSeq !== statusRequestSeq || thisLang !== selectedLang || currentModalInstance !== thisModalInstance) return;
        if (statusArea) statusArea.innerHTML = `<div class="alert-banner alert-danger">${escapeHtml(err.message || String(err))}</div>`;
      }
    }

    langSelect?.addEventListener('change', () => {
      selectedLang = langSelect.value;
      loadStatus();
    });

    cancelBtn?.addEventListener('click', () => {
      isCancelled = true;
      if (cancelBtn) cancelBtn.disabled = true;
      if (progressMsg) progressMsg.textContent += t('memory.semanticPausing');
    });

    startBtn?.addEventListener('click', async () => {
      if (isIndexing) return;
      isIndexing = true;
      isCancelled = false;

      let batchSize = parseInt(batchInput?.value, 10);
      if (isNaN(batchSize) || batchSize < 1) batchSize = 32;
      if (batchSize > 200) batchSize = 200;

      if (startBtn) startBtn.style.display = 'none';
      if (cancelBtn) {
        cancelBtn.style.display = 'inline-block';
        cancelBtn.disabled = false;
      }
      if (langSelect) langSelect.disabled = true;
      if (batchInput) batchInput.disabled = true;
      if (progressContainer) progressContainer.style.display = 'block';

      let cursor = undefined;
      let page = 1;
      let totalProcessed = 0;
      let totalIndexed = 0;
      let totalSkipped = 0;
      let totalFailed = 0;
      let hadPartial = false;
      let terminalReason = null; // 'completed' | 'cancelled' | 'unavailable' | 'error' | 'partial'

      try {
        while (!isCancelled) {
          if (currentModalInstance !== thisModalInstance) {
            terminalReason = 'cancelled';
            break;
          }
          if (progressMsg) {
            progressMsg.textContent = t('memory.semanticIndexingProgress', {
              page,
              processed: totalProcessed,
              indexed: totalIndexed,
              skipped: totalSkipped
            });
          }
          if (progressBar) {
            progressBar.style.width = '60%';
          }

          const payload = {
            project: currentProject,
            language: selectedLang,
            batchSize
          };
          if (cursor) payload.cursor = cursor;

          const res = await callBridge('memory.semantic.index', payload);
          if (isCancelled || currentModalInstance !== thisModalInstance) {
            terminalReason = 'cancelled';
            break;
          }
          if (!res || res.status === 'unavailable') {
            terminalReason = 'unavailable';
            showToast(res?.reason || t('memory.semanticStatusUnavailable'), 'error');
            break;
          }

          if (res.status === 'partial' || (res.failed && res.failed > 0)) {
            hadPartial = true;
          }

          totalProcessed += (res.processed || 0);
          totalIndexed += (res.indexed || 0);
          totalSkipped += (res.skipped || 0);
          totalFailed += (res.failed || 0);
          cursor = res.nextCursor;

          if (!res.hasMore || !cursor) {
            terminalReason = hadPartial ? 'partial' : 'completed';
            if (progressBar) progressBar.style.width = '100%';
            if (progressMsg) {
              progressMsg.textContent = t('memory.semanticIndexingProgress', {
                page,
                processed: totalProcessed,
                indexed: totalIndexed,
                skipped: totalSkipped
              });
            }
            break;
          }
          page++;
        }

        if (isCancelled && !terminalReason) {
          terminalReason = 'cancelled';
        }

        if (terminalReason === 'completed') {
          showToast({ key: 'memory.semanticIndexSuccessToast' });
        } else if (terminalReason === 'partial') {
          showToast({ key: 'memory.semanticIndexPartialToast', params: { failed: totalFailed } }, 'warning');
        } else if (terminalReason === 'cancelled') {
          showToast({ key: 'memory.semanticIndexCancelledToast' }, 'info');
        }
      } catch (err) {
        terminalReason = 'error';
        showToast(err.message || String(err), 'error');
      } finally {
        isIndexing = false;
        if (currentModalInstance === thisModalInstance) {
          if (startBtn) {
            startBtn.style.display = 'inline-block';
            startBtn.disabled = false;
          }
          if (cancelBtn) cancelBtn.style.display = 'none';
          if (langSelect) langSelect.disabled = false;
          if (batchInput) batchInput.disabled = false;
          await loadStatus();
        }
      }
    });

    await loadStatus();
  }

  function getKnowledgeQueryStateBadge(st) {
    const s = (st || '').toLowerCase();
    switch (s) {
      case 'pending_approval':
        return `<span class="status-badge status-amber" data-i18n="ask.statePendingApproval">${escapeHtml(t('ask.statePendingApproval'))}</span>`;
      case 'answered':
        return `<span class="status-badge status-sage" data-i18n="ask.stateAnswered">${escapeHtml(t('ask.stateAnswered'))}</span>`;
      case 'unanswered':
        return `<span class="status-badge status-neutral" data-i18n="ask.stateUnanswered">${escapeHtml(t('ask.stateUnanswered'))}</span>`;
      case 'no_sources':
        return `<span class="status-badge status-neutral" data-i18n="ask.stateNoSources">${escapeHtml(t('ask.stateNoSources'))}</span>`;
      case 'sources_unavailable':
        return `<span class="status-badge status-red" data-i18n="ask.stateSourcesUnavailable">${escapeHtml(t('ask.stateSourcesUnavailable'))}</span>`;
      case 'running_or_uncertain':
      case 'executing_or_uncertain':
      case 'executing':
        return `<span class="status-badge status-blue" data-i18n="loops.stateRunning">${escapeHtml(t('loops.stateRunning'))}</span>`;
      case 'rejected':
        return `<span class="status-badge status-red" data-i18n="loops.stateRejected">${escapeHtml(t('loops.stateRejected'))}</span>`;
      case 'failed':
        return `<span class="status-badge status-red" data-i18n="loops.stateFailed">${escapeHtml(t('loops.stateFailed'))}</span>`;
      case 'needs_review':
        return `<span class="status-badge status-amber" data-i18n="loops.stateNeedsReview">${escapeHtml(t('loops.stateNeedsReview'))}</span>`;
      default:
        return `<span class="status-badge status-neutral">${escapeHtml(st || '-')}</span>`;
    }
  }

  async function openKnowledgeAskModal() {
    const currentProject = state.currentProject;
    const currentPage = state.currentPage;
    if (!currentProject) {
      openModal({ key: 'ask.modalTitle' }, `
        <div class="alert-banner alert-warning">
          <span data-i18n="memory.selectProjectFirst">${escapeHtml(t('memory.selectProjectFirst'))}</span>
        </div>
      `, `<button class="btn btn-secondary" id="btn-close-ask-first" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);
      document.getElementById('btn-close-ask-first')?.addEventListener('click', closeModal);
      return;
    }

    let activeTab = 'new';
    let askTabGeneration = 0;
    const newDraft = {
      question: '',
      searchQuery: '',
      retrievalMode: 'lexical',
      executable: '/usr/local/bin/codex',
      model: 'gpt-5.6-sol',
      effort: 'low',
      maxSources: 8,
      maxSourceBytes: 24000,
      timeoutSeconds: 120
    };

    function saveNewDraft() {
      const qInput = document.getElementById('ask-question-input');
      if (qInput) newDraft.question = qInput.value;
      const sInput = document.getElementById('ask-search-input');
      if (sInput) newDraft.searchQuery = sInput.value;
      const rSelect = document.getElementById('ask-retrieval-mode');
      if (rSelect) newDraft.retrievalMode = rSelect.value;
      const eInput = document.getElementById('ask-exec-input');
      if (eInput) newDraft.executable = eInput.value;
      const mInput = document.getElementById('ask-model-input');
      if (mInput) newDraft.model = mInput.value;
      const efSelect = document.getElementById('ask-effort-select');
      if (efSelect) newDraft.effort = efSelect.value;
      const msInput = document.getElementById('ask-max-sources');
      if (msInput) newDraft.maxSources = parseInt(msInput.value, 10) || 8;
      const mbInput = document.getElementById('ask-max-bytes');
      if (mbInput) newDraft.maxSourceBytes = parseInt(mbInput.value, 10) || 24000;
      const tInput = document.getElementById('ask-timeout');
      if (tInput) newDraft.timeoutSeconds = parseInt(tInput.value, 10) || 120;
    }

    const modalBody = `
      <div class="tabs-nav" style="margin-bottom: 12px;">
        <button class="tab-btn active" id="tab-ask-new" data-i18n="ask.tabNew">${escapeHtml(t('ask.tabNew'))}</button>
        <button class="tab-btn" id="tab-ask-history" data-i18n="ask.tabHistory">${escapeHtml(t('ask.tabHistory'))}</button>
      </div>

      <div id="ask-tab-body"></div>
    `;

    openModal({ key: 'ask.modalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-close-ask-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      <button class="btn btn-primary" id="btn-submit-ask" data-i18n="ask.btnSubmit">${escapeHtml(t('ask.btnSubmit'))}</button>
    `);

    const thisModalInstance = currentModalInstance;

    const tabNew = document.getElementById('tab-ask-new');
    const tabHistory = document.getElementById('tab-ask-history');
    const tabBody = document.getElementById('ask-tab-body');
    const closeBtn = document.getElementById('btn-close-ask-modal');
    const submitBtn = document.getElementById('btn-submit-ask');

    closeBtn?.addEventListener('click', closeModal);

    tabNew?.addEventListener('click', () => {
      if (activeTab === 'new') return;
      activeTab = 'new';
      tabNew.classList.add('active');
      tabHistory?.classList.remove('active');
      renderActiveTab();
    });

    tabHistory?.addEventListener('click', () => {
      if (activeTab === 'history') return;
      saveNewDraft();
      activeTab = 'history';
      tabHistory.classList.add('active');
      tabNew?.classList.remove('active');
      renderActiveTab();
    });

    async function renderActiveTab() {
      const thisGen = ++askTabGeneration;
      if (!tabBody || currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage) return;

      if (activeTab === 'new') {
        if (submitBtn) {
          submitBtn.style.display = 'inline-flex';
          submitBtn.disabled = false;
          submitBtn.textContent = t('ask.btnSubmit');
        }

        tabBody.innerHTML = `
          <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 10px; line-height: 1.4;" data-i18n="ask.modalDesc">${escapeHtml(t('ask.modalDesc'))}</div>

          <div class="form-group">
            <label class="form-label" data-i18n="ask.questionLabel">${escapeHtml(t('ask.questionLabel'))}</label>
            <textarea id="ask-question-input" class="form-control" rows="3" maxlength="4000" data-i18n-placeholder="ask.questionPlaceholder" placeholder="${escapeHtml(t('ask.questionPlaceholder'))}">${escapeHtml(newDraft.question || '')}</textarea>
          </div>

          <div style="display: grid; grid-template-columns: 2fr 1fr; gap: 10px; margin-bottom: 10px;">
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="ask.searchQueryLabel">${escapeHtml(t('ask.searchQueryLabel'))}</label>
              <input type="text" id="ask-search-input" class="form-control" maxlength="1000" value="${escapeHtml(newDraft.searchQuery || '')}" />
            </div>
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="ask.retrievalModeLabel">${escapeHtml(t('ask.retrievalModeLabel'))}</label>
              <select id="ask-retrieval-mode" class="form-select">
                <option value="lexical"${newDraft.retrievalMode === 'lexical' ? ' selected' : ''} data-i18n="ask.modeLexical">${escapeHtml(t('ask.modeLexical'))}</option>
                <option value="library_fts"${newDraft.retrievalMode === 'library_fts' ? ' selected' : ''} data-i18n="ask.modeLibraryFts">${escapeHtml(t('ask.modeLibraryFts'))}</option>
              </select>
            </div>
          </div>

          <div style="display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 10px; margin-bottom: 10px;">
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="ask.colExecutable">${escapeHtml(t('ask.colExecutable'))}</label>
              <input type="text" id="ask-exec-input" class="form-control" value="${escapeHtml(newDraft.executable || '/usr/local/bin/codex')}" />
            </div>
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="ask.colModel">${escapeHtml(t('ask.colModel'))}</label>
              <input type="text" id="ask-model-input" class="form-control" value="${escapeHtml(newDraft.model || 'gpt-5.6-sol')}" />
            </div>
            <div class="form-group" style="margin-bottom: 0;">
              <label class="form-label" data-i18n="loops.reasoningEffortLabel">${escapeHtml(t('loops.reasoningEffortLabel'))}</label>
              <select id="ask-effort-select" class="form-select">
                <option value="low"${newDraft.effort === 'low' ? ' selected' : ''}>low</option>
                <option value="medium"${newDraft.effort === 'medium' ? ' selected' : ''}>medium</option>
                <option value="high"${newDraft.effort === 'high' ? ' selected' : ''}>high</option>
                <option value="xhigh"${newDraft.effort === 'xhigh' ? ' selected' : ''}>xhigh</option>
              </select>
            </div>
          </div>

          <details class="memory-meta-details" style="margin-bottom: 12px;">
            <summary data-i18n="ask.advancedLimits">${escapeHtml(t('ask.advancedLimits'))}</summary>
            <div style="margin-top: 8px;">
              <div class="card" style="margin-bottom: 10px; background: var(--bg-surface-secondary); padding: 8px 10px;">
                <div style="font-size: 11px; font-weight: 600; margin-bottom: 2px;" data-i18n="ask.protocolLimits">${escapeHtml(t('ask.protocolLimits'))}</div>
                <div id="ask-bounds-summary" style="font-size: 11px; color: var(--text-secondary); display: flex; gap: 12px; flex-wrap: wrap;">
                  <span>maxCallsPerRound: 1</span>
                  <span>timeout: 1–300s</span>
                  <span>maxSources: 1–12</span>
                  <span>maxBytes: 1K–32K</span>
                </div>
              </div>
              <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px;">
                <div class="form-group" style="margin-bottom: 0;">
                  <label class="form-label" data-i18n="ask.maxSourcesLabel">${escapeHtml(t('ask.maxSourcesLabel'))}</label>
                  <input type="number" id="ask-max-sources" class="form-control" min="1" max="12" value="${escapeHtml(String(newDraft.maxSources || 8))}" />
                </div>
                <div class="form-group" style="margin-bottom: 0;">
                  <label class="form-label" data-i18n="ask.maxBytesLabel">${escapeHtml(t('ask.maxBytesLabel'))}</label>
                  <input type="number" id="ask-max-bytes" class="form-control" min="1000" max="32000" value="${escapeHtml(String(newDraft.maxSourceBytes || 24000))}" />
                </div>
                <div class="form-group" style="margin-bottom: 0;">
                  <label class="form-label" data-i18n="ask.timeoutLabel">${escapeHtml(t('ask.timeoutLabel'))}</label>
                  <input type="number" id="ask-timeout" class="form-control" min="1" max="300" value="${escapeHtml(String(newDraft.timeoutSeconds || 120))}" />
                </div>
              </div>
            </div>
          </details>

          <div id="ask-submit-result"></div>
        `;

        const qEl = document.getElementById('ask-question-input');
        if (qEl) {
          if (newDraft.question) qEl.value = newDraft.question;
          qEl.addEventListener('input', (e) => { newDraft.question = e.target.value; });
        }
        document.getElementById('ask-search-input')?.addEventListener('input', (e) => { newDraft.searchQuery = e.target.value; });
        document.getElementById('ask-retrieval-mode')?.addEventListener('change', (e) => { newDraft.retrievalMode = e.target.value; });
        document.getElementById('ask-exec-input')?.addEventListener('input', (e) => { newDraft.executable = e.target.value; });
        document.getElementById('ask-model-input')?.addEventListener('input', (e) => { newDraft.model = e.target.value; });
        document.getElementById('ask-effort-select')?.addEventListener('change', (e) => { newDraft.effort = e.target.value; });
        document.getElementById('ask-max-sources')?.addEventListener('input', (e) => { newDraft.maxSources = parseInt(e.target.value, 10) || 8; });
        document.getElementById('ask-max-bytes')?.addEventListener('input', (e) => { newDraft.maxSourceBytes = parseInt(e.target.value, 10) || 24000; });
        document.getElementById('ask-timeout')?.addEventListener('input', (e) => { newDraft.timeoutSeconds = parseInt(e.target.value, 10) || 120; });

        try {
          const desc = await callBridge('ask.describe', {});
          if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage || askTabGeneration !== thisGen || activeTab !== 'new') return;
          const boundsEl = document.getElementById('ask-bounds-summary');
          if (boundsEl && desc) {
            boundsEl.innerHTML = `
              <span>${escapeHtml(desc.protocol || 'vela-knowledge-answer-v1')}</span>
              <span>maxCalls: ${escapeHtml(String(desc.maxCallsPerRound || 1))}</span>
              <span>maxSources: ${escapeHtml(String(desc.maxSources || 12))}</span>
              <span>maxBytes: ${escapeHtml(String(desc.maxSourceBytes || 32000))}</span>
              <span>prompt: ≤${escapeHtml(String(Math.round((desc.maxPromptBytes || 48000) / 1024)))}KB</span>
              <span>answer: ≤${escapeHtml(String(Math.round((desc.maxAnswerBytes || 24000) / 1024)))}KB</span>
            `;
          }
        } catch {}

      } else {
        if (submitBtn) submitBtn.style.display = 'none';

        tabBody.innerHTML = `
          <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
        `;

        let list = [];
        try {
          list = await callBridge('ask.list', { project: currentProject });
        } catch (e) {
          if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage || askTabGeneration !== thisGen || activeTab !== 'history') return;
          tabBody.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
          return;
        }
        if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage || askTabGeneration !== thisGen || activeTab !== 'history') return;

        if (!Array.isArray(list) || list.length === 0) {
          tabBody.innerHTML = `
            <div class="alert-banner alert-neutral" style="margin-bottom: 12px; font-size: 11px;" data-i18n="ask.historyNotice">
              ${escapeHtml(t('ask.historyNotice'))}
            </div>
            <div class="empty-state">
              <div class="empty-state-title" data-i18n="ask.emptyHistory">${escapeHtml(t('ask.emptyHistory'))}</div>
            </div>
          `;
          return;
        }

        tabBody.innerHTML = `
          <div class="alert-banner alert-neutral" style="margin-bottom: 12px; font-size: 11px;" data-i18n="ask.historyNotice">
            ${escapeHtml(t('ask.historyNotice'))}
          </div>
          <div class="table-wrapper">
            <table class="data-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th data-i18n="ask.questionLabel">${escapeHtml(t('ask.questionLabel'))}</th>
                  <th data-i18n="common.status">${escapeHtml(t('common.status'))}</th>
                  <th data-i18n="ask.colRounds">${escapeHtml(t('ask.colRounds'))}</th>
                  <th data-i18n="ask.colCalls">${escapeHtml(t('ask.colCalls'))}</th>
                  <th data-i18n="loops.colCreated">${escapeHtml(t('loops.colCreated'))}</th>
                  <th style="text-align: right;" data-i18n="common.actions">${escapeHtml(t('common.actions'))}</th>
                </tr>
              </thead>
              <tbody>
                ${list.map(q => `
                  <tr>
                    <td><span class="font-mono" style="font-size: 11px;">${escapeHtml((q.id || '').substring(0, 8))}</span></td>
                    <td><strong style="font-size: 12px;">${escapeHtml(q.title || '-')}</strong></td>
                    <td>${getKnowledgeQueryStateBadge(q.state)}</td>
                    <td><span class="font-mono">${escapeHtml(String(q.round ?? 1))}</span></td>
                    <td><span class="font-mono">${escapeHtml(String(q.completedModelCalls ?? 0))}</span></td>
                    <td><span class="font-mono" style="font-size: 11px;">${formatTime(q.createdAt)}</span></td>
                    <td style="text-align: right;">
                      <button class="btn btn-secondary btn-sm btn-open-ask-row" data-id="${escapeHtml(q.id)}" data-i18n="common.view">${escapeHtml(t('common.view'))}</button>
                    </td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>
        `;

        tabBody.querySelectorAll('.btn-open-ask-row').forEach(btn => {
          btn.addEventListener('click', () => {
            const id = btn.getAttribute('data-id');
            if (id) openAskDetailModal(id);
          });
        });
      }
    }

    submitBtn?.addEventListener('click', async () => {
      saveNewDraft();
      const question = (newDraft.question || '').trim();
      if (!question) {
        document.getElementById('ask-question-input')?.focus();
        return;
      }

      const searchQuery = (newDraft.searchQuery || '').trim() || question;
      const retrievalMode = newDraft.retrievalMode || 'lexical';
      const executable = (newDraft.executable || '').trim() || '/usr/local/bin/codex';
      const model = (newDraft.model || '').trim() || 'gpt-5.6-sol';
      const effort = newDraft.effort || 'low';
      const maxSources = parseInt(newDraft.maxSources, 10) || 8;
      const maxSourceBytes = parseInt(newDraft.maxSourceBytes, 10) || 24000;
      const timeoutSeconds = parseInt(newDraft.timeoutSeconds, 10) || 120;

      submitBtn.disabled = true;
      submitBtn.textContent = t('common.loading');

      try {
        const res = await callBridge('ask.create', {
          project: currentProject,
          question,
          searchQuery,
          retrievalMode,
          executable,
          model,
          effort,
          maxSources,
          maxSourceBytes,
          timeoutSeconds
        });

        if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage) return;

        if (res.state === 'no_sources') {
          const resEl = document.getElementById('ask-submit-result');
          if (resEl) {
            resEl.innerHTML = `
              <div class="alert-banner alert-neutral" style="margin-top: 12px;">
                <strong data-i18n="ask.stateNoSources">${escapeHtml(t('ask.stateNoSources'))}</strong>
                <div style="margin-top: 4px;" data-i18n="ask.noSourcesNotice">${escapeHtml(t('ask.noSourcesNotice'))}</div>
                <div style="margin-top: 8px;">
                  <button class="btn btn-secondary btn-sm" id="btn-view-no-src" data-i18n="common.view">${escapeHtml(t('common.view'))}</button>
                </div>
              </div>
            `;
            document.getElementById('btn-view-no-src')?.addEventListener('click', () => {
              openAskDetailModal(res.id);
            });
          }
        } else {
          openAskDetailModal(res.id);
        }
      } catch (e) {
        if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage) return;
        const resEl = document.getElementById('ask-submit-result');
        if (resEl) {
          resEl.innerHTML = `<div class="alert-banner alert-warning" style="margin-top: 12px;">${escapeHtml(e.message)}</div>`;
        }
      } finally {
        if (currentModalInstance === thisModalInstance && state.currentProject === currentProject && state.currentPage === currentPage && activeTab === 'new') {
          submitBtn.disabled = false;
          submitBtn.textContent = t('ask.btnSubmit');
        }
      }
    });

    renderActiveTab();
  }

  async function openAskDetailModal(askId) {
    const currentProject = state.currentProject;
    const currentPage = state.currentPage;
    const thisRenderGeneration = renderGeneration;
    if (!currentProject || !askId) return;

    openModal({ key: 'ask.modalTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-ask-detail" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    const isFresh = (ignoreGen = false) => (
      currentModalInstance === thisModalInstance &&
      state.currentProject === currentProject &&
      state.currentPage === currentPage &&
      (ignoreGen || renderGeneration === thisRenderGeneration) &&
      document.getElementById('modal-container') &&
      !document.getElementById('modal-container').classList.contains('hidden')
    );
    document.getElementById('btn-close-ask-detail')?.addEventListener('click', closeModal);

    let item = null;
    try {
      item = await callBridge('ask.get', { project: currentProject, id: askId });
    } catch (e) {
      if (!isFresh()) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (!isFresh()) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const req = item.request || {};
    const history = Array.isArray(req.history) ? req.history : [];
    const agent = req.agent || {};
    const sources = Array.isArray(req.sources) ? req.sources : [];
    const result = item.result || {};
    const claims = Array.isArray(result.claims) ? result.claims : [];
    const unanswered = Array.isArray(result.unanswered) ? result.unanswered : [];
    const citations = Array.isArray(result.citations) ? result.citations : (Array.isArray(item.citations) ? item.citations : []);

    const scopeObj = req.scope || {};
    const scopeEntries = Object.entries(scopeObj).filter(([_, v]) => v !== undefined && v !== null && v !== '');
    const scopeHtml = `
      <div style="margin-top: 8px; padding-top: 6px; border-top: 1px dashed var(--border-subtle); font-size: 11px;">
        <span style="color: var(--text-secondary);" data-i18n="ask.colScope">${escapeHtml(t('ask.colScope'))}:</span>
        ${scopeEntries.length > 0 ? scopeEntries.map(([k, v]) => `
          <span style="margin-left: 6px;">
            <span class="text-secondary">${escapeHtml(k)}:</span>
            <span class="font-mono font-semibold">${escapeHtml(String(v))}</span>
          </span>
        `).join('') : `<span class="text-secondary" style="margin-left: 6px;" data-i18n="ask.scopeProjectDefault">${escapeHtml(t('ask.scopeProjectDefault'))}</span>`}
      </div>
    `;

    let statusBanner = '';
    if (item.state === 'sources_unavailable') {
      statusBanner = `
        <div class="alert-banner alert-danger" style="margin-bottom: 12px;">
          <strong data-i18n="ask.stateSourcesUnavailable">${escapeHtml(t('ask.stateSourcesUnavailable'))}</strong>
          <div style="margin-top: 4px;" data-i18n="ask.sourcesUnavailableNotice">${escapeHtml(t('ask.sourcesUnavailableNotice'))}</div>
          ${item.error ? `<div class="font-mono" style="font-size: 11px; margin-top: 4px;">${escapeHtml(item.error)}</div>` : ''}
        </div>
      `;
    } else if (item.state === 'no_sources') {
      statusBanner = `
        <div class="alert-banner alert-neutral" style="margin-bottom: 12px;">
          <strong data-i18n="ask.stateNoSources">${escapeHtml(t('ask.stateNoSources'))}</strong>
          <div style="margin-top: 4px;" data-i18n="ask.noSourcesNotice">${escapeHtml(t('ask.noSourcesNotice'))}</div>
        </div>
      `;
    } else if (item.state === 'pending_approval') {
      statusBanner = `
        <div class="alert-banner alert-warning" style="margin-bottom: 12px;">
          <strong data-i18n="ask.statePendingApproval">${escapeHtml(t('ask.statePendingApproval'))}</strong>
          <div style="margin-top: 4px;" data-i18n="ask.pendingApprovalNotice" data-i18n-params="${escapeHtml(JSON.stringify({ count: sources.length }))}">
            ${escapeHtml(t('ask.pendingApprovalNotice', { count: sources.length }))}
          </div>
        </div>
      `;
    }

    b.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px;">
        <div>
          <h4 style="margin: 0 0 4px 0; font-size: 14px;">${escapeHtml(item.title || req.question || '-')}</h4>
          <div class="font-mono text-secondary" style="font-size: 11px;">ID: ${escapeHtml(item.id)} · Round ${escapeHtml(String(item.round ?? 1))} · ${formatTime(item.createdAt)}</div>
        </div>
        <div>
          ${getKnowledgeQueryStateBadge(item.state)}
        </div>
      </div>

      ${statusBanner}

      ${history.length > 0 ? `
        <div class="card" style="margin-bottom: 12px; padding: 10px 12px; background: var(--bg-surface-secondary);">
          <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center;">
            <span><span data-i18n="ask.frozenHistoryTitle">${escapeHtml(t('ask.frozenHistoryTitle'))}</span> (${history.length})</span>
            <span style="font-size: 11px; color: var(--text-secondary);" data-i18n="ask.historyReviewNotice">${escapeHtml(t('ask.historyReviewNotice'))}</span>
          </div>
          <div style="display: flex; flex-direction: column; gap: 8px;">
            ${history.map((h, idx) => `
              <div style="background: var(--bg-surface); border: 1px solid var(--border-subtle); border-radius: 6px; padding: 8px 10px;">
                <div style="font-size: 11px; font-weight: 600; color: var(--text-secondary); margin-bottom: 4px;">
                  <span data-i18n="ask.historyRoundLabel" data-i18n-params="${escapeHtml(JSON.stringify({ round: idx + 1 }))}">${escapeHtml(t('ask.historyRoundLabel', { round: idx + 1 }))}</span>
                </div>
                <div style="margin-bottom: 6px;">
                  <span style="font-size: 11px; color: var(--text-muted);" data-i18n="ask.previousQuestion">${escapeHtml(t('ask.previousQuestion'))}:</span>
                  <div style="font-size: 12px; font-weight: 500; color: var(--text-primary); margin-top: 2px; white-space: pre-wrap;">${escapeHtml(h.question || '-')}</div>
                </div>
                ${h.answer ? `
                  <div style="margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--border-subtle);">
                    <span style="font-size: 11px; color: var(--text-muted);" data-i18n="ask.previousAnswer">${escapeHtml(t('ask.previousAnswer'))}:</span>
                    <div style="font-size: 12px; color: var(--text-secondary); line-height: 1.45; margin-top: 2px; white-space: pre-wrap;">${escapeHtml(h.answer)}</div>
                  </div>
                ` : ''}
                ${Array.isArray(h.unanswered) && h.unanswered.length > 0 ? `
                  <div style="margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--border-subtle); font-size: 11px; color: var(--status-amber-text);">
                    <span data-i18n="ask.previousUnanswered">${escapeHtml(t('ask.previousUnanswered'))}:</span>
                    <ul style="margin: 2px 0 0 16px; padding: 0;">
                      ${h.unanswered.map(u => `<li>${escapeHtml(u)}</li>`).join('')}
                    </ul>
                  </div>
                ` : ''}
              </div>
            `).join('')}
          </div>
        </div>
      ` : ''}

      ${req.question ? `
        <div class="card" style="margin-bottom: 12px; padding: 10px 12px;">
          <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 4px;" data-i18n="ask.questionLabel">${escapeHtml(t('ask.questionLabel'))}</div>
          <div style="font-size: 13px; line-height: 1.5; white-space: pre-wrap;">${escapeHtml(req.question)}</div>
        </div>
      ` : ''}

      <div class="card" style="margin-bottom: 12px; padding: 10px 12px; background: var(--bg-surface-secondary);">
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 6px;" data-i18n="ask.invocationTitle">${escapeHtml(t('ask.invocationTitle'))}</div>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 8px; font-size: 12px;">
          <div>
            <span style="color: var(--text-secondary);" data-i18n="ask.colModel">${escapeHtml(t('ask.colModel'))}:</span>
            <strong class="font-mono" style="margin-left: 4px;">${escapeHtml(agent.model || '-')}</strong>
          </div>
          <div>
            <span style="color: var(--text-secondary);" data-i18n="loops.reasoningEffortLabel">${escapeHtml(t('loops.reasoningEffortLabel'))}:</span>
            <span class="code-badge" style="margin-left: 4px;">${escapeHtml(agent.reasoningEffort || 'low')}</span>
          </div>
          <div>
            <span style="color: var(--text-secondary);" data-i18n="ask.maxCallsLimit">${escapeHtml(t('ask.maxCallsLimit'))}:</span>
            <span class="font-mono" style="margin-left: 4px;">1</span>
          </div>
          <div>
            <span style="color: var(--text-secondary);" data-i18n="ask.timeoutLabel">${escapeHtml(t('ask.timeoutLabel'))}</span>
            <span class="font-mono" style="margin-left: 4px;">${escapeHtml(String(req.timeoutSeconds ?? 120))}</span>
          </div>
        </div>
        ${scopeHtml}
      </div>

      ${claims.length > 0 ? `
        <div style="margin-bottom: 14px;">
          <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;" data-i18n="ask.claimsTitle">${escapeHtml(t('ask.claimsTitle'))} (${claims.length})</div>
          ${claims.map(claim => `
            <div class="card" style="margin-bottom: 10px; padding: 12px; background: var(--bg-surface-secondary);">
              <div style="font-size: 13px; font-weight: 500; line-height: 1.5; margin-bottom: 8px;">${escapeHtml(claim.text || '')}</div>
              ${Array.isArray(claim.citations) && claim.citations.length > 0 ? `
                <div style="border-top: 1px dashed var(--border-subtle); padding-top: 8px; margin-top: 8px;">
                  <div style="font-size: 11px; color: var(--text-secondary); margin-bottom: 6px;" data-i18n="ask.citationsTitle">${escapeHtml(t('ask.citationsTitle'))}</div>
                  ${claim.citations.map(c => `
                    <div style="margin-bottom: 6px; font-size: 11px; background: var(--bg-surface); padding: 6px 8px; border-radius: 4px; border: 1px solid var(--border-subtle);">
                      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px;">
                        <span class="font-mono text-secondary" style="font-size: 11px;">${escapeHtml(c.sourceId)}</span>
                        <span style="color: var(--status-sage-text);" data-i18n="ask.exactQuoteVerified">${escapeHtml(t('ask.exactQuoteVerified'))}</span>
                      </div>
                      <div style="font-style: italic; color: var(--text-primary); margin-top: 2px;">“${escapeHtml(c.quote)}”</div>
                    </div>
                  `).join('')}
                </div>
              ` : ''}
            </div>
          `).join('')}
        </div>
      ` : ''}

      ${unanswered.length > 0 ? `
        <div class="card" style="margin-bottom: 12px; border-color: var(--status-amber-border); background: var(--bg-surface-secondary); padding: 12px;">
          <div style="font-size: 12px; font-weight: 600; color: var(--status-amber-text); margin-bottom: 6px;" data-i18n="ask.unansweredTitle">${escapeHtml(t('ask.unansweredTitle'))} (${unanswered.length})</div>
          <ul style="margin: 0; padding-left: 18px; font-size: 12px; color: var(--text-secondary);">
            ${unanswered.map(u => `<li>${escapeHtml(u)}</li>`).join('')}
          </ul>
        </div>
      ` : ''}

      ${(claims.length > 0 || unanswered.length > 0) ? `
        <div class="alert-banner alert-neutral" style="margin-bottom: 12px; font-size: 11px;">
          <span data-i18n="ask.exactQuoteVerified">${escapeHtml(t('ask.exactQuoteVerified'))}</span>
          <div style="color: var(--text-secondary); margin-top: 2px;" data-i18n="ask.semanticNotice">${escapeHtml(t('ask.semanticNotice'))}</div>
        </div>
      ` : ''}

      ${sources.length > 0 ? `
        <div style="margin-bottom: 12px;">
          <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center;">
            <span><span data-i18n="ask.frozenSourcesTitle">${escapeHtml(t('ask.frozenSourcesTitle'))}</span> (${sources.length})</span>
            <span style="font-size: 11px; color: var(--text-secondary);" data-i18n="ask.sourcesReviewNotice">${escapeHtml(t('ask.sourcesReviewNotice'))}</span>
          </div>
          <div style="display: flex; flex-direction: column; gap: 8px;">
            ${sources.map(s => {
              const content = s.content || '';
              const preview = content.length > 200 ? content.substring(0, 200) + '...' : content;
              return `
                <div class="card" style="padding: 10px 12px; background: var(--bg-surface-secondary);">
                  <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px;">
                    <div>
                      <span class="code-badge">${escapeHtml(s.kind)}</span>
                      <span class="font-mono font-semibold" style="margin-left: 4px;">${escapeHtml(s.sourceId || '')}</span>
                      ${s.title ? `<span style="margin-left: 6px; color: var(--text-primary); font-weight: 500;">${escapeHtml(s.title)}</span>` : ''}
                    </div>
                    <span class="font-mono text-secondary" style="font-size: 11px;">${escapeHtml(String(s.fullSourceBytes || content.length || 0))} B</span>
                  </div>
                  ${preview ? `
                    <div style="font-size: 12px; color: var(--text-secondary); line-height: 1.4; margin-top: 4px; white-space: pre-wrap;">${escapeHtml(preview)}</div>
                  ` : ''}
                  ${content ? `
                    <details class="memory-meta-details" style="margin-top: 6px;">
                      <summary style="font-size: 11px; color: var(--color-primary); cursor: pointer;" data-i18n="ask.viewFullFrozenContent">${escapeHtml(t('ask.viewFullFrozenContent'))}</summary>
                      <div style="margin-top: 6px; padding: 8px 10px; background: var(--bg-surface); border: 1px solid var(--border-subtle); border-radius: 4px; font-size: 11px; line-height: 1.45; white-space: pre-wrap; word-break: break-word; max-height: 280px; overflow-y: auto;">${escapeHtml(content)}</div>
                    </details>
                  ` : ''}
                </div>
              `;
            }).join('')}
          </div>
        </div>
      ` : ''}

      <details class="memory-meta-details" style="margin-bottom: 12px;">
        <summary data-i18n="memory.techMetaSummary">${escapeHtml(t('memory.techMetaSummary'))}</summary>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 6px; font-size: 11px; margin-top: 8px; color: var(--text-secondary);">
          <div><span data-i18n="ask.colExecutable">${escapeHtml(t('ask.colExecutable'))}:</span> <span class="font-mono" style="word-break: break-all;">${escapeHtml(agent.executable || '-')}</span></div>
          <div><span>askHash:</span> <span class="font-mono" style="user-select: all;">${escapeHtml(item.askHash || '-')}</span></div>
          <div><span>runId:</span> <span class="font-mono">${escapeHtml(item.runId || '-')}</span></div>
          <div><span>approvalId:</span> <span class="font-mono">${escapeHtml(item.approvalId || '-')}</span></div>
          <div><span>completedCalls:</span> <span class="font-mono">${escapeHtml(String(item.completedModelCalls ?? 0))}</span></div>
          <div><span>providerAttempts:</span> <span class="font-mono">${escapeHtml(String(item.providerAttempts ?? 0))}</span></div>
          <div><span>observedModel:</span> <span class="font-mono">${escapeHtml(String(item.observedModel || '-'))}</span></div>
          <div><span>retrievalMode:</span> <span class="font-mono">${escapeHtml(req.retrieval?.mode || '-')}</span></div>
        </div>
      </details>

      <div id="ask-followup-container" style="display: none; margin-top: 14px; border-top: 1px solid var(--border-subtle); padding-top: 12px;">
        <div class="form-group">
          <label class="form-label" data-i18n="ask.followupPrompt">${escapeHtml(t('ask.followupPrompt'))}</label>
          <textarea id="ask-followup-input" class="form-control" rows="2" maxlength="4000"></textarea>
        </div>
        <div style="display: flex; justify-content: flex-end; gap: 8px;">
          <button class="btn btn-secondary btn-sm" id="btn-cancel-followup" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
          <button class="btn btn-primary btn-sm" id="btn-submit-followup" data-i18n="ask.btnSubmit">${escapeHtml(t('ask.btnSubmit'))}</button>
        </div>
      </div>
    `;

    let actionButtons = '';
    if (item.state === 'pending_approval') {
      actionButtons = `
        <button class="btn btn-danger btn-sm" id="btn-cancel-ask" data-i18n="ask.btnCancel">${escapeHtml(t('ask.btnCancel'))}</button>
        ${item.approval && item.approval.state === 'pending' ? `
          <button class="btn btn-primary btn-sm" id="btn-approve-ask" data-i18n="inbox.btnApprove">${escapeHtml(t('inbox.btnApprove'))}</button>
        ` : ''}
      `;
    } else if (['answered', 'unanswered'].includes(item.state)) {
      actionButtons = `
        ${citations.length > 0 ? `
          <button class="btn btn-secondary btn-sm" id="btn-view-citations" data-i18n="ask.btnViewCitations">${escapeHtml(t('ask.btnViewCitations'))}</button>
        ` : ''}
        ${(item.round || 1) < 8 && item.sourcesValid ? `
          <button class="btn btn-primary btn-sm" id="btn-followup-ask" data-i18n="ask.btnFollowup">${escapeHtml(t('ask.btnFollowup'))}</button>
        ` : ''}
      `;
    }

    f.innerHTML = `
      <button class="btn btn-secondary" id="btn-close-ask-detail" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      ${actionButtons}
    `;

    document.getElementById('btn-close-ask-detail')?.addEventListener('click', closeModal);

    document.getElementById('btn-cancel-ask')?.addEventListener('click', async () => {
      if (!confirm(t('ask.cancelConfirm'))) return;
      try {
        await callBridge('ask.cancel', { project: currentProject, id: askId, askHash: item.askHash });
        if (!isFresh()) return;
        showToast({ key: 'ask.cancelSuccess' });
        openAskDetailModal(askId);
      } catch (err) {
        if (!isFresh()) return;
        showToast(err.message, 'error');
      }
    });

    document.getElementById('btn-approve-ask')?.addEventListener('click', async () => {
      const btn = document.getElementById('btn-approve-ask');
      if (btn) {
        btn.disabled = true;
        btn.textContent = t('common.loading');
      }
      try {
        await callBridge('approvals.decide', {
          id: item.approval.id,
          decision: 'approve',
          snapshotHash: item.approval.snapshotHash
        });
        if (!isFresh()) return;
        showToast({ key: 'inbox.approvedToast' });
        openAskDetailModal(askId);
      } catch (err) {
        if (!isFresh()) return;
        showToast({ key: 'inbox.approveFailedToast', params: { error: err.message } }, 'error');
        const isExpired = err && (err.message === 'Approval expired; no action was executed. Review a new request.' || String(err.message || '').includes('Approval expired; no action was executed. Review a new request.'));
        if (isExpired) {
          const refreshRes = await refreshDashboard(true, true);
          if (!isFresh(true)) return;
          if (refreshRes && refreshRes.success !== false) {
            openAskDetailModal(askId);
          }
        } else {
          if (btn) {
            btn.disabled = false;
            btn.textContent = t('inbox.btnApprove');
          }
        }
      }
    });

    document.getElementById('btn-view-citations')?.addEventListener('click', () => {
      openAskCitationsModal(askId, item.askHash);
    });

    const followupBox = document.getElementById('ask-followup-container');
    document.getElementById('btn-followup-ask')?.addEventListener('click', () => {
      if (!followupBox) return;
      followupBox.style.display = followupBox.style.display === 'none' ? 'block' : 'none';
      if (followupBox.style.display === 'block') {
        document.getElementById('ask-followup-input')?.focus();
        followupBox.scrollIntoView({ behavior: 'smooth' });
      }
    });

    document.getElementById('btn-cancel-followup')?.addEventListener('click', () => {
      if (followupBox) followupBox.style.display = 'none';
    });

    document.getElementById('btn-submit-followup')?.addEventListener('click', async () => {
      const followInput = document.getElementById('ask-followup-input');
      const followQ = followInput?.value.trim();
      if (!followQ) {
        followInput?.focus();
        return;
      }
      const submitFollowBtn = document.getElementById('btn-submit-followup');
      if (submitFollowBtn) {
        submitFollowBtn.disabled = true;
        submitFollowBtn.textContent = t('common.loading');
      }

      try {
        const agent = req.agent || {};
        const followParams = {
          id: askId,
          askHash: item.askHash,
          project: currentProject,
          question: followQ,
          searchQuery: followQ,
          executable: agent.executable || '/usr/local/bin/codex',
          model: agent.model || 'gpt-5.6-sol',
          effort: agent.reasoningEffort || 'low',
          retrievalMode: req.retrieval?.mode || 'lexical',
          timeoutSeconds: req.timeoutSeconds || 120,
          maxSources: req.retrieval?.maxSources || 8,
          maxSourceBytes: req.retrieval?.maxSourceBytes || 24000
        };
        const origScope = req.scope || {};
        for (const k of ['branch', 'worktree', 'task', 'sessionId']) {
          if (origScope[k] !== undefined && origScope[k] !== null && origScope[k] !== '') {
            followParams[k] = origScope[k];
          }
        }
        const res = await callBridge('ask.followup', followParams);
        if (!isFresh()) return;
        showToast({ key: 'ask.followupSuccess' });
        openAskDetailModal(res.id);
      } catch (err) {
        if (!isFresh()) return;
        showToast(err.message, 'error');
        if (submitFollowBtn) {
          submitFollowBtn.disabled = false;
          submitFollowBtn.textContent = t('ask.btnSubmit');
        }
      }
    });
  }

  async function openAskCitationsModal(askId, askHash) {
    const currentProject = state.currentProject;
    const currentPage = state.currentPage;
    if (!currentProject || !askId) return;

    openModal({ key: 'ask.citationsTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-citations" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-citations')?.addEventListener('click', closeModal);

    let data = null;
    try {
      data = await callBridge('ask.citations', { project: currentProject, id: askId, askHash });
    } catch (e) {
      if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage) return;
      const b = document.getElementById('modal-body');
      if (b) {
        b.innerHTML = `
          <div class="alert-banner alert-danger">${escapeHtml(e.message)}</div>
          <div style="margin-top: 12px;">
            <button class="btn btn-secondary btn-sm" id="btn-back-detail" data-i18n="ask.btnBackToDetail">${escapeHtml(t('ask.btnBackToDetail'))}</button>
          </div>
        `;
        document.getElementById('btn-back-detail')?.addEventListener('click', () => openAskDetailModal(askId));
      }
      return;
    }
    if (currentModalInstance !== thisModalInstance || state.currentProject !== currentProject || state.currentPage !== currentPage) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const citations = Array.isArray(data.citations) ? data.citations : [];
    const sources = Array.isArray(data.sources) ? data.sources : [];

    b.innerHTML = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px;" data-i18n="ask.citationsDesc">${escapeHtml(t('ask.citationsDesc'))}</p>

      <div class="alert-banner alert-neutral" style="margin-bottom: 12px; font-size: 11px;" data-i18n="ask.semanticNotice">
        ${escapeHtml(t('ask.semanticNotice'))}
      </div>

      <div style="margin-bottom: 16px;">
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;">
          <span data-i18n="ask.citationsTitle">${escapeHtml(t('ask.citationsTitle'))}</span> (${citations.length})
        </div>
        ${citations.length === 0 ? `
          <div class="text-secondary" style="font-size: 12px;" data-i18n="common.none">${escapeHtml(t('common.none'))}</div>
        ` : citations.map(c => {
          const parts = (c.sourceId || '').split('#');
          const anchor = parts[1];
          const baseSourceId = parts[0];
          const matchedSource = sources.find(s => s.sourceId === c.sourceId || s.sourceId === baseSourceId);
          const sourceTitle = (matchedSource && matchedSource.title) || c.title || c.sourceId;

          return `
            <div class="card" style="margin-bottom: 8px; padding: 10px 12px; background: var(--bg-surface-secondary);">
              <div style="font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--text-primary);">
                ${escapeHtml(sourceTitle)}
              </div>
              <blockquote style="border-left: 3px solid var(--accent); margin: 6px 0; padding: 6px 10px; background: var(--bg-surface); font-size: 12px; font-style: italic; line-height: 1.4;">
                “${escapeHtml(c.quote)}”
              </blockquote>
              <div style="font-size: 11px; color: var(--status-sage-text); margin-top: 4px;" data-i18n="ask.exactQuoteVerified">
                ${escapeHtml(t('ask.exactQuoteVerified'))}
              </div>
              <details class="memory-meta-details" style="margin-top: 6px;">
                <summary style="font-size: 11px; color: var(--text-secondary); cursor: pointer;" data-i18n="memory.techMetaSummary">${escapeHtml(t('memory.techMetaSummary'))}</summary>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 4px; font-size: 11px; margin-top: 4px; color: var(--text-secondary);">
                  <div><span data-i18n="ask.sourceIdLabel">${escapeHtml(t('ask.sourceIdLabel'))}</span>: <span class="font-mono">${escapeHtml(c.sourceId)}</span></div>
                  <div><span>sourceHash:</span> <span class="font-mono">${escapeHtml((c.sourceHash || '').substring(0, 16))}</span></div>
                  ${anchor ? `<div><span data-i18n="ask.anchorLabel">${escapeHtml(t('ask.anchorLabel'))}</span>: <span class="code-badge">${escapeHtml(anchor)}</span></div>` : ''}
                </div>
              </details>
            </div>
          `;
        }).join('')}
      </div>

      <div>
        <div style="font-size: 12px; font-weight: 600; margin-bottom: 8px;">
          <span data-i18n="ask.frozenSourcesTitle">${escapeHtml(t('ask.frozenSourcesTitle'))}</span> (${sources.length})
        </div>
        ${sources.length === 0 ? `
          <div class="text-secondary" style="font-size: 12px;" data-i18n="common.none">${escapeHtml(t('common.none'))}</div>
        ` : sources.map(s => `
          <details class="memory-meta-details" style="margin-bottom: 8px;">
            <summary style="font-size: 12px; font-weight: 500;">
              ${escapeHtml(s.title || s.sourceId)}
              <span class="code-badge" style="margin-left: 6px;">${escapeHtml(s.kind)}</span>
              ${s.truncated ? '<span class="status-badge status-amber" style="margin-left: 4px;">truncated</span>' : ''}
            </summary>
            <div style="margin-top: 8px;">
              <div class="font-mono text-secondary" style="font-size: 11px; margin-bottom: 4px;">ID: ${escapeHtml(s.sourceId)} · ${escapeHtml(String(s.fullSourceBytes || 0))} bytes</div>
              <pre style="max-height: 180px; overflow-y: auto; background: var(--bg-surface-secondary); padding: 8px; font-size: 11px; border-radius: 4px; border: 1px solid var(--border-subtle); white-space: pre-wrap;">${escapeHtml(s.content || '')}</pre>
            </div>
          </details>
        `).join('')}
      </div>
    `;

    f.innerHTML = `
      <button class="btn btn-secondary" id="btn-back-to-ask-detail" data-i18n="ask.btnBackToDetail">${escapeHtml(t('ask.btnBackToDetail'))}</button>
      <button class="btn btn-secondary" id="btn-close-citations-modal" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
    `;

    document.getElementById('btn-back-to-ask-detail')?.addEventListener('click', () => openAskDetailModal(askId));
    document.getElementById('btn-close-citations-modal')?.addEventListener('click', closeModal);
  }

  function getMemoryStateBadge(stateStr) {
    const s = (stateStr || '').toLowerCase();
    switch (s) {
      case 'active':
        return `<span class="status-badge status-sage" data-i18n="memory.stateActive">${t('memory.stateActive')}</span>`;
      case 'candidate':
        return `<span class="status-badge status-amber" data-i18n="memory.stateCandidate">${t('memory.stateCandidate')}</span>`;
      case 'superseded':
        return `<span class="status-badge status-neutral" data-i18n="memory.stateSuperseded">${t('memory.stateSuperseded')}</span>`;
      case 'archived':
        return `<span class="status-badge status-neutral" data-i18n="memory.stateArchived">${t('memory.stateArchived')}</span>`;
      default:
        return `<span class="status-badge status-neutral">${escapeHtml(stateStr || t('memory.stateUnknown'))}</span>`;
    }
  }

  function openCreateOrEditMemoryModal(initial = {}) {
    const isEdit = !!initial.id;
    const provenanceOrigin = (initial.provenance && initial.provenance.origin) || initial.provenanceOrigin || initial.origin;
    const isObservedCapture = (provenanceOrigin === 'observed_session_capture');
    const isUserEdit = Boolean(
      (initial.provenance && (initial.provenance.user_edit || initial.provenance.edited || initial.provenance.lastModifiedBy === 'user_edit' || initial.provenance.editOrigin === 'user_edit')) ||
      (initial.provenance && Array.isArray(initial.provenance.history) && initial.provenance.history.some(h => h.origin === 'user_edit' || h.type === 'user_edit'))
    );

    const initialSrcSession = initial.sourceSession || (initial.provenance && (initial.provenance.session || initial.provenance.sessionId)) || '';
    const initialSrcMsg = initial.sourceMessage || (initial.provenance && (initial.provenance.message || initial.provenance.messageId)) || '';
    const initialSrcCommit = initial.sourceCommit || (initial.provenance && initial.provenance.commit) || '';
    const initialSrcFile = initial.sourceFile || (initial.provenance && (initial.provenance.file || initial.provenance.filePath)) || '';

    const validTypes = [
      'decision', 'constraint', 'preference', 'failure', 'fact',
      'workflow knowledge', 'observation', 'hypothesis', 'checkpoint'
    ];
    const validScopes = [
      'global', 'project', 'repository', 'branch', 'worktree', 'task', 'session'
    ];

    const modalBody = `
      <div class="form-group">
        <label class="form-label" data-i18n="memory.formTitle">${t('memory.formTitle')}</label>
        <input type="text" id="mem-title" class="form-input" value="${escapeHtml(initial.title || '')}" placeholder="${t('memory.formTitlePlaceholder')}" data-i18n-placeholder="memory.formTitlePlaceholder">
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="memory.formContent">${t('memory.formContent')}</label>
        <textarea id="mem-content" class="form-textarea" placeholder="${t('memory.formContentPlaceholder')}" data-i18n-placeholder="memory.formContentPlaceholder">${escapeHtml(initial.content || '')}</textarea>
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formType">${t('memory.formType')}</label>
          <select id="mem-type" class="form-select">
            ${validTypes.map(typeVal => `<option value="${typeVal}" ${((initial.type || 'fact').toLowerCase() === typeVal) ? 'selected' : ''}>${typeVal}</option>`).join('')}
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formScope">${t('memory.formScope')}</label>
          <select id="mem-scope" class="form-select">
            ${validScopes.map(scopeVal => `<option value="${scopeVal}" ${((initial.scope || 'project').toLowerCase() === scopeVal) ? 'selected' : ''}>${scopeVal}</option>`).join('')}
          </select>
        </div>
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formProject">${t('memory.formProject')}</label>
          <select id="mem-project" class="form-select" ${isObservedCapture ? 'disabled' : ''}>
            <option value="" data-i18n="memory.formProjectGlobal">${t('memory.formProjectGlobal')}</option>
            ${state.registeredProjects.map(p => `
              <option value="${escapeHtml(p.path || p.id)}" ${(initial.project === (p.path || p.id)) ? 'selected' : ''}>${escapeHtml(p.title || p.path)}</option>
            `).join('')}
          </select>
          ${isObservedCapture ? `<div style="font-size: 10px; color: var(--text-secondary); margin-top: 2px;" data-i18n="memory.formProjectLockedNotice">${escapeHtml(t('memory.formProjectLockedNotice'))}</div>` : ''}
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formState">${t('memory.formState')}</label>
          <select id="mem-state" class="form-select" ${isEdit ? 'disabled' : ''}>
            <option value="candidate" ${(initial.state || 'candidate').toLowerCase() === 'candidate' ? 'selected' : ''} data-i18n="memory.stateCandidate">${t('memory.stateCandidate')}</option>
            <option value="active" ${(initial.state || '').toLowerCase() === 'active' ? 'selected' : ''} data-i18n="memory.stateActive">${t('memory.stateActive')}</option>
            <option value="superseded" ${(initial.state || '').toLowerCase() === 'superseded' ? 'selected' : ''} data-i18n="memory.stateSuperseded">${t('memory.stateSuperseded')}</option>
            <option value="archived" ${(initial.state || '').toLowerCase() === 'archived' ? 'selected' : ''} data-i18n="memory.stateArchived">${t('memory.stateArchived')}</option>
          </select>
          ${isEdit ? `<div style="font-size: 10px; color: var(--text-secondary); margin-top: 2px;" data-i18n="memory.formStateEditNotice">${t('memory.formStateEditNotice')}</div>` : ''}
        </div>
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formBranch">${t('memory.formBranch')}</label>
          <input type="text" id="mem-branch" class="form-input" value="${escapeHtml(initial.branch || '')}" placeholder="${t('memory.formBranchPlaceholder')}" data-i18n-placeholder="memory.formBranchPlaceholder">
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formWorktree">${t('memory.formWorktree')}</label>
          <input type="text" id="mem-worktree" class="form-input" value="${escapeHtml(initial.worktree || '')}" placeholder="${t('memory.formWorktreePlaceholder')}" data-i18n-placeholder="memory.formWorktreePlaceholder">
        </div>
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formTask">${t('memory.formTask')}</label>
          <input type="text" id="mem-task" class="form-input" value="${escapeHtml(initial.task || '')}" placeholder="${t('memory.formTaskPlaceholder')}" data-i18n-placeholder="memory.formTaskPlaceholder">
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formSrcSession">${t('memory.formSrcSession')}</label>
          <input type="text" id="mem-src-session" class="form-input" value="${escapeHtml(initialSrcSession)}" placeholder="${t('memory.formSrcSessionPlaceholder')}" data-i18n-placeholder="memory.formSrcSessionPlaceholder" ${isObservedCapture ? 'readonly disabled' : ''}>
        </div>
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formSrcMsg">${t('memory.formSrcMsg')}</label>
          <input type="text" id="mem-src-msg" class="form-input" value="${escapeHtml(initialSrcMsg)}" placeholder="${t('memory.formSrcMsgPlaceholder')}" data-i18n-placeholder="memory.formSrcMsgPlaceholder" ${isObservedCapture ? 'readonly disabled' : ''}>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.formSrcCommit">${t('memory.formSrcCommit')}</label>
          <input type="text" id="mem-src-commit" class="form-input" value="${escapeHtml(initialSrcCommit)}" placeholder="${t('memory.formSrcCommitPlaceholder')}" data-i18n-placeholder="memory.formSrcCommitPlaceholder" ${isObservedCapture ? 'readonly disabled' : ''}>
        </div>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="memory.formSrcFile">${t('memory.formSrcFile')}</label>
        <input type="text" id="mem-src-file" class="form-input" value="${escapeHtml(initialSrcFile)}" placeholder="${t('memory.formSrcFilePlaceholder')}" data-i18n-placeholder="memory.formSrcFilePlaceholder" ${isObservedCapture ? 'readonly disabled' : ''}>
      </div>
      ${isObservedCapture ? `
        <div class="card" style="margin-top: 8px; padding: 10px 12px; background: var(--bg-subtle); border-left: 3px solid var(--accent-color, #3b82f6); font-size: 11px;">
          <div style="font-weight: 600; margin-bottom: 2px;" data-i18n="memory.observedCaptureNoticeTitle">${escapeHtml(t('memory.observedCaptureNoticeTitle'))}</div>
          <div class="text-secondary" style="line-height: 1.45;" data-i18n="memory.observedCaptureNotice">${escapeHtml(t('memory.observedCaptureNotice'))}</div>
          ${isUserEdit ? `
            <div style="margin-top: 6px; display: inline-flex; align-items: center; gap: 4px; font-weight: 500; color: var(--status-amber-text, #f59e0b);" data-i18n="memory.observedCaptureEditedBadge">
              <span class="status-badge status-amber">${escapeHtml(t('memory.observedCaptureEditedBadge'))}</span>
            </div>
          ` : `
            <div style="margin-top: 4px; color: var(--text-secondary); font-size: 10px;" data-i18n="memory.observedCaptureWillAttributeNotice">
              ${escapeHtml(t('memory.observedCaptureWillAttributeNotice'))}
            </div>
          `}
        </div>
      ` : ''}
    `;

    openModal({ key: isEdit ? 'memory.editModalTitle' : 'memory.newModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-mem" data-i18n="common.cancel">${t('common.cancel')}</button>
      <button class="btn btn-primary" id="btn-save-mem" data-i18n="memory.btnSaveMemory">${t('memory.btnSaveMemory')}</button>
    `);

    document.getElementById('btn-cancel-mem').addEventListener('click', closeModal);
    document.getElementById('btn-save-mem').addEventListener('click', async () => {
      const title = document.getElementById('mem-title').value.trim();
      const content = document.getElementById('mem-content').value.trim();
      const type = document.getElementById('mem-type').value.toLowerCase();
      const scope = document.getElementById('mem-scope').value.toLowerCase();
      const project = isObservedCapture ? (initial.project || '') : document.getElementById('mem-project').value;
      const normalizedInitialState = (initial.state || 'candidate').toLowerCase();
      const memState = isEdit ? normalizedInitialState : document.getElementById('mem-state').value.toLowerCase();
      const branch = document.getElementById('mem-branch').value.trim();
      const worktree = document.getElementById('mem-worktree').value.trim();
      const task = document.getElementById('mem-task').value.trim();
      const sourceSession = document.getElementById('mem-src-session').value.trim();
      const sourceMessage = document.getElementById('mem-src-msg').value.trim();
      const sourceFile = document.getElementById('mem-src-file').value.trim();
      const sourceCommit = document.getElementById('mem-src-commit').value.trim();

      if (!title || !content) {
        showToast({ key: 'memory.validationTitleAndContentRequired' }, 'error');
        return;
      }
      if (scope !== 'global' && !project) {
        showToast({ key: 'memory.validationProjectRequired' }, 'error');
        return;
      }
      if (scope === 'branch' && !branch) {
        showToast({ key: 'memory.validationBranchRequired' }, 'error');
        return;
      }
      if (scope === 'worktree' && !worktree) {
        showToast({ key: 'memory.validationWorktreeRequired' }, 'error');
        return;
      }
      if (scope === 'task' && !task) {
        showToast({ key: 'memory.validationTaskRequired' }, 'error');
        return;
      }
      if (scope === 'session' && !sourceSession) {
        showToast({ key: 'memory.validationSessionRequired' }, 'error');
        return;
      }

      const savePayload = {
        id: isEdit ? initial.id : undefined,
        title,
        content,
        type,
        scope,
        project: project || undefined,
        state: memState,
        branch: branch || undefined,
        worktree: worktree || undefined,
        task: task || undefined
      };

      if (!isObservedCapture) {
        if (sourceFile) savePayload.sourceFile = sourceFile;
        if (sourceCommit) savePayload.sourceCommit = sourceCommit;
        if (sourceSession) savePayload.sourceSession = sourceSession;
        if (sourceMessage) savePayload.sourceMessage = sourceMessage;
      }

      try {
        await callBridge('memory.save', savePayload);
        showToast({ key: 'memory.savedToast' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        showToast({ key: 'memory.saveFailedToast', params: { error: err.message } }, 'error');
      }
    });
  }

  function openSupersedeMemoryModal(memoryId) {
    const memories = (state.dashboard && state.dashboard.memories) || [];
    const oldMem = memories.find(m => m.id === memoryId);
    const oldTitle = oldMem ? oldMem.title : memoryId;

    // Filter candidate or active memories from the same project
    const eligibleReplacements = memories.filter(m => {
      if (m.id === memoryId) return false;
      if (oldMem && oldMem.project && m.project !== oldMem.project) return false;
      const st = (m.state || '').toLowerCase();
      return st === 'candidate' || st === 'active';
    });

    const modalBody = `
      <p style="font-size: 12px; color: var(--text-secondary); margin-bottom: 12px; line-height: 1.6;" data-i18n="memory.supersedeNotice" data-i18n-params="${escapeHtml(JSON.stringify({ title: oldTitle }))}">
        ${t('memory.supersedeNotice', { title: escapeHtml(oldTitle) })}
      </p>
      ${eligibleReplacements.length === 0 ? `
        <div class="alert-banner alert-warning" style="margin-bottom: 12px; line-height: 1.6;" data-i18n="memory.noReplacementsNotice">
          ${t('memory.noReplacementsNotice')}
        </div>
      ` : `
        <div class="form-group">
          <label class="form-label" data-i18n="memory.selectReplacementLabel">${t('memory.selectReplacementLabel')}</label>
          <select id="mem-supersede-target" class="form-select">
            <option value="" data-i18n="memory.selectReplacementPlaceholder">${t('memory.selectReplacementPlaceholder')}</option>
            ${eligibleReplacements.map(m => `
              <option value="${escapeHtml(m.id)}">${escapeHtml(m.title)} (${escapeHtml(m.id.substring(0, 8))}) [${escapeHtml(m.state || 'active')}]</option>
            `).join('')}
          </select>
        </div>
      `}
    `;

    openModal({ key: 'memory.supersedeModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-supersede" data-i18n="common.cancel">${t('common.cancel')}</button>
      ${eligibleReplacements.length > 0 ? `<button class="btn btn-primary" id="btn-confirm-supersede" data-i18n="memory.btnConfirmSupersede">${t('memory.btnConfirmSupersede')}</button>` : ''}
    `);

    document.getElementById('btn-cancel-supersede').addEventListener('click', closeModal);
    const confirmBtn = document.getElementById('btn-confirm-supersede');
    if (confirmBtn) {
      confirmBtn.addEventListener('click', async () => {
        const replacementId = document.getElementById('mem-supersede-target').value;
        if (!replacementId) {
          showToast({ key: 'memory.validationSelectReplacement' }, 'error');
          return;
        }
        try {
          // Atomically activate replacement B and mark A as superseded
          await callBridge('memory.transition', {
            id: replacementId,
            state: 'active',
            supersedes: memoryId
          });
          showToast({ key: 'memory.supersededToast', params: { title: oldTitle } });
          closeModal();
          await refreshDashboard(true, true);
        } catch (err) {
          showToast({ key: 'memory.supersedeFailedToast', params: { error: err.message } }, 'error');
        }
      });
    }
  }

  function openRecallModal() {
    const modalBody = `
      <div class="form-group">
        <label class="form-label" data-i18n="memory.recallQueryLabel">${t('memory.recallQueryLabel')}</label>
        <input type="text" id="recall-query" class="form-input" placeholder="${t('memory.recallQueryPlaceholder')}" data-i18n-placeholder="memory.recallQueryPlaceholder">
      </div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.recallProjectLabel">${t('memory.recallProjectLabel')}</label>
          <select id="recall-project" class="form-select">
            ${state.registeredProjects.map(p => `
              <option value="${escapeHtml(p.path || p.id)}">${escapeHtml(p.title || p.path)}</option>
            `).join('')}
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.recallBudgetLabel">${t('memory.recallBudgetLabel')}</label>
          <select id="recall-budget" class="form-select">
            <option value="500" data-i18n="memory.recallBudget500">${t('memory.recallBudget500')}</option>
            <option value="1000" selected data-i18n="memory.recallBudget1000">${t('memory.recallBudget1000')}</option>
            <option value="2000" data-i18n="memory.recallBudget2000">${t('memory.recallBudget2000')}</option>
            <option value="4000" data-i18n="memory.recallBudget4000">${t('memory.recallBudget4000')}</option>
          </select>
        </div>
      </div>
      <div style="display: grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 10px; margin-top: 4px;">
        <div class="form-group">
          <label class="form-label" data-i18n="memory.recallModeLabel">${t('memory.recallModeLabel')}</label>
          <select id="recall-mode" class="form-select">
            <option value="lexical" selected data-i18n="memory.recallModeLexical">${t('memory.recallModeLexical')}</option>
            <option value="semantic" data-i18n="memory.recallModeSemantic">${t('memory.recallModeSemantic')}</option>
            <option value="hybrid" data-i18n="memory.recallModeHybrid">${t('memory.recallModeHybrid')}</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.semanticLangSelect">${t('memory.semanticLangSelect')}</label>
          <select id="recall-language" class="form-select">
            <option value="en" selected data-i18n="memory.semanticLangEn">${t('memory.semanticLangEn')}</option>
            <option value="zh-Hans" data-i18n="memory.semanticLangZh">${t('memory.semanticLangZh')}</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" data-i18n="memory.recallMinSimilarityLabel">${t('memory.recallMinSimilarityLabel')}</label>
          <input type="number" id="recall-min-similarity" class="form-input" min="0" max="1" step="0.05" value="0.0">
        </div>
      </div>
      <details style="margin-top: 8px; margin-bottom: 8px; font-size: 12px; color: var(--text-secondary);">
        <summary style="cursor: pointer; user-select: none; font-weight: 500;" data-i18n="memory.recallAdvancedSummary">${t('memory.recallAdvancedSummary')}</summary>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px;">
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" style="font-size: 12px;" data-i18n="memory.recallBranchLabel">${t('memory.recallBranchLabel')}</label>
            <input type="text" id="recall-branch" class="form-input" style="font-size: 12px;" placeholder="${t('memory.recallBranchPlaceholder')}" data-i18n-placeholder="memory.recallBranchPlaceholder">
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" style="font-size: 12px;" data-i18n="memory.recallWorktreeLabel">${t('memory.recallWorktreeLabel')}</label>
            <input type="text" id="recall-worktree" class="form-input" style="font-size: 12px;" placeholder="${t('memory.recallWorktreePlaceholder')}" data-i18n-placeholder="memory.recallWorktreePlaceholder">
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" style="font-size: 12px;" data-i18n="memory.recallTaskLabel">${t('memory.recallTaskLabel')}</label>
            <input type="text" id="recall-task" class="form-input" style="font-size: 12px;" placeholder="${t('memory.recallTaskPlaceholder')}" data-i18n-placeholder="memory.recallTaskPlaceholder">
          </div>
          <div class="form-group" style="margin-bottom: 0;">
            <label class="form-label" style="font-size: 12px;" data-i18n="memory.recallSessionIdLabel">${t('memory.recallSessionIdLabel')}</label>
            <input type="text" id="recall-session-id" class="form-input" style="font-size: 12px;" placeholder="${t('memory.recallSessionIdPlaceholder')}" data-i18n-placeholder="memory.recallSessionIdPlaceholder">
          </div>
        </div>
      </details>
      <div id="recall-results-area" style="margin-top: 10px; max-height: 240px; overflow-y: auto;"></div>
    `;

    openModal({ key: 'memory.recallModalTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-close-recall" data-i18n="common.close">${t('common.close')}</button>
      <button class="btn btn-primary" id="btn-do-recall" data-i18n="memory.btnDoRecall">${t('memory.btnDoRecall')}</button>
    `);

    document.getElementById('btn-close-recall').addEventListener('click', closeModal);
    document.getElementById('btn-do-recall').addEventListener('click', async () => {
      const query = document.getElementById('recall-query').value.trim();
      const project = document.getElementById('recall-project').value;
      const budget = parseInt(document.getElementById('recall-budget').value, 10);
      const retrievalMode = document.getElementById('recall-mode')?.value || 'lexical';
      const language = document.getElementById('recall-language')?.value || 'en';
      const minSimilarity = parseFloat(document.getElementById('recall-min-similarity')?.value || '0');
      const resultsArea = document.getElementById('recall-results-area');

      if (!query) {
        showToast({ key: 'memory.recallQueryRequired' }, 'error');
        return;
      }

      const branchVal = (document.getElementById('recall-branch')?.value || '').trim();
      const worktreeVal = (document.getElementById('recall-worktree')?.value || '').trim();
      const taskVal = (document.getElementById('recall-task')?.value || '').trim();
      const sessionIdVal = (document.getElementById('recall-session-id')?.value || '').trim();

      const recallPayload = {
        query,
        project,
        budget,
        retrievalMode,
        language
      };
      if (!isNaN(minSimilarity) && minSimilarity > 0) {
        recallPayload.minSimilarity = minSimilarity;
      }
      if (branchVal) recallPayload.branch = branchVal;
      if (worktreeVal) recallPayload.worktree = worktreeVal;
      if (taskVal) recallPayload.task = taskVal;
      if (sessionIdVal) recallPayload.sessionId = sessionIdVal;

      resultsArea.innerHTML = `<div class="text-secondary" style="font-size: 11px;" data-i18n="memory.recalling">${t('memory.recalling')}</div>`;

      try {
        const res = await callBridge('recall', recallPayload);
        const items = (res && res.items) || [];
        const used = (res && res.usedTokens) || 0;
        const isFallback = Boolean((res && res.fallbackReason) || (res && res.requestedRetrievalMode && res.requestedRetrievalMode !== res.retrievalMode));
        const fallbackReason = (res && res.fallbackReason) || (res && res.status === 'unavailable' ? '模型不可用' : '回退到词面检索');
        const isIndexIncomplete = Boolean(res && res.indexIncomplete);

        resultsArea.innerHTML = `
          ${isFallback ? `
            <div class="alert-banner alert-warning" style="margin-bottom: 8px; font-size: 11px;">
              <span data-i18n="memory.recallFallbackNotice" data-i18n-params="${escapeHtml(JSON.stringify({ reason: fallbackReason }))}">
                ${t('memory.recallFallbackNotice', { reason: fallbackReason })}
              </span>
            </div>
          ` : ''}
          ${isIndexIncomplete ? `
            <div class="alert-banner alert-warning" style="margin-bottom: 8px; font-size: 11px;" data-i18n="memory.recallIndexIncompleteNotice">
              ${t('memory.recallIndexIncompleteNotice')}
            </div>
          ` : ''}
          <div style="margin-bottom: 6px; font-size: 11px; display: flex; justify-content: space-between;">
            <span data-i18n="memory.recallMatchedCount" data-i18n-params="${escapeHtml(JSON.stringify({ count: items.length }))}">${t('memory.recallMatchedCount', { count: items.length })}</span>
            <span class="font-mono" data-i18n="memory.recallTokensUsed" data-i18n-params="${escapeHtml(JSON.stringify({ used, budget }))}">${t('memory.recallTokensUsed', { used, budget })}</span>
          </div>
          <div style="display: flex; flex-direction: column; gap: 6px;">
            ${items.length === 0 ? `<div style="font-size: 11px; color: var(--text-muted);" data-i18n="memory.recallEmpty">${t('memory.recallEmpty')}</div>` : ''}
            ${items.map(it => {
              const srcBadge = it.retrievalSource ? `<span class="badge-subtle font-mono" style="font-size: 10px;">${escapeHtml(it.retrievalSource)}</span>` : '';
              const simStr = (typeof it.semanticSimilarity === 'number') ? `<span class="badge-subtle font-mono" style="font-size: 10px;" title="${t('memory.similarityLabel')}">cos: ${it.semanticSimilarity.toFixed(4)}</span>` : '';
              const scoreStr = (typeof it.rankingScore === 'number') ? `<span class="badge-subtle font-mono" style="font-size: 10px;" title="${t('memory.rankingScoreLabel')}">rank: ${it.rankingScore.toFixed(4)}</span>` : '';
              return `
                <div class="card" style="padding: 6px 10px; margin-bottom: 0;">
                  <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-bottom: 2px;">
                    <div style="font-weight: 600; font-size: 11px;">${escapeHtml(it.title)}</div>
                    <div style="display: flex; gap: 4px; align-items: center;">
                      ${srcBadge}
                      ${simStr}
                      ${scoreStr}
                    </div>
                  </div>
                  <div style="font-size: 11px; color: var(--text-secondary);">${escapeHtml(it.content)}</div>
                </div>
              `;
            }).join('')}
          </div>
        `;
      } catch (err) {
        resultsArea.innerHTML = `<div class="alert-banner alert-danger">${escapeHtml(err.message)}</div>`;
      }
    });
  }

  // --- Library Section (supports text, path, url, folders, search, index) ---
  async function renderLibrarySection(target) {
    const thisGen = renderGeneration;
    const thisScope = state.currentProject;
    let library = (state.dashboard && state.dashboard.library) || [];

    try {
      const list = await callBridge('library.list', {
        project: thisScope || undefined,
        includeArchived: Boolean(state.libraryIncludeArchived)
      });
      if (thisGen !== renderGeneration || thisScope !== state.currentProject) return;
      if (Array.isArray(list)) {
        library = list;
        if (state.dashboard) {
          state.dashboard.library = list;
        }
      }
    } catch (e) {
      // fallback to dashboard library
    }

    const folders = Array.from(new Set(library.map(item => (item.folder || '').trim()).filter(Boolean))).sort();

    let filtered = library;
    if (state.librarySelectedFolder === '__root__') {
      filtered = filtered.filter(item => !(item.folder || '').trim());
    } else if (state.librarySelectedFolder) {
      filtered = filtered.filter(item => (item.folder || '').trim() === state.librarySelectedFolder);
    }

    target.innerHTML = `
      <div class="list-toolbar">
        <span class="list-toolbar-note" data-i18n="setupL.library.headerDesc" data-i18n-params="${escapeHtml(JSON.stringify({ count: library.length }))}">${escapeHtml(t('setupL.library.headerDesc', { count: library.length }))}</span>
        <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
          <select id="sel-lib-folder-filter" class="filter-select" aria-label="${escapeHtml(t('library.colFolder'))}" data-i18n-aria-label="library.colFolder">
            <option value="" ${!state.librarySelectedFolder ? 'selected' : ''} data-i18n="library.allFolders">${escapeHtml(t('library.allFolders'))}</option>
            <option value="__root__" ${state.librarySelectedFolder === '__root__' ? 'selected' : ''} data-i18n="library.noFolder">${escapeHtml(t('library.noFolder'))}</option>
            ${folders.map(f => `<option value="${escapeHtml(f)}" ${state.librarySelectedFolder === f ? 'selected' : ''}>${escapeHtml(f)}</option>`).join('')}
          </select>
          <label class="form-checkbox-label">
            <input type="checkbox" id="chk-lib-include-archived" ${state.libraryIncludeArchived ? 'checked' : ''} />
            <span data-i18n="library.includeArchived">${escapeHtml(t('library.includeArchived'))}</span>
          </label>
          <button id="btn-library-search" class="btn btn-secondary btn-sm" data-i18n="library.btnSearchParagraphs">${escapeHtml(t('library.btnSearchParagraphs'))}</button>
          <button id="btn-library-index" class="btn btn-secondary btn-sm" data-i18n="library.btnIndexStatus">${escapeHtml(t('library.btnIndexStatus'))}</button>
          <button id="btn-add-library" class="btn btn-primary btn-sm" data-i18n="setupL.library.btnAdd">${escapeHtml(t('setupL.library.btnAdd'))}</button>
        </div>
      </div>

      ${filtered.length === 0 ? `
        <div class="empty-state">
          <div class="empty-state-title" data-i18n="${library.length === 0 ? 'setupL.library.emptyText' : 'list.emptyFiltered'}">${escapeHtml(t(library.length === 0 ? 'setupL.library.emptyText' : 'list.emptyFiltered'))}</div>
        </div>
      ` : `
        <div class="record-list">
          ${filtered.map(lib => {
            const libTitle = lib.title || t('common.unnamedSession');
            const libFolder = (lib.folder || '').trim();
            const libProject = lib.project ? lib.project.split('/').filter(Boolean).pop() : t('setupL.scope.global');
            const libVisibility = lib.state === 'archived'
              ? t('library.badgeArchived')
              : (lib.private ? t('setupL.library.badgePrivateShort') : t('setupL.library.badgePublicShort'));
            const libSource = lib.url || lib.path || (lib.content ? t('library.detailTextContent') : '');
            return `<article class="record-row" data-id="${escapeHtml(lib.id)}">
              <div class="record-main">
                <button class="record-title btn-view-library" data-id="${escapeHtml(lib.id)}" title="${escapeHtml(libTitle)}">${escapeHtml(libTitle)}</button>
                ${lib.content ? `<div class="record-snippet">${escapeHtml(String(lib.content).substring(0, 80))}</div>` : ''}
                <div class="record-meta">
                  ${libFolder ? `<span>${escapeHtml(libFolder)}</span>` : ''}
                  <span>${escapeHtml(libProject)}</span>
                  <span>${escapeHtml(libVisibility)}</span>
                  ${libSource ? `<span class="record-source" title="${escapeHtml(libSource)}">${escapeHtml(libSource)}</span>` : ''}
                  ${typeof lib.tokens === 'number' ? `<span>${escapeHtml(t('library.detailTokens'))} ${lib.tokens}</span>` : ''}
                </div>
              </div>
              ${actionMenu(`
                <button class="btn btn-edit-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnEdit" ${lib.state === 'archived' ? 'disabled' : ''}>${escapeHtml(t('library.btnEdit'))}</button>
                <button class="btn btn-export-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnExport">${escapeHtml(t('library.btnExport'))}</button>
                <button class="btn btn-history-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnHistory">${escapeHtml(t('library.btnHistory'))}</button>
                ${(lib.path || lib.url) && lib.state !== 'archived' ? `<button class="btn btn-refresh-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnRefreshSource">${escapeHtml(t('library.btnRefreshSource'))}</button>` : ''}
                ${lib.state === 'archived'
                  ? `<button class="btn btn-restore-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnRestore">${escapeHtml(t('library.btnRestore'))}</button>`
                  : `<button class="btn btn-archive-library" data-id="${escapeHtml(lib.id)}" data-i18n="library.btnArchive">${escapeHtml(t('library.btnArchive'))}</button>`}
              `, 'asset.rowActions')}
            </article>`;
          }).join('')}
        </div>
      `}
    `;

    document.getElementById('btn-add-library')?.addEventListener('click', openAddLibraryModal);
    document.getElementById('btn-library-search')?.addEventListener('click', openLibrarySearchModal);
    document.getElementById('btn-library-index')?.addEventListener('click', openLibraryIndexModal);

    document.getElementById('sel-lib-folder-filter')?.addEventListener('change', (e) => {
      state.librarySelectedFolder = e.target.value;
      renderLibrarySection(target);
    });

    document.getElementById('chk-lib-include-archived')?.addEventListener('change', (e) => {
      state.libraryIncludeArchived = e.target.checked;
      renderLibrarySection(target);
    });

    target.querySelectorAll('.btn-view-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) openLibraryDetailModal(id);
      });
    });

    target.querySelectorAll('.btn-edit-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) openEditLibraryModal(id);
      });
    });

    target.querySelectorAll('.btn-export-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) exportLibraryDocument(id);
      });
    });

    target.querySelectorAll('.btn-history-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) openLibraryHistoryModal(id);
      });
    });

    target.querySelectorAll('.btn-refresh-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) refreshLibrarySource(id);
      });
    });

    target.querySelectorAll('.btn-archive-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) archiveLibraryDocument(id);
      });
    });

    target.querySelectorAll('.btn-restore-library').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        if (id) restoreLibraryDocument(id);
      });
    });
  }

  function openAddLibraryModal() {
    const modalBody = `
      <div class="form-group">
        <label class="form-label" data-i18n="setupL.library.modalSourceTypeLabel">${escapeHtml(t('setupL.library.modalSourceTypeLabel'))}</label>
        <select id="lib-source-type" class="form-select">
          <option value="content" data-i18n="setupL.library.sourceTypeContent">${escapeHtml(t('setupL.library.sourceTypeContent'))}</option>
          <option value="path" data-i18n="setupL.library.sourceTypePath">${escapeHtml(t('setupL.library.sourceTypePath'))}</option>
          <option value="url" data-i18n="setupL.library.sourceTypeUrl">${escapeHtml(t('setupL.library.sourceTypeUrl'))}</option>
        </select>
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="setupL.library.modalDocTitleLabel">${escapeHtml(t('setupL.library.modalDocTitleLabel'))}</label>
        <input type="text" id="lib-title" class="form-input" placeholder="${escapeHtml(t('setupL.library.modalDocTitlePlaceholder'))}" data-i18n-placeholder="setupL.library.modalDocTitlePlaceholder">
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="library.folderLabel">${escapeHtml(t('library.folderLabel'))}</label>
        <input type="text" id="lib-folder" class="form-input" placeholder="engineering/parser">
      </div>
      <div class="form-group">
        <label class="form-label" data-i18n="setupL.library.modalProjectLabel">${escapeHtml(t('setupL.library.modalProjectLabel'))}</label>
        <select id="lib-project" class="form-select">
          <option value="" data-i18n="setupL.library.modalProjectGlobal">${escapeHtml(t('setupL.library.modalProjectGlobal'))}</option>
          ${state.registeredProjects.map(p => `
            <option value="${escapeHtml(p.path || p.id)}">${escapeHtml(p.title || p.path)}</option>
          `).join('')}
        </select>
      </div>
      <div class="form-group" id="lib-group-content">
        <label class="form-label" data-i18n="setupL.library.modalTextContentLabel">${escapeHtml(t('setupL.library.modalTextContentLabel'))}</label>
        <textarea id="lib-content" class="form-textarea" placeholder="${escapeHtml(t('setupL.library.modalTextContentPlaceholder'))}" data-i18n-placeholder="setupL.library.modalTextContentPlaceholder"></textarea>
      </div>
      <div class="form-group hidden" id="lib-group-path">
        <label class="form-label" data-i18n="setupL.library.modalPathLabel">${escapeHtml(t('setupL.library.modalPathLabel'))}</label>
        <input type="text" id="lib-path" class="form-input font-mono" placeholder="/path/to/document.md">
      </div>
      <div class="form-group hidden" id="lib-group-url">
        <label class="form-label" data-i18n="setupL.library.modalUrlLabel">${escapeHtml(t('setupL.library.modalUrlLabel'))}</label>
        <input type="url" id="lib-url" class="form-input font-mono" placeholder="https://example.com/docs">
      </div>
      <div class="form-group">
        <label class="form-checkbox-label">
          <input type="checkbox" id="lib-private" checked>
          <span data-i18n="setupL.library.modalPrivateCheckbox">${escapeHtml(t('setupL.library.modalPrivateCheckbox'))}</span>
        </label>
      </div>
    `;

    openModal({ key: 'setupL.library.modalAddTitle' }, modalBody, `
      <button class="btn btn-secondary" id="btn-cancel-lib" data-i18n="setupL.common.cancel">${escapeHtml(t('setupL.common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-save-lib" data-i18n="setupL.library.btnSave">${escapeHtml(t('setupL.library.btnSave'))}</button>
    `);

    const selType = document.getElementById('lib-source-type');
    const pathInput = document.getElementById('lib-path');
    const privCb = document.getElementById('lib-private');

    const forcedPrivateSubstrings = ['.env', 'credentials', 'secret', 'id_rsa', '.key', '.pem'];
    const updateForcedPrivatePolicy = () => {
      if (selType.value === 'path') {
        const val = (pathInput.value || '').toLowerCase();
        const isForced = forcedPrivateSubstrings.some(sub => val.includes(sub));
        if (isForced) {
          privCb.checked = true;
          privCb.disabled = true;
        } else {
          privCb.disabled = false;
        }
      } else {
        privCb.disabled = false;
      }
    };

    pathInput.addEventListener('input', updateForcedPrivatePolicy);
    selType.addEventListener('change', () => {
      const v = selType.value;
      document.getElementById('lib-group-content').classList.toggle('hidden', v !== 'content');
      document.getElementById('lib-group-path').classList.toggle('hidden', v !== 'path');
      document.getElementById('lib-group-url').classList.toggle('hidden', v !== 'url');
      updateForcedPrivatePolicy();
    });

    document.getElementById('btn-cancel-lib').addEventListener('click', closeModal);
    document.getElementById('btn-save-lib').addEventListener('click', async () => {
      const title = document.getElementById('lib-title').value.trim();
      const project = document.getElementById('lib-project').value;
      const folder = (document.getElementById('lib-folder')?.value || '').trim();
      const sourceType = selType.value;
      const isPrivate = privCb.checked || privCb.disabled;

      if (!title) {
        showToast({ key: 'setupL.library.toastTitleRequired' }, 'error');
        return;
      }

      if (folder && (folder.startsWith('/') || folder.includes('..') || folder.includes('\\'))) {
        showToast({ key: 'library.folderInvalid' }, 'error');
        return;
      }

      let payload = {
        title,
        project: project || undefined,
        folder: folder || undefined,
        private: Boolean(isPrivate)
      };

      if (sourceType === 'content') {
        payload.content = document.getElementById('lib-content').value.trim();
      } else if (sourceType === 'path') {
        payload.path = document.getElementById('lib-path').value.trim();
      } else if (sourceType === 'url') {
        payload.url = document.getElementById('lib-url').value.trim();
      }

      try {
        await callBridge('library.add', payload);
        showToast({ key: 'setupL.library.toastAdded' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (e) {
        showToast({ key: 'setupL.library.toastAddFailed', params: { error: e.message } }, 'error');
      }
    });
  }

  async function openLibraryDetailModal(docId) {
    const currentProject = state.currentProject;
    openModal({ key: 'library.detailTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-lib-detail" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-lib-detail')?.addEventListener('click', closeModal);

    let res = null;
    try {
      res = await callBridge('library.get', { id: docId, project: currentProject || undefined });
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const item = res.item || {};
    const snapshotHash = res.snapshotHash || '';
    const isArchived = item.state === 'archived';
    const isPrivate = item.private !== false;
    const hasSource = Boolean(item.path || item.sourcePath || item.url || item.sourceURL);

    // Also populate drawer if open for full test/layout compatibility
    const drawer = document.getElementById('drawer');
    const drawerContent = document.getElementById('drawer-content');
    if (drawer && drawer.classList.contains('open') && drawerContent) {
      drawerContent.innerHTML = `
        <div class="card">
          <div class="card-header">
            <span class="card-title" data-i18n="setupL.drawer.basicInfo">${escapeHtml(t('setupL.drawer.basicInfo'))}</span>
            ${isPrivate ? `<span class="status-badge status-amber">${escapeHtml(t('setupL.library.badgePrivateShort'))}</span>` : `<span class="status-badge status-neutral">${escapeHtml(t('setupL.library.badgePublicShort'))}</span>`}
          </div>
          <div style="font-size: 11px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
            <div><span class="text-secondary">${escapeHtml(t('setupL.guidelines.projectLabel'))}</span> ${item.project ? escapeHtml(item.project) : tHtml('setupL.scope.global')}</div>
            <div><span class="text-secondary">${escapeHtml(t('setupL.library.createdAtLabel'))}</span> ${formatTime(item.sourceCapturedAt || item.createdAt)}</div>
          </div>
        </div>
        <div>
          <h3 style="font-size: 13px; font-weight: 600; margin-bottom: 6px;">${escapeHtml(t('setupL.library.contentTitle'))}</h3>
          <div class="code-view">${escapeHtml(item.content || '')}</div>
        </div>
      `;
    }

    const loc = formatAssetLocation(item.sourcePath || item.assetPath || item.path, item.project ? 'project' : 'global', item.project || currentProject);

    b.innerHTML = `
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px;">
        <div>
          <h3 style="font-size: 14px; font-weight: 600; margin: 0;">${escapeHtml(item.title || docId)}</h3>
          <div class="asset-location" data-testid="asset-location" title="${escapeHtml(item.sourcePath || item.assetPath || item.path || '')}" style="font-size: 14px; font-family: var(--font-mono); color: var(--text-secondary); margin-top: 2px;">${escapeHtml(loc.displayText)}</div>
        </div>
        <div style="display: flex; gap: 6px;">
          ${isArchived ? `<span class="status-badge status-neutral" data-i18n="library.badgeArchived">${escapeHtml(t('library.badgeArchived'))}</span>` : ''}
          ${isPrivate
            ? `<span class="status-badge status-amber" data-i18n="setupL.library.badgePrivate">${escapeHtml(t('setupL.library.badgePrivate'))}</span>`
            : `<span class="status-badge status-neutral" data-i18n="setupL.library.badgePublic">${escapeHtml(t('setupL.library.badgePublic'))}</span>`}
        </div>
      </div>

      <div class="card" style="margin-bottom: 12px; font-size: 11px; background: var(--bg-subtle);">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
          <div><span class="text-secondary" data-i18n="setupL.library.tableProject">${escapeHtml(t('setupL.library.tableProject'))}:</span> ${item.project ? escapeHtml(item.project) : tHtml('setupL.scope.global')}</div>
          <div><span class="text-secondary" data-i18n="library.detailFolder">${escapeHtml(t('library.detailFolder'))}</span> ${item.folder ? escapeHtml(item.folder) : '<span class="text-secondary">-</span>'}</div>
          <div><span class="text-secondary" data-i18n="library.detailVersion">${escapeHtml(t('library.detailVersion'))}</span> v${item.version || 1}</div>
          <div><span class="text-secondary" data-i18n="library.detailTokens">${escapeHtml(t('library.detailTokens'))}</span> ${item.tokens || '-'}</div>
        </div>
        ${item.sourcePath ? `<div style="margin-top: 6px; font-family: var(--font-mono); color: var(--text-muted);"><span data-i18n="library.detailSourcePath">${escapeHtml(t('library.detailSourcePath'))}</span> ${escapeHtml(item.sourcePath)}</div>` : ''}
        ${item.sourceURL ? `<div style="margin-top: 6px; font-family: var(--font-mono); color: var(--text-muted);"><span data-i18n="library.detailSourceURL">${escapeHtml(t('library.detailSourceURL'))}</span> ${escapeHtml(item.sourceURL)}</div>` : ''}
      </div>

      <div>
        <h4 style="font-size: 12px; font-weight: 600; margin-bottom: 4px;" data-i18n="setupL.library.contentTitle">${escapeHtml(t('setupL.library.contentTitle'))}</h4>
        <div class="code-view" style="max-height: 240px; overflow-y: auto; white-space: pre-wrap; font-size: 12px; padding: 8px 10px; background: var(--bg-main); border: 1px solid var(--border-color); border-radius: 4px;">${escapeHtml(item.content || '')}</div>
      </div>

      <details class="tech-meta-details" style="margin-top: 12px; border-top: 1px solid var(--border-color); padding-top: 8px;">
        <summary style="font-size: 11px; color: var(--text-secondary); cursor: pointer;" data-i18n="library.techMetaSummary">${escapeHtml(t('library.techMetaSummary'))}</summary>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px; font-size: 11px; margin-top: 8px; font-family: var(--font-mono);">
          <div><span class="text-secondary" data-i18n="library.metaSnapshotHash">${escapeHtml(t('library.metaSnapshotHash'))}</span> ${escapeHtml(snapshotHash.substring(0, 16))}...</div>
          <div><span class="text-secondary" data-i18n="library.metaSourceHash">${escapeHtml(t('library.metaSourceHash'))}</span> ${escapeHtml(String(item.sourceHash || '-').substring(0, 16))}...</div>
          <div><span class="text-secondary" data-i18n="library.metaId">${escapeHtml(t('library.metaId'))}</span> ${escapeHtml(item.id)}</div>
          <div><span class="text-secondary" data-i18n="library.metaAssetPath">${escapeHtml(t('library.metaAssetPath'))}</span> ${escapeHtml(item.assetPath || '-')}</div>
        </div>
      </details>
    `;

    f.innerHTML = `
      <div style="display: flex; justify-content: space-between; width: 100%; flex-wrap: wrap; gap: 6px;">
        <div style="display: flex; gap: 6px;">
          ${!isArchived ? `
            <button class="btn btn-secondary btn-sm" id="btn-detail-edit-lib" data-i18n="library.btnEdit">${escapeHtml(t('library.btnEdit'))}</button>
            ${hasSource ? `<button class="btn btn-secondary btn-sm" id="btn-detail-refresh-lib" data-i18n="library.btnRefreshSource">${escapeHtml(t('library.btnRefreshSource'))}</button>` : ''}
            <button class="btn btn-danger btn-sm" id="btn-detail-archive-lib" data-i18n="library.btnArchive">${escapeHtml(t('library.btnArchive'))}</button>
          ` : `
            <button class="btn btn-primary btn-sm" id="btn-detail-restore-lib" data-i18n="library.btnRestore">${escapeHtml(t('library.btnRestore'))}</button>
          `}
          <button class="btn btn-secondary btn-sm" id="btn-detail-export-lib" data-i18n="library.btnExport">${escapeHtml(t('library.btnExport'))}</button>
          <button class="btn btn-secondary btn-sm" id="btn-detail-history-lib" data-i18n="library.btnHistory">${escapeHtml(t('library.btnHistory'))}</button>
        </div>
        <button class="btn btn-secondary btn-sm" id="btn-close-detail-lib-2" data-i18n="common.close">${escapeHtml(t('common.close'))}</button>
      </div>
    `;

    document.getElementById('btn-close-detail-lib-2')?.addEventListener('click', closeModal);
    document.getElementById('btn-detail-edit-lib')?.addEventListener('click', () => openEditLibraryModal(docId));
    document.getElementById('btn-detail-export-lib')?.addEventListener('click', () => exportLibraryDocument(docId));
    document.getElementById('btn-detail-history-lib')?.addEventListener('click', () => openLibraryHistoryModal(docId));
    document.getElementById('btn-detail-refresh-lib')?.addEventListener('click', () => refreshLibrarySource(docId, snapshotHash));
    document.getElementById('btn-detail-archive-lib')?.addEventListener('click', () => archiveLibraryDocument(docId, snapshotHash));
    document.getElementById('btn-detail-restore-lib')?.addEventListener('click', () => restoreLibraryDocument(docId, snapshotHash));
  }

  async function openEditLibraryModal(docId) {
    const currentProject = state.currentProject;
    openModal({ key: 'library.editModalTitle' }, `
      <div class="text-secondary" style="font-size: 12px; padding: 24px; text-align: center;">${escapeHtml(t('common.loading'))}</div>
    `, `<button class="btn btn-secondary" id="btn-close-lib-edit" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>`);

    const thisModalInstance = currentModalInstance;
    document.getElementById('btn-close-lib-edit')?.addEventListener('click', closeModal);

    let res = null;
    try {
      res = await callBridge('library.get', { id: docId, project: currentProject || undefined });
    } catch (e) {
      if (currentModalInstance !== thisModalInstance) return;
      const b = document.getElementById('modal-body');
      if (b) b.innerHTML = `<div class="alert-banner alert-warning">${escapeHtml(e.message)}</div>`;
      return;
    }
    if (currentModalInstance !== thisModalInstance) return;

    const b = document.getElementById('modal-body');
    const f = document.getElementById('modal-footer');
    if (!b || !f) return;

    const item = res.item || {};
    const snapshotHash = res.snapshotHash || '';
    const isSourceLocked = item.sourceLabeledPrivate === true || (item.sourcePath && ['.env', 'credentials', 'secret', 'id_rsa', '.key', '.pem'].some(s => item.sourcePath.toLowerCase().includes(s)));

    b.innerHTML = `
      <div class="alert-banner alert-info" style="font-size: 11px; margin-bottom: 12px;" data-i18n="library.editNotice">
        ${escapeHtml(t('library.editNotice'))}
      </div>

      <div class="form-group">
        <label class="form-label" data-i18n="library.titleLabel">${escapeHtml(t('library.titleLabel'))}</label>
        <input type="text" id="lib-edit-title" class="form-input" value="${escapeHtml(item.title || '')}" maxlength="300">
      </div>

      <div class="form-group">
        <label class="form-label" data-i18n="library.folderLabel">${escapeHtml(t('library.folderLabel'))}</label>
        <input type="text" id="lib-edit-folder" class="form-input" value="${escapeHtml(item.folder || '')}" placeholder="engineering/parser">
      </div>

      <div class="form-group">
        <label class="form-checkbox-label">
          <input type="checkbox" id="lib-edit-private" ${item.private !== false || isSourceLocked ? 'checked' : ''} ${isSourceLocked ? 'disabled' : ''}>
          <span data-i18n="library.privacyLabel">${escapeHtml(t('library.privacyLabel'))}</span>
        </label>
        ${isSourceLocked
          ? `<div class="form-hint" style="color: var(--status-amber-text);" data-i18n="library.privacyLockedDesc">${escapeHtml(t('library.privacyLockedDesc'))}</div>`
          : `<div class="form-hint" data-i18n="library.privacyDesc">${escapeHtml(t('library.privacyDesc'))}</div>`}
      </div>

      <div class="form-group">
        <label class="form-label" data-i18n="library.contentLabel">${escapeHtml(t('library.contentLabel'))}</label>
        <textarea id="lib-edit-content" class="form-textarea code-editor" style="min-height: 180px; font-size: 12px;">${escapeHtml(item.content || '')}</textarea>
      </div>

      <div style="font-size: 10px; font-family: var(--font-mono); color: var(--text-muted);">
        snapshotHash: ${escapeHtml(snapshotHash.substring(0, 16))}...
      </div>

      <div id="lib-edit-stale-warn" class="alert-banner alert-warning hidden" style="margin-top: 10px;"></div>
    `;

    f.innerHTML = `
      <button class="btn btn-secondary" id="btn-cancel-edit-lib" data-i18n="common.cancel">${escapeHtml(t('common.cancel'))}</button>
      <button class="btn btn-primary" id="btn-save-edit-lib" data-i18n="library.btnSaveVersion">${escapeHtml(t('library.btnSaveVersion'))}</button>
    `;

    document.getElementById('btn-cancel-edit-lib')?.addEventListener('click', closeModal);
    document.getElementById('btn-save-edit-lib')?.addEventListener('click', async () => {
      const title = (document.getElementById('lib-edit-title')?.value || '').trim();
      const folder = (document.getElementById('lib-edit-folder')?.value || '').trim();
      const content = document.getElementById('lib-edit-content')?.value || '';
      const isPrivate = isSourceLocked ? true : Boolean(document.getElementById('lib-edit-private')?.checked);
      const warnEl = document.getElementById('lib-edit-stale-warn');

      if (!title) {
        showToast({ key: 'setupL.library.toastTitleRequired' }, 'error');
        return;
      }
      if (folder && (folder.startsWith('/') || folder.includes('..') || folder.includes('\\'))) {
        showToast({ key: 'library.folderInvalid' }, 'error');
        return;
      }

      try {
        await callBridge('library.update', {
          id: docId,
          project: currentProject || undefined,
          snapshotHash,
          title,
          folder: folder || undefined,
          content,
          private: isPrivate
        });
        showToast({ key: 'library.saveSuccess' });
        closeModal();
        await refreshDashboard(true, true);
      } catch (err) {
        if (err.message && err.message.includes('changed since review')) {
          if (warnEl) {
            warnEl.textContent = t('library.staleWarning');
            warnEl.classList.remove('hidden');
          }
          showToast({ key: 'library.staleWarning' }, 'error');
        } else {
          showToast(err.message, 'error');
        }
      }
    });
  }

